class XMLDocument(BaseModel):
    model_config = ConfigDict(extra="ignore")
    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    company_id: str
    competencia: str
    tipo: str = ""  # entrada, saida - será preenchido pelo validator se tipo_operacao existir
    modelo: str = "nfe"  # nfe, nfce, nfse
    chave_nfe: str = ""  # Será preenchido pelo validator se chave_acesso existir
    numero_nfe: str
    serie: str = ""
    data_emissao: str
    data_saida_entrada: str = ""  # dhSaiEnt - Data de saída/entrada (usado para competência de entradas)
    # Dados do emitente
    emitente_cnpj: str
    emitente_nome: str
    emitente_ie: str = ""
    emitente_uf: str = ""
    emitente_endereco: Dict[str, Any] = {}
    # Dados do destinatário
    destinatario_cnpj: str
    destinatario_nome: str
    destinatario_ie: str = ""
    destinatario_uf: str = ""
    destinatario_endereco: Dict[str, Any] = {}
    # Valores
    valor_total: float
    valor_servicos: float = 0.0
    # Totais extras (IPI, ST, frete, etc)
    total_produtos: float = 0.0  # vProd - soma dos valores dos produtos
    total_ipi: float = 0.0
    total_icms_st: float = 0.0
    total_fcp_st: float = 0.0  # FCP-ST (Fundo de Combate à Pobreza sobre ST)
    total_frete: float = 0.0
    total_seguro: float = 0.0
    total_outras_despesas: float = 0.0
    total_desconto: float = 0.0
    # Conteúdo e itens
    xml_content: str = ""  # Pode não existir em documentos antigos
    produtos: List[Dict[str, Any]] = []
    servicos: List[Dict[str, Any]] = []
    status_validacao: str = "pendente"
    uploaded_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))
    uploaded_by: str = ""
    # Campos de cancelamento
    cancelada: bool = False
    cStat_cancelamento: str = ""
    xMotivo_cancelamento: str = ""
    dhRecbto_cancelamento: str = ""
    nProt_cancelamento: str = ""
    # Campos de cancelamento por evento (mantidos por compatibilidade)
    data_cancelamento: str = ""
    justificativa_cancelamento: str = ""
    protocolo_cancelamento: str = ""
    # Campos para notas desconsideradas por devolução de fornecedor
    desconsiderada_devolucao: bool = False
    motivo_desconsideracao: str = ""
    nfe_referenciada: str = ""  # Chave da NF original (quando é uma devolução)
    nfe_vinculada_devolucao: str = ""  # Chave da NF de devolução que causou desconsideração
    
    @model_validator(mode='before')
    @classmethod
    def normalize_fields(cls, data):
        """Normaliza campos com nomes alternativos do banco de dados"""
        if isinstance(data, dict):
            # tipo_operacao -> tipo
            if not data.get('tipo') and data.get('tipo_operacao'):
                data['tipo'] = data['tipo_operacao']
            # chave_acesso -> chave_nfe
            if not data.get('chave_nfe') and data.get('chave_acesso'):
                data['chave_nfe'] = data['chave_acesso']
            # modelo '55' -> 'nfe'
            if data.get('modelo') == '55':
                data['modelo'] = 'nfe'
        return data

