@api_router.get("/auth/users/{user_id}/permissions")
async def get_user_permissions_endpoint(
    user_id: str,
    current_user: User = Depends(get_current_user)
):
    """
    Retorna as permissões efetivas de um usuário específico.
    """
    # Verificar se pode ver permissões
    if not has_permission(current_user.model_dump(), PermissionFlags.USERS_PERMISSIONS):
        if current_user.id != user_id:
            raise HTTPException(status_code=403, detail="Sem permissão para ver permissões de outros usuários")
    
    user = await db.users.find_one({"id": user_id})
    if not user:
        raise HTTPException(status_code=404, detail="Usuário não encontrado")
    
    effective_permissions = get_user_permissions(user)
    role_default = DEFAULT_PERMISSIONS.get(user.get('role', 'operacional'), [])
    
    return {
        "user_id": user_id,
        "user_name": user.get('name'),
        "role": user.get('role'),
        "role_permissions": role_default,
        "custom_permissions": user.get('permissions', []),
        "denied_permissions": user.get('denied_permissions', []),
        "effective_permissions": effective_permissions,
        "has_full_access": "*" in effective_permissions
    }


@api_router.put("/auth/users/{user_id}/permissions")
async def update_user_permissions(
    user_id: str,
    permissions_data: dict,
    current_user: User = Depends(get_current_user)
):
    """
    Atualiza as permissões customizadas de um usuário.
    
    Body:
    {
        "permissions": ["permission.key", ...],      // Permissões adicionais
        "denied_permissions": ["permission.key", ...]  // Permissões negadas
    }
    """
    # Verificar se pode editar permissões
    if not has_permission(current_user.model_dump(), PermissionFlags.USERS_PERMISSIONS):
        raise HTTPException(status_code=403, detail="Sem permissão para gerenciar permissões")
    
    user = await db.users.find_one({"id": user_id})
    if not user:
        raise HTTPException(status_code=404, detail="Usuário não encontrado")
    
    # Não pode editar permissões de super_admin (exceto se for super_admin)
    if user.get('role') == 'super_admin' and current_user.role != 'super_admin':
        raise HTTPException(status_code=403, detail="Apenas Super Admin pode editar permissões de Super Admin")
    
    update_fields = {}
    
    if 'permissions' in permissions_data:
        update_fields['permissions'] = permissions_data['permissions']
    
    if 'denied_permissions' in permissions_data:
        update_fields['denied_permissions'] = permissions_data['denied_permissions']
    
    if update_fields:
        await db.users.update_one(
            {"id": user_id},
            {"$set": update_fields}
        )
        
        # Registrar no audit log
        await db.audit_log.insert_one({
            "id": str(uuid.uuid4()),
            "action": "permissions_updated",
            "entity_type": "user",
            "entity_id": user_id,
            "user_id": current_user.id,
            "user_name": current_user.name,
            "details": {
                "permissions_added": permissions_data.get('permissions', []),
                "permissions_denied": permissions_data.get('denied_permissions', [])
            },
            "timestamp": datetime.now(timezone.utc)
        })
    
    # Buscar usuário atualizado
    updated_user = await db.users.find_one({"id": user_id})
    effective = get_user_permissions(updated_user)
    
    return {
        "success": True,
        "message": f"Permissões de {user.get('name')} atualizadas",
        "effective_permissions": effective
    }


@api_router.post("/auth/users/{user_id}/permissions/toggle")
async def toggle_user_permission(
    user_id: str,
    toggle_data: dict,
    current_user: User = Depends(get_current_user)
):
    """
    Liga/desliga uma permissão específica para um usuário.
    
    Body:
    {
        "permission": "permission.key",
        "enabled": true/false
    }
    """
    if not has_permission(current_user.model_dump(), PermissionFlags.USERS_PERMISSIONS):
        raise HTTPException(status_code=403, detail="Sem permissão para gerenciar permissões")
    
    permission_key = toggle_data.get('permission')
    enabled = toggle_data.get('enabled', True)
    
    if not permission_key:
        raise HTTPException(status_code=400, detail="Permissão não especificada")
    
    user = await db.users.find_one({"id": user_id})
    if not user:
        raise HTTPException(status_code=404, detail="Usuário não encontrado")
    
    current_permissions = set(user.get('permissions', []))
    current_denied = set(user.get('denied_permissions', []))
    role_default = set(DEFAULT_PERMISSIONS.get(user.get('role', 'operacional'), []))
    
    if enabled:
        # Adicionar permissão
        if permission_key in role_default:
            # Se já é padrão do role, apenas remover da lista de negados
            current_denied.discard(permission_key)
        else:
            # Adicionar como permissão customizada
            current_permissions.add(permission_key)
            current_denied.discard(permission_key)
    else:
        # Remover/negar permissão
        if permission_key in role_default:
            # Se é padrão do role, adicionar à lista de negados
            current_denied.add(permission_key)
        else:
            # Apenas remover da lista de permissões customizadas
            current_permissions.discard(permission_key)
    
    await db.users.update_one(
        {"id": user_id},
        {"$set": {
            "permissions": list(current_permissions),
            "denied_permissions": list(current_denied)
        }}
    )
    
    # Registrar no audit log
    await db.audit_log.insert_one({
        "id": str(uuid.uuid4()),
        "action": "permission_toggled",
        "entity_type": "user",
        "entity_id": user_id,
        "user_id": current_user.id,
        "user_name": current_user.name,
        "details": {
            "permission": permission_key,
            "enabled": enabled
        },
        "timestamp": datetime.now(timezone.utc)
    })
    
    updated_user = await db.users.find_one({"id": user_id})
    effective = get_user_permissions(updated_user)
    
    return {
        "success": True,
        "permission": permission_key,
        "enabled": enabled,
        "effective_permissions": effective
    }


@api_router.post("/auth/users/cleanup-inactive")
async def cleanup_inactive_users(
    current_user: User = Depends(get_current_user)
):
    """
    Delete all inactive and test users (excluding admins).
    Only Admin can do this.
    """
    if current_user.role not in ["super_admin", "admin"]:
        raise HTTPException(status_code=403, detail="Apenas Admin pode fazer limpeza de usuários")
    
    # Critérios para exclusão:
    # 1. Usuários inativos (is_active = false)
    # 2. Emails contendo 'test' ou '@test'
    # 3. Não ser admin, super_admin ou o próprio usuário logado
    
    protected_roles = ["super_admin", "admin"]
    
    # Buscar usuários para excluir
    users_to_delete = await db.users.find({
        "$and": [
            {"id": {"$ne": current_user.id}},
            {"role": {"$nin": protected_roles}},
            {"$or": [
                {"is_active": False},
                {"email": {"$regex": "test", "$options": "i"}}
            ]}
        ]
    }).to_list(1000)
    
    deleted_count = 0
    deleted_names = []
    
    for user in users_to_delete:
        result = await db.users.delete_one({"id": user["id"]})
        if result.deleted_count > 0:
            deleted_count += 1
            deleted_names.append(user.get("name", user.get("email")))
    
    return {
        "status": "ok",
        "deleted_count": deleted_count,
        "deleted_users": deleted_names,
        "message": f"{deleted_count} usuário(s) excluído(s) permanentemente"
    }


@api_router.post("/companies/{company_id}/responsaveis")
async def add_responsavel_to_company(
    company_id: str,
    data: dict,
    current_user: User = Depends(get_current_user)
):
    """
    Add a user as responsible for a company.
    Only Master or Admin can do this.
    """
    check_master_or_admin(current_user)
    
    user_id = data.get("user_id")
    if not user_id:
        raise HTTPException(status_code=400, detail="user_id é obrigatório")
    
    company = await db.companies.find_one({"id": company_id})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    user = await db.users.find_one({"id": user_id})
    if not user:
        raise HTTPException(status_code=404, detail="Usuário não encontrado")
    
    # Adicionar usuário aos responsáveis da empresa
    await db.companies.update_one(
        {"id": company_id},
        {"$addToSet": {"responsavel_ids": user_id}}
    )
    
    # Adicionar CNPJ da empresa aos company_ids do usuário
    await db.users.update_one(
        {"id": user_id},
        {"$addToSet": {"company_ids": company.get("cnpj")}}
    )
    
    return {"status": "ok", "message": f"Usuário {user['name']} adicionado como responsável"}


@api_router.delete("/companies/{company_id}/responsaveis/{user_id}")
async def remove_responsavel_from_company(
    company_id: str,
    user_id: str,
    current_user: User = Depends(get_current_user)
):
    """
    Remove a user from company responsáveis.
    Only Master or Admin can do this.
    """
    check_master_or_admin(current_user)
    
    company = await db.companies.find_one({"id": company_id})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    # Remover usuário dos responsáveis da empresa
    await db.companies.update_one(
        {"id": company_id},
        {"$pull": {"responsavel_ids": user_id}}
    )
    
    # Remover CNPJ da empresa dos company_ids do usuário
    await db.users.update_one(
        {"id": user_id},
        {"$pull": {"company_ids": company.get("cnpj")}}
    )
    
    return {"status": "ok", "message": "Responsável removido com sucesso"}


@api_router.delete("/companies/{company_id}")
async def delete_company(company_id: str, current_user: User = Depends(get_current_user)):
    allowed_roles = ["super_admin", "master", "admin"]
    if current_user.role not in allowed_roles:
        raise HTTPException(status_code=403, detail="Apenas administradores podem excluir empresas")
    
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    # Excluir documentos vinculados primeiro (Cascade Delete)
    docs_count = await db.xml_documents.count_documents({"company_id": company_id})
    if docs_count > 0:
        await db.xml_documents.delete_many({"company_id": company_id})
        # Também apagar regras aprendidas
        await db.learned_rules.delete_many({"company_id": company_id})
    
    await db.companies.delete_one({"id": company_id})
    return {"message": f"Empresa e {docs_count} documento(s) excluídos com sucesso"}

@api_router.post("/companies", response_model=Company)
async def create_company(company_data: CompanyCreate, current_user: User = Depends(get_current_user)):
    # Admin, master e operacional podem criar empresas
    # Operacional só verá as empresas que ele criou
    allowed_roles = ["super_admin", "master", "admin", "operacional"]
    if current_user.role not in allowed_roles:
        raise HTTPException(status_code=403, detail="Você não tem permissão para criar empresas")
    
    # Verificar se CNPJ já existe
    existing = await db.companies.find_one({"cnpj": company_data.cnpj}, {"_id": 0})
    if existing:
        raise HTTPException(status_code=400, detail="CNPJ já cadastrado")
    
    company = Company(**company_data.model_dump())
    company.created_by = current_user.id  # Definir quem criou a empresa
    doc = company.model_dump()
    doc['created_at'] = doc['created_at'].isoformat()
    
    await db.companies.insert_one(doc)
    return company


class GerarKeywordsRequest(BaseModel):
    descricao: str
    tipo_atividade: str = "comercio"


@api_router.post("/companies/gerar-keywords-ia")
async def gerar_keywords_com_ia(request: GerarKeywordsRequest, current_user: User = Depends(get_current_user)):
    """
    Usa IA para analisar a descrição do negócio e gerar palavras-chave
    para classificação de produtos (revenda, insumo, despesa, etc.)
    """
    try:
        prompt = f"""Analise a descrição do negócio abaixo e gere palavras-chave para classificação de produtos fiscais.

DESCRIÇÃO DO NEGÓCIO:
{request.descricao}

TIPO DE ATIVIDADE: {request.tipo_atividade}

Responda APENAS em formato JSON válido com as seguintes categorias:
{{
  "produtos_comercializados": ["lista de produtos que a empresa REVENDE ou COMERCIALIZA"],
  "insumos_producao": ["lista de insumos/matérias-primas usados na PRODUÇÃO/INDUSTRIALIZAÇÃO"],
  "produtos_despesa": ["lista de produtos de USO E CONSUMO (limpeza, escritório, manutenção)"],
  "produtos_aplicacao_servico": ["lista de materiais APLICADOS em serviços prestados"]
}}

REGRAS:
1. Use termos genéricos e palavras-chave que aparecem em descrições de notas fiscais
2. Para produtos_comercializados: foque nos produtos que a empresa VENDE
3. Para insumos_producao: foque em matérias-primas que ENTRAM na produção
4. Para produtos_despesa: use termos como "papel", "limpeza", "escritório", "manutenção"
5. Para produtos_aplicacao_servico: só preencha se for empresa de SERVIÇOS
6. Cada lista deve ter entre 3 e 10 itens relevantes
7. Use letras minúsculas
8. Não repita itens entre categorias

Responda APENAS o JSON, sem explicações."""

        from emergentintegrations.llm.chat import LlmChat, UserMessage
        
        EMERGENT_API_KEY = os.environ.get("EMERGENT_LLM_KEY", "sk-emergent-bE6955669B918F9301")
        
        chat = LlmChat(
            api_key=EMERGENT_API_KEY,
            session_id=f"keywords-{current_user.id}",
            system_message="Você é um especialista em classificação fiscal de produtos. Responda sempre em JSON válido."
        ).with_model("gemini", "gemini-2.5-flash")
        
        response = await chat.send_message(UserMessage(text=prompt))
        
        # Extrair texto da resposta
        response_text = response if isinstance(response, str) else str(response)
        response_text = response_text.strip()
        
        # Limpar markdown se presente
        if response_text.startswith("```"):
            lines = response_text.split("\n")
            json_lines = []
            in_json = False
            for line in lines:
                if line.startswith("```json"):
                    in_json = True
                    continue
                elif line.startswith("```"):
                    in_json = False
                    continue
                if in_json:
                    json_lines.append(line)
            response_text = "\n".join(json_lines)
        
        keywords = json.loads(response_text)
        
        # Garantir que todas as chaves existam
        result = {
            "produtos_comercializados": keywords.get("produtos_comercializados", []),
            "insumos_producao": keywords.get("insumos_producao", []),
            "produtos_despesa": keywords.get("produtos_despesa", []),
            "produtos_aplicacao_servico": keywords.get("produtos_aplicacao_servico", [])
        }
        
        return result
        
    except json.JSONDecodeError as e:
        logger.error(f"Erro ao parsear JSON da IA: {e}")
        raise HTTPException(status_code=500, detail="Erro ao processar resposta da IA")
    except Exception as e:
        logger.error(f"Erro ao gerar keywords: {e}")
        raise HTTPException(status_code=500, detail=f"Erro ao gerar palavras-chave: {str(e)}")

@api_router.get("/companies", response_model=List[Company])
async def list_companies(
    current_user: User = Depends(get_current_user),
    responsavel_id: Optional[str] = Query(None, description="Filtrar por ID do usuário responsável")
):
    """
    List companies based on user role:
    - Admin/Master: all companies (can filter by responsavel_id)
    - Operacional: only companies where user is responsible OR companies they created OR in company_ids
    """
    allowed_roles = ["super_admin", "master", "admin"]
    
    if current_user.role in allowed_roles:
        # Admin pode ver todas, mas pode filtrar por responsável
        query = {}
        if responsavel_id:
            query["responsavel_ids"] = responsavel_id
        companies = await db.companies.find(query, {"_id": 0}).to_list(1000)
    else:
        # Operacional só vê empresas onde é responsável OU que ele criou OU está em company_ids
        user_company_ids = current_user.company_ids or []
        companies = await db.companies.find(
            {"$or": [
                {"responsavel_ids": current_user.id},
                {"created_by": current_user.id},
                {"cnpj": {"$in": user_company_ids}},
                {"id": {"$in": user_company_ids}}  # Também verificar por ID
            ]}, 
            {"_id": 0}
        ).to_list(1000)
    
    for c in companies:
        if 'created_at' in c:
            if isinstance(c['created_at'], str):
                c['created_at'] = datetime.fromisoformat(c['created_at'])
        else:
            c['created_at'] = datetime.now(timezone.utc) # Fallback for old records
    
    return companies

