# Upload de logo da empresa
@api_router.post("/upload/logo/{company_id}")
async def upload_company_logo(
    company_id: str,
    file: UploadFile = File(...),
    current_user: User = Depends(get_current_user)
):
    """
    Upload de logo da empresa. Retorna URL da imagem e salva na empresa.
    Aceita PNG, JPG, JPEG, WEBP. Máximo 2MB.
    """
    # Verificar acesso à empresa
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Validar tipo de arquivo
    allowed_types = ['image/png', 'image/jpeg', 'image/jpg', 'image/webp']
    if file.content_type not in allowed_types:
        raise HTTPException(status_code=400, detail="Tipo de arquivo não permitido. Use PNG, JPG ou WEBP.")
    
    # Ler conteúdo
    content = await file.read()
    
    # Validar tamanho (max 2MB)
    if len(content) > 2 * 1024 * 1024:
        raise HTTPException(status_code=400, detail="Arquivo muito grande. Máximo 2MB.")
    
    # Gerar nome único
    import hashlib
    file_hash = hashlib.md5(content).hexdigest()[:12]
    extension = file.filename.split('.')[-1].lower()
    filename = f"logo_{file_hash}.{extension}"
    
    # Converter para base64 para armazenar no banco
    import base64
    base64_content = base64.b64encode(content).decode('utf-8')
    
    # Retornar como data URL
    data_url = f"data:{file.content_type};base64,{base64_content}"
    
    # Salvar na empresa
    await db.companies.update_one(
        {"id": company_id},
        {"$set": {"logo_url": data_url}}
    )
    
    return {"url": data_url, "filename": filename, "company_id": company_id}


# Upload de logo da empresa (endpoint legado sem company_id)
@api_router.post("/upload/logo")
async def upload_company_logo_legacy(
    file: UploadFile = File(...),
    current_user: User = Depends(get_current_user)
):
    """
    Upload de logo da empresa (legado). Retorna URL da imagem.
    Aceita PNG, JPG, JPEG, WEBP. Máximo 2MB.
    """
    # Validar tipo de arquivo
    allowed_types = ['image/png', 'image/jpeg', 'image/jpg', 'image/webp']
    if file.content_type not in allowed_types:
        raise HTTPException(status_code=400, detail="Tipo de arquivo não permitido. Use PNG, JPG ou WEBP.")
    
    # Ler conteúdo
    content = await file.read()
    
    # Validar tamanho (max 2MB)
    if len(content) > 2 * 1024 * 1024:
        raise HTTPException(status_code=400, detail="Arquivo muito grande. Máximo 2MB.")
    
    # Gerar nome único
    import hashlib
    file_hash = hashlib.md5(content).hexdigest()[:12]
    extension = file.filename.split('.')[-1].lower()
    filename = f"logo_{file_hash}.{extension}"
    
    # Converter para base64 para armazenar no banco ou servir diretamente
    import base64
    base64_content = base64.b64encode(content).decode('utf-8')
    
    # Retornar como data URL
    data_url = f"data:{file.content_type};base64,{base64_content}"
    
    return {"url": data_url, "filename": filename}


@api_router.post("/xml/upload")
async def upload_xml_batch(
    company_id: str = Form(...),
    competencia: str = Form(...),
    tipo: str = Form(...),
    files: List[UploadFile] = File(...),
    current_user: User = Depends(get_current_user)
):
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Extrair CNPJ da empresa selecionada (limpar formatação)
    cnpj_empresa = company.get('cnpj', '').replace('.', '').replace('/', '').replace('-', '')
    uf_empresa = company.get('uf', 'SP')
    regime_tributario = company.get('regime_tributario', 'lucro_presumido')
    
    results = []
    errors = []
    conversion_report = []
    duplicadas = []
    rejeitadas_cnpj = []
    rejeitadas_competencia = []
    alertas_cfop = []  # Alertas de CFOPs de operações distintas
    notas_devolucao_fornecedor = []  # Notas desconsideradas por devolução do fornecedor
    notas_canceladas = []  # Notas canceladas detectadas durante a importação
    
    # Estatísticas de performance do cache
    total_stats = {"from_cache": 0, "from_rules": 0, "from_ai": 0, "total": 0}
    
    # CFOPs de operações distintas que precisam de alerta
    CFOPS_OPERACOES_DISTINTAS_UPLOAD = {
        '5910': 'Remessa em bonificação',
        '5911': 'Remessa de amostra grátis',
        '5912': 'Remessa de mercadoria para demonstração',
        '5913': 'Retorno de mercadoria para demonstração',
        '5914': 'Remessa de mercadoria para exposição/feira',
        '5915': 'Remessa de mercadoria para consignação',
        '5916': 'Retorno de mercadoria de consignação',
        '5917': 'Remessa de mercadoria em consignação simbólica',
        '5918': 'Devolução de mercadoria de consignação simbólica',
        '5919': 'Devolução simbólica por venda em consignação',
        '5920': 'Remessa de vasilhame/sacaria',
        '5921': 'Devolução de vasilhame/sacaria',
        '5922': 'Lançamento para simples faturamento',
        '5923': 'Remessa de mercadoria por conta e ordem',
        '5924': 'Remessa para industrialização por conta e ordem',
        '5925': 'Retorno de mercadoria de depósito',
        '5949': 'Outra saída não especificada',
        '5201': 'Devolução de compra - indústria',
        '5202': 'Devolução de compra - comercialização',
        '5208': 'Devolução de mercadoria em transferência',
        '5209': 'Devolução de mercadoria para uso/consumo',
        '5210': 'Devolução de compra para industrialização',
        '5122': 'Venda com entrega futura',
        '5123': 'Venda de mercadoria em consignação mercantil',
        '6910': 'Remessa em bonificação (interestadual)',
        '6911': 'Remessa de amostra grátis (interestadual)',
        '6912': 'Remessa para demonstração (interestadual)',
        '6949': 'Outra saída não especificada (interestadual)',
        '6201': 'Devolução de compra - indústria (interestadual)',
        '6202': 'Devolução de compra - comercialização (interestadual)',
        '6122': 'Venda com entrega futura (interestadual)',
    }
    
    # ===== PRÉ-CARREGAR CACHE DE VENDAS (uma vez só, antes do loop) =====
    sales_cache = {"company_id": company_id}
    if tipo == 'entrada':
        try:
            saidas_cursor = db.xml_documents.find({
                "company_id": company_id,
                "tipo": "saida",
                **get_filtro_notas_ativas()
            }, {"produtos.descricao": 1, "produtos.ncm": 1, "_id": 0}).limit(200)
            
            saidas = await saidas_cursor.to_list(length=200)
            ncms_vendidos = set()
            palavras_produtos_vendidos = set()
            produtos_vendidos = set()
            
            for doc in saidas:
                for prod in doc.get('produtos', []):
                    desc = prod.get('descricao', '')
                    ncm = prod.get('ncm', '')
                    
                    if ncm and len(ncm) >= 4:
                        ncms_vendidos.add(ncm[:4])
                        ncms_vendidos.add(ncm[:6])
                    
                    if desc and len(desc) > 5:
                        palavras = [p.upper() for p in desc.split() if len(p) > 3 and p.upper() not in ['PARA', 'COM', 'SEM', 'UNID', 'PEÇA', 'PECA', 'CADA', 'CAIXA']]
                        for palavra in palavras[:3]:
                            palavras_produtos_vendidos.add(palavra)
                        if palavras:
                            produtos_vendidos.add(' '.join(palavras[:2]))
            
            sales_cache["ncms_vendidos"] = ncms_vendidos
            sales_cache["palavras_produtos_vendidos"] = palavras_produtos_vendidos
            sales_cache["produtos_vendidos_list"] = list(produtos_vendidos)[:50]
            
            logger.info(f"UPLOAD-BATCH: Cache de vendas carregado - {len(ncms_vendidos)} NCMs")
        except Exception as e:
            logger.warning(f"UPLOAD-BATCH: Erro ao carregar cache de vendas: {e}")
            sales_cache = None
    else:
        sales_cache = None  # Não precisa para saídas
    
    for file in files:
        try:
            content = await file.read()
            xml_str = content.decode('utf-8')
            
            # Detectar tipo de XML automaticamente
            xml_type = detect_xml_type(xml_str)
            
            # Verificar se é uma lista de NFS-e (múltiplas notas em um único arquivo)
            if is_lista_nfse(xml_str):
                # Processar lista de NFS-e
                lista_nfse = parse_xml_lista_nfse(xml_str)
                print(f"Arquivo com {len(lista_nfse)} NFS-e detectado")
                
                for idx, parsed_data in enumerate(lista_nfse):
                    try:
                        # Processar cada NFS-e individualmente
                        chave_nfe = parsed_data['chave_nfe']
                        modelo = parsed_data.get('modelo', 'nfse')
                        
                        # VALIDAR CNPJ
                        cnpj_emitente = parsed_data.get('emitente_cnpj', '').replace('.', '').replace('/', '').replace('-', '')
                        cnpj_destinatario = parsed_data.get('destinatario_cnpj', '').replace('.', '').replace('/', '').replace('-', '')
                        
                        # Para NFS-e Prestados, a empresa é o PRESTADOR (emitente)
                        # Para NFS-e Tomados, a empresa é o TOMADOR (destinatário)
                        cnpj_valido = False
                        if tipo == 'saida':  # NFS-e Prestados
                            cnpj_valido = cnpj_emitente == cnpj_empresa
                        else:  # NFS-e Tomados
                            cnpj_valido = cnpj_destinatario == cnpj_empresa
                        
                        if not cnpj_valido:
                            rejeitadas_cnpj.append({
                                "arquivo": f"{file.filename} (nota {idx + 1})",
                                "numero": parsed_data.get('numero_nfe', ''),
                                "cnpj_encontrado": cnpj_emitente if tipo == 'saida' else cnpj_destinatario,
                                "cnpj_esperado": cnpj_empresa
                            })
                            continue
                        
                        # Verificar duplicidade
                        existing = await db.xml_documents.find_one({
                            "chave_nfe": chave_nfe,
                            "company_id": company_id
                        })
                        
                        if existing:
                            duplicadas.append({
                                "arquivo": f"{file.filename} (nota {idx + 1})",
                                "numero": parsed_data.get('numero_nfe', ''),
                                "chave": chave_nfe
                            })
                            continue
                        
                        # Extrair competência da NFS-e
                        competencia_nfse = parsed_data.get('competencia_nfse', '')
                        if competencia_nfse:
                            try:
                                # Formato: 2026-01-01T00:00:00
                                comp_date = competencia_nfse.split('T')[0]
                                ano, mes, _ = comp_date.split('-')
                                competencia_doc = f"{mes}/{ano}"
                            except:
                                competencia_doc = competencia
                        else:
                            competencia_doc = competencia
                        
                        # Preparar documento
                        document = {
                            "id": str(uuid.uuid4()),
                            "company_id": company_id,
                            "chave_nfe": chave_nfe,
                            "numero_nfe": parsed_data.get('numero_nfe', ''),
                            "serie": parsed_data.get('serie', '1'),
                            "modelo": modelo,
                            "data_emissao": parsed_data.get('data_emissao', ''),
                            "data_saida_entrada": parsed_data.get('data_saida_entrada', ''),  # dhSaiEnt - usado para competência de entradas
                            "valor_total": parsed_data.get('valor_total', 0),
                            "valor_servicos": parsed_data.get('valor_servicos', 0),
                            "emitente_cnpj": cnpj_emitente,
                            "emitente_nome": parsed_data.get('emitente_nome', ''),
                            "emitente_ie": parsed_data.get('emitente_ie', ''),
                            "emitente_uf": parsed_data.get('emitente_uf', ''),
                            "emitente_endereco": parsed_data.get('emitente_endereco', {}),
                            "destinatario_cnpj": cnpj_destinatario,
                            "destinatario_nome": parsed_data.get('destinatario_nome', ''),
                            "destinatario_ie": parsed_data.get('destinatario_ie', ''),
                            "destinatario_uf": parsed_data.get('destinatario_uf', ''),
                            "destinatario_endereco": parsed_data.get('destinatario_endereco', {}),
                            "produtos": parsed_data.get('produtos', []),
                            "servicos": parsed_data.get('servicos', []),
                            "tipo": tipo,
                            "tipo_operacao": "prestado" if tipo == "saida" else "tomado",
                            "competencia": competencia_doc,
                            "imported_at": datetime.now(timezone.utc).isoformat(),
                            "status": "active"
                        }
                        
                        await db.xml_documents.insert_one(document)
                        results.append({
                            "arquivo": f"{file.filename} (nota {idx + 1})",
                            "numero": parsed_data.get('numero_nfe', ''),
                            "tipo": tipo,
                            "valor": parsed_data.get('valor_total', 0),
                            "modelo": modelo,
                            "competencia": competencia_doc
                        })
                        
                    except Exception as e:
                        errors.append({
                            "arquivo": f"{file.filename} (nota {idx + 1})",
                            "erro": str(e)
                        })
                
                # Pular o resto do loop para este arquivo (já processamos todas as NFS-e)
                continue
            
            # Parser apropriado para cada tipo (arquivo único)
            if xml_type == 'nfse':
                parsed_data = parse_xml_nfse(xml_str)
            elif xml_type == 'nfce':
                parsed_data = parse_xml_nfce(xml_str)
            else:
                parsed_data = parse_xml_nfe(xml_str)
            
            chave_nfe = parsed_data['chave_nfe']
            modelo = parsed_data.get('modelo', xml_type)
            
            # VALIDAR CNPJ - Verificar se a NF-e pertence à empresa selecionada
            # Para ENTRADA: o destinatário deve ser a empresa
            # Para SAÍDA: o emitente deve ser a empresa
            # Para NFC-e (modelo 65): emitente deve ser a empresa (NFC-e é sempre saída, consumidor final)
            cnpj_emitente = parsed_data.get('emitente_cnpj', '').replace('.', '').replace('/', '').replace('-', '')
            cnpj_destinatario = parsed_data.get('destinatario_cnpj', '').replace('.', '').replace('/', '').replace('-', '')
            
            # ================================================================
            # CLASSIFICAÇÃO AUTOMÁTICA DE TIPO (entrada/saída)
            # Regra de negócio definitiva:
            # - Se CNPJ emitente == CNPJ empresa -> SAÍDA (empresa emitiu)
            # - Se CNPJ emitente != CNPJ empresa -> ENTRADA (empresa recebeu)
            # ================================================================
            tipo_calculado = 'saida' if cnpj_emitente == cnpj_empresa else 'entrada'
            tipo = tipo_calculado  # Sobrescreve o tipo enviado pelo formulário
            
            logger.info(f"CLASSIFICAÇÃO AUTO: NF {parsed_data.get('numero_nfe', '')} - CNPJ emit={cnpj_emitente}, CNPJ empresa={cnpj_empresa} -> {tipo}")
            
            cnpj_valido = True  # Validação já é feita implicitamente pela classificação
            
            # ==== TRATAMENTO ESPECIAL PARA NFC-e (MODELO 65) ====
            # NFC-e é sempre venda para consumidor final, então:
            # - Emitente deve ser a empresa (pela classificação automática, já seria saída)
            # - Se a classificação automática resultou em 'entrada', significa que o emitente NÃO é a empresa, então rejeitamos
            if modelo in ['nfce', 'NFCE', 'NFC-e', '65']:
                if tipo == 'entrada':
                    # NFC-e não pode ser entrada (emitente não é a empresa)
                    rejeitadas_cnpj.append({
                        "filename": file.filename,
                        "numero_nfe": parsed_data.get('numero_nfe', ''),
                        "motivo": f"NFC-e (cupom fiscal) só pode ser importada se a empresa for o emitente. CNPJ do emitente ({cnpj_emitente}) difere da empresa ({cnpj_empresa})",
                        "emitente": parsed_data.get('emitente_razao_social', parsed_data.get('emitente_nome', '')),
                        "destinatario": "Consumidor Final"
                    })
                    continue
                
                # NFC-e validada - pular para processamento (não precisa das validações de NF-e)
                is_devolucao_fornecedor = False
                motivo_devolucao = ""
                nfe_ref_devolucao = ""
            else:
                # ==== PROCESSAMENTO NORMAL PARA NF-e (MODELO 55) ====
                # Com a classificação automática baseada no CNPJ do emitente:
                # - tipo='saida' significa que a empresa é o emitente
                # - tipo='entrada' significa que a empresa NÃO é o emitente (recebeu de terceiro)
                
                is_devolucao_fornecedor = False
                motivo_devolucao = ""
                nfe_ref_devolucao = ""
                is_emissao_propria_entrada = False  # Não aplicável mais com classificação automática
                
                # ==== DETECTAR DEVOLUÇÃO DO FORNECEDOR (apenas para entradas) ====
                # IMPORTANTE: Desconsiderar APENAS quando:
                # 1. Emitente é TERCEIRO (fornecedor) - tipo='entrada'
                # 2. CFOP no XML já é de ENTRADA (1xxx/2xxx)
                # 3. CFOP é de devolução de entrada (1411, 2411, 1201, 2201, etc.)
                nfe_ref_devolucao = ""
                
                # Extrair dados para análise
                finalidade_nfe = parsed_data.get('finalidade_nfe', '1')
                natureza_operacao = parsed_data.get('natureza_operacao', '').upper()
                cfops_xml = [str(p.get('cfop', '')) for p in parsed_data.get('produtos', [])]
                nfe_ref_devolucao = parsed_data.get('nfe_referenciada', '') or ''
                
                # Usar a lista global de CFOPs de devolução para garantir consistência
                cfops_devolucao_entrada = CFOPS_DEVOLUCAO_TERCEIROS_GLOBAL
                
                # Verificar se emitente é diferente da empresa (fornecedor emitiu a nota)
                if cnpj_emitente != cnpj_empresa:
                    # Verificar se TODOS os CFOPs já são de ENTRADA (1xxx, 2xxx, 3xxx)
                    # Se tiver CFOP de saída (5xxx, 6xxx), NÃO é devolução do fornecedor a desconsiderar
                    cfops_sao_entrada = all(
                        cfop and len(cfop) >= 1 and cfop[0] in ['1', '2', '3'] 
                        for cfop in cfops_xml if cfop
                    )
                    
                    # Verificar se os CFOPs são especificamente de devolução de entrada
                    is_devolucao_por_cfop = any(cfop in cfops_devolucao_entrada for cfop in cfops_xml)
                    
                    logger.info(f"DEBUG DEVOLUÇÃO: NF {parsed_data.get('numero_nfe')} - CFOPs: {cfops_xml}, São entrada: {cfops_sao_entrada}, É devolução: {is_devolucao_por_cfop}")
                    
                    # SOMENTE desconsiderar se:
                    # - CFOPs já são de entrada (não são CFOPs de saída que serão convertidos)
                    # - E são CFOPs de devolução de entrada
                    if cfops_sao_entrada and is_devolucao_por_cfop:
                        # CFOPs da lista CFOPS_DEVOLUCAO_TERCEIROS_GLOBAL devem ser desconsiderados
                        # MESMO SEM critérios adicionais (finNFe, NFe ref, natureza)
                        # Isso garante consistência com a importação em lote
                        
                        cfops_unicos = list(set(cfops_xml))[:3]
                        is_devolucao_por_finalidade = str(finalidade_nfe) == '4'
                        is_devolucao_por_natureza = any(termo in natureza_operacao for termo in ['DEVOLUC', 'DEV ', 'DEVOL'])
                        tem_nfe_referenciada = bool(nfe_ref_devolucao and len(nfe_ref_devolucao) > 10)
                        
                        logger.info(f"DEBUG DEVOLUÇÃO: finNFe: {finalidade_nfe}, natOp: {natureza_operacao}, Tem NFe Ref: {tem_nfe_referenciada}")
                        
                        # IMPORTANTE: CFOPs na lista global SEMPRE são desconsiderados
                        # Critérios adicionais são apenas para log/documentação
                        logger.info(f"DEBUG DEVOLUÇÃO: DETECTADA! CFOPs únicos: {cfops_unicos}, NFe Ref: {nfe_ref_devolucao}")
                        
                        # Marcar como devolução do fornecedor (será processada mas desconsiderada)
                        is_devolucao_fornecedor = True
                        motivo_devolucao = f"NF de terceiro com CFOP de devolução/bonificação ({parsed_data.get('emitente_nome', '')[:40]}) - CFOP: {', '.join(cfops_unicos)}"
                        
                        # Registrar para o relatório de retorno
                        notas_devolucao_fornecedor.append({
                            "tipo": "devolucao_entrada",
                            "filename": file.filename,
                            "chave_nfe": chave_nfe,
                            "numero_nfe": parsed_data.get('numero_nfe', ''),
                            "data_emissao": parsed_data.get('data_emissao', ''),
                            "valor_total": parsed_data.get('valor_total', 0),
                            "cfops": cfops_unicos,
                            "emitente_cnpj": cnpj_emitente,
                            "emitente_nome": parsed_data.get('emitente_nome', ''),
                            "nfe_referenciada": nfe_ref_devolucao,
                            "motivo": motivo_devolucao
                        })
                    else:
                        # CFOP de saída ou misto - processar normalmente (será convertido)
                        logger.info(f"DEBUG: NF {parsed_data.get('numero_nfe')} - CFOP saída/misto, processando como entrada normal")
            
            # CALCULAR COMPETÊNCIA DO DOCUMENTO
            # Para ENTRADAS (compras): usar data_saida_entrada (dhSaiEnt) quando disponível
            #   - dhSaiEnt representa quando o fornecedor DESPACHOU a mercadoria
            #   - É a data correta para competência de entradas
            # Para SAÍDAS (vendas da própria empresa): usar data_emissao (dhEmi)
            data_emissao = parsed_data.get('data_emissao', '')
            data_saida_entrada = parsed_data.get('data_saida_entrada', '')
            
            # Detectar se é NF de emissão própria (vendas da empresa)
            is_emissao_propria = cnpj_emitente == cnpj_empresa
            
            # LOG PARA DEBUG
            logger.info(f"COMPETÊNCIA DEBUG - NF {parsed_data.get('numero_nfe', '')}: tipo={tipo_operacao}, dhEmi={data_emissao[:10] if data_emissao else 'N/A'}, dhSaiEnt={data_saida_entrada[:10] if data_saida_entrada else 'N/A'}, emissao_propria={is_emissao_propria}")
            
            # Determinar qual data usar para a competência
            if tipo_operacao == 'saida' or is_emissao_propria:
                # Para SAÍDAS ou emissão própria, usar data de emissão
                data_para_competencia = data_emissao
                tipo_data = "emissão"
            elif tipo_operacao == 'entrada' and data_saida_entrada:
                # Para ENTRADAS, priorizar data de saída (quando o fornecedor despachou)
                data_para_competencia = data_saida_entrada
                tipo_data = "saída"
            else:
                # Fallback: usar data de emissão
                data_para_competencia = data_emissao
                tipo_data = "emissão"
            
            # Calcular a competência real do documento
            competencia_documento = competencia  # Default: usar a competência selecionada
            if data_para_competencia:
                # data pode ser formato ISO: 2024-01-15T10:30:00-03:00
                try:
                    if 'T' in data_para_competencia:
                        data_competencia_dt = datetime.fromisoformat(data_para_competencia.replace('Z', '+00:00'))
                    else:
                        data_competencia_dt = datetime.strptime(data_para_competencia[:10], '%Y-%m-%d')
                    
                    # Extrair mês/ano para competência
                    mes_nfe = str(data_competencia_dt.month).zfill(2)
                    ano_nfe = str(data_competencia_dt.year)
                    competencia_documento = f"{mes_nfe}/{ano_nfe}"
                    
                    # Informar se a competência calculada é diferente da selecionada
                    if competencia_documento != competencia:
                        # Para entradas com data de saída diferente, usar a competência da data de saída
                        # e adicionar uma observação (não rejeitar)
                        print(f"INFO: Documento {parsed_data.get('numero_nfe', '')} - Competência ajustada de {competencia} para {competencia_documento} (baseada na data de {tipo_data})")
                except Exception as e:
                    # Se não conseguir parsear a data, usar competência selecionada
                    pass
            
            # VERIFICAR DUPLICAÇÃO - usar a competência calculada
            existing_doc = await db.xml_documents.find_one({
                "company_id": company_id,
                "competencia": competencia_documento,
                "chave_nfe": chave_nfe
            }, {"_id": 0})
            
            if existing_doc:
                duplicadas.append({
                    "filename": file.filename,
                    "chave": chave_nfe,
                    "numero_nfe": parsed_data['numero_nfe']
                })
                continue
            
            file_conversions = []
            file_alertas_cfop = []  # Alertas de CFOP para este arquivo
            
            # Mapeamento de CFOPs de saída para entrada (mantendo natureza)
            CFOP_SAIDA_PARA_ENTRADA = {
                # Estadual (5xxx -> 1xxx) - Vendas normais
                '5101': '1101', '5102': '1102', '5103': '1103', '5104': '1104',
                '5105': '1105', '5106': '1106', '5109': '1109', '5110': '1110',
                '5111': '1111', '5112': '1112', '5113': '1113', '5114': '1114',
                '5115': '1115', '5116': '1116', '5117': '1117', '5118': '1118',
                '5119': '1119', '5120': '1120', '5122': '1102', '5123': '1102',
                '5124': '1124', '5125': '1125',
                # Substituição Tributária (5xxx -> 1xxx)
                '5401': '1401', '5402': '1402', '5403': '1403', '5405': '1405',
                '5408': '1408', '5409': '1409', '5410': '1410', '5411': '1411',
                '5412': '1412', '5413': '1413', '5414': '1414', '5415': '1415',
                # Devoluções e Remessas
                '5201': '1201', '5202': '1202', '5208': '1208', '5209': '1209', '5210': '1210',
                '5910': '1910', '5911': '1911', '5912': '1912', '5913': '1913',
                '5914': '1914', '5915': '1915', '5916': '1916', '5917': '1917',
                '5918': '1918', '5919': '1919', '5920': '1920', '5921': '1921',
                '5922': '1922', '5923': '1923', '5924': '1924', '5925': '1925',
                '5949': '1949',
                # Interestadual (6xxx -> 2xxx) - Vendas normais
                '6101': '2101', '6102': '2102', '6103': '2103', '6104': '2104',
                '6105': '2105', '6106': '2106', '6107': '2107', '6108': '2108',
                '6109': '2109', '6110': '2110', '6111': '2111', '6112': '2112',
                '6113': '2113', '6114': '2114', '6115': '2115', '6116': '2116',
                '6117': '2117', '6118': '2118', '6119': '2119', '6120': '2120',
                '6122': '2102', '6123': '2123', '6124': '2124', '6125': '2125',
                # Substituição Tributária (6xxx -> 2xxx)
                '6401': '2401', '6402': '2402', '6403': '2403', '6404': '2404',
                '6408': '2408', '6409': '2409', '6410': '2410', '6411': '2411',
                '6412': '2412', '6413': '2413', '6414': '2414', '6415': '2415',
                # Devoluções e Remessas Interestaduais
                '6201': '2201', '6202': '2202',
                '6910': '2910', '6911': '2911', '6912': '2912', '6913': '2913',
                '6949': '2949',
            }
            
            emitente_uf = parsed_data.get('emitente_uf', '')
            
            # Separar produtos para classificação
            produtos_para_classificar = []
            produtos_operacao_distinta = []
            
            # 1. Primeira passada: Aplicar CST e separar produtos
            for product in parsed_data['produtos']:
                cfop_original = product.get('cfop', '')
                ncm = product.get('ncm', '')
                
                # APLICAR CST CALCULADO DE PIS/COFINS
                cst_info = calcular_cst_pis_cofins(
                    ncm=ncm,
                    cfop=cfop_original,
                    tipo_operacao=tipo,
                    cst_xml=product.get('cst_pis_xml', product.get('cst_pis', '')),
                    regime=regime_tributario
                )
                
                product.update({
                    'cst_pis_calculado': cst_info['cst_calculado'],
                    'cst_cofins_calculado': cst_info['cst_calculado'],
                    'cst_pis': cst_info['cst_calculado'],
                    'cst_cofins': cst_info['cst_calculado'],
                    'cst_divergente': cst_info['divergente'],
                    'cst_motivo': cst_info['motivo'],
                    'ncm_aliq_zero': cst_info['aliq_zero'],
                    'cfop_sem_incidencia': cst_info.get('sem_incidencia', False)
                })

                if tipo == 'entrada':
                    # IMPORTANTE: NÃO converter CFOP de notas de emissão própria
                    # Notas de emissão própria com CFOP de entrada devem preservar o CFOP original
                    if is_emissao_propria_entrada:
                        # Emissão própria: preservar CFOP original, não classificar
                        product['cfop_original_emissor'] = cfop_original
                        product['emissao_propria'] = True
                        logger.info(f"EMISSÃO PRÓPRIA: Preservando CFOP {cfop_original} do produto {product.get('descricao', '')[:30]}")
                    elif is_devolucao_fornecedor:
                        # IMPORTANTE: Notas de terceiros com natureza entrada que serão desconsideradas
                        # NÃO devem ser reclassificadas pela IA - preservar CFOP original
                        product['cfop_original_emissor'] = cfop_original
                        product['preservar_cfop_terceiro'] = True
                        logger.info(f"TERCEIRO ENTRADA: Preservando CFOP {cfop_original} do produto {product.get('descricao', '')[:30]} - será desconsiderado")
                    elif cfop_original in CFOPS_OPERACOES_DISTINTAS_UPLOAD:
                        produtos_operacao_distinta.append((product, cfop_original))
                    else:
                        # IMPORTANTE: Preservar CFOP original do emissor ANTES de classificar
                        # Isso é necessário para detectar corretamente ST (5403, 6403, etc.)
                        product['cfop_original_emissor'] = cfop_original
                        produtos_para_classificar.append(product)
            
            # 2. Processar operações distintas (CFOPs especiais)
            for product, cfop_original in produtos_operacao_distinta:
                cfop_convertido = CFOP_SAIDA_PARA_ENTRADA.get(cfop_original, cfop_original)
                product['cfop_original_emissor'] = cfop_original
                product['cfop'] = cfop_convertido
                product['pendente_revisao_cfop'] = True
                product['natureza_operacao_original'] = CFOPS_OPERACOES_DISTINTAS_UPLOAD[cfop_original]
                
                # Usar a categoria específica baseada no CFOP convertido
                categoria_especifica = obter_categoria_por_cfop(cfop_convertido) or 'operacao_distinta'
                product['categoria_classificada'] = categoria_especifica
                
                file_alertas_cfop.append({
                    'produto': product.get('descricao', ''),
                    'codigo': product.get('codigo', ''),
                    'cfop_emissor': cfop_original,
                    'cfop_convertido': cfop_convertido,
                    'descricao_cfop': CFOPS_OPERACOES_DISTINTAS_UPLOAD[cfop_original],
                    'valor': product.get('valor_total', 0),
                    'acao_tomada': f'Convertido para {cfop_convertido} (pendente revisão)',
                    'categoria': categoria_especifica
                })
                
                file_conversions.append({
                    'produto': product.get('descricao', ''),
                    'codigo': product.get('codigo', ''),
                    'cfop_original': cfop_original,
                    'cfop_convertido': cfop_convertido,
                    'categoria': categoria_especifica,
                    'motivo': f"CFOP {cfop_original} ({CFOPS_OPERACOES_DISTINTAS_UPLOAD[cfop_original]}) → {cfop_convertido}"
                })
            
            # 3. PRÉ-PROCESSAR PRODUTOS COM CFOP DE DEVOLUÇÃO
            # CFOPs de devolução devem ser classificados como "devolucao" ANTES da IA
            produtos_para_ia = []
            for product in produtos_para_classificar:
                cfop_original = product.get('cfop', '')
                categoria_cfop = obter_categoria_por_cfop(cfop_original)
                
                if categoria_cfop == 'devolucao':
                    # CFOP de devolução: classificar diretamente como devolução
                    product['cfop_original'] = cfop_original
                    product['categoria_classificada'] = 'devolucao'
                    product['justificativa_ia'] = f'CFOP {cfop_original} é devolução - classificação automática'
                    product['status_validacao'] = 'validado'
                    
                    file_conversions.append({
                        'produto': product.get('descricao', ''),
                        'codigo': product.get('codigo', ''),
                        'cfop_original': cfop_original,
                        'cfop_convertido': cfop_original,
                        'categoria': 'devolucao',
                        'motivo': f'CFOP {cfop_original} - Devolução (classificação automática)',
                        'origem': 'cfop'
                    })
                    
                    total_stats["from_rules"] += 1
                    total_stats["total"] += 1
                else:
                    # Outros produtos: enviar para classificação IA
                    produtos_para_ia.append(product)
            
            # 4. CLASSIFICAR COM CACHE + IA (OTIMIZADO) - apenas produtos não de devolução
            if produtos_para_ia and tipo == 'entrada':
                classifications, stats = await classify_products_with_cache(
                    produtos_para_ia, 
                    company_id, 
                    company, 
                    emitente_uf,
                    sales_cache  # Usar cache pré-carregado
                )
                
                # Acumular estatísticas
                total_stats["from_cache"] += stats.get("from_cache", 0)
                total_stats["from_rules"] += stats.get("from_rules", 0)
                total_stats["from_ai"] += stats.get("from_ai", 0)
                total_stats["from_sales_inference"] = total_stats.get("from_sales_inference", 0) + stats.get("from_sales_inference", 0)
                total_stats["total"] += stats.get("total", 0)
                
                # Log de performance
                sales_inf = stats.get('from_sales_inference', 0)
                print(f"📊 Classificação: {stats['from_cache']} cache, {stats['from_rules']} regras, {sales_inf} aprendizado, {stats['from_ai']} IA")
                
                # Aplicar classificações
                for idx, product in enumerate(produtos_para_ia):
                    p_id = str(idx)
                    if p_id in classifications:
                        result = classifications[p_id]
                        cfop_original = product.get('cfop', '')
                        cfop_novo = result['cfop']
                        
                        product['cfop_original'] = cfop_original
                        product['cfop'] = cfop_novo
                        product['cfop_sugerido'] = cfop_novo
                        product['categoria_classificada'] = result['categoria']
                        product['justificativa_ia'] = result['justificativa']
                        
                        # Marcar origem da classificação
                        origem = "cache" if "Memorizado" in result['justificativa'] else ("regra" if "cadastrado" in result['justificativa'].lower() else "ia")
                        
                        file_conversions.append({
                            'produto': product.get('descricao', ''),
                            'codigo': product.get('codigo', ''),
                            'cfop_original': cfop_original,
                            'cfop_convertido': cfop_novo,
                            'categoria': result['categoria'],
                            'motivo': result['justificativa'],
                            'origem': origem
                        })
                    else:
                        # FALLBACK: Nenhuma NF de entrada pode ficar sem classificação
                        # Na dúvida, classificar como REVENDA
                        cfop_original = product.get('cfop', '')
                        cst = product.get('cst', '')
                        # IMPORTANTE: Verificar ST tanto pelo CST quanto pelo CFOP original
                        cfops_st_originais = ['5403', '5405', '5408', '5409', '5410', '5411', '5412', '5413', '5414', '5415',
                                              '6403', '6404', '6405', '6408', '6409', '6410', '6411', '6412', '6413', '6414', '6415']
                        is_st_by_cfop = cfop_original in cfops_st_originais
                        is_st = is_st_by_cfop or cst in ['10', '30', '60', '70', '201', '202', '203', '500']
                        cfop_prefix = '2' if (emitente_uf and emitente_uf != uf_empresa) else '1'
                        cfop_novo = (cfop_prefix + '403') if is_st else (cfop_prefix + '102')
                        
                        product['cfop_original'] = cfop_original
                        product['cfop'] = cfop_novo
                        product['cfop_sugerido'] = cfop_novo
                        product['categoria_classificada'] = 'revenda'
                        product['justificativa_ia'] = 'Classificação padrão: REVENDA (produto para comercialização)'
                        
                        file_conversions.append({
                            'produto': product.get('descricao', ''),
                            'codigo': product.get('codigo', ''),
                            'cfop_original': cfop_original,
                            'cfop_convertido': cfop_novo,
                            'categoria': 'revenda',
                            'motivo': 'Classificação padrão (REVENDA)',
                            'origem': 'fallback'
                        })
            
            # Registrar alertas de CFOP para este arquivo
            if file_alertas_cfop:
                alertas_cfop.append({
                    "arquivo": file.filename,
                    "nfe": parsed_data['numero_nfe'],
                    "emitente": parsed_data.get('emitente_nome', ''),
                    "qtd_produtos": len(file_alertas_cfop),
                    "alertas": file_alertas_cfop
                })
            
            xml_doc = XMLDocument(
                company_id=company_id,
                competencia=competencia_documento,  # Usar competência calculada pela data de saída (entradas) ou emissão (saídas)
                tipo=tipo,
                modelo=modelo,
                xml_content=xml_str,
                uploaded_by=current_user.id,
                **{k: v for k, v in parsed_data.items() if k != 'modelo'}
            )
            
            doc = xml_doc.model_dump()
            doc['uploaded_at'] = doc['uploaded_at'].isoformat()
            
            # ==== VERIFICAR SE É DEVOLUÇÃO DO FORNECEDOR ====
            if is_devolucao_fornecedor:
                doc['desconsiderada_devolucao'] = True
                doc['motivo_desconsideracao'] = motivo_devolucao
                doc['nfe_referenciada'] = nfe_ref_devolucao
                doc['status_validacao'] = 'desconsiderada'
            
            # ==== VERIFICAR SE HÁ EVENTO DE CANCELAMENTO PENDENTE ====
            chave_nfe = parsed_data.get('chave_nfe', '')
            if chave_nfe:
                evento_cancelamento = await db.eventos_cancelamento.find_one({"chave_nfe": chave_nfe})
                if evento_cancelamento:
                    # Marcar nota como cancelada
                    doc['cancelada'] = True
                    doc['data_cancelamento'] = evento_cancelamento.get('data_cancelamento', '')
                    doc['justificativa_cancelamento'] = evento_cancelamento.get('justificativa', '')
                    doc['protocolo_cancelamento'] = evento_cancelamento.get('protocolo', '')
                    
                    # Marcar evento como processado
                    await db.eventos_cancelamento.update_one(
                        {"chave_nfe": chave_nfe},
                        {"$set": {"processado": True}}
                    )
            
            await db.xml_documents.insert_one(doc)
            
            result_entry = {
                "filename": file.filename,
                "status": "success",
                "chave": parsed_data['chave_nfe'],
                "conversoes": len(file_conversions)
            }
            
            # Indicar se a nota foi importada já cancelada
            if doc.get('cancelada'):
                result_entry['status'] = 'cancelada'
                # Verificar a origem da detecção de cancelamento
                if parsed_data.get('cancelada'):
                    # Cancelamento detectado pelo protocolo no próprio XML
                    motivo = parsed_data.get('xMotivo_cancelamento', 'Status de cancelamento no protocolo')
                    result_entry['mensagem'] = f'Nota CANCELADA (detectado no XML: {motivo})'
                else:
                    # Cancelamento detectado por evento externo
                    result_entry['mensagem'] = 'Nota importada como CANCELADA (evento de cancelamento encontrado)'
                
                # Adicionar ao array de notas canceladas
                notas_canceladas.append({
                    "numero_nfe": parsed_data.get('numero_nfe'),
                    "chave": chave_nfe,
                    "emitente": parsed_data.get('emitente_nome', ''),
                    "valor": parsed_data.get('valor_total', 0),
                    "data_emissao": parsed_data.get('data_emissao', ''),
                    "motivo": result_entry['mensagem']
                })
            
            # Indicar se a nota foi importada como devolução do fornecedor
            if is_devolucao_fornecedor:
                result_entry['status'] = 'devolucao_fornecedor'
                result_entry['mensagem'] = motivo_devolucao
                result_entry['nfe_referenciada'] = nfe_ref_devolucao
            
            results.append(result_entry)
            
            if file_conversions:
                conversion_report.append({
                    "arquivo": file.filename,
                    "nfe": parsed_data['numero_nfe'],
                    "conversoes": file_conversions
                })
            
        except Exception as e:
            errors.append({"filename": file.filename, "error": str(e)})
    
    # ===== PROCESSAR NOTAS ORIGINAIS REFERENCIADAS NAS DEVOLUÇÕES =====
    # Marcar as notas originais que foram referenciadas nas devoluções como desconsideradas também
    notas_desconsideradas_salvas = []
    for dev in notas_devolucao_fornecedor:
        try:
            chave_nfe_dev = dev['chave_nfe']
            nfe_ref = dev.get('nfe_referenciada', '')
            
            # Registrar a devolução no relatório
            nota_dev_info = {
                "tipo": "devolucao_entrada",
                "chave_nfe": chave_nfe_dev,
                "numero_nfe": dev.get('numero_nfe', ''),
                "data_emissao": dev.get('data_emissao', ''),
                "valor_total": dev.get('valor_total', 0),
                "emitente": dev.get('emitente_nome', ''),
                "nfe_referenciada": nfe_ref,
                "motivo": dev.get('motivo', '')
            }
            notas_desconsideradas_salvas.append(nota_dev_info)
            
            # Se tiver NFe referenciada, marcar a nota original como desconsiderada também
            if nfe_ref:
                nota_original = None
                
                # Tentar buscar pela chave completa de 44 dígitos
                if len(nfe_ref) == 44 and nfe_ref.isdigit():
                    nota_original = await db.xml_documents.find_one({
                        "company_id": company_id,
                        "chave_nfe": nfe_ref
                    })
                
                # Se não encontrou e a referência parece um número de NF, buscar pelo número
                if not nota_original:
                    # Extrair apenas dígitos para pegar o número da NF
                    import re
                    nf_numeros = re.findall(r'\d+', nfe_ref)
                    if nf_numeros:
                        # Pegar o maior número (provavelmente o número da NF)
                        numero_nf = max(nf_numeros, key=lambda x: len(x))
                        if len(numero_nf) >= 1:
                            # Buscar por número da NF no mesmo período/empresa
                            nota_original = await db.xml_documents.find_one({
                                "company_id": company_id,
                                "numero_nfe": numero_nf,
                                "tipo": "saida"
                            })
                            
                            # Se não encontrou, tentar com leading zeros
                            if not nota_original:
                                nota_original = await db.xml_documents.find_one({
                                    "company_id": company_id,
                                    "numero_nfe": {"$regex": f"^0*{numero_nf}$"},
                                    "tipo": "saida"
                                })
                
                if nota_original:
                    # Marcar a nota original como desconsiderada
                    await db.xml_documents.update_one(
                        {"id": nota_original['id']},
                        {"$set": {
                            "desconsiderada_devolucao": True,
                            "motivo_desconsideracao": f"Nota devolvida pelo fornecedor. Devolução: NF {dev.get('numero_nfe', '')}",
                            "nfe_vinculada_devolucao": chave_nfe_dev,
                            "status_validacao": "desconsiderada"
                        }}
                    )
                    
                    notas_desconsideradas_salvas.append({
                        "tipo": "saida_original",
                        "chave_nfe": nfe_ref,
                        "numero_nfe": nota_original.get('numero_nfe', ''),
                        "data_emissao": nota_original.get('data_emissao', ''),
                        "valor_total": nota_original.get('valor_total', 0),
                        "destinatario": nota_original.get('destinatario_nome', ''),
                        "vinculada_a": dev.get('numero_nfe', ''),
                        "motivo": f"Nota devolvida pelo fornecedor. Devolução: NF {dev.get('numero_nfe', '')}"
                    })
                else:
                    # Nota original não encontrada - registrar para referência
                    notas_desconsideradas_salvas.append({
                        "tipo": "saida_original_nao_encontrada",
                        "chave_nfe": nfe_ref,
                        "numero_nfe": "N/A",
                        "vinculada_a": dev.get('numero_nfe', ''),
                        "motivo": f"Nota original referenciada não encontrada no sistema. Chave: {nfe_ref[:20]}..."
                    })
        
        except Exception as e:
            errors.append({"filename": dev.get('filename', 'devolucao'), "error": f"Erro ao processar devolução: {str(e)}"})
    
    return {
        "success": results,
        "errors": errors,
        "duplicadas": duplicadas,
        "rejeitadas_cnpj": rejeitadas_cnpj,
        "rejeitadas_competencia": rejeitadas_competencia,
        "relatorio_conversoes": conversion_report,
        "alertas_cfop": alertas_cfop,
        "notas_desconsideradas_devolucao": notas_desconsideradas_salvas,
        "total_conversoes": sum(len(r['conversoes']) for r in conversion_report),
        "total_alertas_cfop": sum(len(a['alertas']) for a in alertas_cfop),
        "performance": {
            "produtos_do_cache": total_stats["from_cache"],
            "produtos_de_regras": total_stats["from_rules"],
            "produtos_da_ia": total_stats["from_ai"],
            "total_classificados": total_stats["total"]
        },
        "resumo": {
            "total_arquivos": len(files),
            "importados": len(results),
            "duplicados": len(duplicadas),
            "rejeitados_cnpj": len(rejeitadas_cnpj),
            "rejeitados_competencia": len(rejeitadas_competencia),
            "desconsideradas_devolucao": len(notas_devolucao_fornecedor),
            "erros": len(errors),
            "alertas_cfop": len(alertas_cfop)
        },
        "alertas_viloes_ncm": await identificar_ncms_viloes_importacao(company_id, results)
    }


# ============== IDENTIFICADOR DE NCMs VILÕES NA IMPORTAÇÃO ==============

async def identificar_ncms_viloes_importacao(company_id: str, notas_importadas: List[Dict]) -> List[Dict]:
    """
    Identifica NCMs de risco tributário nas notas recém importadas.
    Verifica se os NCMs têm histórico de alta carga tributária.
    """
    try:
        # Buscar vilões já identificados da empresa
        company = await db.companies.find_one({"id": company_id}, {"_id": 0})
        if not company:
            return []
        
        # Buscar vilões tributários calculados anteriormente
        # Primeiro tentar buscar do cache de indicadores
        cache_key = f"viloes_ncm_{company_id}"
        viloes_conhecidos = {}
        
        # Buscar documentos de saída da empresa para calcular vilões em tempo real
        saidas = await db.xml_documents.find({
            "company_id": company_id,
            "tipo": "saida",
            **get_filtro_notas_ativas()
        }, {"_id": 0, "produtos": 1}).to_list(length=500)
        
        # Agregar débitos por NCM
        debitos_por_ncm = {}
        for doc in saidas:
            for prod in doc.get('produtos', []):
                ncm = str(prod.get('ncm', ''))[:8]
                if not ncm:
                    continue
                    
                v_icms = float(prod.get('v_icms', 0) or 0)
                v_pis = float(prod.get('v_pis', 0) or 0)
                v_cofins = float(prod.get('v_cofins', 0) or 0)
                valor = float(prod.get('valor_total', 0) or 0)
                
                if ncm not in debitos_por_ncm:
                    debitos_por_ncm[ncm] = {
                        'total_debito': 0,
                        'total_valor': 0,
                        'descricoes': set()
                    }
                
                debitos_por_ncm[ncm]['total_debito'] += v_icms + v_pis + v_cofins
                debitos_por_ncm[ncm]['total_valor'] += valor
                debitos_por_ncm[ncm]['descricoes'].add(prod.get('descricao', '')[:40])
        
        # Calcular NCMs com alta carga tributária (> 15% do valor)
        for ncm, dados in debitos_por_ncm.items():
            if dados['total_valor'] > 1000:
                carga = (dados['total_debito'] / dados['total_valor']) * 100
                if carga > 15:
                    viloes_conhecidos[ncm] = {
                        'carga_percentual': round(carga, 1),
                        'total_debito': round(dados['total_debito'], 2),
                        'descricao': list(dados['descricoes'])[0] if dados['descricoes'] else ncm
                    }
        
        # Verificar produtos nas notas importadas
        alertas = []
        ncms_alertados = set()
        
        for nota in notas_importadas:
            if isinstance(nota, dict):
                nota_id = nota.get('id', '')
                numero_nf = nota.get('numero_nfe', nota.get('numero', ''))
                
                # Buscar a nota completa do banco para ter os produtos
                doc = await db.xml_documents.find_one({"id": nota_id}, {"_id": 0})
                if not doc:
                    continue
                    
                for prod in doc.get('produtos', []):
                    ncm = str(prod.get('ncm', ''))[:8]
                    
                    if ncm in viloes_conhecidos and ncm not in ncms_alertados:
                        vilao = viloes_conhecidos[ncm]
                        alertas.append({
                            'ncm': ncm,
                            'descricao_produto': prod.get('descricao', '')[:50],
                            'nota_fiscal': numero_nf,
                            'carga_historica': vilao['carga_percentual'],
                            'debito_acumulado': vilao['total_debito'],
                            'descricao_historico': vilao['descricao'],
                            'severidade': 'alta' if vilao['carga_percentual'] > 20 else 'media',
                            'mensagem': f"NCM {ncm} tem carga tributária histórica de {vilao['carga_percentual']:.1f}%. Total de débitos: R$ {vilao['total_debito']:,.2f}"
                        })
                        ncms_alertados.add(ncm)
        
        return alertas[:10]  # Limitar a 10 alertas
        
    except Exception as e:
        logger.error(f"Erro ao identificar NCMs vilões: {str(e)}")
        return []


# ============== UPLOAD COM PROGRESSO (SSE) ==============
# Cache em memória para performance, com fallback para MongoDB
upload_progress_store: Dict[str, Dict] = {}

async def get_upload_session(upload_id: str) -> Optional[Dict]:
    """Busca sessão de upload primeiro em memória, depois no MongoDB"""
    # Tentar memória primeiro (mais rápido)
    if upload_id in upload_progress_store:
        return upload_progress_store[upload_id]
    
    # Fallback para MongoDB (persistente)
    session = await db.upload_sessions.find_one({"upload_id": upload_id}, {"_id": 0})
    if session:
        # Restaurar para memória para operações subsequentes
        # IMPORTANTE: Armazenar o objeto para que modificações sejam refletidas
        upload_progress_store[upload_id] = session
        return upload_progress_store[upload_id]  # Retornar referência do store
    
    return None

async def save_upload_session(upload_id: str, session_data: Dict):
    """Salva sessão de upload em memória e MongoDB"""
    upload_progress_store[upload_id] = session_data
    # Persistir no MongoDB de forma assíncrona
    try:
        await db.upload_sessions.update_one(
            {"upload_id": upload_id},
            {"$set": {**session_data, "upload_id": upload_id, "updated_at": datetime.now(timezone.utc).isoformat()}},
            upsert=True
        )
        logger.debug(f"UPLOAD-SESSION: Salvo upload_id={upload_id[:20]}...")
    except Exception as e:
        logger.error(f"UPLOAD-SESSION: Erro ao salvar no MongoDB: {e}")

async def delete_upload_session(upload_id: str):
    """Remove sessão de upload da memória e do MongoDB"""
    if upload_id in upload_progress_store:
        del upload_progress_store[upload_id]
    await db.upload_sessions.delete_one({"upload_id": upload_id})

@api_router.post("/xml/upload-init")
async def init_upload(
    company_id: str = Form(...),
    competencia: str = Form(...),
    tipo: str = Form(...),
    total_files: int = Form(...),
    skip_ai: bool = Form(False),
    current_user: User = Depends(get_current_user)
):
    """Inicializa uma sessão de upload e retorna um upload_id para acompanhar o progresso"""
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    upload_id = str(uuid.uuid4())
    session_data = {
        "status": "initialized",
        "total_files": total_files,
        "processed_files": 0,
        "processed_in_session": 0,  # Total processado em todos os lotes
        "current_file": "",
        "current_step": "Aguardando arquivos...",
        "progress_percent": 0,
        "company_id": company_id,
        "competencia": competencia,
        "tipo": tipo,
        "skip_ai": skip_ai,  # Flag para pular classificação IA
        "user_id": current_user.id,
        "results": None,
        "completed": False,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "all_results": {  # Acumula resultados de todos os lotes
            "success": [],
            "errors": [],
            "duplicadas": [],
            "rejeitadas_cnpj": [],
            "relatorio_conversoes": [],
            "alertas_cfop": [],
            "notas_desconsideradas_devolucao": [],
            "notas_canceladas": []
        }
    }
    
    # Salvar em memória e MongoDB
    await save_upload_session(upload_id, session_data)
    
    if skip_ai:
        logger.info(f"UPLOAD-INIT: Iniciado upload_id={upload_id} com skip_ai=True (importação rápida)")
    
    return {"upload_id": upload_id}


# ============================================================
# ENDPOINTS DE UPLOAD EM BACKGROUND (Celery)
# ============================================================

@api_router.post("/xml/upload-background")
async def upload_background(
    files: List[UploadFile] = File(...),
    company_id: str = Form(...),
    competencia: str = Form(...),
    tipo: str = Form(...),
    current_user: User = Depends(get_current_user)
):
    """
    Upload de XMLs para processamento em background (Celery).
    Retorna imediatamente com job_id para acompanhar o progresso.
    
    Ideal para uploads de 1.000+ arquivos.
    
    NOTA: Requer Redis e Celery rodando.
    """
    import base64
    
    # Verificar se Celery/Redis está disponível antes de prosseguir
    redis_available = False
    try:
        import redis
        redis_url = os.environ.get('REDIS_URL', 'redis://localhost:6379/0')
        r = redis.from_url(redis_url, socket_connect_timeout=2)
        r.ping()
        redis_available = True
    except Exception as redis_err:
        logger.warning(f"BACKGROUND-UPLOAD: Redis não disponível: {redis_err}")
    
    if not redis_available:
        raise HTTPException(
            status_code=503, 
            detail="Serviço de processamento em background não disponível. Redis não está conectado. Use o upload normal."
        )
    
    # Importar task do Celery apenas se Redis estiver OK
    try:
        from celery_tasks import process_xml_batch
    except Exception as import_err:
        logger.warning(f"BACKGROUND-UPLOAD: Erro ao importar celery_tasks: {import_err}")
        raise HTTPException(
            status_code=503, 
            detail="Serviço de processamento em background não disponível. Use o upload normal."
        )
    
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Gerar job_id
    job_id = str(uuid.uuid4())
    
    # Ler e codificar arquivos em base64
    xml_contents = []
    for file in files:
        try:
            content = await file.read()
            if content:
                xml_contents.append({
                    'filename': file.filename,
                    'content_b64': base64.b64encode(content).decode('utf-8')
                })
        except Exception as e:
            logger.warning(f"Erro ao ler arquivo {file.filename}: {e}")
    
    if not xml_contents:
        raise HTTPException(status_code=400, detail="Nenhum arquivo válido encontrado")
    
    # Criar registro do job
    job_record = {
        'job_id': job_id,
        'company_id': company_id,
        'competencia': competencia,
        'tipo': tipo,
        'user_id': current_user.id,
        'status': 'queued',
        'total_files': len(xml_contents),
        'created_at': datetime.now(timezone.utc).isoformat()
    }
    
    await db.import_jobs.insert_one(job_record)
    
    # Enviar para fila Celery
    try:
        task = process_xml_batch.delay(
            job_id=job_id,
            xml_contents=xml_contents,
            company_id=company_id,
            competencia=competencia,
            tipo=tipo,
            user_id=current_user.id
        )
        
        # Atualizar com task_id do Celery
        await db.import_jobs.update_one(
            {'job_id': job_id},
            {'$set': {'celery_task_id': task.id, 'status': 'processing'}}
        )
        
        logger.info(f"BACKGROUND-UPLOAD: Job {job_id} criado com {len(xml_contents)} arquivos")
        
        return {
            "job_id": job_id,
            "celery_task_id": task.id,
            "status": "queued",
            "total_files": len(xml_contents),
            "message": f"Upload de {len(xml_contents)} arquivos iniciado em background. Você pode fechar esta página."
        }
    
    except Exception as e:
        logger.error(f"BACKGROUND-UPLOAD: Erro ao enviar para Celery: {e}")
        # Fallback: Se Celery não estiver disponível, processar síncrono
        await db.import_jobs.update_one(
            {'job_id': job_id},
            {'$set': {'status': 'error', 'error': str(e)}}
        )
        raise HTTPException(
            status_code=503, 
            detail=f"Serviço de processamento em background não disponível. Use o upload normal."
        )


@api_router.get("/xml/job-status/{job_id}")
async def get_job_status(
    job_id: str,
    current_user: User = Depends(get_current_user)
):
    """
    Retorna o status de um job de importação em background.
    """
    job = await db.import_jobs.find_one({'job_id': job_id}, {'_id': 0})
    
    if not job:
        raise HTTPException(status_code=404, detail="Job não encontrado")
    
    # Verificar acesso
    if job.get('user_id') != current_user.id and current_user.role not in ['admin', 'super_admin']:
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Se ainda está processando, tentar obter progresso do Celery
    if job.get('status') in ['queued', 'processing'] and job.get('celery_task_id'):
        try:
            from celery.result import AsyncResult
            from celery_config import celery_app
            
            task_result = AsyncResult(job['celery_task_id'], app=celery_app)
            
            if task_result.state == 'PROCESSING':
                meta = task_result.info or {}
                job['progress'] = {
                    'current': meta.get('current', 0),
                    'total': meta.get('total', job.get('total_files', 0)),
                    'status': meta.get('status', 'Processando...'),
                    'importados': meta.get('importados', 0),
                    'duplicados': meta.get('duplicados', 0),
                    'erros': meta.get('erros', 0)
                }
            elif task_result.state == 'SUCCESS':
                job['status'] = 'completed'
            elif task_result.state == 'FAILURE':
                job['status'] = 'error'
                job['error'] = str(task_result.info)
        except Exception as e:
            logger.warning(f"Erro ao obter status do Celery: {e}")
    
    return job


@api_router.get("/xml/jobs")
async def list_jobs(
    company_id: str = None,
    status: str = None,
    limit: int = 20,
    current_user: User = Depends(get_current_user)
):
    """
    Lista jobs de importação do usuário.
    """
    query = {'user_id': current_user.id}
    
    if company_id:
        query['company_id'] = company_id
    
    if status:
        query['status'] = status
    
    jobs = await db.import_jobs.find(
        query, 
        {'_id': 0, 'results': 0, 'errors': 0, 'duplicadas': 0}  # Excluir campos grandes
    ).sort('created_at', -1).limit(limit).to_list(length=limit)
    
    return {"jobs": jobs, "total": len(jobs)}


@api_router.post("/xml/upload-zip")
async def upload_zip_with_progress(
    file: UploadFile = File(...),
    company_id: str = Form(...),
    competencia: str = Form(...),
    tipo: str = Form(...),
    current_user: User = Depends(get_current_user)
):
    """
    Upload de arquivo ZIP contendo XMLs de notas fiscais.
    Extrai os XMLs do ZIP e processa cada um individualmente.
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Verificar se é um arquivo ZIP
    if not file.filename.lower().endswith('.zip'):
        raise HTTPException(status_code=400, detail="O arquivo deve ser um ZIP")
    
    # Ler o conteúdo do ZIP
    try:
        zip_content = await file.read()
        zip_buffer = BytesIO(zip_content)
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Erro ao ler arquivo ZIP: {str(e)}")
    
    # Extrair XMLs do ZIP
    xml_files = []
    try:
        with zipfile.ZipFile(zip_buffer, 'r') as zip_ref:
            for file_info in zip_ref.infolist():
                # Ignorar diretórios e arquivos não-XML
                if file_info.is_dir():
                    continue
                
                # Pegar apenas o nome do arquivo (sem caminho)
                base_filename = os.path.basename(file_info.filename)
                
                if base_filename.lower().endswith('.xml'):
                    try:
                        xml_content = zip_ref.read(file_info.filename)
                        xml_files.append({
                            "filename": base_filename,
                            "content": xml_content
                        })
                    except Exception as e:
                        logger.warning(f"Erro ao ler {file_info.filename} do ZIP: {e}")
    except zipfile.BadZipFile:
        raise HTTPException(status_code=400, detail="Arquivo ZIP inválido ou corrompido")
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Erro ao extrair ZIP: {str(e)}")
    
    if not xml_files:
        raise HTTPException(status_code=400, detail="Nenhum arquivo XML encontrado no ZIP")
    
    # Criar sessão de upload
    upload_id = str(uuid.uuid4())
    total_files = len(xml_files)
    
    session_data = {
        "status": "processing",
        "total_files": total_files,
        "processed_files": 0,
        "processed_in_session": 0,
        "current_file": "",
        "current_step": f"Extraídos {total_files} XMLs do ZIP. Processando...",
        "progress_percent": 0,
        "company_id": company_id,
        "competencia": competencia,
        "tipo": tipo,
        "user_id": current_user.id,
        "results": None,
        "completed": False,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "all_results": {
            "success": [],
            "errors": [],
            "duplicadas": [],
            "rejeitadas_cnpj": [],
            "relatorio_conversoes": [],
            "alertas_cfop": [],
            "notas_desconsideradas_devolucao": [],
            "notas_canceladas": []
        }
    }
    
    await save_upload_session(upload_id, session_data)
    
    logger.info(f"ZIP-UPLOAD: Extraídos {total_files} XMLs do arquivo {file.filename}")
    
    return {
        "upload_id": upload_id,
        "total_files_extracted": total_files,
        "message": f"ZIP extraído com sucesso. {total_files} arquivos XML encontrados.",
        "xml_files": [{"filename": f["filename"], "size": len(f["content"])} for f in xml_files[:100]]  # Limitar preview
    }


@api_router.post("/xml/upload-zip-process")
async def process_zip_upload(
    file: UploadFile = File(...),
    company_id: str = Form(...),
    competencia: str = Form(...),
    tipo: str = Form(...),
    background_tasks: BackgroundTasks = None,
    current_user: User = Depends(get_current_user)
):
    """
    Upload e processamento completo de arquivo ZIP contendo XMLs.
    Extrai, valida e processa todos os XMLs do ZIP em uma única operação.
    Retorna um upload_id para acompanhar o progresso.
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Verificar se é um arquivo ZIP
    if not file.filename.lower().endswith('.zip'):
        raise HTTPException(status_code=400, detail="O arquivo deve ser um ZIP")
    
    # Ler o conteúdo do ZIP
    try:
        zip_content = await file.read()
        zip_buffer = BytesIO(zip_content)
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Erro ao ler arquivo ZIP: {str(e)}")
    
    # Extrair XMLs do ZIP
    xml_files = []
    try:
        with zipfile.ZipFile(zip_buffer, 'r') as zip_ref:
            for file_info in zip_ref.infolist():
                if file_info.is_dir():
                    continue
                
                base_filename = os.path.basename(file_info.filename)
                
                if base_filename.lower().endswith('.xml'):
                    try:
                        xml_content = zip_ref.read(file_info.filename)
                        xml_files.append({
                            "filename": base_filename,
                            "content": xml_content
                        })
                    except Exception as e:
                        logger.warning(f"Erro ao ler {file_info.filename} do ZIP: {e}")
    except zipfile.BadZipFile:
        raise HTTPException(status_code=400, detail="Arquivo ZIP inválido ou corrompido")
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Erro ao extrair ZIP: {str(e)}")
    
    if not xml_files:
        raise HTTPException(status_code=400, detail="Nenhum arquivo XML encontrado no ZIP")
    
    total_files = len(xml_files)
    upload_id = str(uuid.uuid4())
    
    # Criar sessão de upload
    session_data = {
        "status": "processing",
        "total_files": total_files,
        "processed_files": 0,
        "processed_in_session": 0,
        "current_file": "",
        "current_step": f"Extraídos {total_files} XMLs. Iniciando processamento...",
        "progress_percent": 0,
        "company_id": company_id,
        "competencia": competencia,
        "tipo": tipo,
        "user_id": current_user.id,
        "results": None,
        "completed": False,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "all_results": {
            "success": [],
            "errors": [],
            "duplicadas": [],
            "rejeitadas_cnpj": [],
            "relatorio_conversoes": [],
            "alertas_cfop": [],
            "notas_desconsideradas_devolucao": [],
            "notas_canceladas": []
        },
        "zip_xml_files": xml_files  # Armazenar XMLs extraídos para processamento
    }
    
    await save_upload_session(upload_id, session_data)
    
    logger.info(f"ZIP-PROCESS: Iniciado upload_id={upload_id} com {total_files} XMLs do arquivo {file.filename}")
    
    return {
        "upload_id": upload_id,
        "total_files": total_files,
        "message": f"ZIP recebido. {total_files} XMLs extraídos e prontos para processamento."
    }


@api_router.get("/xml/upload-progress/{upload_id}")
async def stream_upload_progress(upload_id: str):
    """Stream de progresso do upload via Server-Sent Events"""
    
    async def event_generator():
        last_progress = -1
        retry_count = 0
        max_retries = 10  # Aguardar até 3 segundos para a sessão aparecer
        
        while True:
            # Usar a função que busca em memória e MongoDB
            progress = await get_upload_session(upload_id)
            
            if progress is None:
                retry_count += 1
                if retry_count <= max_retries:
                    # Aguardar um pouco e tentar novamente (race condition com upload-init)
                    await asyncio.sleep(0.3)
                    continue
                else:
                    yield f"data: {json.dumps({'error': 'Upload não encontrado'})}\n\n"
                    break
            
            current_progress = progress.get("progress_percent", 0)
            
            # Enviar atualização apenas se houver mudança
            if current_progress != last_progress or progress.get("completed"):
                event_data = {
                    "status": progress["status"],
                    "total_files": progress["total_files"],
                    "processed_files": progress["processed_files"],
                    "current_file": progress["current_file"],
                    "current_step": progress["current_step"],
                    "progress_percent": progress["progress_percent"],
                    "completed": progress.get("completed", False)
                }
                
                if progress.get("completed") and progress.get("results"):
                    event_data["results"] = progress["results"]
                    yield f"data: {json.dumps(event_data)}\n\n"
                    # Limpar dados após enviar resultados
                    await asyncio.sleep(1)
                    await delete_upload_session(upload_id)
                    break
                
                yield f"data: {json.dumps(event_data)}\n\n"
                last_progress = current_progress
            
            await asyncio.sleep(0.3)  # Verificar a cada 300ms
    
    return StreamingResponse(
        event_generator(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no"
        }
    )


@api_router.get("/xml/upload-status/{upload_id}")
async def get_upload_status(upload_id: str, current_user: User = Depends(get_current_user)):
    """Endpoint de polling para verificar status do upload (fallback quando SSE não funciona)"""
    progress = await get_upload_session(upload_id)
    
    if progress is None:
        return {"error": "Upload não encontrado", "completed": False}
    
    response_data = {
        "status": progress.get("status", "unknown"),
        "total_files": progress.get("total_files", 0),
        "processed_files": progress.get("processed_files", 0),
        "current_file": progress.get("current_file", ""),
        "current_step": progress.get("current_step", ""),
        "progress_percent": progress.get("progress_percent", 0),
        "completed": progress.get("completed", False)
    }
    
    if progress.get("completed") and progress.get("results"):
        response_data["results"] = progress["results"]
    
    if progress.get("error"):
        response_data["error"] = progress["error"]
    
    return response_data


