@api_router.get("/viloes-oportunidades/{company_id}")
async def get_viloes_oportunidades(
    company_id: str,
    competencia: str,
    current_user: User = Depends(get_current_user)
):
    """
    Endpoint dedicado para Vilões e Oportunidades Tributárias.
    Inclui análise completa de ICMS, PIS e COFINS.
    Agrupa por NCM e por palavra-chave.
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    regime = company.get('regime_tributario', 'lucro_presumido').lower().replace(' ', '_')
    
    # Buscar documentos de entrada e saída
    # Suportar tanto 'tipo' quanto 'tipo_operacao' para compatibilidade
    docs_entrada = await db.xml_documents.find({
        "company_id": company_id,
        "competencia": competencia,
        "$or": [{"tipo": "entrada"}, {"tipo_operacao": "entrada"}]
    }, {"_id": 0}).to_list(100000)
    
    docs_saida = await db.xml_documents.find({
        "company_id": company_id,
        "competencia": competencia,
        "$or": [{"tipo": "saida"}, {"tipo_operacao": "saida"}]
    }, {"_id": 0}).to_list(100000)
    
    # Agrupar por NCM
    produtos_por_ncm = {}
    produtos_por_keyword = {}
    
    # Função para extrair palavra-chave da descrição
    def extrair_keyword(descricao):
        if not descricao:
            return "outros"
        desc_lower = descricao.lower()
        
        keywords_map = {
            'cerveja': ['cerveja', 'beer', 'pilsen', 'lager', 'ipa'],
            'refrigerante': ['refrigerante', 'coca', 'pepsi', 'fanta', 'guarana', 'sprite'],
            'suco': ['suco', 'nectar', 'juice'],
            'agua': ['agua', 'mineral', 'h2o'],
            'bebida': ['energetico', 'isotônico', 'energético', 'gatorade', 'red bull'],
            'destilado': ['whisky', 'vodka', 'gin', 'rum', 'cachaça', 'tequila', 'conhaque'],
            'vinho': ['vinho', 'wine', 'espumante', 'champagne'],
            'cigarro': ['cigarro', 'tabaco', 'fumo'],
            'combustivel': ['gasolina', 'diesel', 'etanol', 'alcool', 'gnv'],
            'alimento': ['arroz', 'feijão', 'macarrão', 'farinha', 'açucar', 'oleo', 'leite'],
            'limpeza': ['detergente', 'sabão', 'desinfetante', 'limpa', 'alvejante'],
            'higiene': ['papel', 'sabonete', 'shampoo', 'creme', 'desodorante'],
        }
        
        for keyword, termos in keywords_map.items():
            for termo in termos:
                if termo in desc_lower:
                    return keyword
        
        return "outros"
    
    # Processar entradas
    for doc in docs_entrada:
        for prod in doc.get('produtos', []):
            ncm = prod.get('ncm', '00000000')[:8]
            descricao = prod.get('descricao', '')
            valor = prod.get('valor_total', 0) or 0
            icms = prod.get('v_icms', 0) or 0
            pis = prod.get('v_pis', 0) or 0
            cofins = prod.get('v_cofins', 0) or 0
            cfop = prod.get('cfop', '')
            keyword = extrair_keyword(descricao)
            
            # Por NCM
            if ncm not in produtos_por_ncm:
                produtos_por_ncm[ncm] = {
                    'ncm': ncm,
                    'descricao': descricao[:50],
                    'entrada': {'valor': 0, 'icms': 0, 'pis': 0, 'cofins': 0, 'qtd': 0, 'produtos': []},
                    'saida': {'valor': 0, 'icms': 0, 'pis': 0, 'cofins': 0, 'qtd': 0, 'produtos': []}
                }
            produtos_por_ncm[ncm]['entrada']['valor'] += valor
            produtos_por_ncm[ncm]['entrada']['icms'] += icms
            produtos_por_ncm[ncm]['entrada']['pis'] += pis
            produtos_por_ncm[ncm]['entrada']['cofins'] += cofins
            produtos_por_ncm[ncm]['entrada']['qtd'] += 1
            produtos_por_ncm[ncm]['entrada']['produtos'].append({
                'descricao': descricao, 'valor': valor, 'icms': icms, 'pis': pis, 'cofins': cofins,
                'cfop': cfop, 'nota': doc.get('numero_nfe', ''), 'emitente': doc.get('emitente_nome', '')
            })
            
            # Por Keyword
            if keyword not in produtos_por_keyword:
                produtos_por_keyword[keyword] = {
                    'keyword': keyword,
                    'entrada': {'valor': 0, 'icms': 0, 'pis': 0, 'cofins': 0, 'qtd': 0, 'produtos': []},
                    'saida': {'valor': 0, 'icms': 0, 'pis': 0, 'cofins': 0, 'qtd': 0, 'produtos': []}
                }
            produtos_por_keyword[keyword]['entrada']['valor'] += valor
            produtos_por_keyword[keyword]['entrada']['icms'] += icms
            produtos_por_keyword[keyword]['entrada']['pis'] += pis
            produtos_por_keyword[keyword]['entrada']['cofins'] += cofins
            produtos_por_keyword[keyword]['entrada']['qtd'] += 1
            produtos_por_keyword[keyword]['entrada']['produtos'].append({
                'descricao': descricao, 'valor': valor, 'ncm': ncm, 'icms': icms, 'pis': pis, 'cofins': cofins
            })
    
    # Processar saídas
    for doc in docs_saida:
        for prod in doc.get('produtos', []):
            ncm = prod.get('ncm', '00000000')[:8]
            descricao = prod.get('descricao', '')
            valor = prod.get('valor_total', 0) or 0
            icms = prod.get('v_icms', 0) or 0
            pis = prod.get('v_pis', 0) or 0
            cofins = prod.get('v_cofins', 0) or 0
            cfop = prod.get('cfop', '')
            keyword = extrair_keyword(descricao)
            
            # Por NCM
            if ncm not in produtos_por_ncm:
                produtos_por_ncm[ncm] = {
                    'ncm': ncm,
                    'descricao': descricao[:50],
                    'entrada': {'valor': 0, 'icms': 0, 'pis': 0, 'cofins': 0, 'qtd': 0, 'produtos': []},
                    'saida': {'valor': 0, 'icms': 0, 'pis': 0, 'cofins': 0, 'qtd': 0, 'produtos': []}
                }
            produtos_por_ncm[ncm]['saida']['valor'] += valor
            produtos_por_ncm[ncm]['saida']['icms'] += icms
            produtos_por_ncm[ncm]['saida']['pis'] += pis
            produtos_por_ncm[ncm]['saida']['cofins'] += cofins
            produtos_por_ncm[ncm]['saida']['qtd'] += 1
            produtos_por_ncm[ncm]['saida']['produtos'].append({
                'descricao': descricao, 'valor': valor, 'icms': icms, 'pis': pis, 'cofins': cofins,
                'cfop': cfop, 'nota': doc.get('numero_nfe', ''), 'cliente': doc.get('destinatario_nome', '')
            })
            
            # Por Keyword
            if keyword not in produtos_por_keyword:
                produtos_por_keyword[keyword] = {
                    'keyword': keyword,
                    'entrada': {'valor': 0, 'icms': 0, 'pis': 0, 'cofins': 0, 'qtd': 0, 'produtos': []},
                    'saida': {'valor': 0, 'icms': 0, 'pis': 0, 'cofins': 0, 'qtd': 0, 'produtos': []}
                }
            produtos_por_keyword[keyword]['saida']['valor'] += valor
            produtos_por_keyword[keyword]['saida']['icms'] += icms
            produtos_por_keyword[keyword]['saida']['pis'] += pis
            produtos_por_keyword[keyword]['saida']['cofins'] += cofins
            produtos_por_keyword[keyword]['saida']['qtd'] += 1
            produtos_por_keyword[keyword]['saida']['produtos'].append({
                'descricao': descricao, 'valor': valor, 'ncm': ncm, 'icms': icms, 'pis': pis, 'cofins': cofins
            })
    
    # Identificar vilões e oportunidades
    viloes = []
    oportunidades = []
    
    for ncm, dados in produtos_por_ncm.items():
        entrada = dados['entrada']
        saida = dados['saida']
        
        if entrada['qtd'] == 0 or saida['qtd'] == 0:
            continue
        
        # Impacto total de impostos
        icms_credito = entrada['icms']
        icms_debito = saida['icms']
        pis_credito = entrada['pis']
        pis_debito = saida['pis']
        cofins_credito = entrada['cofins']
        cofins_debito = saida['cofins']
        
        impacto_icms = icms_debito - icms_credito
        impacto_pis = pis_debito - pis_credito
        impacto_cofins = cofins_debito - cofins_credito
        impacto_total = impacto_icms + impacto_pis + impacto_cofins
        
        # Vilão: impacto negativo alto
        if impacto_total > 100:
            # Calcular margem para análise
            margem_valor = ((saida['valor'] - entrada['valor']) / entrada['valor'] * 100) if entrada['valor'] > 0 else 0
            
            # Gerar explicação concisa (sem repetir valores que já aparecem no grid)
            impostos_impacto = []
            if impacto_icms > 50:
                impostos_impacto.append("ICMS")
            if impacto_pis > 50:
                impostos_impacto.append("PIS")
            if impacto_cofins > 50:
                impostos_impacto.append("COFINS")
            
            if len(impostos_impacto) == 3:
                motivo = "Os débitos de ICMS, PIS e COFINS superam os créditos, gerando impacto negativo na apuração."
            elif len(impostos_impacto) == 2:
                motivo = f"Os débitos de {' e '.join(impostos_impacto)} superam os créditos, gerando impacto negativo."
            elif len(impostos_impacto) == 1:
                motivo = f"O débito de {impostos_impacto[0]} supera significativamente o crédito."
            else:
                motivo = "O somatório dos débitos tributários supera os créditos."
            
            # Análise de precificação
            if margem_valor < 10:
                analise_preco = "⚠️ MARGEM MUITO BAIXA - Risco de prejuízo considerando a carga tributária"
            elif margem_valor < 20:
                analise_preco = "⚠️ MARGEM APERTADA - Revisar precificação"
            else:
                analise_preco = "Margem aparentemente adequada, porém os impostos corroem parte do lucro"
            
            viloes.append({
                'tipo': 'IMPACTO_NEGATIVO',
                'ncm': ncm,
                'descricao': dados['descricao'],
                'entrada_valor': round(entrada['valor'], 2),
                'saida_valor': round(saida['valor'], 2),
                'margem_percentual': round(margem_valor, 2),
                'icms': {'credito': round(icms_credito, 2), 'debito': round(icms_debito, 2), 'impacto': round(impacto_icms, 2)},
                'pis': {'credito': round(pis_credito, 2), 'debito': round(pis_debito, 2), 'impacto': round(impacto_pis, 2)},
                'cofins': {'credito': round(cofins_credito, 2), 'debito': round(cofins_debito, 2), 'impacto': round(impacto_cofins, 2)},
                'impacto_total': round(impacto_total, 2),
                'qtd_entrada': entrada['qtd'],
                'qtd_saida': saida['qtd'],
                'produtos_entrada': sorted(entrada['produtos'], key=lambda x: x.get('descricao', ''))[:10],
                'produtos_saida': sorted(saida['produtos'], key=lambda x: x.get('descricao', ''))[:10],
                'motivo_classificacao': motivo,
                'analise_preco': analise_preco,
                'explicacao': motivo
            })
        
        # Oportunidade: crédito maior que débito
        elif impacto_total < -100:
            # Calcular margem para análise
            margem_valor = ((saida['valor'] - entrada['valor']) / entrada['valor'] * 100) if entrada['valor'] > 0 else 0
            
            # Gerar explicação concisa (sem repetir valores que já aparecem no grid)
            impostos_beneficio = []
            if -impacto_icms > 50:
                impostos_beneficio.append("ICMS")
            if -impacto_pis > 50:
                impostos_beneficio.append("PIS")
            if -impacto_cofins > 50:
                impostos_beneficio.append("COFINS")
            
            if len(impostos_beneficio) == 3:
                motivo = "Os créditos de ICMS, PIS e COFINS superam os débitos, gerando benefício fiscal."
            elif len(impostos_beneficio) == 2:
                motivo = f"Os créditos de {' e '.join(impostos_beneficio)} superam os débitos, gerando benefício."
            elif len(impostos_beneficio) == 1:
                motivo = f"O crédito de {impostos_beneficio[0]} supera significativamente o débito."
            else:
                motivo = "O somatório dos créditos tributários supera os débitos."
            
            # Análise de oportunidade
            if saida['valor'] < entrada['valor'] * 0.5:
                analise_preco = "💡 Compras muito superiores às vendas - possível formação de estoque"
            elif saida['valor'] < entrada['valor'] * 0.8:
                analise_preco = "💡 Crédito acumulado pode ser aproveitado em compensações futuras"
            else:
                analise_preco = "Boa performance fiscal neste NCM - crédito excedente"
            
            oportunidades.append({
                'tipo': 'CREDITO_EXCEDENTE',
                'ncm': ncm,
                'descricao': dados['descricao'],
                'entrada_valor': round(entrada['valor'], 2),
                'saida_valor': round(saida['valor'], 2),
                'margem_percentual': round(margem_valor, 2),
                'icms': {'credito': round(icms_credito, 2), 'debito': round(icms_debito, 2), 'beneficio': round(-impacto_icms, 2)},
                'pis': {'credito': round(pis_credito, 2), 'debito': round(pis_debito, 2), 'beneficio': round(-impacto_pis, 2)},
                'cofins': {'credito': round(cofins_credito, 2), 'debito': round(cofins_debito, 2), 'beneficio': round(-impacto_cofins, 2)},
                'beneficio_total': round(-impacto_total, 2),
                'qtd_entrada': entrada['qtd'],
                'qtd_saida': saida['qtd'],
                'produtos_entrada': sorted(entrada['produtos'], key=lambda x: x.get('descricao', ''))[:10],
                'produtos_saida': sorted(saida['produtos'], key=lambda x: x.get('descricao', ''))[:10],
                'motivo_classificacao': motivo,
                'analise_preco': analise_preco,
                'explicacao': motivo
            })
    
    # Ordenar por impacto
    viloes.sort(key=lambda x: x['impacto_total'], reverse=True)
    oportunidades.sort(key=lambda x: x['beneficio_total'], reverse=True)
    
    # Agrupar por keyword
    viloes_por_keyword = []
    oportunidades_por_keyword = []
    
    for keyword, dados in produtos_por_keyword.items():
        entrada = dados['entrada']
        saida = dados['saida']
        
        if entrada['qtd'] == 0 and saida['qtd'] == 0:
            continue
        
        impacto_icms = saida['icms'] - entrada['icms']
        impacto_pis = saida['pis'] - entrada['pis']
        impacto_cofins = saida['cofins'] - entrada['cofins']
        impacto_total = impacto_icms + impacto_pis + impacto_cofins
        
        item = {
            'keyword': keyword,
            'entrada_valor': round(entrada['valor'], 2),
            'saida_valor': round(saida['valor'], 2),
            'icms': {'credito': round(entrada['icms'], 2), 'debito': round(saida['icms'], 2)},
            'pis': {'credito': round(entrada['pis'], 2), 'debito': round(saida['pis'], 2)},
            'cofins': {'credito': round(entrada['cofins'], 2), 'debito': round(saida['cofins'], 2)},
            'impacto_total': round(impacto_total, 2),
            'qtd_entrada': entrada['qtd'],
            'qtd_saida': saida['qtd'],
            'produtos': entrada['produtos'][:10] + saida['produtos'][:10]
        }
        
        if impacto_total > 50:
            viloes_por_keyword.append(item)
        elif impacto_total < -50:
            item['beneficio_total'] = round(-impacto_total, 2)
            oportunidades_por_keyword.append(item)
    
    viloes_por_keyword.sort(key=lambda x: x['impacto_total'], reverse=True)
    oportunidades_por_keyword.sort(key=lambda x: x.get('beneficio_total', 0), reverse=True)
    
    # Gerar análise geral automática
    analise_geral = {
        "conclusao": "",
        "pontos_atencao": [],
        "recomendacoes": []
    }
    
    impacto_total_viloes = sum(v['impacto_total'] for v in viloes)
    beneficio_total_oportunidades = sum(o['beneficio_total'] for o in oportunidades)
    saldo_tributario = beneficio_total_oportunidades - impacto_total_viloes
    
    # Conclusão geral
    if saldo_tributario > 0:
        analise_geral["conclusao"] = f"📊 BALANÇO POSITIVO: A empresa tem mais créditos tributários do que débitos nos NCMs analisados. Saldo favorável de R$ {saldo_tributario:,.2f}."
    elif saldo_tributario < -1000:
        analise_geral["conclusao"] = f"⚠️ ATENÇÃO: A empresa tem um impacto tributário negativo significativo de R$ {abs(saldo_tributario):,.2f}. Os 'vilões' superam as 'oportunidades'."
    else:
        analise_geral["conclusao"] = f"📊 BALANÇO EQUILIBRADO: Diferença de R$ {abs(saldo_tributario):,.2f} entre débitos e créditos tributários."
    
    # Pontos de atenção
    if viloes:
        # Top 3 vilões
        for i, v in enumerate(viloes[:3]):
            if v['impacto_total'] > 500:
                ponto = f"NCM {v['ncm']} ({v['descricao'][:30]}): Impacto de R$ {v['impacto_total']:,.2f}"
                if v.get('margem_percentual', 0) < 15:
                    ponto += f" | MARGEM BAIXA ({v.get('margem_percentual', 0):.1f}%) - RISCO DE PREJUÍZO"
                analise_geral["pontos_atencao"].append(ponto)
    
    # Verificar margens apertadas
    ncms_margem_baixa = [v for v in viloes if v.get('margem_percentual', 100) < 15 and v['impacto_total'] > 200]
    if ncms_margem_baixa:
        analise_geral["pontos_atencao"].append(f"🔴 {len(ncms_margem_baixa)} NCM(s) com margem abaixo de 15% e impacto tributário alto - revisar precificação urgente")
    
    # Verificar desequilíbrio entrada/saída
    ncms_estoque = [v for v in viloes if v['entrada_valor'] > v['saida_valor'] * 2]
    if ncms_estoque:
        analise_geral["pontos_atencao"].append(f"📦 {len(ncms_estoque)} NCM(s) com compras muito superiores às vendas - verificar giro de estoque")
    
    # Recomendações
    if impacto_total_viloes > 1000:
        analise_geral["recomendacoes"].append("📋 Revisar precificação dos produtos 'vilões' considerando a carga tributária real")
    
    if any(v['icms'].get('impacto', 0) > 300 for v in viloes):
        analise_geral["recomendacoes"].append("🏷️ Verificar se há benefícios fiscais de ICMS aplicáveis aos NCMs com maior impacto")
    
    if any(v['pis'].get('impacto', 0) + v['cofins'].get('impacto', 0) > 200 for v in viloes):
        analise_geral["recomendacoes"].append("📊 Verificar se os NCMs vilões são monofásicos ou com alíquota reduzida de PIS/COFINS")
    
    if beneficio_total_oportunidades > 500:
        analise_geral["recomendacoes"].append("💰 Aproveitar os créditos acumulados das 'oportunidades' para compensação tributária")
    
    # Análise por categoria
    if viloes_por_keyword:
        categorias_criticas = [k['keyword'].upper() for k in viloes_por_keyword[:3] if k['impacto_total'] > 300]
        if categorias_criticas:
            analise_geral["pontos_atencao"].append(f"📌 Categorias com maior impacto: {', '.join(categorias_criticas)}")
    
    return {
        "empresa": company.get('razao_social', ''),
        "competencia": competencia,
        "regime_tributario": regime,
        "resumo": {
            "total_viloes": len(viloes),
            "total_oportunidades": len(oportunidades),
            "impacto_total_viloes": round(impacto_total_viloes, 2),
            "beneficio_total_oportunidades": round(beneficio_total_oportunidades, 2),
            "saldo_tributario": round(saldo_tributario, 2)
        },
        "analise_geral": analise_geral,
        "por_ncm": {
            "viloes": viloes[:20],
            "oportunidades": oportunidades[:20]
        },
        "por_keyword": {
            "viloes": viloes_por_keyword[:15],
            "oportunidades": oportunidades_por_keyword[:15]
        }
    }


@api_router.get("/analise-pis-cofins-completa/{company_id}")
async def analise_pis_cofins_completa(
    company_id: str,
    competencia: str,
    current_user: User = Depends(get_current_user)
):
    """
    Análise COMPLETA de PIS/COFINS nas saídas:
    - Compara CST e alíquotas usados vs corretos por NCM e CFOP
    - Identifica NCMs monofásicos tributados indevidamente
    - Identifica CFOPs que não deveriam gerar débito
    - Calcula impacto financeiro real
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    regime = company.get('regime_tributario', 'lucro_real').lower().replace(' ', '_')
    if regime not in ALIQUOTAS_PADRAO:
        regime = 'lucro_real'
    
    aliq_padrao = ALIQUOTAS_PADRAO[regime]
    
    # Buscar documentos de saída
    documents = await db.xml_documents.find({
        "company_id": company_id,
        "competencia": competencia,
        "tipo": "saida"
    }, {"_id": 0}).to_list(100000)
    
    if not documents:
        return {
            "empresa": company.get('razao_social', ''),
            "competencia": competencia,
            "regime_tributario": regime,
            "total_documentos": 0,
            "total_produtos": 0,
            "resumo": {},
            "divergencias": []
        }
    
    def get_ncm_prefix(ncm_str):
        """Retorna o prefixo de 4 dígitos do NCM"""
        ncm_clean = str(ncm_str).replace('.', '').replace('-', '').strip()
        return ncm_clean[:4] if len(ncm_clean) >= 4 else ncm_clean
    
    def analisa_produto(produto, cfop):
        """Analisa um produto e retorna a classificação correta"""
        ncm = str(produto.get('ncm', '')).replace('.', '').replace('-', '').strip()
        ncm_prefix = ncm[:4] if len(ncm) >= 4 else ncm
        
        cst_pis_atual = str(produto.get('cst_pis', '') or '')
        cst_cofins_atual = str(produto.get('cst_cofins', '') or '')
        
        aliq_pis_atual = float(produto.get('p_pis', 0) or 0)
        aliq_cofins_atual = float(produto.get('p_cofins', 0) or 0)
        
        v_pis_atual = float(produto.get('v_pis', 0) or 0)
        v_cofins_atual = float(produto.get('v_cofins', 0) or 0)
        
        valor_produto = float(produto.get('valor_total', 0) or 0)
        bc_pis = float(produto.get('v_bc_pis', valor_produto) or valor_produto)
        bc_cofins = float(produto.get('v_bc_cofins', valor_produto) or valor_produto)
        
        # CSTs que indicam não-tributação (não geram débito)
        csts_nao_tributados = ['04', '05', '06', '07', '08', '09', '49']
        cst_pis_nao_tributado = cst_pis_atual in csts_nao_tributados
        cst_cofins_nao_tributado = cst_cofins_atual in csts_nao_tributados
        
        resultado = {
            'descricao': produto.get('descricao', ''),
            'codigo': produto.get('codigo', ''),
            'ncm': ncm,
            'cfop': cfop,
            'valor_produto': valor_produto,
            'bc_pis': bc_pis,
            'bc_cofins': bc_cofins,
            # Valores ATUAIS
            'cst_pis_atual': cst_pis_atual,
            'cst_cofins_atual': cst_cofins_atual,
            'aliq_pis_atual': aliq_pis_atual,
            'aliq_cofins_atual': aliq_cofins_atual,
            'v_pis_atual': v_pis_atual,
            'v_cofins_atual': v_cofins_atual,
            # Valores CORRETOS (a serem preenchidos)
            'cst_pis_correto': '',
            'cst_cofins_correto': '',
            'aliq_pis_correto': 0,
            'aliq_cofins_correto': 0,
            'v_pis_correto': 0,
            'v_cofins_correto': 0,
            # Análise
            'motivo': '',
            'tipo_divergencia': None,
            'divergente': False,
            'impacto_pis': 0,
            'impacto_cofins': 0
        }
        
        # 1. Verificar se CFOP não gera débito
        cfop_str = str(cfop)[:4]
        if cfop_str in CFOPS_SEM_DEBITO_SAIDA:
            info = CFOPS_SEM_DEBITO_SAIDA[cfop_str]
            resultado['cst_pis_correto'] = '08'  # Sem incidência
            resultado['cst_cofins_correto'] = '08'
            resultado['aliq_pis_correto'] = 0
            resultado['aliq_cofins_correto'] = 0
            resultado['v_pis_correto'] = 0
            resultado['v_cofins_correto'] = 0
            resultado['motivo'] = f"CFOP {cfop_str}: {info['motivo']}"
            
            # Só é divergência se PAGOU imposto quando não deveria
            # Se o CST atual já é não-tributado E valor é zero, está correto
            if v_pis_atual > 0.01 or v_cofins_atual > 0.01:
                resultado['divergente'] = True
                resultado['tipo_divergencia'] = 'CFOP_SEM_DEBITO'
                resultado['impacto_pis'] = v_pis_atual
                resultado['impacto_cofins'] = v_cofins_atual
            
            return resultado
        
        # 2. Verificar se NCM é monofásico
        if ncm_prefix in NCMS_MONOFASICOS:
            info = NCMS_MONOFASICOS[ncm_prefix]
            resultado['cst_pis_correto'] = '04'  # Monofásico - alíquota zero
            resultado['cst_cofins_correto'] = '04'
            resultado['aliq_pis_correto'] = 0
            resultado['aliq_cofins_correto'] = 0
            resultado['v_pis_correto'] = 0
            resultado['v_cofins_correto'] = 0
            resultado['motivo'] = f"{info['tipo']}: {info['motivo']}"
            
            # Só é divergência se PAGOU imposto quando não deveria
            if v_pis_atual > 0.01 or v_cofins_atual > 0.01:
                resultado['divergente'] = True
                resultado['tipo_divergencia'] = 'NCM_MONOFASICO'
                resultado['impacto_pis'] = v_pis_atual
                resultado['impacto_cofins'] = v_cofins_atual
            
            return resultado
        
        # 3. Verificar se NCM é alíquota zero específico
        if ncm_prefix in NCMS_ALIQUOTA_ZERO_ESPECIFICOS:
            info = NCMS_ALIQUOTA_ZERO_ESPECIFICOS[ncm_prefix]
            resultado['cst_pis_correto'] = '06'  # Alíquota zero
            resultado['cst_cofins_correto'] = '06'
            resultado['aliq_pis_correto'] = 0
            resultado['aliq_cofins_correto'] = 0
            resultado['v_pis_correto'] = 0
            resultado['v_cofins_correto'] = 0
            resultado['motivo'] = info['motivo']
            
            # Só é divergência se PAGOU imposto quando não deveria
            if v_pis_atual > 0.01 or v_cofins_atual > 0.01:
                resultado['divergente'] = True
                resultado['tipo_divergencia'] = 'NCM_ALIQUOTA_ZERO'
                resultado['impacto_pis'] = v_pis_atual
                resultado['impacto_cofins'] = v_cofins_atual
            
            return resultado
        
        # 4. Operação tributada normalmente
        resultado['cst_pis_correto'] = '01'  # Tributável
        resultado['cst_cofins_correto'] = '01'
        resultado['aliq_pis_correto'] = aliq_padrao['pis']
        resultado['aliq_cofins_correto'] = aliq_padrao['cofins']
        resultado['v_pis_correto'] = round(bc_pis * aliq_padrao['pis'] / 100, 2)
        resultado['v_cofins_correto'] = round(bc_cofins * aliq_padrao['cofins'] / 100, 2)
        resultado['motivo'] = 'Operação tributável normal'
        
        # Verificar se está tributando menos que deveria
        diff_pis = resultado['v_pis_correto'] - v_pis_atual
        diff_cofins = resultado['v_cofins_correto'] - v_cofins_atual
        
        # Tolerância de R$ 0.50 para arredondamentos
        if abs(diff_pis) > 0.50 or abs(diff_cofins) > 0.50:
            resultado['divergente'] = True
            resultado['tipo_divergencia'] = 'ALIQUOTA_INCORRETA'
            resultado['impacto_pis'] = round(diff_pis, 2)
            resultado['impacto_cofins'] = round(diff_cofins, 2)
        
        return resultado
    
    # Processar todos os documentos
    divergencias = []
    total_produtos = 0
    total_divergentes = 0
    
    resumo = {
        'total_valor_saidas': 0,
        'total_pis_declarado': 0,
        'total_cofins_declarado': 0,
        'total_pis_correto': 0,
        'total_cofins_correto': 0,
        'por_tipo_divergencia': {
            'CFOP_SEM_DEBITO': {'qtd': 0, 'impacto_pis': 0, 'impacto_cofins': 0},
            'NCM_MONOFASICO': {'qtd': 0, 'impacto_pis': 0, 'impacto_cofins': 0},
            'NCM_ALIQUOTA_ZERO': {'qtd': 0, 'impacto_pis': 0, 'impacto_cofins': 0},
            'ALIQUOTA_INCORRETA': {'qtd': 0, 'impacto_pis': 0, 'impacto_cofins': 0}
        }
    }
    
    for doc in documents:
        doc_info = {
            'documento_id': doc.get('id', ''),
            'numero_nfe': doc.get('numero_nfe', ''),
            'serie': doc.get('serie', '1'),
            'cliente': doc.get('destinatario_nome', ''),
            'cnpj_cliente': doc.get('destinatario_cnpj', ''),
            'data_emissao': doc.get('data_emissao', ''),
            'valor_total': float(doc.get('valor_total', 0) or 0),
            'produtos': []
        }
        
        resumo['total_valor_saidas'] += doc_info['valor_total']
        
        for produto in doc.get('produtos', []):
            total_produtos += 1
            cfop = produto.get('cfop', '')
            
            analise = analisa_produto(produto, cfop)
            
            resumo['total_pis_declarado'] += analise['v_pis_atual']
            resumo['total_cofins_declarado'] += analise['v_cofins_atual']
            resumo['total_pis_correto'] += analise['v_pis_correto']
            resumo['total_cofins_correto'] += analise['v_cofins_correto']
            
            if analise['divergente']:
                total_divergentes += 1
                doc_info['produtos'].append(analise)
                
                tipo = analise['tipo_divergencia']
                if tipo in resumo['por_tipo_divergencia']:
                    resumo['por_tipo_divergencia'][tipo]['qtd'] += 1
                    resumo['por_tipo_divergencia'][tipo]['impacto_pis'] += analise['impacto_pis']
                    resumo['por_tipo_divergencia'][tipo]['impacto_cofins'] += analise['impacto_cofins']
        
        if doc_info['produtos']:
            divergencias.append(doc_info)
    
    # Arredondar valores do resumo
    resumo['total_pis_declarado'] = round(resumo['total_pis_declarado'], 2)
    resumo['total_cofins_declarado'] = round(resumo['total_cofins_declarado'], 2)
    resumo['total_pis_correto'] = round(resumo['total_pis_correto'], 2)
    resumo['total_cofins_correto'] = round(resumo['total_cofins_correto'], 2)
    resumo['diferenca_pis'] = round(resumo['total_pis_declarado'] - resumo['total_pis_correto'], 2)
    resumo['diferenca_cofins'] = round(resumo['total_cofins_declarado'] - resumo['total_cofins_correto'], 2)
    resumo['diferenca_total'] = round(resumo['diferenca_pis'] + resumo['diferenca_cofins'], 2)
    
    for tipo in resumo['por_tipo_divergencia']:
        resumo['por_tipo_divergencia'][tipo]['impacto_pis'] = round(resumo['por_tipo_divergencia'][tipo]['impacto_pis'], 2)
        resumo['por_tipo_divergencia'][tipo]['impacto_cofins'] = round(resumo['por_tipo_divergencia'][tipo]['impacto_cofins'], 2)
        resumo['por_tipo_divergencia'][tipo]['impacto_total'] = round(
            resumo['por_tipo_divergencia'][tipo]['impacto_pis'] + resumo['por_tipo_divergencia'][tipo]['impacto_cofins'], 2
        )
    
    # Criar agrupamentos por produto e por NCM
    agrup_produto = {}
    agrup_ncm = {}
    
    for doc in divergencias:
        for prod in doc['produtos']:
            # Agrupamento por código do produto
            codigo = prod.get('codigo', '') or prod.get('descricao', '')[:30]
            if codigo not in agrup_produto:
                agrup_produto[codigo] = {
                    'codigo': codigo,
                    'descricao': prod.get('descricao', ''),
                    'ncm': prod.get('ncm', ''),
                    'cfop': prod.get('cfop', ''),
                    'qtd_ocorrencias': 0,
                    'valor_total': 0,
                    # CST e Alíquotas (média/moda)
                    'cst_pis_atual': prod.get('cst_pis_atual', ''),
                    'cst_pis_correto': prod.get('cst_pis_correto', ''),
                    'cst_cofins_atual': prod.get('cst_cofins_atual', ''),
                    'cst_cofins_correto': prod.get('cst_cofins_correto', ''),
                    'aliq_pis_atual': prod.get('aliq_pis_atual', 0),
                    'aliq_pis_correto': prod.get('aliq_pis_correto', 0),
                    'aliq_cofins_atual': prod.get('aliq_cofins_atual', 0),
                    'aliq_cofins_correto': prod.get('aliq_cofins_correto', 0),
                    # Valores
                    'v_pis_atual': 0,
                    'v_pis_correto': 0,
                    'v_cofins_atual': 0,
                    'v_cofins_correto': 0,
                    'impacto_pis': 0,
                    'impacto_cofins': 0,
                    'tipo_divergencia': prod.get('tipo_divergencia', ''),
                    'motivo': prod.get('motivo', '')
                }
            agrup_produto[codigo]['qtd_ocorrencias'] += 1
            agrup_produto[codigo]['valor_total'] += prod.get('valor_produto', 0)
            agrup_produto[codigo]['v_pis_atual'] += prod.get('v_pis_atual', 0)
            agrup_produto[codigo]['v_pis_correto'] += prod.get('v_pis_correto', 0)
            agrup_produto[codigo]['v_cofins_atual'] += prod.get('v_cofins_atual', 0)
            agrup_produto[codigo]['v_cofins_correto'] += prod.get('v_cofins_correto', 0)
            agrup_produto[codigo]['impacto_pis'] += prod.get('impacto_pis', 0)
            agrup_produto[codigo]['impacto_cofins'] += prod.get('impacto_cofins', 0)
            
            # Agrupamento por NCM
            ncm = prod.get('ncm', '')[:4]  # Primeiros 4 dígitos
            if ncm and ncm not in agrup_ncm:
                agrup_ncm[ncm] = {
                    'ncm': ncm,
                    'ncm_completo': prod.get('ncm', ''),
                    'produtos': set(),
                    'qtd_ocorrencias': 0,
                    'valor_total': 0,
                    # CST e Alíquotas
                    'cst_pis_atual': prod.get('cst_pis_atual', ''),
                    'cst_pis_correto': prod.get('cst_pis_correto', ''),
                    'cst_cofins_atual': prod.get('cst_cofins_atual', ''),
                    'cst_cofins_correto': prod.get('cst_cofins_correto', ''),
                    'aliq_pis_atual': prod.get('aliq_pis_atual', 0),
                    'aliq_pis_correto': prod.get('aliq_pis_correto', 0),
                    'aliq_cofins_atual': prod.get('aliq_cofins_atual', 0),
                    'aliq_cofins_correto': prod.get('aliq_cofins_correto', 0),
                    # Valores
                    'v_pis_atual': 0,
                    'v_pis_correto': 0,
                    'v_cofins_atual': 0,
                    'v_cofins_correto': 0,
                    'impacto_pis': 0,
                    'impacto_cofins': 0,
                    'tipo_divergencia': prod.get('tipo_divergencia', ''),
                    'motivo': prod.get('motivo', '')
                }
            if ncm:
                agrup_ncm[ncm]['produtos'].add(prod.get('descricao', '')[:50])
                agrup_ncm[ncm]['qtd_ocorrencias'] += 1
                agrup_ncm[ncm]['valor_total'] += prod.get('valor_produto', 0)
                agrup_ncm[ncm]['v_pis_atual'] += prod.get('v_pis_atual', 0)
                agrup_ncm[ncm]['v_pis_correto'] += prod.get('v_pis_correto', 0)
                agrup_ncm[ncm]['v_cofins_atual'] += prod.get('v_cofins_atual', 0)
                agrup_ncm[ncm]['v_cofins_correto'] += prod.get('v_cofins_correto', 0)
                agrup_ncm[ncm]['impacto_pis'] += prod.get('impacto_pis', 0)
                agrup_ncm[ncm]['impacto_cofins'] += prod.get('impacto_cofins', 0)
    
    # Converter sets para listas e arredondar valores
    for codigo in agrup_produto:
        agrup_produto[codigo]['valor_total'] = round(agrup_produto[codigo]['valor_total'], 2)
        agrup_produto[codigo]['v_pis_atual'] = round(agrup_produto[codigo]['v_pis_atual'], 2)
        agrup_produto[codigo]['v_pis_correto'] = round(agrup_produto[codigo]['v_pis_correto'], 2)
        agrup_produto[codigo]['v_cofins_atual'] = round(agrup_produto[codigo]['v_cofins_atual'], 2)
        agrup_produto[codigo]['v_cofins_correto'] = round(agrup_produto[codigo]['v_cofins_correto'], 2)
        agrup_produto[codigo]['impacto_pis'] = round(agrup_produto[codigo]['impacto_pis'], 2)
        agrup_produto[codigo]['impacto_cofins'] = round(agrup_produto[codigo]['impacto_cofins'], 2)
        agrup_produto[codigo]['impacto_total'] = round(
            agrup_produto[codigo]['impacto_pis'] + agrup_produto[codigo]['impacto_cofins'], 2
        )
    
    for ncm in agrup_ncm:
        agrup_ncm[ncm]['produtos'] = list(agrup_ncm[ncm]['produtos'])[:5]  # Max 5 exemplos
        agrup_ncm[ncm]['valor_total'] = round(agrup_ncm[ncm]['valor_total'], 2)
        agrup_ncm[ncm]['v_pis_atual'] = round(agrup_ncm[ncm]['v_pis_atual'], 2)
        agrup_ncm[ncm]['v_pis_correto'] = round(agrup_ncm[ncm]['v_pis_correto'], 2)
        agrup_ncm[ncm]['v_cofins_atual'] = round(agrup_ncm[ncm]['v_cofins_atual'], 2)
        agrup_ncm[ncm]['v_cofins_correto'] = round(agrup_ncm[ncm]['v_cofins_correto'], 2)
        agrup_ncm[ncm]['impacto_pis'] = round(agrup_ncm[ncm]['impacto_pis'], 2)
        agrup_ncm[ncm]['impacto_cofins'] = round(agrup_ncm[ncm]['impacto_cofins'], 2)
        agrup_ncm[ncm]['impacto_total'] = round(
            agrup_ncm[ncm]['impacto_pis'] + agrup_ncm[ncm]['impacto_cofins'], 2
        )
    
    # Ordenar por impacto
    agrup_produto_list = sorted(agrup_produto.values(), key=lambda x: -x['impacto_total'])
    agrup_ncm_list = sorted(agrup_ncm.values(), key=lambda x: -x['impacto_total'])
    
    return {
        "empresa": company.get('razao_social', ''),
        "competencia": competencia,
        "regime_tributario": regime.replace('_', ' ').title(),
        "aliquotas_regime": aliq_padrao,
        "total_documentos": len(documents),
        "total_produtos": total_produtos,
        "total_divergentes": total_divergentes,
        "resumo": resumo,
        "divergencias": divergencias,
        "agrupamentos": {
            "por_produto": agrup_produto_list,
            "por_ncm": agrup_ncm_list
        }
    }


