def obter_categoria_por_cfop(cfop: str) -> str:
    """
    Retorna a categoria de classificação baseada no CFOP.
    NUNCA retorna None - sempre classifica (padrão é revenda).
    """
    cfop = str(cfop).strip()
    
    # Busca direta
    if cfop in CFOP_PARA_CATEGORIA:
        return CFOP_PARA_CATEGORIA[cfop]
    
    # CFOPs de DEVOLUÇÃO (natureza devolução)
    # ENTRADAS: 1201-1210 (estadual), 2201-2210 (interestadual), 1411, 2411 (anulação), etc.
    # SAÍDAS: 5201-5210 (estadual), 6201-6210 (interestadual) - devolução de compras
    cfops_devolucao = [
        # Devoluções de ENTRADA
        '1201', '1202', '1203', '1204', '1205', '1206', '1207', '1208', '1209', '1210',
        '1411', '1410', '1503', '1504', '1553', '1660', '1661', '1662',
        '2201', '2202', '2203', '2204', '2205', '2206', '2207', '2208', '2209', '2210',
        '2411', '2410', '2503', '2504', '2553', '2660', '2661', '2662',
        # Devoluções de SAÍDA (devolução de compra ao fornecedor)
        '5201', '5202', '5203', '5204', '5205', '5206', '5207', '5208', '5209', '5210',
        '5411', '5412', '5413', '5503', '5553', '5660', '5661', '5662',
        '6201', '6202', '6203', '6204', '6205', '6206', '6207', '6208', '6209', '6210',
        '6411', '6412', '6413', '6503', '6553', '6660', '6661', '6662',
        # Devoluções de exportação/importação
        '3201', '3202', '3211', '7201', '7202', '7210', '7211'
    ]
    if cfop in cfops_devolucao:
        return 'devolucao'
    
    # Regras genéricas baseadas no padrão do CFOP
    if cfop.startswith(('1102', '2102', '1403', '2403')):
        return 'revenda'
    if cfop.startswith(('1101', '2101', '1401', '2401')):
        return 'insumo'
    if cfop.startswith(('1551', '2551', '1406', '2406')):
        return 'ativo_imobilizado'
    if cfop.startswith(('1556', '2556', '1253', '1303', '1407', '2407')):
        return 'despesa'
    if cfop.startswith(('165', '265', '1653', '2653')):  # CFOPs de combustível
        return 'combustivel'
    
    # Bonificações e amostras têm categorias próprias
    if cfop in ('1910', '2910'):
        return 'bonificacao'
    if cfop in ('1911', '2911'):
        return 'amostra_gratis'
    
    # 1949/2949 são "Outras Entradas"
    if cfop in ('1949', '2949'):
        return 'outras_entradas'
    
    # 1128/2128 são aplicação em serviços
    if cfop in ('1128', '2128'):
        return 'servico_aplicacao'
    
    # PADRÃO: Se não identificar, assume como compra para revenda (nunca pendente)
    return 'revenda'


def obter_nome_categoria(categoria: str) -> str:
    """Retorna o nome amigável de uma categoria - NUNCA retorna Pendente"""
    if not categoria or categoria.lower() in ['pendente', 'none', 'null', '']:
        return 'Compra p/ Revenda'  # Padrão é revenda, nunca pendente
    return CATEGORIA_NOMES.get(categoria, categoria.replace('_', ' ').title())

@api_router.get("/alertas-cfop/{company_id}")
async def alertas_cfop_operacoes_distintas(
    company_id: str,
    competencia: str,
    current_user: User = Depends(get_current_user)
):
    """
    Busca documentos de entrada com produtos pendentes de revisão de CFOP.
    Estes são produtos que foram convertidos automaticamente durante o upload
    (CFOPs de operações distintas como bonificação, remessa, etc.)
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Buscar documentos de entrada que tenham produtos pendentes de revisão
    documents = await db.xml_documents.find({
        "company_id": company_id,
        "competencia": competencia,
        "tipo": "entrada"
    }, {"_id": 0}).to_list(100000)
    
    alertas = []
    total_pendentes = 0
    
    for doc in documents:
        doc_alertas = []
        
        for idx, prod in enumerate(doc.get('produtos', [])):
            # Verificar se produto está pendente de revisão
            if prod.get('pendente_revisao_cfop'):
                cfop_atual = str(prod.get('cfop', ''))
                cfop_original = str(prod.get('cfop_original_emissor', ''))
                natureza = prod.get('natureza_operacao_original', '')
                
                # Sugestões de conversão - RESPEITANDO ST
                cfop_compra = cfop_atual.replace('9', '0') if '9' in cfop_atual else cfop_atual[:2] + '02'
                
                # Verificar se é operação com ST pelo CFOP original
                cfops_st = ['5403', '5405', '5408', '5409', '5410', '5411', '5412', '5413', '5414', '5415',
                           '6403', '6404', '6405', '6408', '6409', '6410', '6411', '6412', '6413', '6414', '6415']
                is_st = cfop_original in cfops_st
                
                if cfop_atual.startswith('1'):
                    cfop_compra = '1403' if is_st else '1102'  # Compra estadual (com ou sem ST)
                elif cfop_atual.startswith('2'):
                    cfop_compra = '2403' if is_st else '2102'  # Compra interestadual (com ou sem ST)
                
                doc_alertas.append({
                    'produto_idx': idx,
                    'produto_codigo': prod.get('codigo', ''),
                    'produto_descricao': prod.get('descricao', ''),
                    'ncm': prod.get('ncm', ''),
                    'valor': prod.get('valor_total', 0),
                    'cfop_original_emissor': cfop_original,
                    'cfop_atual': cfop_atual,
                    'natureza_operacao': natureza,
                    'opcoes': {
                        'manter_natureza': {
                            'cfop': cfop_atual,
                            'descricao': f'Manter como {natureza}'
                        },
                        'converter_compra': {
                            'cfop': cfop_compra,
                            'descricao': f'Converter para compra ({cfop_compra})'
                        }
                    }
                })
                total_pendentes += 1
        
        if doc_alertas:
            alertas.append({
                'documento_id': doc.get('id', ''),
                'numero_nfe': doc.get('numero_nfe', ''),
                'emitente': doc.get('emitente_nome', ''),
                'data_emissao': doc.get('data_emissao', ''),
                'valor_total': doc.get('valor_total', 0),
                'qtd_pendentes': len(doc_alertas),
                'produtos': doc_alertas
            })
    
    return {
        "empresa": company['razao_social'],
        "competencia": competencia,
        "total_documentos_entrada": len(documents),
        "documentos_com_alerta": len(alertas),
        "total_produtos_pendentes": total_pendentes,
        "alertas": alertas
    }

@api_router.get("/alertas-cfop/{company_id}/agrupado")
async def alertas_cfop_agrupado_por_cfop(
    company_id: str,
    competencia: str,
    current_user: User = Depends(get_current_user)
):
    """
    Retorna alertas de CFOP AGRUPADOS por CFOP, para facilitar ação em lote.
    Cada grupo contém todos os produtos com o mesmo CFOP pendente de revisão.
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Buscar documentos de entrada que tenham produtos pendentes de revisão
    documents = await db.xml_documents.find({
        "company_id": company_id,
        "competencia": competencia,
        "tipo": "entrada"
    }, {"_id": 0}).to_list(100000)
    
    # Agrupar por CFOP atual
    grupos_cfop = {}
    total_pendentes = 0
    
    for doc in documents:
        for idx, prod in enumerate(doc.get('produtos', [])):
            if prod.get('pendente_revisao_cfop'):
                cfop_atual = str(prod.get('cfop', ''))
                cfop_original = str(prod.get('cfop_original_emissor', ''))
                natureza = prod.get('natureza_operacao_original', '')
                
                # Sugestões de conversão - RESPEITANDO ST
                cfop_compra = cfop_atual.replace('9', '0') if '9' in cfop_atual else cfop_atual[:2] + '02'
                
                # Verificar se é operação com ST pelo CFOP original
                cfops_st = ['5403', '5405', '5408', '5409', '5410', '5411', '5412', '5413', '5414', '5415',
                           '6403', '6404', '6405', '6408', '6409', '6410', '6411', '6412', '6413', '6414', '6415']
                is_st = cfop_original in cfops_st
                
                if cfop_atual.startswith('1'):
                    cfop_compra = '1403' if is_st else '1102'  # Compra estadual (com ou sem ST)
                elif cfop_atual.startswith('2'):
                    cfop_compra = '2403' if is_st else '2102'  # Compra interestadual (com ou sem ST)
                
                # Criar grupo se não existir
                if cfop_atual not in grupos_cfop:
                    # Buscar descrição do CFOP
                    cfop_info = CFOPS_OPERACOES_DISTINTAS_GLOBAL.get(cfop_original, {})
                    descricao_cfop = cfop_info.get('descricao', natureza or f'Operação {cfop_atual}')
                    
                    # Obter categoria sugerida para cada opção
                    categoria_manter = obter_categoria_por_cfop(cfop_atual)
                    categoria_compra = obter_categoria_por_cfop(cfop_compra)
                    
                    grupos_cfop[cfop_atual] = {
                        'cfop': cfop_atual,
                        'cfop_original': cfop_original,
                        'descricao': descricao_cfop,
                        'natureza_operacao': natureza,
                        'quantidade': 0,
                        'valor_total': 0,
                        'produtos': [],
                        'sugestao_manter': {
                            'cfop': cfop_atual,
                            'descricao': f'Manter {cfop_atual} - {descricao_cfop}',
                            'categoria': categoria_manter,
                            'categoria_nome': obter_nome_categoria(categoria_manter)
                        },
                        'sugestao_compra': {
                            'cfop': cfop_compra,
                            'descricao': f'Converter para {cfop_compra} - Compra',
                            'categoria': categoria_compra,
                            'categoria_nome': obter_nome_categoria(categoria_compra)
                        }
                    }
                
                # Adicionar produto ao grupo
                grupos_cfop[cfop_atual]['quantidade'] += 1
                grupos_cfop[cfop_atual]['valor_total'] += prod.get('valor_total', 0)
                grupos_cfop[cfop_atual]['produtos'].append({
                    'documento_id': doc.get('id', ''),
                    'produto_idx': idx,
                    'numero_nfe': doc.get('numero_nfe', ''),
                    'emitente': doc.get('emitente_nome', ''),
                    'data_emissao': doc.get('data_emissao', ''),
                    'produto_codigo': prod.get('codigo', ''),
                    'produto_descricao': prod.get('descricao', ''),
                    'ncm': prod.get('ncm', ''),
                    'valor': prod.get('valor_total', 0),
                    'cfop_original_emissor': cfop_original
                })
                total_pendentes += 1
    
    # Converter para lista ordenada por quantidade (maior primeiro)
    grupos_lista = sorted(grupos_cfop.values(), key=lambda x: -x['quantidade'])
    
    return {
        "empresa": company['razao_social'],
        "competencia": competencia,
        "total_grupos": len(grupos_lista),
        "total_produtos_pendentes": total_pendentes,
        "grupos": grupos_lista
    }

@api_router.post("/alertas-cfop/resolver-grupo")
async def resolver_alerta_cfop_por_grupo(
    company_id: str,
    competencia: str,
    cfop_atual: str,
    novo_cfop: str,
    categoria: str = None,  # Se não informado, será inferida pelo CFOP
    salvar_regra: bool = False,
    current_user: User = Depends(get_current_user)
):
    """
    Resolve todos os alertas de um CFOP específico em lote.
    Também classifica automaticamente os produtos baseado no CFOP.
    """
    documents = await db.xml_documents.find({
        "company_id": company_id,
        "competencia": competencia,
        "tipo": "entrada"
    }).to_list(100000)
    
    # Determinar categoria baseada no CFOP se não foi informada
    categoria_final = categoria or obter_categoria_por_cfop(novo_cfop)
    
    total_resolvidos = 0
    
    for doc in documents:
        produtos = doc.get('produtos', [])
        atualizado = False
        
        for idx, prod in enumerate(produtos):
            if prod.get('pendente_revisao_cfop') and str(prod.get('cfop', '')) == cfop_atual:
                cfop_anterior = prod.get('cfop', '')
                
                # Atualizar CFOP
                produtos[idx]['cfop'] = novo_cfop
                produtos[idx]['pendente_revisao_cfop'] = False
                produtos[idx]['cfop_revisado_por'] = current_user.id
                produtos[idx]['cfop_revisado_em'] = datetime.now(timezone.utc).isoformat()
                
                # CLASSIFICAR AUTOMATICAMENTE baseado no CFOP
                if categoria_final:
                    produtos[idx]['categoria'] = categoria_final
                    produtos[idx]['categoria_classificada'] = categoria_final  # Campo correto para classificação
                    produtos[idx]['categoria_origem'] = 'cfop_auto'
                    produtos[idx]['categoria_classificada_em'] = datetime.now(timezone.utc).isoformat()
                
                atualizado = True
                total_resolvidos += 1
                
                # Salvar regra se solicitado
                if salvar_regra and total_resolvidos == 1:  # Salvar apenas uma vez
                    await db.learned_rules.insert_one({
                        "id": str(uuid.uuid4()),
                        "company_id": company_id,
                        "cfop_original": cfop_anterior,
                        "cfop_correto": novo_cfop,
                        "categoria_correta": categoria_final or "conversao_cfop_grupo",
                        "motivo": f"Conversão em lote de {cfop_anterior} para {novo_cfop}" + (f" → {categoria_final}" if categoria_final else ""),
                        "aprendido_de": "user_batch_correction",
                        "created_by": current_user.id,
                        "created_at": datetime.now(timezone.utc)
                    })
        
        if atualizado:
            await db.xml_documents.update_one(
                {"id": doc['id']},
                {"$set": {"produtos": produtos}}
            )
    
    categoria_msg = f" e classificados como '{categoria_final}'" if categoria_final else ""
    return {
        "success": True, 
        "message": f"{total_resolvidos} produto(s) atualizados de {cfop_atual} para {novo_cfop}{categoria_msg}",
        "total_resolvidos": total_resolvidos,
        "categoria_atribuida": categoria_final
    }

@api_router.post("/alertas-cfop/resolver-individual")
async def resolver_alerta_cfop_individual(
    documento_id: str,
    produto_idx: int,
    novo_cfop: str,
    categoria: str = None,  # Se não informado, será inferida pelo CFOP
    salvar_regra: bool = False,
    current_user: User = Depends(get_current_user)
):
    """
    Resolve um alerta de CFOP individual.
    Também classifica automaticamente o produto baseado no CFOP.
    """
    doc = await db.xml_documents.find_one({"id": documento_id})
    if not doc:
        raise HTTPException(status_code=404, detail="Documento não encontrado")
    
    produtos = doc.get('produtos', [])
    if produto_idx >= len(produtos):
        raise HTTPException(status_code=404, detail="Produto não encontrado")
    
    produto = produtos[produto_idx]
    cfop_anterior = produto.get('cfop', '')
    
    # Determinar categoria baseada no CFOP se não foi informada
    categoria_final = categoria or obter_categoria_por_cfop(novo_cfop)
    
    # Atualizar CFOP
    produtos[produto_idx]['cfop'] = novo_cfop
    produtos[produto_idx]['pendente_revisao_cfop'] = False
    produtos[produto_idx]['cfop_revisado_por'] = current_user.id
    produtos[produto_idx]['cfop_revisado_em'] = datetime.now(timezone.utc).isoformat()
    
    # CLASSIFICAR AUTOMATICAMENTE baseado no CFOP
    if categoria_final:
        produtos[produto_idx]['categoria'] = categoria_final
        produtos[produto_idx]['categoria_classificada'] = categoria_final  # Campo correto para classificação
        produtos[produto_idx]['categoria_origem'] = 'cfop_auto'
        produtos[produto_idx]['categoria_classificada_em'] = datetime.now(timezone.utc).isoformat()
    
    await db.xml_documents.update_one(
        {"id": documento_id},
        {"$set": {"produtos": produtos}}
    )
    
    # Salvar regra se solicitado
    if salvar_regra:
        await db.learned_rules.insert_one({
            "id": str(uuid.uuid4()),
            "company_id": doc.get('company_id'),
            "produto_descricao": produto.get('descricao', ''),
            "produto_codigo": produto.get('codigo', ''),
            "ncm": produto.get('ncm', ''),
            "cfop_original": produto.get('cfop_original_emissor', cfop_anterior),
            "cfop_correto": novo_cfop,
            "categoria_correta": categoria_final or "conversao_cfop",
            "motivo": f"Conversão manual de {cfop_anterior} para {novo_cfop}" + (f" → {categoria_final}" if categoria_final else ""),
            "aprendido_de": "user_correction",
            "created_by": current_user.id,
            "created_at": datetime.now(timezone.utc)
        })
    
    categoria_msg = f" e classificado como '{categoria_final}'" if categoria_final else ""
    return {
        "success": True, 
        "message": f"CFOP alterado de {cfop_anterior} para {novo_cfop}{categoria_msg}",
        "categoria_atribuida": categoria_final
    }

@api_router.post("/alertas-cfop/resolver-lote")
async def resolver_alerta_cfop_lote(
    company_id: str,
    competencia: str,
    acao: str,  # 'manter_natureza' ou 'converter_compra'
    current_user: User = Depends(get_current_user)
):
    """
    Resolve todos os alertas de CFOP em lote.
    acao: 'manter_natureza' mantém o CFOP convertido, 'converter_compra' converte para CFOP de compra
    """
    documents = await db.xml_documents.find({
        "company_id": company_id,
        "competencia": competencia,
        "tipo": "entrada"
    }).to_list(100000)
    
    total_resolvidos = 0
    
    for doc in documents:
        produtos = doc.get('produtos', [])
        atualizado = False
        
        for idx, prod in enumerate(produtos):
            if prod.get('pendente_revisao_cfop'):
                cfop_atual = prod.get('cfop', '')
                
                if acao == 'converter_compra':
                    # Converter para CFOP de compra - RESPEITANDO ST
                    cfop_original = prod.get('cfop_original_emissor', '')
                    cfops_st = ['5403', '5405', '5408', '5409', '5410', '5411', '5412', '5413', '5414', '5415',
                               '6403', '6404', '6405', '6408', '6409', '6410', '6411', '6412', '6413', '6414', '6415']
                    is_st = cfop_original in cfops_st
                    
                    if cfop_atual.startswith('1'):
                        novo_cfop = '1403' if is_st else '1102'
                    elif cfop_atual.startswith('2'):
                        novo_cfop = '2403' if is_st else '2102'
                    else:
                        novo_cfop = cfop_atual
                    produtos[idx]['cfop'] = novo_cfop
                # Se 'manter_natureza', mantém o CFOP atual
                
                produtos[idx]['pendente_revisao_cfop'] = False
                produtos[idx]['cfop_revisado_por'] = current_user.id
                produtos[idx]['cfop_revisado_em'] = datetime.now(timezone.utc).isoformat()
                produtos[idx]['acao_lote'] = acao
                atualizado = True
                total_resolvidos += 1
        
        if atualizado:
            await db.xml_documents.update_one(
                {"id": doc['id']},
                {"$set": {"produtos": produtos}}
            )
    
    return {
        "success": True, 
        "total_resolvidos": total_resolvidos,
        "acao": acao,
        "message": f"{total_resolvidos} produtos atualizados com ação '{acao}'"
    }

@api_router.post("/alertas-cfop/resolver-ia")
async def resolver_alerta_cfop_ia(
    company_id: str,
    competencia: str,
    comando: str,
    current_user: User = Depends(get_current_user)
):
    """
    Resolve alertas de CFOP usando comando de IA.
    Ex: "classificar bonificações como 1910", "converter todas remessas para compra"
    """
    from emergentintegrations.llm.chat import LlmChat, UserMessage
    
    # Buscar produtos pendentes
    documents = await db.xml_documents.find({
        "company_id": company_id,
        "competencia": competencia,
        "tipo": "entrada"
    }).to_list(100000)
    
    produtos_pendentes = []
    for doc in documents:
        for idx, prod in enumerate(doc.get('produtos', [])):
            if prod.get('pendente_revisao_cfop'):
                produtos_pendentes.append({
                    'doc_id': doc['id'],
                    'idx': idx,
                    'descricao': prod.get('descricao', ''),
                    'codigo': prod.get('codigo', ''),
                    'ncm': prod.get('ncm', ''),
                    'cfop_atual': prod.get('cfop', ''),
                    'cfop_original': prod.get('cfop_original_emissor', ''),
                    'natureza': prod.get('natureza_operacao_original', ''),
                    'valor': prod.get('valor_total', 0)
                })
    
    if not produtos_pendentes:
        return {"success": True, "message": "Nenhum produto pendente de revisão", "alteracoes": []}
    
    # Preparar contexto para IA
    produtos_texto = "\n".join([
        f"- {p['descricao']} (NCM: {p['ncm']}, CFOP atual: {p['cfop_atual']}, Original emissor: {p['cfop_original']}, Natureza: {p['natureza']})"
        for p in produtos_pendentes[:50]  # Limitar para não estourar contexto
    ])
    
    prompt = f"""Você é um assistente fiscal especializado. O usuário quer aplicar uma regra para classificar CFOPs.

Comando do usuário: "{comando}"

Produtos pendentes de classificação:
{produtos_texto}

CFOPs de entrada comuns:
- 1102: Compra para comercialização (estadual)
- 2102: Compra para comercialização (interestadual)
- 1910: Entrada de bonificação (estadual)
- 2910: Entrada de bonificação (interestadual)
- 1949: Outra entrada não especificada (estadual)
- 2949: Outra entrada não especificada (interestadual)

Com base no comando do usuário, retorne um JSON com as alterações a serem feitas.
Formato: {{"alteracoes": [{{"descricao_produto": "...", "cfop_atual": "...", "novo_cfop": "...", "motivo": "..."}}]}}

Se o comando não for claro ou não se aplicar a nenhum produto, retorne {{"alteracoes": [], "erro": "mensagem explicativa"}}
"""

    try:
        llm = LlmChat(
            api_key=os.environ.get('EMERGENT_LLM_KEY'),
            session_id=f"cfop-resolver-{company_id}-{competencia}",
            system_message="Você é um assistente fiscal especializado em classificação de CFOPs. Responda sempre em formato JSON válido."
        ).with_model("gemini", "gemini-2.5-flash")
        response = await llm.send_message(UserMessage(text=prompt))
        
        # Extrair JSON da resposta
        response_text = response if isinstance(response, str) else str(response)
        json_match = re.search(r'\{[\s\S]*\}', response_text)
        
        if json_match:
            resultado = json.loads(json_match.group())
        else:
            # Não encontrou JSON, mas pode ter uma mensagem da IA
            return {"success": True, "message": response_text, "alteracoes": [], "total_alteracoes": 0}
        
        if resultado.get('erro'):
            return {"success": True, "message": resultado['erro'], "alteracoes": [], "total_alteracoes": 0}
        
        # Aplicar alterações em LOTE - processar TODOS os produtos que correspondem
        alteracoes_aplicadas = []
        docs_atualizados = {}  # Cache para evitar múltiplas leituras do mesmo documento
        
        for alt in resultado.get('alteracoes', []):
            cfop_destino = alt.get('novo_cfop', '')
            if not cfop_destino:
                continue
                
            # Encontrar TODOS os produtos correspondentes
            for p in produtos_pendentes:
                # Match por descrição parcial, CFOP atual, ou natureza
                desc_match = alt.get('descricao_produto', '').lower() in p['descricao'].lower() if alt.get('descricao_produto') else False
                cfop_match = p['cfop_atual'] == alt.get('cfop_atual')
                natureza_match = alt.get('natureza', '').lower() in p.get('natureza', '').lower() if alt.get('natureza') else False
                
                # Se o comando menciona "todas" ou "todos", aplicar a todos com CFOP correspondente
                aplicar_todos = 'todas' in comando.lower() or 'todos' in comando.lower()
                
                if cfop_match or desc_match or natureza_match or aplicar_todos:
                    doc_id = p['doc_id']
                    
                    # Buscar documento do cache ou do banco
                    if doc_id not in docs_atualizados:
                        doc = await db.xml_documents.find_one({"id": doc_id})
                        if doc:
                            docs_atualizados[doc_id] = doc.get('produtos', [])
                    
                    if doc_id in docs_atualizados:
                        produtos_doc = docs_atualizados[doc_id]
                        if p['idx'] < len(produtos_doc):
                            produtos_doc[p['idx']]['cfop'] = cfop_destino
                            produtos_doc[p['idx']]['pendente_revisao_cfop'] = False
                            produtos_doc[p['idx']]['cfop_revisado_por'] = current_user.id
                            produtos_doc[p['idx']]['cfop_revisado_por_ia'] = True
                            produtos_doc[p['idx']]['motivo_ia'] = alt.get('motivo', comando)
                            
                            alteracoes_aplicadas.append({
                                'produto': p['descricao'],
                                'cfop_anterior': p['cfop_atual'],
                                'cfop_novo': cfop_destino,
                                'motivo': alt.get('motivo', comando)
                            })
        
        # Salvar todas as atualizações no banco
        for doc_id, produtos in docs_atualizados.items():
            await db.xml_documents.update_one(
                {"id": doc_id},
                {"$set": {"produtos": produtos}}
            )
        
        return {
            "success": True,
            "total_alteracoes": len(alteracoes_aplicadas),
            "alteracoes": alteracoes_aplicadas,
            "comando_original": comando
        }
        
    except Exception as e:
        return {"success": False, "message": f"Erro ao processar com IA: {str(e)}", "alteracoes": []}

@api_router.post("/converter-cfop")
async def converter_cfop_documento(
    documento_id: str,
    produto_codigo: str,
    novo_cfop: str,
    aplicar_regra: bool = False,
    current_user: User = Depends(get_current_user)
):
    """
    Converte o CFOP de um produto específico em um documento.
    Se aplicar_regra=True, salva como regra para aplicação futura.
    """
    doc = await db.xml_documents.find_one({"id": documento_id})
    if not doc:
        raise HTTPException(status_code=404, detail="Documento não encontrado")
    
    # Atualizar o CFOP do produto
    produtos = doc.get('produtos', [])
    atualizado = False
    
    for i, prod in enumerate(produtos):
        if prod.get('codigo') == produto_codigo:
            produtos[i]['cfop'] = novo_cfop
            produtos[i]['cfop_original'] = prod.get('cfop', '')
            produtos[i]['cfop_convertido'] = True
            atualizado = True
            break
    
    if not atualizado:
        raise HTTPException(status_code=404, detail="Produto não encontrado no documento")
    
    # Atualizar documento no banco
    await db.xml_documents.update_one(
        {"id": documento_id},
        {"$set": {"produtos": produtos}}
    )
    
    # Se solicitado, salvar como regra
    if aplicar_regra:
        prod_info = next((p for p in produtos if p.get('codigo') == produto_codigo), {})
        await db.learned_rules.insert_one({
            "id": str(uuid.uuid4()),
            "company_id": doc.get('company_id'),
            "produto_descricao": prod_info.get('descricao', ''),
            "produto_codigo": produto_codigo,
            "ncm": prod_info.get('ncm', ''),
            "categoria_correta": "conversao_cfop",
            "cfop_correto": novo_cfop,
            "cfop_original": prod_info.get('cfop_original', ''),
            "motivo": f"Conversão de {prod_info.get('cfop_original', '')} para {novo_cfop}",
            "aprendido_de": "user_correction",
            "created_by": current_user.id,
            "created_at": datetime.now(timezone.utc)
        })
    
    return {"success": True, "message": f"CFOP convertido para {novo_cfop}"}

@api_router.get("/reports/by-product/{company_id}")
async def report_by_product(
    company_id: str,
    competencia: Optional[str] = None,
    tipo: Optional[str] = None,
    current_user: User = Depends(get_current_user)
):
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    query = {"company_id": company_id}
    if competencia:
        query['competencia'] = competencia
    if tipo and tipo != 'todos':
        query['tipo'] = tipo
    
    documents = await db.xml_documents.find(query, {"_id": 0}).to_list(100000)
    
    product_summary = defaultdict(lambda: {
        'descricao': '',
        'ncm': '',
        'quantidade': 0,
        'valor_total': 0,
        'credito_icms': 0,
        'credito_pis': 0,
        'credito_cofins': 0,
        'documentos': 0
    })
    
    for doc in documents:
        for prod in doc.get('produtos', []):
            codigo = prod.get('codigo', '')
            product_summary[codigo]['descricao'] = prod.get('descricao', '')
            product_summary[codigo]['ncm'] = prod.get('ncm', '')
            product_summary[codigo]['quantidade'] += prod.get('quantidade', 0)
            product_summary[codigo]['valor_total'] += prod.get('valor_total', 0)
            product_summary[codigo]['credito_icms'] += prod.get('v_icms', 0)
            product_summary[codigo]['credito_pis'] += prod.get('v_pis', 0)
            product_summary[codigo]['credito_cofins'] += prod.get('v_cofins', 0)
            product_summary[codigo]['documentos'] += 1
    
    report = []
    for codigo, data in product_summary.items():
        report.append({
            'codigo': codigo,
            **data
        })
    
    return sorted(report, key=lambda x: x['valor_total'], reverse=True)

@api_router.get("/classification/suggestions/{company_id}")
async def get_classification_suggestions(
    company_id: str,
    competencia: str,
    current_user: User = Depends(get_current_user)
):
    """
    Retorna sugestões de classificação de produtos para validação.
    Agrupa produtos por código/descrição e mostra status de classificação.
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    # Buscar documentos de entrada (onde os produtos precisam ser classificados)
    query = {
        "company_id": company_id,
        "competencia": competencia,
        "tipo": "entrada",
        **get_filtro_notas_ativas()
    }
    
    documents = await db.xml_documents.find(query, {"_id": 0, "xml_content": 0}).to_list(100000)
    
    # Agrupar produtos por código+descricao
    produtos_agrupados = defaultdict(lambda: {
        'codigo': '',
        'descricao': '',
        'ncm': '',
        'cfop_atual': '',
        'categoria_atual': '',
        'quantidade': 0,
        'valor_total': 0,
        'ocorrencias': [],
        'classificado': False
    })
    
    # Lista de categorias conhecidas como classificadas (expandida)
    categorias_classificadas = [
        'revenda', 'insumo', 'despesa', 'ativo_imobilizado', 'combustivel',
        'servico_aplicacao', 'servico', 'materia_prima', 'outras_entradas',
        'uso_consumo', 'energia', 'comunicacao', 'transporte', 'bonificacao',
        'amostra_gratis', 'devolucao', 'transferencia', 'remessa', 'retorno',
        'conserto', 'garantia', 'locacao', 'comodato', 'demonstracao',
        'aplicacao_servico', 'compra_revenda', 'imobilizado'
    ]
    total_produtos = 0
    validados = 0
    pendentes = 0
    
    for doc in documents:
        for produto_idx, prod in enumerate(doc.get('produtos', [])):
            codigo = prod.get('codigo', '') or 'SEM_CODIGO'
            descricao = prod.get('descricao', '')
            chave = f"{codigo}_{descricao[:50]}"
            
            grupo = produtos_agrupados[chave]
            grupo['codigo'] = codigo
            grupo['descricao'] = descricao
            grupo['ncm'] = prod.get('ncm', '')
            grupo['cfop_atual'] = prod.get('cfop', '')
            
            # Verificar categoria classificada - aceita qualquer valor não vazio
            categoria = prod.get('categoria_classificada', '')
            if categoria and categoria.strip() and categoria.lower() not in ['', 'pendente', 'pendente_classificacao', 'none', 'null']:
                # Se já tem categoria definida no grupo, só sobrescreve se for diferente de pendente
                if grupo['categoria_atual'] == 'pendente' or not grupo['categoria_atual']:
                    grupo['categoria_atual'] = categoria
                grupo['classificado'] = True
            elif not grupo['classificado']:
                # Só marca como pendente se o grupo ainda não foi classificado
                grupo['categoria_atual'] = 'pendente'
            
            grupo['quantidade'] += prod.get('quantidade', 0)
            grupo['valor_total'] += prod.get('valor_total', 0)
            grupo['ocorrencias'].append({
                'doc_id': doc['id'],
                'numero_nfe': doc.get('numero_nfe', ''),
                'nf': doc.get('numero_nfe', ''),
                'produto_idx': produto_idx  # IMPORTANTE: índice do produto no array
            })
            total_produtos += 1
    
    # Converter para lista e contar validados/pendentes
    sugestoes = []
    for chave, dados in produtos_agrupados.items():
        if dados['classificado']:
            validados += 1
        else:
            pendentes += 1
        sugestoes.append(dados)
    
    # Ordenar por valor total decrescente
    sugestoes.sort(key=lambda x: x['valor_total'], reverse=True)
    
    return {
        "empresa": company.get('razao_social', ''),
        "competencia": competencia,
        "resumo": {
            "total_produtos": len(sugestoes),
            "validados": validados,
            "pendentes": pendentes,
            "valor_total": sum(s['valor_total'] for s in sugestoes)
        },
        "sugestoes": sugestoes
    }

@api_router.post("/products/classify-single")
async def classificar_produto_individual(
    document_id: str = Body(...),
    product_idx: int = Body(...),
    nova_categoria: str = Body(...),
    salvar_regra: bool = Body(False),
    current_user: User = Depends(get_current_user)
):
    """
    Reclassifica um produto individual em um documento específico.
    """
    doc = await db.xml_documents.find_one({"id": document_id})
    if not doc:
        raise HTTPException(status_code=404, detail="Documento não encontrado")
    
    produtos = doc.get('produtos', [])
    if product_idx >= len(produtos):
        raise HTTPException(status_code=404, detail="Produto não encontrado")
    
    produto = produtos[product_idx]
    categoria_anterior = produto.get('categoria_classificada', 'pendente')
    
    # Atualizar categoria
    produtos[product_idx]['categoria_classificada'] = nova_categoria
    produtos[product_idx]['categoria_origem'] = 'manual_user'
    produtos[product_idx]['categoria_classificada_em'] = datetime.now(timezone.utc).isoformat()
    produtos[product_idx]['categoria_classificada_por'] = current_user.id
    
    # Atualizar CFOP baseado na categoria
    cfop_novo = obter_cfop_por_categoria(nova_categoria, produto.get('cfop', ''))
    if cfop_novo:
        produtos[product_idx]['cfop'] = cfop_novo
        produtos[product_idx]['cfop_anterior'] = produto.get('cfop', '')
    
    await db.xml_documents.update_one(
        {"id": document_id},
        {"$set": {"produtos": produtos}}
    )
    
    # Salvar regra se solicitado
    if salvar_regra:
        descricao_produto = produto.get('descricao', '')
        regra_existente = await db.learned_rules.find_one({
            "company_id": doc.get('company_id'),
            "produto_descricao": descricao_produto
        })
        
        if regra_existente:
            # Atualizar regra existente
            await db.learned_rules.update_one(
                {"id": regra_existente['id']},
                {"$set": {
                    "categoria_correta": nova_categoria,
                    "cfop_correto": cfop_novo,
                    "motivo": f"Reclassificado manualmente por {current_user.email}",
                    "updated_at": datetime.now(timezone.utc).isoformat()
                }}
            )
        else:
            await db.learned_rules.insert_one({
                "id": str(uuid.uuid4()),
                "company_id": doc.get('company_id'),
                "produto_descricao": descricao_produto,
                "produto_codigo": produto.get('codigo', ''),
                "ncm": produto.get('ncm', ''),
                "categoria_correta": nova_categoria,
                "cfop_correto": cfop_novo,
                "aprendido_de": "user_manual_classification",
                "created_by": current_user.email,
                "created_at": datetime.now(timezone.utc).isoformat()
            })
    
    return {
        "success": True,
        "message": f"Produto reclassificado de {categoria_anterior} para {nova_categoria}",
        "categoria_anterior": categoria_anterior,
        "categoria_nova": nova_categoria,
        "cfop_novo": cfop_novo
    }


def obter_cfop_por_categoria(categoria: str, cfop_atual: str) -> str:
    """
    Retorna o CFOP apropriado baseado na categoria do produto.
    Mantém o prefixo estadual/interestadual e considera se é operação com ST.
    
    CFOPs de ENTRADA (compra):
    - 1102/2102: Compra para comercialização (REVENDA)
    - 1101/2101: Compra para industrialização (INSUMO)
    - 1407/2407: Compra para uso e consumo (DESPESA)
    - 1406/2406: Compra de bem para ativo imobilizado (ATIVO)
    - 1652/2652: Compra de combustível para comercialização
    - 1653/2653: Compra de combustível para uso (frota)
    - 1403/2403: Compra para comercialização com ST (REVENDA ST)
    - 1401/2401: Compra para industrialização com ST (INSUMO ST)
    - 1556/2556: Compra para uso e consumo com ST (DESPESA ST) - menos comum
    - 1128/2128: Compra para prestação de serviço
    """
    if not cfop_atual or len(cfop_atual) < 4:
        cfop_atual = '1102'
    
    # Prefixo: 1 (estadual), 2 (interestadual), 3 (exterior)
    prefixo = cfop_atual[0] if cfop_atual[0] in ['1', '2', '3', '5', '6', '7'] else '1'
    
    # Se é CFOP de saída (5xxx, 6xxx, 7xxx), converter para entrada
    if prefixo in ['5', '6', '7']:
        # 5 -> 1, 6 -> 2, 7 -> 3
        prefixo = {'5': '1', '6': '2', '7': '3'}.get(prefixo, '1')
    
    # Verificar se é operação com ST (4xx indica ST para entrada, ou vem de 54xx/64xx de saída)
    # Considera tanto CFOPs de entrada (14xx, 24xx) quanto de saída (54xx, 64xx)
    is_st = False
    if len(cfop_atual) >= 2:
        segundo_digito = cfop_atual[1]
        # Para CFOPs de entrada: 14xx, 24xx
        # Para CFOPs de saída: 54xx, 64xx (que serão convertidos para entrada)
        is_st = segundo_digito == '4'
    
    # Mapeamento base (sem ST)
    mapeamento_base = {
        'revenda': '102',       # Compra para comercialização
        'produto': '102',       # Alias para revenda
        'insumo': '101',        # Compra para industrialização
        'despesa': '556',       # Compra para uso e consumo (sem ST = 1556)
        'uso_consumo': '556',   # Alias para despesa
        'ativo_imobilizado': '551',  # Compra de bem para ativo imobilizado (sem ST = 1551)
        'ativo': '551',         # Alias para ativo
        'combustivel': '653',   # Compra de combustível para uso (frota própria)
        'servico_aplicacao': '128',  # Compra para prestação de serviço
        'servico': '933',       # Serviço tomado (NFS-e)
        'bonificacao': '910',   # Bonificação/Doação
        'devolucao': '201',     # Devolução de compra
    }
    
    # Mapeamento com ST (4xx) - mercadorias com substituição tributária
    mapeamento_st = {
        'revenda': '403',       # Compra para comercialização com ST
        'produto': '403',       # Alias para revenda com ST
        'insumo': '401',        # Compra para industrialização com ST
        'despesa': '407',       # Uso e consumo com ST (1407/2407)
        'uso_consumo': '407',   # Alias para despesa com ST
        'ativo_imobilizado': '406',  # Ativo imobilizado com ST (1406/2406)
        'ativo': '406',         # Alias para ativo com ST
        'combustivel': '653',   # Combustível (mantém)
        'servico_aplicacao': '128',  # Compra para prestação de serviço
        'servico': '933',       # Serviço
        'bonificacao': '910',   # Bonificação
        'devolucao': '201',     # Devolução
    }
    
    categoria_lower = categoria.lower() if categoria else ''
    
    if is_st:
        sufixo = mapeamento_st.get(categoria_lower, mapeamento_base.get(categoria_lower, ''))
    else:
        sufixo = mapeamento_base.get(categoria_lower, '')
    
    if sufixo:
        return f'{prefixo}{sufixo}'
    
    return ''


@api_router.post("/classification/ia-command/{company_id}")
async def classificar_produtos_ia(
    company_id: str,
    competencia: str,
    comando: str,
    current_user: User = Depends(get_current_user)
):
    """
    Classifica produtos usando comando de IA em linguagem natural.
    Ex: "classificar etanol como combustível", "todos produtos limpeza são despesa"
    
    MELHORIA: Analisa os produtos de SAÍDA da empresa para entender o que ela comercializa,
    e usa isso como referência para classificar as ENTRADAS como revenda.
    """
    from emergentintegrations.llm.chat import LlmChat, UserMessage
    
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    tipo_atividade = company.get('tipo_atividade', 'comercio')
    
    # NOVA LÓGICA: Buscar produtos de SAÍDA para entender o que a empresa vende
    produtos_vendidos = set()
    ncms_vendidos = set()
    
    docs_saida = await db.xml_documents.find({
        "company_id": company_id,
        "$or": [
            {"tipo": "saida"},
            {"tipo_operacao": {"$in": ["saida", "prestado"]}}
        ],
        **get_filtro_notas_ativas()
    }, {"_id": 0, "produtos": 1}).to_list(5000)
    
    for doc in docs_saida:
        for prod in doc.get('produtos', []):
            desc = prod.get('descricao', '').lower().strip()[:50]
            ncm = str(prod.get('ncm', '')).replace('.', '')[:8]
            if desc:
                produtos_vendidos.add(desc)
            if ncm and len(ncm) >= 4:
                ncms_vendidos.add(ncm)
    
    # Buscar produtos de entrada
    documents = await db.xml_documents.find({
        "company_id": company_id,
        "competencia": competencia,
        "tipo": "entrada",
        **get_filtro_notas_ativas()
    }).to_list(100000)
    
    # Agrupar produtos únicos
    produtos_unicos = {}
    for doc in documents:
        for idx, prod in enumerate(doc.get('produtos', [])):
            codigo = prod.get('codigo', '') or 'SEM_CODIGO'
            descricao = prod.get('descricao', '')
            chave = f"{codigo}_{descricao[:50]}"
            
            if chave not in produtos_unicos:
                produtos_unicos[chave] = {
                    'codigo': codigo,
                    'descricao': descricao,
                    'ncm': prod.get('ncm', ''),
                    'categoria_atual': prod.get('categoria_classificada', 'pendente'),
                    'ocorrencias': []
                }
            
            produtos_unicos[chave]['ocorrencias'].append({
                'doc_id': doc['id'],
                'idx': idx
            })
    
    if not produtos_unicos:
        return {"success": True, "message": "Nenhum produto encontrado", "alteracoes": [], "total_alteracoes": 0}
    
    # ============= DICIONÁRIO DE EXPANSÃO SEMÂNTICA =============
    # Mapeamento de palavras-chave genéricas para termos relacionados
    EXPANSAO_SEMANTICA = {
        # Carnes e proteínas
        'carne': ['picanha', 'alcatra', 'costela', 'filé', 'bife', 'coxão', 'patinho', 'maminha', 'cupim', 'acém', 
                  'contrafilé', 'chã', 'lagarto', 'músculo', 'carne moída', 'carne bovina', 'carne suína', 'pernil',
                  'lombo', 'bisteca', 'bacon', 'linguiça', 'salsicha', 'presunto', 'mortadela', 'hamburguer'],
        'frango': ['coxa', 'sobrecoxa', 'peito de frango', 'asa', 'coxinha', 'filé de frango', 'frango inteiro', 
                   'frango congelado', 'ave', 'galinha'],
        'peixe': ['tilápia', 'salmão', 'bacalhau', 'atum', 'sardinha', 'merluza', 'pescada', 'camarão', 'peixe congelado'],
        
        # Frutas
        'fruta': ['abacaxi', 'banana', 'maçã', 'laranja', 'uva', 'melancia', 'melão', 'mamão', 'morango', 'manga',
                  'pera', 'kiwi', 'limão', 'abacate', 'goiaba', 'pêssego', 'ameixa', 'cereja', 'coco', 'maracujá',
                  'tangerina', 'mexerica', 'bergamota', 'acerola', 'jabuticaba', 'caju', 'pitanga'],
        
        # Verduras e legumes
        'verdura': ['alface', 'rúcula', 'agrião', 'espinafre', 'couve', 'repolho', 'brócolis', 'couve-flor',
                    'acelga', 'chicória', 'almeirão', 'salsinha', 'cebolinha', 'coentro', 'manjericão'],
        'legume': ['tomate', 'cebola', 'cenoura', 'batata', 'beterraba', 'abobrinha', 'berinjela', 'pepino',
                   'pimentão', 'abóbora', 'chuchu', 'mandioca', 'inhame', 'nabo', 'rabanete', 'vagem', 'quiabo'],
        
        # Laticínios
        'laticínio': ['leite', 'queijo', 'manteiga', 'margarina', 'iogurte', 'creme de leite', 'requeijão', 
                      'mussarela', 'parmesão', 'gorgonzola', 'ricota', 'cottage', 'nata', 'leite condensado'],
        'leite': ['leite integral', 'leite desnatado', 'leite semi', 'leite em pó', 'leite longa vida'],
        'queijo': ['mussarela', 'parmesão', 'gorgonzola', 'provolone', 'prato', 'minas', 'ricota', 'cottage', 'coalho'],
        
        # Bebidas
        'bebida': ['água', 'refrigerante', 'suco', 'cerveja', 'vinho', 'vodka', 'whisky', 'cachaça', 'espumante',
                   'energético', 'isotônico', 'chá', 'café', 'achocolatado'],
        
        # Limpeza
        'limpeza': ['detergente', 'desinfetante', 'água sanitária', 'sabão', 'esponja', 'vassoura', 'rodo', 
                    'pano de chão', 'lustra móveis', 'limpa vidros', 'alvejante', 'amaciante', 'sabão em pó',
                    'multiuso', 'cloro', 'saco de lixo'],
        
        # Escritório
        'escritório': ['caneta', 'lápis', 'borracha', 'papel', 'grampeador', 'grampo', 'clips', 'envelope',
                       'pasta', 'caderno', 'bloco', 'post-it', 'fita adesiva', 'tesoura', 'régua', 'calculadora'],
    }
    
    def expandir_palavras_chave(palavras):
        """Expande uma lista de palavras-chave incluindo termos relacionados"""
        resultado = set()
        for palavra in palavras:
            palavra_lower = palavra.lower().strip()
            resultado.add(palavra_lower)
            
            # Verificar se há expansão disponível
            for chave, expansoes in EXPANSAO_SEMANTICA.items():
                if chave in palavra_lower or palavra_lower in chave:
                    resultado.update([e.lower() for e in expansoes])
                # Também verificar se a palavra é uma das expansões
                if palavra_lower in [e.lower() for e in expansoes]:
                    resultado.add(chave)
                    resultado.update([e.lower() for e in expansoes])
        
        return list(resultado)
    
    # ============= PRÉ-CLASSIFICAÇÃO POR PALAVRAS-CHAVE =============
    # PRIORIDADE 1: Classificar baseado nas palavras-chave cadastradas ANTES de usar IA
    # Isso garante que as palavras-chave sempre tenham prioridade sobre a IA
    
    produtos_comercializados = company.get('produtos_comercializados', [])
    produtos_aplicacao_servico = company.get('produtos_aplicacao_servico', [])
    insumos_producao = company.get('insumos_producao', [])
    produtos_despesa = company.get('produtos_despesa', [])
    
    # Expandir palavras-chave com sinônimos e termos relacionados
    palavras_revenda = expandir_palavras_chave(produtos_comercializados)
    palavras_servico = expandir_palavras_chave(produtos_aplicacao_servico)
    palavras_insumo = expandir_palavras_chave(insumos_producao)
    palavras_despesa = expandir_palavras_chave(produtos_despesa)
    
    # Log para debug
    import logging
    logging.info(f"[EXPANSAO] Insumo original: {insumos_producao}")
    logging.info(f"[EXPANSAO] Insumo expandido: {palavras_insumo[:20]}...")
    
    # Pré-classificar produtos com base nas palavras-chave expandidas
    produtos_pre_classificados = {}
    produtos_para_ia = {}
    
    for chave, dados in produtos_unicos.items():
        descricao_lower = dados['descricao'].lower()
        categoria_encontrada = None
        palavra_match = None
        
        # Verificar palavras-chave em ordem de prioridade
        # 1. Insumo (mais específico)
        for palavra in palavras_insumo:
            if palavra in descricao_lower:
                categoria_encontrada = 'insumo'
                palavra_match = palavra
                break
        
        # 2. Despesa
        if not categoria_encontrada:
            for palavra in palavras_despesa:
                if palavra in descricao_lower:
                    categoria_encontrada = 'despesa'
                    palavra_match = palavra
                    break
        
        # 3. Serviço aplicação
        if not categoria_encontrada:
            for palavra in palavras_servico:
                if palavra in descricao_lower:
                    categoria_encontrada = 'servico_aplicacao'
                    palavra_match = palavra
                    break
        
        # 4. Revenda
        if not categoria_encontrada:
            for palavra in palavras_revenda:
                if palavra in descricao_lower:
                    categoria_encontrada = 'revenda'
                    palavra_match = palavra
                    break
        
        if categoria_encontrada:
            dados['categoria_sugerida'] = categoria_encontrada
            dados['palavra_match'] = palavra_match
            dados['fonte'] = 'palavra_chave'
            produtos_pre_classificados[chave] = dados
        else:
            produtos_para_ia[chave] = dados
    
    # Log para debug
    import logging
    logging.info(f"[IA-CLASSIFICACAO] Pré-classificados por palavra-chave: {len(produtos_pre_classificados)}")
    logging.info(f"[IA-CLASSIFICACAO] Enviados para IA: {len(produtos_para_ia)}")
    
    # Preparar contexto para IA (apenas produtos não pré-classificados)
    produtos_texto = "\n".join([
        f"- {p['descricao'][:80]} (NCM: {p['ncm']}, categoria atual: {p['categoria_atual']})"
        for p in list(produtos_para_ia.values())[:100]
    ]) if produtos_para_ia else "Nenhum produto pendente"
    
    # Carregar regras existentes
    regras_existentes = await db.learned_rules.find({"company_id": company_id}).to_list(100)
    regras_texto = "\n".join([
        f"- {r.get('descricao_produto', '')} → {r.get('categoria', '')}"
        for r in regras_existentes
    ]) if regras_existentes else "Nenhuma regra cadastrada"
    
    # NOVA LÓGICA: Adicionar contexto dos produtos vendidos
    produtos_vendidos_texto = "\n".join([f"- {p}" for p in list(produtos_vendidos)[:50]]) if produtos_vendidos else "Nenhum produto de saída encontrado"
    ncms_vendidos_texto = ", ".join(list(ncms_vendidos)[:20]) if ncms_vendidos else "N/A"
    
    # Palavras-chave cadastradas pela empresa (para incluir no prompt da IA)
    produtos_aplicacao_servico = company.get('produtos_aplicacao_servico', [])
    insumos_producao = company.get('insumos_producao', [])
    produtos_despesa = company.get('produtos_despesa', [])
    palavras_chave_personalizadas = company.get('palavras_chave_classificacao', [])  # NOVO: Palavras-chave genéricas
    
    palavras_chave_texto = ""
    if produtos_comercializados:
        palavras_chave_texto += f"\n- REVENDA: {', '.join(produtos_comercializados)}"
    if produtos_aplicacao_servico:
        palavras_chave_texto += f"\n- APLICAÇÃO EM SERVIÇOS: {', '.join(produtos_aplicacao_servico)}"
    if insumos_producao:
        palavras_chave_texto += f"\n- INSUMO: {', '.join(insumos_producao)}"
    if produtos_despesa:
        palavras_chave_texto += f"\n- DESPESA: {', '.join(produtos_despesa)}"
    if palavras_chave_personalizadas:
        palavras_chave_texto += f"\n- PALAVRAS-CHAVE PERSONALIZADAS: {', '.join(palavras_chave_personalizadas)}"
    
    # NOVO: Palavras-chave por setor da empresa (ex: construção, tecnologia, etc.)
    descricao_atividade = company.get('descricao_atividade', '') or company.get('objeto_social', '') or ''
    setores_detectados = []
    
    # Detectar setor baseado na descrição da atividade
    if any(palavra in descricao_atividade.lower() for palavra in ['construção', 'construcao', 'obra', 'edificação', 'reforma']):
        setores_detectados.append('construção')
    if any(palavra in descricao_atividade.lower() for palavra in ['tecnologia', 'software', 'informática', 'informatica', 'ti', 'desenvolvimento']):
        setores_detectados.append('tecnologia')
    if any(palavra in descricao_atividade.lower() for palavra in ['alimentação', 'alimentacao', 'restaurante', 'lanchonete', 'bar', 'padaria']):
        setores_detectados.append('alimentação')
    if any(palavra in descricao_atividade.lower() for palavra in ['saúde', 'saude', 'clínica', 'clinica', 'hospital', 'médico', 'medico', 'dentista']):
        setores_detectados.append('saúde')
    if any(palavra in descricao_atividade.lower() for palavra in ['veículo', 'veiculo', 'automóvel', 'automovel', 'peças', 'pecas', 'auto peças']):
        setores_detectados.append('automotivo')
    
    if setores_detectados:
        palavras_chave_texto += f"\n- SETOR DA EMPRESA: {', '.join(setores_detectados)}"
    
    # Definir categoria padrão baseada na atividade e configuração da empresa
    if tipo_atividade == 'servicos':
        categoria_padrao = "servico_aplicacao"
    elif tipo_atividade == 'mista' and len(produtos_aplicacao_servico) > len(produtos_comercializados):
        categoria_padrao = "servico_aplicacao"  # Se tem mais palavras-chave de serviço
    elif tipo_atividade in ['comercio', 'mista']:
        categoria_padrao = "revenda"
    elif tipo_atividade == 'industria':
        categoria_padrao = "insumo"
    else:
        categoria_padrao = "revenda"
    
    prompt = f"""Você é um assistente fiscal especializado em classificação de produtos para fins tributários.

Comando do usuário: "{comando}"

**CONTEXTO DA EMPRESA:**
- Tipo de atividade: {tipo_atividade.upper()}
- Categoria padrão para dúvidas: {categoria_padrao}
{f'- Palavras-chave cadastradas:{palavras_chave_texto}' if palavras_chave_texto else ''}

**PRODUTOS QUE A EMPRESA VENDE (referência para classificar como REVENDA):**
{produtos_vendidos_texto}

**NCMs dos produtos vendidos:** {ncms_vendidos_texto}

**REGRAS DE PRIORIDADE ABSOLUTA - EXPANSÃO SEMÂNTICA:**
As palavras-chave cadastradas devem ser EXPANDIDAS SEMANTICAMENTE para incluir todos os produtos relacionados:

Exemplos de expansão semântica:
- "carne" → inclui: picanha, alcatra, costela, frango, peixe, linguiça, bacon, filé, bife, coxão, patinho, maminha, cupim, acém, contrafilé, chã de dentro, lagarto, músculo, coxinha da asa, sobrecoxa, peito de frango, tilápia, salmão, camarão, etc.
- "frutas" → inclui: abacaxi, banana, maçã, laranja, uva, melancia, melão, mamão, morango, manga, pera, kiwi, limão, abacate, goiaba, etc.
- "verduras" ou "legumes" → inclui: alface, tomate, cebola, cenoura, batata, beterraba, abobrinha, berinjela, brócolis, couve, espinafre, etc.
- "laticínios" → inclui: leite, queijo, manteiga, iogurte, creme de leite, requeijão, etc.
- "bebidas" → inclui: água, refrigerante, suco, cerveja, vinho, etc.
- "limpeza" → inclui: detergente, desinfetante, água sanitária, sabão, esponja, vassoura, rodo, etc.

**APLIQUE ESTA EXPANSÃO PARA AS PALAVRAS-CHAVE CADASTRADAS:**
{palavras_chave_texto if palavras_chave_texto else 'Nenhuma palavra-chave cadastrada'}

**REGRAS IMPORTANTES:** 
1. PRIORIDADE MÁXIMA: Se um produto for semanticamente relacionado a uma palavra-chave cadastrada, classificar na categoria dessa palavra-chave.
2. Se um produto de ENTRADA tiver descrição ou NCM similar aos produtos de SAÍDA, ele é para REVENDA.
3. Se a empresa for de SERVIÇOS, classificar materiais de entrada como SERVICO_APLICACAO.
4. Em caso de DÚVIDA para empresas de comércio, classificar como REVENDA.
5. Em caso de DÚVIDA para empresas de serviços, classificar como SERVICO_APLICACAO.

Categorias válidas:
- revenda: Mercadorias compradas para revenda (PRIORIZAR para empresas de comércio)
- servico_aplicacao: Materiais aplicados na prestação de serviços (PRIORIZAR para empresas de serviços)
- insumo: Matérias-primas e insumos de produção industrial ou restaurante
- despesa: Material de uso e consumo, limpeza, escritório, manutenção
- ativo_imobilizado: Máquinas, equipamentos, móveis, veículos
- combustivel: Gasolina, etanol, diesel, GNV
- bonificacao: Produtos recebidos em bonificação/doação

Palavras-chave para DESPESA (padrão):
- limpeza, desinfetante, papel toalha, papel higiênico, sabonete, detergente
- escritório, caneta, papel A4, impressora, toner, cartucho
- manutenção, peças de reposição, ferramenta
- segurança, EPI, luva, máscara, capacete

Regras já cadastradas para esta empresa:
{regras_texto}

Produtos de ENTRADA para classificar:
{produtos_texto}

IMPORTANTE: 
1. Analise o comando E as palavras-chave cadastradas
2. EXPANDA SEMANTICAMENTE as palavras-chave para incluir TODOS os produtos relacionados
3. Classifique cada produto na categoria correta baseado na expansão semântica
4. Considere variações de nome, sinônimos e produtos relacionados

Retorne um JSON com:
{{
    "alteracoes": [
        {{"descricao_produto": "texto parcial para match", "nova_categoria": "categoria_valida", "motivo": "explicação (mencionar se foi por expansão semântica de palavra-chave)"}}
    ],
    "nova_regra": {{
        "padrao": "padrão de texto para identificar produtos similares no futuro",
        "categoria": "categoria_valida",
        "descricao": "descrição da regra para referência"
    }}
}}

Se o comando não for claro, retorne {{"alteracoes": [], "erro": "mensagem explicativa"}}
"""

    try:
        llm = LlmChat(
            api_key=os.environ.get('EMERGENT_LLM_KEY'),
            session_id=f"classificacao-{company_id}-{competencia}",
            system_message="Você é um assistente fiscal especializado. Responda sempre em formato JSON válido."
        ).with_model("gemini", "gemini-2.5-flash")
        response = await llm.send_message(UserMessage(text=prompt))
        
        response_text = response if isinstance(response, str) else str(response)
        json_match = re.search(r'\{[\s\S]*\}', response_text)
        
        if json_match:
            resultado = json.loads(json_match.group())
        else:
            return {"success": True, "message": response_text, "alteracoes": [], "total_alteracoes": 0}
        
        if resultado.get('erro'):
            return {"success": True, "message": resultado['erro'], "alteracoes": [], "total_alteracoes": 0}
        
        # Aplicar alterações
        alteracoes_aplicadas = []
        docs_atualizados = {}
        
        # ============= APLICAR PRÉ-CLASSIFICAÇÕES POR PALAVRAS-CHAVE =============
        # Estas têm PRIORIDADE sobre a IA
        for chave, dados in produtos_pre_classificados.items():
            categoria_destino = dados['categoria_sugerida']
            
            # Atualizar todas as ocorrências deste produto
            for occ in dados['ocorrencias']:
                doc_id = occ['doc_id']
                idx = occ['idx']
                
                if doc_id not in docs_atualizados:
                    doc = await db.xml_documents.find_one({"id": doc_id})
                    if doc:
                        docs_atualizados[doc_id] = doc.get('produtos', [])
                
                if doc_id in docs_atualizados:
                    produtos_doc = docs_atualizados[doc_id]
                    if idx < len(produtos_doc):
                        produtos_doc[idx]['categoria_classificada'] = categoria_destino
                        produtos_doc[idx]['classificado_por_ia'] = False
                        produtos_doc[idx]['classificado_por_palavra_chave'] = True
                        produtos_doc[idx]['comando_ia'] = comando
                        
                        # ATUALIZAR CFOP baseado na categoria
                        # Usar cfop_original_emissor para detectar ST, senão usar cfop atual
                        cfop_referencia = produtos_doc[idx].get('cfop_original_emissor', produtos_doc[idx].get('cfop', '1102'))
                        cfop_atual = produtos_doc[idx].get('cfop', '1102')
                        cfop_novo = obter_cfop_por_categoria(categoria_destino, cfop_referencia)
                        if cfop_novo:
                            produtos_doc[idx]['cfop_anterior'] = cfop_atual
                            produtos_doc[idx]['cfop'] = cfop_novo
            
            alteracoes_aplicadas.append({
                'produto': dados['descricao'],
                'categoria_anterior': dados['categoria_atual'],
                'categoria_nova': categoria_destino,
                'ocorrencias': len(dados['ocorrencias']),
                'motivo': f"Palavra-chave: '{dados.get('palavra_match', 'N/A')}'",
                'fonte': 'palavra_chave'
            })
        
        # ============= APLICAR ALTERAÇÕES DA IA =============
        # Apenas para produtos que NÃO foram pré-classificados
        for alt in resultado.get('alteracoes', []):
            categoria_destino = alt.get('nova_categoria', '')
            if categoria_destino not in ['revenda', 'insumo', 'despesa', 'ativo_imobilizado', 'combustivel', 'servico_aplicacao', 'bonificacao']:
                continue
            
            desc_match = alt.get('descricao_produto', '').lower().strip()
            
            # MELHORIA: Match mais inteligente - considera palavras-chave separadamente
            palavras_match = [p for p in desc_match.split() if len(p) > 2]
            
            # Encontrar produtos correspondentes (APENAS nos que foram para IA)
            for chave, dados in produtos_para_ia.items():
                descricao_produto = dados['descricao'].lower()
                
                # Match exato ou por palavras-chave
                match_encontrado = False
                if desc_match in descricao_produto:
                    match_encontrado = True
                elif len(palavras_match) > 0:
                    # Se pelo menos 2 palavras-chave coincidem, considera match
                    palavras_encontradas = sum(1 for p in palavras_match if p in descricao_produto)
                    if palavras_encontradas >= min(2, len(palavras_match)):
                        match_encontrado = True
                
                if match_encontrado:
                    # Atualizar todas as ocorrências deste produto
                    for occ in dados['ocorrencias']:
                        doc_id = occ['doc_id']
                        idx = occ['idx']
                        
                        if doc_id not in docs_atualizados:
                            doc = await db.xml_documents.find_one({"id": doc_id})
                            if doc:
                                docs_atualizados[doc_id] = doc.get('produtos', [])
                        
                        if doc_id in docs_atualizados:
                            produtos_doc = docs_atualizados[doc_id]
                            if idx < len(produtos_doc):
                                produtos_doc[idx]['categoria_classificada'] = categoria_destino
                                produtos_doc[idx]['classificado_por_ia'] = True
                                produtos_doc[idx]['comando_ia'] = comando
                                
                                # ATUALIZAR CFOP baseado na categoria
                                # Usar cfop_original_emissor para detectar ST
                                cfop_referencia = produtos_doc[idx].get('cfop_original_emissor', produtos_doc[idx].get('cfop', '1102'))
                                cfop_atual = produtos_doc[idx].get('cfop', '1102')
                                cfop_novo = obter_cfop_por_categoria(categoria_destino, cfop_referencia)
                                if cfop_novo:
                                    produtos_doc[idx]['cfop_anterior'] = cfop_atual
                                    produtos_doc[idx]['cfop'] = cfop_novo
                    
                    alteracoes_aplicadas.append({
                        'produto': dados['descricao'],
                        'categoria_anterior': dados['categoria_atual'],
                        'categoria_nova': categoria_destino,
                        'ocorrencias': len(dados['ocorrencias']),
                        'motivo': alt.get('motivo', comando),
                        'fonte': 'ia'
                    })
        
        # Salvar alterações no banco
        for doc_id, produtos in docs_atualizados.items():
            await db.xml_documents.update_one(
                {"id": doc_id},
                {"$set": {"produtos": produtos}}
            )
        
        # Salvar nova regra se fornecida - formato compatível com learned_rules
        if resultado.get('nova_regra') and resultado['nova_regra'].get('padrao'):
            nova_regra = resultado['nova_regra']
            padrao = nova_regra.get('padrao', '')
            categoria = nova_regra.get('categoria', '')
            cfop_sugerido = obter_cfop_por_categoria(categoria, '1102')
            
            # Verificar se já existe
            regra_existente = await db.learned_rules.find_one({
                "company_id": company_id,
                "produto_descricao": padrao
            })
            
            if not regra_existente:
                regra_doc = {
                    "id": str(uuid.uuid4()),
                    "company_id": company_id,
                    "produto_descricao": padrao,
                    "padrao": padrao,
                    "categoria_correta": categoria,
                    "cfop_correto": cfop_sugerido,
                    "motivo": nova_regra.get('descricao', comando),
                    "aprendido_de": "ia_command",
                    "created_by": current_user.email,
                    "created_at": datetime.now(timezone.utc).isoformat(),
                    "comando_original": comando
                }
                await db.learned_rules.insert_one(regra_doc)
        
        # NOVO: Salvar também cada produto alterado como regra para aprendizado
        for alt in alteracoes_aplicadas:
            descricao_produto = alt.get('produto', '')
            categoria = alt.get('categoria_nova', '')
            cfop_sugerido = obter_cfop_por_categoria(categoria, '1102')
            
            # Verificar se já existe - se existir, ATUALIZAR
            regra_existente = await db.learned_rules.find_one({
                "company_id": company_id,
                "produto_descricao": descricao_produto
            })
            
            if regra_existente:
                # ATUALIZAR regra existente
                await db.learned_rules.update_one(
                    {"id": regra_existente.get('id')},
                    {"$set": {
                        "categoria": categoria,
                        "categoria_correta": categoria,
                        "cfop": cfop_sugerido,
                        "cfop_correto": cfop_sugerido,
                        "motivo": alt.get('motivo', comando),
                        "updated_by": current_user.email,
                        "updated_at": datetime.now(timezone.utc).isoformat(),
                        "atualizado_por_comando": comando
                    }}
                )
            else:
                # Criar nova regra
                await db.learned_rules.insert_one({
                    "id": str(uuid.uuid4()),
                    "company_id": company_id,
                    "produto_descricao": descricao_produto,
                    "categoria": categoria,
                    "categoria_correta": categoria,
                    "cfop": cfop_sugerido,
                    "cfop_correto": cfop_sugerido,
                    "motivo": alt.get('motivo', comando),
                    "aprendido_de": "ia_command_produto",
                    "created_by": current_user.email,
                    "created_at": datetime.now(timezone.utc).isoformat()
                })
        
        return {
            "success": True,
            "total_alteracoes": len(alteracoes_aplicadas),
            "alteracoes": alteracoes_aplicadas,
            "comando_original": comando,
            "regra_salva": bool(resultado.get('nova_regra', {}).get('padrao'))
        }
        
    except Exception as e:
        error_msg = str(e)
        logger.error(f"Erro ao classificar com IA: {e}")
        
        # Verificar se é erro de budget
        if 'budget' in error_msg.lower() or 'exceeded' in error_msg.lower():
            return {
                "success": False, 
                "message": "Budget da IA excedido. Adicione mais créditos em Perfil → Universal Key → Add Balance",
                "alteracoes": [],
                "budget_error": True
            }
        
        return {"success": False, "message": f"Erro ao processar com IA: {str(e)}", "alteracoes": []}

@api_router.get("/reports/by-ncm/{company_id}")
async def report_by_ncm(
    company_id: str,
    competencia: Optional[str] = None,
    tipo: Optional[str] = None,
    current_user: User = Depends(get_current_user)
):
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    query = {"company_id": company_id}
    if competencia:
        query['competencia'] = competencia
    if tipo and tipo != 'todos':
        query['tipo'] = tipo
    
    documents = await db.xml_documents.find(query, {"_id": 0}).to_list(100000)
    
    ncm_summary = defaultdict(lambda: {
        'quantidade_produtos': 0,
        'quantidade': 0,
        'valor_total': 0,
        'credito_icms': 0,
        'credito_pis': 0,
        'credito_cofins': 0,
        'documentos': set()
    })
    
    for doc in documents:
        for prod in doc.get('produtos', []):
            ncm = prod.get('ncm', '')
            ncm_summary[ncm]['quantidade_produtos'] += 1
            ncm_summary[ncm]['quantidade'] += prod.get('quantidade', 0)
            ncm_summary[ncm]['valor_total'] += prod.get('valor_total', 0)
            ncm_summary[ncm]['credito_icms'] += prod.get('v_icms', 0)
            ncm_summary[ncm]['credito_pis'] += prod.get('v_pis', 0)
            ncm_summary[ncm]['credito_cofins'] += prod.get('v_cofins', 0)
            ncm_summary[ncm]['documentos'].add(doc['id'])
    
    report = []
    for ncm, data in ncm_summary.items():
        report.append({
            'ncm': ncm,
            'quantidade_produtos': data['quantidade_produtos'],
            'quantidade': data['quantidade'],
            'valor_total': data['valor_total'],
            'credito_icms': data['credito_icms'],
            'credito_pis': data['credito_pis'],
            'credito_cofins': data['credito_cofins'],
            'documentos': len(data['documentos'])
        })
    
    return sorted(report, key=lambda x: x['valor_total'], reverse=True)

@api_router.post("/cfop/rules", response_model=CFOPRule)
async def create_cfop_rule(rule_data: CFOPRule, current_user: User = Depends(get_current_user)):
    if not UserRole.has_full_access(current_user.role):
        raise HTTPException(status_code=403, detail="Apenas administradores podem criar regras")
    
    doc = rule_data.model_dump()
    doc['created_at'] = doc['created_at'].isoformat()
    
    await db.cfop_rules.insert_one(doc)
    return rule_data

@api_router.get("/cfop/rules", response_model=List[CFOPRule])
async def list_cfop_rules(current_user: User = Depends(get_current_user)):
    rules = await db.cfop_rules.find({}, {"_id": 0}).to_list(1000)
    
    for rule in rules:
        if isinstance(rule['created_at'], str):
            rule['created_at'] = datetime.fromisoformat(rule['created_at'])
    
    return rules

@api_router.post("/exceptions", response_model=ValidationException)
async def create_exception(
    exception_data: ExceptionCreate,
    current_user: User = Depends(get_current_user)
):
    exception = ValidationException(**exception_data.model_dump(), created_by=current_user.id)
    
    doc = exception.model_dump()
    doc['created_at'] = doc['created_at'].isoformat()
    
    await db.validation_exceptions.insert_one(doc)
    
    await db.xml_documents.update_one(
        {"id": exception_data.xml_document_id},
        {"$set": {"status_validacao": "com_excecao"}}
    )
    
    return exception

@api_router.get("/exceptions")
async def list_exceptions(
    document_id: Optional[str] = None,
    current_user: User = Depends(get_current_user)
):
    query = {}
    if document_id:
        query['xml_document_id'] = document_id
    
    exceptions = await db.validation_exceptions.find(query, {"_id": 0}).to_list(1000)
    
    for exc in exceptions:
        if isinstance(exc['created_at'], str):
            exc['created_at'] = datetime.fromisoformat(exc['created_at'])
    
    return exceptions

@api_router.get("/sped/export/{company_id}")
@api_router.get("/sped/export/{company_id}")
async def export_sped(
    company_id: str,
    competencia: Optional[str] = None,
    excluir_creditos_despesa_st: bool = False,
    aplicar_beneficio_fiscal: bool = False,
    current_user: User = Depends(get_current_user)
):
    """
    Exporta SPED Fiscal para a empresa e competência especificadas.
    
    Parâmetros:
    - excluir_creditos_despesa_st: Se True, exclui créditos de ICMS de CFOPs de despesa (1556, 2556) e ST na apuração
    - aplicar_beneficio_fiscal: Se True, aplica regras de benefício fiscal para créditos de ICMS
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # EXCLUIR notas canceladas e desconsideradas
    query = {
        "company_id": company_id
    }
    query.update(get_filtro_notas_ativas())
    if competencia:
        query['competencia'] = competencia
    
    documents = await db.xml_documents.find(query, {"_id": 0}).to_list(100000)
    
    for doc in documents:
        if isinstance(doc['uploaded_at'], str):
            doc['uploaded_at'] = datetime.fromisoformat(doc['uploaded_at'])
    
    xml_docs = [XMLDocument(**doc) for doc in documents]
    
    if isinstance(company['created_at'], str):
        company['created_at'] = datetime.fromisoformat(company['created_at'])
    
    company_obj = Company(**company)
    
    # Se não foi explicitamente passado, usar o valor do cadastro da empresa
    usar_beneficio_fiscal = aplicar_beneficio_fiscal or company.get('beneficio_fiscal_icms', False)
    
    # Usar competência para gerar o período correto
    periodo = competencia or "01/2024"
    sped_content = generate_sped_fiscal(company_obj, xml_docs, periodo, excluir_creditos_despesa_st, usar_beneficio_fiscal)
    
    return {
        "content": sped_content,
        "filename": f"SPED_FISCAL_{company['cnpj']}_{competencia or periodo}.txt",
        "excluir_creditos_despesa_st": excluir_creditos_despesa_st,
        "aplicar_beneficio_fiscal": usar_beneficio_fiscal
    }


@api_router.get("/sped/validar/{company_id}")
async def validar_sped(
    company_id: str,
    competencia: Optional[str] = None,
    excluir_creditos_despesa_st: bool = False,
    current_user: User = Depends(get_current_user)
):
    """
    Valida o SPED gerado confrontando com a apuração do sistema.
    Retorna comparativo de totalizadores por CFOP.
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    query = {"company_id": company_id}
    if competencia:
        query['competencia'] = competencia
    # IMPORTANTE: Excluir notas canceladas e desconsideradas (igual à Apuração Mensal)
    query.update(get_filtro_notas_ativas())
    
    documents = await db.xml_documents.find(query, {"_id": 0}).to_list(100000)
    
    # CFOPs sem crédito de ICMS (despesa e ST)
    CFOPS_SEM_CREDITO = {
        '1403', '1409', '2403', '2409', '3403', '3409',
        '1407', '2407', '1556', '2556', '1557', '2557',
        '1128', '2128', '1551', '2551', '1553', '2553',
        '1554', '2554', '1406', '2406', '1408', '2408'
    }
    
    # Calcular totais do sistema (fonte: documentos XML)
    totais_sistema = {
        'entradas': {'valor': 0, 'icms': 0, 'icms_excluido': 0, 'pis': 0, 'cofins': 0, 'por_cfop': {}},
        'saidas': {'valor': 0, 'icms': 0, 'pis': 0, 'cofins': 0, 'por_cfop': {}}
    }
    
    for doc in documents:
        tipo = 'entradas' if doc.get('tipo') == 'entrada' else 'saidas'
        
        for prod in doc.get('produtos', []):
            cfop = str(prod.get('cfop', ''))
            valor = float(prod.get('valor_total', 0) or 0)
            v_icms = float(prod.get('v_icms', 0) or 0)
            v_pis = float(prod.get('v_pis', 0) or 0)
            v_cofins = float(prod.get('v_cofins', 0) or 0)
            
            # Totais gerais
            totais_sistema[tipo]['valor'] += valor
            totais_sistema[tipo]['pis'] += v_pis
            totais_sistema[tipo]['cofins'] += v_cofins
            
            # ICMS com lógica de exclusão
            if tipo == 'entradas' and excluir_creditos_despesa_st and cfop in CFOPS_SEM_CREDITO:
                totais_sistema[tipo]['icms_excluido'] += v_icms
            else:
                totais_sistema[tipo]['icms'] += v_icms
            
            # Totais por CFOP
            if cfop not in totais_sistema[tipo]['por_cfop']:
                totais_sistema[tipo]['por_cfop'][cfop] = {
                    'cfop': cfop,
                    'qtd_notas': 0,
                    'qtd_itens': 0,
                    'valor': 0,
                    'icms': 0,
                    'pis': 0,
                    'cofins': 0,
                    'credito_excluido': cfop in CFOPS_SEM_CREDITO if tipo == 'entradas' else False
                }
            
            totais_sistema[tipo]['por_cfop'][cfop]['qtd_itens'] += 1
            totais_sistema[tipo]['por_cfop'][cfop]['valor'] += valor
            totais_sistema[tipo]['por_cfop'][cfop]['icms'] += v_icms
            totais_sistema[tipo]['por_cfop'][cfop]['pis'] += v_pis
            totais_sistema[tipo]['por_cfop'][cfop]['cofins'] += v_cofins
    
    # Contar notas por CFOP
    notas_por_cfop = {'entradas': {}, 'saidas': {}}
    for doc in documents:
        tipo = 'entradas' if doc.get('tipo') == 'entrada' else 'saidas'
        cfops_na_nota = set()
        for prod in doc.get('produtos', []):
            cfop = str(prod.get('cfop', ''))
            if cfop:
                cfops_na_nota.add(cfop)
        for cfop in cfops_na_nota:
            if cfop in totais_sistema[tipo]['por_cfop']:
                totais_sistema[tipo]['por_cfop'][cfop]['qtd_notas'] += 1
    
    # Calcular apuração
    total_debitos = totais_sistema['saidas']['icms']
    total_creditos = totais_sistema['entradas']['icms']
    total_creditos_excluidos = totais_sistema['entradas']['icms_excluido']
    
    saldo_icms = total_debitos - total_creditos
    icms_a_pagar = max(0, saldo_icms)
    icms_a_compensar = max(0, -saldo_icms)
    
    # Preparar resposta
    return {
        "empresa": company.get('razao_social'),
        "competencia": competencia,
        "excluir_creditos_despesa_st": excluir_creditos_despesa_st,
        "resumo": {
            "entradas": {
                "total_valor": round(totais_sistema['entradas']['valor'], 2),
                "total_icms_creditavel": round(totais_sistema['entradas']['icms'], 2),
                "total_icms_excluido": round(totais_sistema['entradas']['icms_excluido'], 2),
                "total_pis": round(totais_sistema['entradas']['pis'], 2),
                "total_cofins": round(totais_sistema['entradas']['cofins'], 2),
                "qtd_cfops": len(totais_sistema['entradas']['por_cfop'])
            },
            "saidas": {
                "total_valor": round(totais_sistema['saidas']['valor'], 2),
                "total_icms": round(totais_sistema['saidas']['icms'], 2),
                "total_pis": round(totais_sistema['saidas']['pis'], 2),
                "total_cofins": round(totais_sistema['saidas']['cofins'], 2),
                "qtd_cfops": len(totais_sistema['saidas']['por_cfop'])
            },
            "apuracao_icms": {
                "debitos": round(total_debitos, 2),
                "creditos": round(total_creditos, 2),
                "creditos_excluidos": round(total_creditos_excluidos, 2),
                "saldo": round(saldo_icms, 2),
                "icms_a_pagar": round(icms_a_pagar, 2),
                "icms_a_compensar": round(icms_a_compensar, 2)
            }
        },
        "detalhamento_cfop": {
            "entradas": sorted(
                [
                    {
                        **v,
                        'valor': round(v['valor'], 2),
                        'icms': round(v['icms'], 2),
                        'pis': round(v['pis'], 2),
                        'cofins': round(v['cofins'], 2)
                    }
                    for v in totais_sistema['entradas']['por_cfop'].values()
                ],
                key=lambda x: x['cfop']
            ),
            "saidas": sorted(
                [
                    {
                        **v,
                        'valor': round(v['valor'], 2),
                        'icms': round(v['icms'], 2),
                        'pis': round(v['pis'], 2),
                        'cofins': round(v['cofins'], 2)
                    }
                    for v in totais_sistema['saidas']['por_cfop'].values()
                ],
                key=lambda x: x['cfop']
            )
        }
    }


@api_router.get("/analise-tributaria-ia/{company_id}")
async def analise_tributaria_ia(
    company_id: str,
    competencia: Optional[str] = None,
    current_user: User = Depends(get_current_user)
):
    """
    Análise Tributária Inteligente por IA.
    Identifica vilões tributários, oportunidades e gera insights personalizados.
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    query = {"company_id": company_id}
    if competencia:
        query['competencia'] = competencia
    
    documents = await db.xml_documents.find(query, {"_id": 0, "xml_content": 0}).to_list(100000)
    
    if not documents:
        return {
            "empresa": company.get('razao_social'),
            "competencia": competencia,
            "total_documentos": 0,
            "viloes_tributarios": [],
            "oportunidades": [],
            "analise_por_ncm": [],
            "insights_ia": None,
            "resumo": {
                "total_entradas": 0,
                "total_saidas": 0,
                "credito_icms": 0,
                "debito_icms": 0,
                "saldo_icms": 0
            }
        }
    
    # Separar entradas e saídas
    entradas = [d for d in documents if d.get('tipo') == 'entrada']
    saidas = [d for d in documents if d.get('tipo') == 'saida']
    
    # Agrupar produtos por código+NCM para análise cruzada entrada/saída
    produtos_entrada = {}  # {codigo_ncm: {aliq_icms, cst, valor, qtd, st}}
    produtos_saida = {}    # {codigo_ncm: {aliq_icms, cst, valor, qtd, st}}
    
    # CFOPs de ST (Substituição Tributária)
    CFOPS_ST_ENTRADA = {'1401', '1403', '1407', '1408', '1409', '2401', '2403', '2407', '2408', '2409'}
    CFOPS_ST_SAIDA = {'5401', '5403', '5405', '5408', '5409', '6401', '6403', '6405', '6408', '6409'}
    # CFOPs de despesa (não geram crédito)
    CFOPS_DESPESA = {'1556', '2556'}
    
    # CSTs do Simples Nacional (CSOSN) - não geram crédito de ICMS
    CSOSN_SIMPLES = {'101', '102', '103', '201', '202', '203', '300', '400', '500', '900'}
    
    # Processar entradas - agrupar por NCM para análise
    produtos_entrada = {}  # Por NCM
    
    for doc in entradas:
        # Verificar se fornecedor é do Simples Nacional
        emit_crt = doc.get('emitente_crt', '')  # CRT 1 = Simples Nacional
        is_fornecedor_simples = emit_crt == '1' or emit_crt == 1
        
        for prod in doc.get('produtos', []):
            ncm = str(prod.get('ncm', ''))[:8]
            if not ncm or ncm == '':
                continue
                
            descricao = prod.get('descricao', '')[:50]
            cfop = str(prod.get('cfop', ''))
            v_icms = float(prod.get('v_icms', 0) or 0)
            valor = float(prod.get('valor_total', 0) or 0)
            cst = str(prod.get('cst_icms', '') or '')
            p_icms = float(prod.get('p_icms', 0) or 0)  # Alíquota real do XML
            
            # Se p_icms não estiver disponível, calcular a partir de v_icms e v_bc_icms
            if p_icms == 0 and v_icms > 0:
                bc_icms = float(prod.get('v_bc_icms', 0) or 0)
                if bc_icms > 0:
                    p_icms = round((v_icms / bc_icms) * 100)
                elif valor > 0:
                    p_icms = round((v_icms / valor) * 100)
            
            is_st = cfop in CFOPS_ST_ENTRADA or cst in ['10', '30', '60', '70']
            is_despesa = cfop in CFOPS_DESPESA
            is_simples = cst in CSOSN_SIMPLES or is_fornecedor_simples
            sem_credito = is_st or is_despesa or is_simples or v_icms == 0
            
            # Extrair PIS/COFINS do produto
            v_pis = float(prod.get('v_pis', 0) or 0)
            v_cofins = float(prod.get('v_cofins', 0) or 0)
            
            # Agrupar por NCM para cruzamento
            if ncm not in produtos_entrada:
                produtos_entrada[ncm] = {
                    'ncm': ncm,
                    'descricoes': set(),
                    'total_icms': 0,
                    'total_icms_creditavel': 0,
                    'total_pis': 0,
                    'total_cofins': 0,
                    'total_valor': 0,
                    'total_valor_tributado': 0,  # Apenas itens tributados
                    'qtd_itens': 0,
                    'tem_st': False,
                    'tem_tributado': False,
                    'tem_despesa': False,
                    'tem_simples': False,  # Compras do Simples Nacional
                    'cfops': set(),
                    'csts': set(),
                    'aliquotas_reais': [],  # Alíquotas do XML (p_icms)
                    'aliquota_predominante': 0
                }
            
            produtos_entrada[ncm]['descricoes'].add(descricao)
            produtos_entrada[ncm]['total_icms'] += v_icms
            produtos_entrada[ncm]['total_pis'] += v_pis
            produtos_entrada[ncm]['total_cofins'] += v_cofins
            produtos_entrada[ncm]['total_valor'] += valor
            produtos_entrada[ncm]['qtd_itens'] += 1
            produtos_entrada[ncm]['cfops'].add(cfop)
            produtos_entrada[ncm]['csts'].add(cst)
            
            # Registrar alíquota real apenas de itens tributados
            if p_icms > 0:
                produtos_entrada[ncm]['aliquotas_reais'].append(p_icms)
            
            if not sem_credito:
                produtos_entrada[ncm]['total_icms_creditavel'] += v_icms
                produtos_entrada[ncm]['total_valor_tributado'] += valor
                produtos_entrada[ncm]['tem_tributado'] = True
            
            if is_st:
                produtos_entrada[ncm]['tem_st'] = True
            if is_despesa:
                produtos_entrada[ncm]['tem_despesa'] = True
            if is_simples:
                produtos_entrada[ncm]['tem_simples'] = True
    
    # Processar saídas - agrupar por NCM
    produtos_saida = {}
    
    # CSTs de saída que não geram débito (isentos, ST, etc.)
    CSTS_SEM_DEBITO = ['40', '41', '50', '51', '60']  # Isento, não tributado, suspensão, diferimento, ST
    
    for doc in saidas:
        for prod in doc.get('produtos', []):
            ncm = str(prod.get('ncm', ''))[:8]
            if not ncm or ncm == '':
                continue
                
            descricao = prod.get('descricao', '')[:50]
            cfop = str(prod.get('cfop', ''))
            v_icms = float(prod.get('v_icms', 0) or 0)
            v_pis = float(prod.get('v_pis', 0) or 0)
            v_cofins = float(prod.get('v_cofins', 0) or 0)
            valor = float(prod.get('valor_total', 0) or 0)
            cst = str(prod.get('cst_icms', '') or '')
            p_icms = float(prod.get('p_icms', 0) or 0)  # Alíquota real do XML
            
            # Se p_icms não estiver disponível, calcular a partir de v_icms e v_bc_icms
            if p_icms == 0 and v_icms > 0:
                bc_icms = float(prod.get('v_bc_icms', 0) or 0)
                if bc_icms > 0:
                    p_icms = round((v_icms / bc_icms) * 100)
                elif valor > 0:
                    p_icms = round((v_icms / valor) * 100)
            
            # Identificar CST numérico (últimos 2 dígitos)
            cst_num = cst[-2:] if len(cst) >= 2 else cst
            
            is_st = cfop in CFOPS_ST_SAIDA or cst_num in ['10', '30', '60', '70']
            is_isento = cst_num in CSTS_SEM_DEBITO or v_icms == 0
            
            if ncm not in produtos_saida:
                produtos_saida[ncm] = {
                    'ncm': ncm,
                    'descricoes': set(),
                    'total_icms': 0,
                    'total_pis': 0,
                    'total_cofins': 0,
                    'total_valor': 0,
                    'total_valor_tributado': 0,  # Apenas itens tributados
                    'qtd_itens': 0,
                    'tem_st': False,
                    'tem_tributado': False,
                    'tem_isento': False,  # Saída isenta/0%
                    'cfops': set(),
                    'csts': set(),
                    'aliquotas_reais': [],  # Alíquotas do XML (p_icms)
                    'aliquota_predominante': 0
                }
            
            produtos_saida[ncm]['descricoes'].add(descricao)
            produtos_saida[ncm]['total_icms'] += v_icms
            produtos_saida[ncm]['total_pis'] += v_pis
            produtos_saida[ncm]['total_cofins'] += v_cofins
            produtos_saida[ncm]['total_valor'] += valor
            produtos_saida[ncm]['qtd_itens'] += 1
            produtos_saida[ncm]['cfops'].add(cfop)
            produtos_saida[ncm]['csts'].add(cst)
            
            # Registrar alíquota real apenas de itens tributados
            if p_icms > 0:
                produtos_saida[ncm]['aliquotas_reais'].append(p_icms)
                produtos_saida[ncm]['total_valor_tributado'] += valor
            
            if is_st:
                produtos_saida[ncm]['tem_st'] = True
            elif is_isento:
                produtos_saida[ncm]['tem_isento'] = True
            else:
                produtos_saida[ncm]['tem_tributado'] = True
    
    # Calcular alíquota PREDOMINANTE (moda) usando aliquotas reais do XML
    from collections import Counter
    
    def get_aliquota_predominante(aliquotas):
        """Retorna a alíquota mais frequente (moda) ou 0 se não houver"""
        if not aliquotas:
            return 0
        # Arredondar para valores inteiros típicos de ICMS (7, 12, 18, etc.)
        aliquotas_arredondadas = [round(a) for a in aliquotas]
        counter = Counter(aliquotas_arredondadas)
        mais_comum = counter.most_common(1)
        return mais_comum[0][0] if mais_comum else 0
    
    for ncm, prod in produtos_entrada.items():
        # Alíquota predominante (moda das alíquotas reais)
        prod['aliquota_predominante'] = get_aliquota_predominante(prod.get('aliquotas_reais', []))
        # Alíquota creditável só se tiver itens tributados
        if prod['total_valor_tributado'] > 0:
            prod['aliq_creditavel'] = prod['aliquota_predominante']
        else:
            prod['aliq_creditavel'] = 0
        # Manter média para compatibilidade
        if prod['total_valor'] > 0:
            prod['aliq_icms_media'] = round((prod['total_icms'] / prod['total_valor']) * 100, 2)
        else:
            prod['aliq_icms_media'] = 0
    
    for ncm, prod in produtos_saida.items():
        # Alíquota predominante (moda das alíquotas reais)
        prod['aliquota_predominante'] = get_aliquota_predominante(prod.get('aliquotas_reais', []))
        # Manter média para compatibilidade
        if prod['total_valor'] > 0:
            prod['aliq_icms_media'] = round((prod['total_icms'] / prod['total_valor']) * 100, 2)
        else:
            prod['aliq_icms_media'] = 0
    
    # ===== IDENTIFICAR VILÕES TRIBUTÁRIOS =====
    viloes = []
    oportunidades = []
    
    # Função auxiliar para formatar moeda
    def formatCurrency(value):
        return f"R$ {value:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
    
    # Cruzar produtos entrada x saída por NCM
    ncms_comuns = set(produtos_entrada.keys()) & set(produtos_saida.keys())
    
    for ncm in ncms_comuns:
        entrada = produtos_entrada[ncm]
        saida = produtos_saida[ncm]
        
        # Usar alíquotas PREDOMINANTES (valores inteiros reais do ICMS)
        aliq_entrada = entrada.get('aliquota_predominante', 0)
        aliq_saida = saida.get('aliquota_predominante', 0)
        aliq_creditavel = entrada.get('aliq_creditavel', 0)
        
        # Usar ICMS creditável (exclui ST/Despesa/Simples) para cálculo de impacto
        icms_credito = entrada['total_icms_creditavel']
        icms_debito = saida['total_icms']
        impacto = icms_debito - icms_credito
        
        # Descrições combinadas para exibição
        descricoes_entrada = list(entrada['descricoes'])[:3]
        descricoes_saida = list(saida['descricoes'])[:3]
        descricao_principal = descricoes_entrada[0] if descricoes_entrada else (descricoes_saida[0] if descricoes_saida else ncm)
        
        # Vilão 1: Entrada com crédito menor que débito na saída (ex: entra 12%, sai 18%)
        if aliq_creditavel > 0 and aliq_saida > aliq_creditavel and impacto > 100:
            viloes.append({
                'tipo': 'ALIQUOTA_DESFAVORAVEL',
                'ncm': ncm,
                'descricao': descricao_principal,
                'descricoes_entrada': descricoes_entrada,
                'descricoes_saida': descricoes_saida,
                'aliq_entrada': aliq_creditavel,
                'aliq_saida': aliq_saida,
                'diferenca_aliquota': round(aliq_saida - aliq_creditavel, 2),
                'icms_credito': round(icms_credito, 2),
                'icms_debito': round(icms_debito, 2),
                'impacto_negativo': round(impacto, 2),
                'qtd_entrada': entrada['qtd_itens'],
                'qtd_saida': saida['qtd_itens'],
                'valor_entrada': round(entrada['total_valor'], 2),
                'valor_saida': round(saida['total_valor'], 2),
                'cfops_entrada': list(entrada['cfops']),
                'cfops_saida': list(saida['cfops']),
                'explicacao': f"Entra com crédito de {aliq_creditavel}% e sai com débito de {aliq_saida}%. Diferença de {round(aliq_saida - aliq_creditavel)}pp gera prejuízo."
            })
        
        # Vilão 2: Entrada ST (sem crédito) → Saída tributada (com débito)
        if entrada['tem_st'] and not entrada['tem_tributado'] and saida['tem_tributado'] and icms_debito > 100:
            if not any(v['ncm'] == ncm for v in viloes):  # Evitar duplicatas
                viloes.append({
                    'tipo': 'ST_ENTRADA_TRIBUTADO_SAIDA',
                    'ncm': ncm,
                    'descricao': descricao_principal,
                    'descricoes_entrada': descricoes_entrada,
                    'descricoes_saida': descricoes_saida,
                    'aliq_entrada': 0,
                    'aliq_saida': aliq_saida,
                    'diferenca_aliquota': aliq_saida,
                    'icms_credito': 0,
                    'icms_debito': round(icms_debito, 2),
                    'impacto_negativo': round(icms_debito, 2),
                    'qtd_entrada': entrada['qtd_itens'],
                    'qtd_saida': saida['qtd_itens'],
                    'valor_entrada': round(entrada['total_valor'], 2),
                    'valor_saida': round(saida['total_valor'], 2),
                    'cfops_entrada': list(entrada['cfops']),
                    'cfops_saida': list(saida['cfops']),
                    'explicacao': f"Entra com ST (sem crédito) mas sai tributado a {aliq_saida}%. Todo débito é prejuízo."
                })
        
        # Vilão 3: Compra do SIMPLES NACIONAL (sem crédito) → Saída tributada
        if entrada.get('tem_simples') and not entrada['tem_tributado'] and saida['tem_tributado'] and icms_debito > 100:
            if not any(v['ncm'] == ncm for v in viloes):
                viloes.append({
                    'tipo': 'SIMPLES_ENTRADA_TRIBUTADO_SAIDA',
                    'ncm': ncm,
                    'descricao': descricao_principal,
                    'descricoes_entrada': descricoes_entrada,
                    'descricoes_saida': descricoes_saida,
                    'aliq_entrada': 0,
                    'aliq_saida': aliq_saida,
                    'diferenca_aliquota': aliq_saida,
                    'icms_credito': 0,
                    'icms_debito': round(icms_debito, 2),
                    'impacto_negativo': round(icms_debito, 2),
                    'qtd_entrada': entrada['qtd_itens'],
                    'qtd_saida': saida['qtd_itens'],
                    'valor_entrada': round(entrada['total_valor'], 2),
                    'valor_saida': round(saida['total_valor'], 2),
                    'cfops_entrada': list(entrada['cfops']),
                    'cfops_saida': list(saida['cfops']),
                    'explicacao': f"Compra de fornecedor SIMPLES NACIONAL (sem crédito) mas sai tributado a {aliq_saida}%. Todo débito é prejuízo."
                })
        
        # ===== NOVO: Vilão 4: Alíquotas próximas mas alto imposto a recolher =====
        # Mesmo com alíquotas similares, diferença de volume gera muito imposto
        if aliq_creditavel > 0 and aliq_saida > 0 and abs(aliq_creditavel - aliq_saida) <= 2:  # Alíquotas próximas (até 2pp de diferença)
            diferenca_icms = icms_debito - icms_credito
            if diferenca_icms > 500:  # Diferença significativa > R$ 500
                if not any(v['ncm'] == ncm for v in viloes):
                    viloes.append({
                        'tipo': 'VOLUME_DESFAVORAVEL',
                        'ncm': ncm,
                        'descricao': descricao_principal,
                        'descricoes_entrada': descricoes_entrada,
                        'descricoes_saida': descricoes_saida,
                        'aliq_entrada': aliq_creditavel,
                        'aliq_saida': aliq_saida,
                        'diferenca_aliquota': round(aliq_saida - aliq_creditavel, 2),
                        'icms_credito': round(icms_credito, 2),
                        'icms_debito': round(icms_debito, 2),
                        'impacto_negativo': round(diferenca_icms, 2),
                        'qtd_entrada': entrada['qtd_itens'],
                        'qtd_saida': saida['qtd_itens'],
                        'valor_entrada': round(entrada['total_valor'], 2),
                        'valor_saida': round(saida['total_valor'], 2),
                        'cfops_entrada': list(entrada['cfops']),
                        'cfops_saida': list(saida['cfops']),
                        'explicacao': f"Alíquotas próximas ({aliq_creditavel}% vs {aliq_saida}%) mas diferença de volume: vende mais do que compra. Imposto: R$ {diferenca_icms:,.2f}."
                    })
        
        # ===== NOVO: Vilão 5: Débito alto (para Lucro Presumido, onde não há crédito) =====
        if icms_credito == 0 and icms_debito > 500:  # Sem crédito e muito débito
            if not any(v['ncm'] == ncm for v in viloes):
                viloes.append({
                    'tipo': 'DEBITO_ALTO_SEM_CREDITO',
                    'ncm': ncm,
                    'descricao': descricao_principal,
                    'descricoes_entrada': descricoes_entrada,
                    'descricoes_saida': descricoes_saida,
                    'aliq_entrada': 0,
                    'aliq_saida': aliq_saida,
                    'diferenca_aliquota': aliq_saida,
                    'icms_credito': 0,
                    'icms_debito': round(icms_debito, 2),
                    'impacto_negativo': round(icms_debito, 2),
                    'qtd_entrada': entrada['qtd_itens'],
                    'qtd_saida': saida['qtd_itens'],
                    'valor_entrada': round(entrada['total_valor'], 2),
                    'valor_saida': round(saida['total_valor'], 2),
                    'cfops_entrada': list(entrada['cfops']),
                    'cfops_saida': list(saida['cfops']),
                    'explicacao': f"Produto gera R$ {icms_debito:,.2f} de ICMS débito sem crédito na entrada. Avaliar fornecedores que gerem crédito."
                })
        
        # Oportunidade 1: Entrada tributada → Saída ST (favorável)
        if entrada['tem_tributado'] and saida['tem_st'] and not saida['tem_tributado'] and icms_credito > 100:
            oportunidades.append({
                'tipo': 'TRIBUTADO_ENTRADA_ST_SAIDA',
                'ncm': ncm,
                'descricao': descricao_principal,
                'descricoes_entrada': descricoes_entrada,
                'descricoes_saida': descricoes_saida,
                'aliq_entrada': aliq_creditavel,
                'aliq_saida': 0,
                'icms_credito': round(icms_credito, 2),
                'icms_debito': 0,
                'beneficio': round(icms_credito, 2),
                'qtd_entrada': entrada['qtd_itens'],
                'qtd_saida': saida['qtd_itens'],
                'cfops_entrada': list(entrada['cfops']),
                'cfops_saida': list(saida['cfops']),
                'explicacao': f"Entra tributado a {aliq_creditavel}% e sai com ST (sem débito). Crédito integral de R$ {round(icms_credito, 2):,.2f}."
            })
        
        # Oportunidade 2: Entrada tributada → Saída ISENTA (0%) - ex: Arroz
        if entrada['tem_tributado'] and saida.get('tem_isento') and icms_debito == 0 and icms_credito > 100:
            if not any(o['ncm'] == ncm for o in oportunidades):
                oportunidades.append({
                    'tipo': 'TRIBUTADO_ENTRADA_ISENTO_SAIDA',
                    'ncm': ncm,
                    'descricao': descricao_principal,
                    'descricoes_entrada': descricoes_entrada,
                    'descricoes_saida': descricoes_saida,
                    'aliq_entrada': aliq_creditavel,
                    'aliq_saida': 0,
                    'icms_credito': round(icms_credito, 2),
                    'icms_debito': 0,
                    'beneficio': round(icms_credito, 2),
                    'qtd_entrada': entrada['qtd_itens'],
                    'qtd_saida': saida['qtd_itens'],
                    'cfops_entrada': list(entrada['cfops']),
                    'cfops_saida': list(saida['cfops']),
                    'explicacao': f"Entra tributado a {aliq_creditavel}% e sai ISENTO (0%). Crédito integral de R$ {round(icms_credito, 2):,.2f} sem débito."
                })
        
        # Oportunidade 3: Alíquota favorável (entrada > saída com débito)
        if aliq_creditavel > 0 and aliq_saida > 0 and aliq_creditavel > aliq_saida and icms_credito > icms_debito:
            beneficio = icms_credito - icms_debito
            if beneficio > 100 and not any(o['ncm'] == ncm for o in oportunidades):
                oportunidades.append({
                    'tipo': 'ALIQUOTA_FAVORAVEL',
                    'ncm': ncm,
                    'descricao': descricao_principal,
                    'descricoes_entrada': descricoes_entrada,
                    'descricoes_saida': descricoes_saida,
                    'aliq_entrada': aliq_creditavel,
                    'aliq_saida': aliq_saida,
                    'diferenca_aliquota': round(aliq_creditavel - aliq_saida, 2),
                    'icms_credito': round(icms_credito, 2),
                    'icms_debito': round(icms_debito, 2),
                    'beneficio': round(beneficio, 2),
                    'qtd_entrada': entrada['qtd_itens'],
                    'qtd_saida': saida['qtd_itens'],
                    'cfops_entrada': list(entrada['cfops']),
                    'cfops_saida': list(saida['cfops']),
                    'explicacao': f"Entra a {aliq_creditavel}% e sai a {aliq_saida}%. Crédito maior que débito gera benefício de R$ {round(beneficio, 2):,.2f}."
                })
        
        # ===== NOVA: Oportunidade 4: Crédito próximo do débito (baixo imposto) =====
        # Produto com crédito próximo ao débito = pouco imposto a pagar
        if icms_credito > 0 and icms_debito > 0:
            diferenca = abs(icms_debito - icms_credito)
            percentual_diferenca = (diferenca / max(icms_debito, icms_credito)) * 100 if max(icms_debito, icms_credito) > 0 else 0
            
            if percentual_diferenca <= 10 and icms_credito >= 100:  # Diferença <= 10%
                if not any(o['ncm'] == ncm for o in oportunidades):
                    oportunidades.append({
                        'tipo': 'CREDITO_PROXIMO_DEBITO',
                        'ncm': ncm,
                        'descricao': descricao_principal,
                        'descricoes_entrada': descricoes_entrada,
                        'descricoes_saida': descricoes_saida,
                        'aliq_entrada': aliq_creditavel,
                        'aliq_saida': aliq_saida,
                        'icms_credito': round(icms_credito, 2),
                        'icms_debito': round(icms_debito, 2),
                        'beneficio': round(icms_credito, 2),  # O benefício é o crédito que compensa
                        'qtd_entrada': entrada['qtd_itens'],
                        'qtd_saida': saida['qtd_itens'],
                        'cfops_entrada': list(entrada['cfops']),
                        'cfops_saida': list(saida['cfops']),
                        'explicacao': f"Crédito ({formatCurrency(icms_credito)}) muito próximo do débito ({formatCurrency(icms_debito)}). Imposto líquido de apenas {formatCurrency(diferenca)}."
                    })
        
        # ===== NOVA: Oportunidade 5: Débito baixo =====
        # Produto com débito baixo em relação ao valor vendido
        if saida['total_valor'] > 1000 and icms_debito > 0:
            percentual_debito = (icms_debito / saida['total_valor']) * 100
            if percentual_debito <= 5:  # Débito <= 5% do valor vendido
                if not any(o['ncm'] == ncm for o in oportunidades):
                    oportunidades.append({
                        'tipo': 'DEBITO_BAIXO',
                        'ncm': ncm,
                        'descricao': descricao_principal,
                        'descricoes_entrada': descricoes_entrada,
                        'descricoes_saida': descricoes_saida,
                        'aliq_entrada': aliq_creditavel,
                        'aliq_saida': aliq_saida,
                        'icms_credito': round(icms_credito, 2),
                        'icms_debito': round(icms_debito, 2),
                        'beneficio': round(saida['total_valor'] - icms_debito, 2),
                        'qtd_entrada': entrada['qtd_itens'],
                        'qtd_saida': saida['qtd_itens'],
                        'valor_venda': round(saida['total_valor'], 2),
                        'cfops_entrada': list(entrada['cfops']),
                        'cfops_saida': list(saida['cfops']),
                        'explicacao': f"ICMS débito de apenas {percentual_debito:.1f}% do valor vendido (R$ {saida['total_valor']:,.2f}). Produto com carga tributária favorável."
                    })
        
        # ===== ANÁLISE DE PIS/COFINS =====
        pis_credito = entrada.get('total_pis', 0)
        pis_debito = saida.get('total_pis', 0)
        cofins_credito = entrada.get('total_cofins', 0)
        cofins_debito = saida.get('total_cofins', 0)
        
        pis_cofins_credito = pis_credito + cofins_credito
        pis_cofins_debito = pis_debito + cofins_debito
        impacto_pis_cofins = pis_cofins_debito - pis_cofins_credito
        
        # Vilão PIS/COFINS: Alto débito sem crédito proporcional
        if pis_cofins_debito > 200 and pis_cofins_credito == 0:
            if not any(v['ncm'] == ncm and v['tipo'] == 'PIS_COFINS_SEM_CREDITO' for v in viloes):
                viloes.append({
                    'tipo': 'PIS_COFINS_SEM_CREDITO',
                    'ncm': ncm,
                    'descricao': descricao_principal,
                    'descricoes_entrada': descricoes_entrada,
                    'descricoes_saida': descricoes_saida,
                    'pis_credito': round(pis_credito, 2),
                    'cofins_credito': round(cofins_credito, 2),
                    'pis_debito': round(pis_debito, 2),
                    'cofins_debito': round(cofins_debito, 2),
                    'impacto_negativo': round(impacto_pis_cofins, 2),
                    'qtd_entrada': entrada['qtd_itens'],
                    'qtd_saida': saida['qtd_itens'],
                    'valor_entrada': round(entrada['total_valor'], 2),
                    'valor_saida': round(saida['total_valor'], 2),
                    'cfops_entrada': list(entrada['cfops']),
                    'cfops_saida': list(saida['cfops']),
                    'explicacao': f"PIS/COFINS débito de R$ {pis_cofins_debito:,.2f} sem crédito na entrada. Avaliar fornecedores com destaque de PIS/COFINS."
                })
        
        # Vilão PIS/COFINS: Diferença alta entre débito e crédito
        elif impacto_pis_cofins > 300 and pis_cofins_credito > 0:
            percentual_perda = (impacto_pis_cofins / pis_cofins_debito) * 100 if pis_cofins_debito > 0 else 0
            if percentual_perda > 30 and not any(v['ncm'] == ncm and v['tipo'] == 'PIS_COFINS_DIFERENCA_ALTA' for v in viloes):
                viloes.append({
                    'tipo': 'PIS_COFINS_DIFERENCA_ALTA',
                    'ncm': ncm,
                    'descricao': descricao_principal,
                    'descricoes_entrada': descricoes_entrada,
                    'descricoes_saida': descricoes_saida,
                    'pis_credito': round(pis_credito, 2),
                    'cofins_credito': round(cofins_credito, 2),
                    'pis_debito': round(pis_debito, 2),
                    'cofins_debito': round(cofins_debito, 2),
                    'impacto_negativo': round(impacto_pis_cofins, 2),
                    'qtd_entrada': entrada['qtd_itens'],
                    'qtd_saida': saida['qtd_itens'],
                    'valor_entrada': round(entrada['total_valor'], 2),
                    'valor_saida': round(saida['total_valor'], 2),
                    'cfops_entrada': list(entrada['cfops']),
                    'cfops_saida': list(saida['cfops']),
                    'explicacao': f"Crédito PIS/COFINS de R$ {pis_cofins_credito:,.2f} vs Débito de R$ {pis_cofins_debito:,.2f}. Diferença de {percentual_perda:.0f}% gera saldo a pagar de R$ {impacto_pis_cofins:,.2f}."
                })
        
        # Oportunidade PIS/COFINS: Crédito maior que débito
        if pis_cofins_credito > pis_cofins_debito and pis_cofins_credito > 200:
            beneficio_pis_cofins = pis_cofins_credito - pis_cofins_debito
            if not any(o['ncm'] == ncm and o['tipo'] == 'PIS_COFINS_CREDITO_MAIOR' for o in oportunidades):
                oportunidades.append({
                    'tipo': 'PIS_COFINS_CREDITO_MAIOR',
                    'ncm': ncm,
                    'descricao': descricao_principal,
                    'descricoes_entrada': descricoes_entrada,
                    'descricoes_saida': descricoes_saida,
                    'pis_credito': round(pis_credito, 2),
                    'cofins_credito': round(cofins_credito, 2),
                    'pis_debito': round(pis_debito, 2),
                    'cofins_debito': round(cofins_debito, 2),
                    'beneficio': round(beneficio_pis_cofins, 2),
                    'qtd_entrada': entrada['qtd_itens'],
                    'qtd_saida': saida['qtd_itens'],
                    'valor_entrada': round(entrada['total_valor'], 2),
                    'valor_saida': round(saida['total_valor'], 2),
                    'cfops_entrada': list(entrada['cfops']),
                    'cfops_saida': list(saida['cfops']),
                    'explicacao': f"Crédito PIS/COFINS (R$ {pis_cofins_credito:,.2f}) maior que débito (R$ {pis_cofins_debito:,.2f}). Saldo credor de R$ {beneficio_pis_cofins:,.2f}."
                })
        
        # ===== ANÁLISE COMBINADA ICMS + PIS/COFINS =====
        imposto_total_credito = icms_credito + pis_cofins_credito
        imposto_total_debito = icms_debito + pis_cofins_debito
        impacto_total = imposto_total_debito - imposto_total_credito
        
        # Vilão: Produto com alta carga tributária total
        if impacto_total > 1000 and not any(v['ncm'] == ncm and v['tipo'] == 'CARGA_TRIBUTARIA_TOTAL_ALTA' for v in viloes):
            carga_percentual = (impacto_total / saida['total_valor']) * 100 if saida['total_valor'] > 0 else 0
            if carga_percentual > 15:  # Carga > 15% do valor vendido
                viloes.append({
                    'tipo': 'CARGA_TRIBUTARIA_TOTAL_ALTA',
                    'ncm': ncm,
                    'descricao': descricao_principal,
                    'descricoes_entrada': descricoes_entrada,
                    'descricoes_saida': descricoes_saida,
                    'icms_credito': round(icms_credito, 2),
                    'icms_debito': round(icms_debito, 2),
                    'pis_cofins_credito': round(pis_cofins_credito, 2),
                    'pis_cofins_debito': round(pis_cofins_debito, 2),
                    'impacto_negativo': round(impacto_total, 2),
                    'carga_percentual': round(carga_percentual, 1),
                    'qtd_entrada': entrada['qtd_itens'],
                    'qtd_saida': saida['qtd_itens'],
                    'valor_entrada': round(entrada['total_valor'], 2),
                    'valor_saida': round(saida['total_valor'], 2),
                    'cfops_entrada': list(entrada['cfops']),
                    'cfops_saida': list(saida['cfops']),
                    'explicacao': f"Carga tributária total de {carga_percentual:.1f}% ({formatCurrency(impacto_total)}). ICMS: {formatCurrency(icms_debito - icms_credito)}, PIS/COFINS: {formatCurrency(impacto_pis_cofins)}. Avaliar estratégia de fornecedores."
                })
        
        # Oportunidade: Produto com baixa carga tributária total
        if imposto_total_debito > 0 and saida['total_valor'] > 1000:
            carga_percentual = (max(0, impacto_total) / saida['total_valor']) * 100
            if carga_percentual <= 5 and not any(o['ncm'] == ncm and o['tipo'] == 'CARGA_TRIBUTARIA_BAIXA' for o in oportunidades):
                oportunidades.append({
                    'tipo': 'CARGA_TRIBUTARIA_BAIXA',
                    'ncm': ncm,
                    'descricao': descricao_principal,
                    'descricoes_entrada': descricoes_entrada,
                    'descricoes_saida': descricoes_saida,
                    'icms_credito': round(icms_credito, 2),
                    'icms_debito': round(icms_debito, 2),
                    'pis_cofins_credito': round(pis_cofins_credito, 2),
                    'pis_cofins_debito': round(pis_cofins_debito, 2),
                    'beneficio': round(saida['total_valor'], 2),
                    'carga_percentual': round(carga_percentual, 1),
                    'qtd_entrada': entrada['qtd_itens'],
                    'qtd_saida': saida['qtd_itens'],
                    'valor_entrada': round(entrada['total_valor'], 2),
                    'valor_saida': round(saida['total_valor'], 2),
                    'cfops_entrada': list(entrada['cfops']),
                    'cfops_saida': list(saida['cfops']),
                    'explicacao': f"Carga tributária baixa de apenas {carga_percentual:.1f}% sobre R$ {saida['total_valor']:,.2f} em vendas. Produto rentável tributariamente."
                })
    
    # Ordenar vilões pelo impacto (maior primeiro)
    viloes = sorted(viloes, key=lambda x: x.get('impacto_negativo', 0), reverse=True)
    oportunidades = sorted(oportunidades, key=lambda x: x.get('beneficio', 0), reverse=True)
    
    # ===== ANÁLISE POR NCM =====
    analise_ncm = {}
    
    # Usar os dados já agrupados por NCM
    for ncm, prod in produtos_entrada.items():
        if ncm not in analise_ncm:
            analise_ncm[ncm] = {
                'ncm': ncm,
                'descricoes': [],
                'entrada_valor': 0,
                'entrada_icms': 0,
                'entrada_icms_creditavel': 0,
                'entrada_qtd': 0,
                'saida_valor': 0,
                'saida_icms': 0,
                'saida_qtd': 0,
                'saldo_icms': 0,
                'margem_icms': 0,
                'tem_st_entrada': False,
                'tem_tributado_entrada': False,
                'aliq_entrada': 0,
                'aliq_saida': 0
            }
        analise_ncm[ncm]['descricoes'].extend(list(prod.get('descricoes', set()))[:2])
        analise_ncm[ncm]['entrada_valor'] += prod['total_valor']
        analise_ncm[ncm]['entrada_icms'] += prod['total_icms']
        analise_ncm[ncm]['entrada_icms_creditavel'] += prod.get('total_icms_creditavel', 0)
        analise_ncm[ncm]['entrada_qtd'] += prod['qtd_itens']
        analise_ncm[ncm]['tem_st_entrada'] = prod.get('tem_st', False)
        analise_ncm[ncm]['tem_simples_entrada'] = prod.get('tem_simples', False)
        analise_ncm[ncm]['tem_tributado_entrada'] = prod.get('tem_tributado', False)
        # Usar alíquota predominante (inteira) em vez de média
        analise_ncm[ncm]['aliq_entrada'] = prod.get('aliquota_predominante', 0)
    
    for ncm, prod in produtos_saida.items():
        if ncm not in analise_ncm:
            analise_ncm[ncm] = {
                'ncm': ncm,
                'descricoes': [],
                'entrada_valor': 0,
                'entrada_icms': 0,
                'entrada_icms_creditavel': 0,
                'entrada_qtd': 0,
                'saida_valor': 0,
                'saida_icms': 0,
                'saida_qtd': 0,
                'saldo_icms': 0,
                'margem_icms': 0,
                'tem_st_entrada': False,
                'tem_tributado_entrada': False,
                'aliq_entrada': 0,
                'aliq_saida': 0
            }
        analise_ncm[ncm]['descricoes'].extend(list(prod.get('descricoes', set()))[:2])
        analise_ncm[ncm]['saida_valor'] += prod['total_valor']
        analise_ncm[ncm]['saida_icms'] += prod['total_icms']
        analise_ncm[ncm]['saida_qtd'] += prod['qtd_itens']
        analise_ncm[ncm]['tem_isento_saida'] = prod.get('tem_isento', False)
        analise_ncm[ncm]['tem_st_saida'] = prod.get('tem_st', False)
        # Usar alíquota predominante (inteira) em vez de média
        analise_ncm[ncm]['aliq_saida'] = prod.get('aliquota_predominante', 0)
    
    # Calcular saldo e margem usando crédito correto (excluindo ST)
    for ncm, dados in analise_ncm.items():
        # Saldo = débito - crédito VÁLIDO (não conta ST/Despesa)
        credito_valido = dados['entrada_icms_creditavel']
        dados['saldo_icms'] = round(dados['saida_icms'] - credito_valido, 2)
        dados['entrada_valor'] = round(dados['entrada_valor'], 2)
        dados['entrada_icms'] = round(dados['entrada_icms'], 2)
        dados['entrada_icms_creditavel'] = round(credito_valido, 2)
        dados['saida_valor'] = round(dados['saida_valor'], 2)
        dados['saida_icms'] = round(dados['saida_icms'], 2)
        dados['aliq_entrada'] = round(dados['aliq_entrada'], 2)
        dados['aliq_saida'] = round(dados['aliq_saida'], 2)
        # Margem = quanto % do valor de saída virou imposto líquido
        if dados['saida_valor'] > 0:
            dados['margem_icms'] = round((dados['saldo_icms'] / dados['saida_valor']) * 100, 2)
        # Limitar descrições únicas a 3
        dados['descricoes'] = list(set(dados['descricoes']))[:3]
    
    analise_ncm_list = sorted(analise_ncm.values(), key=lambda x: x['saldo_icms'], reverse=True)
    
    # ===== RESUMO GERAL =====
    # Usar crédito creditável (excluindo ST/Despesa) no resumo
    total_entrada_valor = sum(p['total_valor'] for p in produtos_entrada.values())
    total_entrada_icms_creditavel = sum(p.get('total_icms_creditavel', 0) for p in produtos_entrada.values())
    total_saida_valor = sum(p['total_valor'] for p in produtos_saida.values())
    total_saida_icms = sum(p['total_icms'] for p in produtos_saida.values())
    
    resumo = {
        'total_documentos': len(documents),
        'total_entradas': len(entradas),
        'total_saidas': len(saidas),
        'valor_entradas': round(total_entrada_valor, 2),
        'valor_saidas': round(total_saida_valor, 2),
        'credito_icms': round(total_entrada_icms_creditavel, 2),  # Apenas crédito válido
        'debito_icms': round(total_saida_icms, 2),
        'saldo_icms': round(total_saida_icms - total_entrada_icms_creditavel, 2),
        'total_viloes': len(viloes),
        'impacto_viloes': round(sum(v.get('impacto_negativo', 0) for v in viloes), 2),
        'total_oportunidades': len(oportunidades),
        'beneficio_oportunidades': round(sum(o.get('beneficio', 0) for o in oportunidades), 2)
    }
    
    # ===== GERAR INSIGHTS COM IA =====
    insights_ia = None
    try:
        # Calcular métricas adicionais para análise
        margem_bruta = ((resumo['valor_saidas'] - resumo['valor_entradas']) / resumo['valor_saidas'] * 100) if resumo['valor_saidas'] > 0 else 0
        carga_tributaria_efetiva = ((resumo['debito_icms'] + resumo.get('pis_saida', 0) + resumo.get('cofins_saida', 0)) / resumo['valor_saidas'] * 100) if resumo['valor_saidas'] > 0 else 0
        aproveitamento_creditos = ((resumo['credito_icms']) / resumo['debito_icms'] * 100) if resumo['debito_icms'] > 0 else 0
        
        # Identificar compras interestaduais
        compras_interestaduais = await db.xml_documents.aggregate([
            {"$match": {"company_id": company_id, "competencia": competencia, "tipo": "entrada", **get_filtro_notas_ativas()}},
            {"$match": {"$expr": {"$ne": [{"$ifNull": ["$emitente_uf", ""]}, company.get("uf", "SP")]}}},
            {"$group": {
                "_id": "$emitente_uf",
                "valor": {"$sum": {"$toDouble": {"$ifNull": ["$valor_total", 0]}}},
                "docs": {"$sum": 1}
            }},
            {"$sort": {"valor": -1}}
        ]).to_list(10)
        
        total_interestadual = sum(c['valor'] for c in compras_interestaduais)
        pct_interestadual = (total_interestadual / resumo['valor_entradas'] * 100) if resumo['valor_entradas'] > 0 else 0
        
        # Identificar principais fornecedores
        top_fornecedores = await db.xml_documents.aggregate([
            {"$match": {"company_id": company_id, "competencia": competencia, "tipo": "entrada", **get_filtro_notas_ativas()}},
            {"$group": {
                "_id": {"cnpj": "$emitente_cnpj", "nome": "$emitente_nome"},
                "valor": {"$sum": {"$toDouble": {"$ifNull": ["$valor_total", 0]}}},
                "icms": {"$sum": {"$toDouble": {"$ifNull": ["$icms_total", 0]}}}
            }},
            {"$sort": {"valor": -1}},
            {"$limit": 5}
        ]).to_list(5)
        
        prompt = f"""Você é um consultor tributário sênior especializado em planejamento tributário brasileiro.
Faça uma análise DIRETA, OBJETIVA e ACIONÁVEL dos dados abaixo. Evite explicações genéricas.

═══════════════════════════════════════════════════════════════
                    DADOS DA EMPRESA
═══════════════════════════════════════════════════════════════
Empresa: {company.get('razao_social')}
CNPJ: {company.get('cnpj')}
Regime: {company.get('regime_tributario', 'lucro_real').upper()}
Atividade: {company.get('tipo_atividade', 'comercio').upper()}
UF: {company.get('uf', 'SP')}
Competência: {competencia}

═══════════════════════════════════════════════════════════════
                    MÉTRICAS PRINCIPAIS
═══════════════════════════════════════════════════════════════
• FATURAMENTO (Saídas): R$ {resumo['valor_saidas']:,.2f}
• COMPRAS (Entradas): R$ {resumo['valor_entradas']:,.2f}
• Margem Bruta Aparente: {margem_bruta:.1f}%
• Carga Tributária Efetiva: {carga_tributaria_efetiva:.1f}% sobre vendas

═══════════════════════════════════════════════════════════════
                    APURAÇÃO ICMS
═══════════════════════════════════════════════════════════════
• Débito ICMS (vendas): R$ {resumo['debito_icms']:,.2f}
• Crédito ICMS (compras): R$ {resumo['credito_icms']:,.2f}
• SALDO: R$ {resumo['saldo_icms']:,.2f} {'A PAGAR' if resumo['saldo_icms'] > 0 else 'CREDOR'}
• Aproveitamento de Créditos: {aproveitamento_creditos:.1f}%

═══════════════════════════════════════════════════════════════
                    COMPRAS INTERESTADUAIS
═══════════════════════════════════════════════════════════════
• % do total de compras: {pct_interestadual:.1f}%
• Valor: R$ {total_interestadual:,.2f}
• Origem principal: {compras_interestaduais[0]['_id'] if compras_interestaduais else 'N/A'} (R$ {compras_interestaduais[0]['valor']:,.2f} if compras_interestaduais else 0)
• ⚠️ ALERTA DIFAL: Compras de fora do estado geram diferencial de alíquota

═══════════════════════════════════════════════════════════════
                    TOP 5 FORNECEDORES
═══════════════════════════════════════════════════════════════
{chr(10).join([f"• {f['_id']['nome'][:40]} - R$ {f['valor']:,.2f}" for f in top_fornecedores])}

═══════════════════════════════════════════════════════════════
                    VILÕES TRIBUTÁRIOS
═══════════════════════════════════════════════════════════════
Total identificados: {resumo['total_viloes']}
Impacto negativo: R$ {resumo['impacto_viloes']:,.2f}
{chr(10).join([f"• {v.get('descricao', 'N/A')[:50]} | Impacto: R$ {v.get('impacto', 0):,.2f}" for v in viloes[:5]])}

═══════════════════════════════════════════════════════════════
                    SUA ANÁLISE (SEJA DIRETO)
═══════════════════════════════════════════════════════════════
Forneça EXATAMENTE neste formato, com BULLETS CURTOS:

## 🔴 PROBLEMAS IDENTIFICADOS
(Liste 3-4 problemas ESPECÍFICOS com valores)

## ✅ AÇÕES IMEDIATAS
(Liste 3-4 ações CONCRETAS com impacto estimado em R$)

## 💰 PRECIFICAÇÃO
(Analise se a margem cobre a carga tributária. Sugira markup mínimo)

## ⚠️ RISCOS FISCAIS
(Liste riscos de multa/autuação que precisam atenção)

## 📈 OPORTUNIDADES
(Benefícios fiscais, regimes especiais, planejamento)

REGRAS:
- Seja DIRETO. Nada de "é importante considerar" ou "recomenda-se avaliar"
- Use NÚMEROS. Mostre valores em R$ sempre que possível
- Foque em AÇÃO. O que fazer, não teoria tributária
- Máximo 3-4 bullets por seção
- Se a empresa tem saldo CREDOR de ICMS, isso é POSITIVO (vendas com ST ou isentas)"""

        llm = LlmChat(
            api_key=os.environ.get('EMERGENT_LLM_KEY'),
            session_id=f"analise_tributaria_{company_id}_{competencia}_{datetime.now().timestamp()}",
            system_message="Você é um consultor tributário objetivo e direto. Forneça análises acionáveis, sem rodeios."
        ).with_model("gemini", "gemini-2.5-flash")
        
        response = await llm.send_message(UserMessage(text=prompt))
        
        insights_ia = response if isinstance(response, str) else str(response)
        
    except Exception as e:
        logging.error(f"Erro ao gerar insights IA: {e}")
        insights_ia = f"Não foi possível gerar análise por IA: {str(e)}"
    
    # Converter sets para lists antes de retornar
    for v in viloes:
        if 'cfops_entrada' not in v:
            v['cfops_entrada'] = []
        if 'cfops_saida' not in v:
            v['cfops_saida'] = []
    
    return {
        "empresa": company.get('razao_social'),
        "competencia": competencia,
        "resumo": resumo,
        "viloes_tributarios": viloes[:20],  # Top 20 vilões
        "oportunidades": oportunidades[:20],  # Top 20 oportunidades
        "analise_por_ncm": analise_ncm_list[:30],  # Top 30 NCMs
        "insights_ia": insights_ia
    }


@api_router.post("/sped/exportar-e-validar/{company_id}")
async def exportar_e_validar_sped(
    company_id: str,
    competencia: str,
    excluir_creditos_despesa_st: bool = False,
    aplicar_beneficio_fiscal: bool = False,
    current_user: User = Depends(get_current_user)
):
    """
    Exporta o SPED Fiscal e automaticamente valida confrontando o arquivo gerado
    com os dados do sistema.
    
    Parâmetros:
    - excluir_creditos_despesa_st: Se True, exclui créditos de ICMS de CFOPs de despesa e ST
    - aplicar_beneficio_fiscal: Se True, aplica regras de benefício fiscal para créditos de ICMS
    """
    company_doc = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company_doc:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    company = Company(**company_doc)
    
    # Se não foi explicitamente passado, usar o valor do cadastro da empresa
    usar_beneficio_fiscal = aplicar_beneficio_fiscal or company_doc.get('beneficio_fiscal_icms', False)
    
    # Buscar documentos da competência - EXCLUIR notas canceladas e desconsideradas
    query = {
        "company_id": company_id,
        "competencia": competencia
    }
    query.update(get_filtro_notas_ativas())
    documents_cursor = db.xml_documents.find(query, {"_id": 0})
    documents_data = await documents_cursor.to_list(100000)
    
    if not documents_data:
        raise HTTPException(status_code=404, detail=f"Nenhum documento encontrado para competência {competencia}")
    
    documents = [XMLDocument(**d) for d in documents_data]
    
    # Gerar o SPED
    periodo = competencia.replace('/', '')
    sped_content = generate_sped_fiscal(company, documents, competencia, excluir_creditos_despesa_st, usar_beneficio_fiscal)
    
    # ===== VALIDAR O SPED GERADO =====
    # Parse do arquivo SPED para extrair totais
    sped_totais = {
        'entradas': {'por_cfop': {}, 'total_icms': 0, 'total_valor': 0},
        'saidas': {'por_cfop': {}, 'total_icms': 0, 'total_valor': 0},
        'apuracao': {'debitos': 0, 'creditos': 0, 'saldo': 0}
    }
    
    # Totais do sistema (banco de dados)
    sistema_totais = {
        'entradas': {'por_cfop': {}, 'total_icms': 0, 'total_valor': 0},
        'saidas': {'por_cfop': {}, 'total_icms': 0, 'total_valor': 0}
    }
    
    # CFOPs sem crédito (despesa e ST)
    CFOPS_SEM_CREDITO = {
        '1403', '1409', '2403', '2409', '3403', '3409',
        '1407', '2407', '1556', '2556', '1557', '2557',
        '1128', '2128', '1551', '2551', '1553', '2553',
        '1554', '2554', '1406', '2406', '1408', '2408'
    }
    
    # Lista para armazenar itens com divergência (CST tributado mas ICMS = 0)
    itens_pendentes = []
    
    # CSTs que indicam tributação de ICMS
    CSTS_TRIBUTADOS = ['00', '10', '20', '70', '90']
    
    # CFOPs de despesas, ST e outras operações que NÃO devem gerar inconsistência de ICMS
    # Esses CFOPs são desconsiderados no cálculo de crédito quando flag ativo
    CFOPS_DESPESAS_ST_IGNORAR = [
        # Despesas / Uso e Consumo
        '1556', '2556',  # Compras para uso/consumo
        '1407', '2407',  # Compra para ativo imobilizado
        '1551', '2551',  # Compra de ativo imobilizado
        '1552', '2552',  # Transferência de ativo
        '1553', '2553',  # Devolução de ativo
        '1557', '2557',  # Transferência material uso/consumo
        '1932', '2932',  # Aquisição de serviços
        '1933', '2933',  # Aquisição de serviços tributados
        '1949', '2949',  # Outras entradas não especificadas
        # Substituição Tributária (ST)
        '1401', '2401', '3401',  # Compra para industrialização com ST
        '1403', '2403', '3403',  # Compra p/ comercialização com ST
        '1406', '2406',  # Compra para ativo com ST
        '1407', '2407',  # Compra para uso/consumo com ST
        '1408', '2408',  # Transferência para industrialização com ST
        '1409', '2409', '3409',  # Transferência para comercialização com ST
        '1410', '2410',  # Devolução de venda com ST
        '1411', '2411',  # Devolução de venda p/ ZFM com ST
        # Outras operações
        '1910', '2910',  # Entrada em bonificação
        '1911', '2911',  # Entrada de amostra grátis
        '1152', '2152',  # Transferência para comercialização
        '1153', '2153',  # Transferência de energia
        '1154', '2154',  # Transferência para industrialização
        '1201', '2201',  # Devolução de venda
        '1202', '2202',  # Devolução de venda - ativo
        '1908', '2908',  # Entrada de embalagem
        '1909', '2909',  # Retorno de remessa
    ]
    
    # Calcular totais do sistema usando valores IGUAIS ao que vai no SPED
    # VL_ITEM = valor_produto + frete + seguro + outras (sem IPI, sem ST, desconto separado)
    for doc in documents:
        tipo = 'entradas' if doc.tipo == 'entrada' else 'saidas'
        
        for prod_idx, prod in enumerate(doc.produtos):
            # Usar CFOP da classificação do sistema
            cfop = str(prod.get('cfop', ''))
            
            # USAR valor_total para comparação (igual à Apuração Mensal)
            # valor_total = valor_produto + IPI + ST + frete + seg + outras - desconto
            valor = float(prod.get('valor_total', 0) or 0)
            
            # Usar ICMS do XML
            v_icms = float(prod.get('v_icms', 0) or 0)
            
            # Verificar se é item com divergência (CST tributado mas ICMS = 0)
            # IGNORAR CFOPs de despesas e outras operações
            cst_icms = str(prod.get('cst_icms', '') or prod.get('cst', '') or '')
            cst_icms_num = cst_icms[-2:] if len(cst_icms) >= 2 else cst_icms
            
            # Só adiciona pendência se NÃO for CFOP de despesa
            if cst_icms_num in CSTS_TRIBUTADOS and v_icms == 0 and valor > 0 and cfop not in CFOPS_DESPESAS_ST_IGNORAR:
                itens_pendentes.append({
                    'document_id': doc.id,
                    'product_index': prod_idx,
                    'tipo': tipo,
                    'cfop': cfop,
                    'descricao': prod.get('descricao', '')[:50],
                    'ncm': prod.get('ncm', ''),
                    'valor': round(valor, 2),
                    'cst': cst_icms,
                    'motivo': f'CST {cst_icms} indica tributação mas ICMS = R$ 0,00',
                    'numero_nf': doc.numero_nfe or '',
                    'chave': (doc.chave_nfe or '')[:20],
                    'codigo_produto': prod.get('codigo', '')
                })
            
            sistema_totais[tipo]['total_valor'] += valor
            
            # Aplicar lógica de exclusão de créditos de despesa/ST - IGUAL ao SPED
            # CFOPs de ST e Despesa não geram crédito de ICMS
            icms_para_comparacao = v_icms
            if tipo == 'entradas' and cfop in CFOPS_SEM_CREDITO:
                icms_para_comparacao = 0  # Zerar ICMS igual ao SPED
            
            sistema_totais[tipo]['total_icms'] += icms_para_comparacao
            
            if cfop not in sistema_totais[tipo]['por_cfop']:
                sistema_totais[tipo]['por_cfop'][cfop] = {'valor': 0, 'icms': 0, 'qtd': 0}
            
            sistema_totais[tipo]['por_cfop'][cfop]['valor'] += valor
            sistema_totais[tipo]['por_cfop'][cfop]['icms'] += icms_para_comparacao
            sistema_totais[tipo]['por_cfop'][cfop]['qtd'] += 1
    
    # Parse das linhas do SPED para extrair C100 e E110
    linhas = sped_content.split('\n')
    documento_atual = {'tipo': None, 'cfop': None}
    
    for linha in linhas:
        campos = linha.split('|')
        if len(campos) < 2:
            continue
        
        reg = campos[1] if len(campos) > 1 else ''
        
        # C100 - Documento (NF-e)
        if reg == 'C100':
            # |C100|IND_OPER|IND_EMIT|COD_PART|COD_MOD|COD_SIT|SER|NUM_DOC|CHV_NFE|...
            if len(campos) > 2:
                ind_oper = campos[2]  # 0=Entrada, 1=Saída
                documento_atual['tipo'] = 'entradas' if ind_oper == '0' else 'saidas'
        
        # C170 - Itens do documento
        elif reg == 'C170' and documento_atual['tipo']:
            # Layout C170 após split por '|':
            # [0]=vazio, [1]=C170, [2]=NUM_ITEM, [3]=COD_ITEM, [4]=DESCR_COMPL, [5]=QTD, [6]=UNID
            # [7]=VL_ITEM, [8]=VL_DESC, [9]=IND_MOV, [10]=CST_ICMS, [11]=CFOP, [12]=COD_NAT
            # [13]=VL_BC_ICMS, [14]=ALIQ_ICMS, [15]=VL_ICMS, [16]=VL_BC_ICMS_ST, [17]=ALIQ_ICMS_ST, [18]=VL_ICMS_ST
            # [19]=IND_APUR, [20]=CST_IPI, [21]=COD_ENQ, [22]=VL_BC_IPI, [23]=ALIQ_IPI, [24]=VL_IPI
            # [25-30]=PIS, [31-36]=COFINS
            if len(campos) > 15:
                cfop = campos[11] if len(campos) > 11 else ''
                
                # VL_ITEM = valor BRUTO (antes do desconto)
                # VL_DESC = desconto
                vl_item = float(campos[7].replace(',', '.')) if len(campos) > 7 and campos[7] else 0
                vl_desc = float(campos[8].replace(',', '.')) if len(campos) > 8 and campos[8] else 0
                
                # VL_ICMS_ST está no índice 18
                vl_icms_st = float(campos[18].replace(',', '.')) if len(campos) > 18 and campos[18] else 0
                # VL_IPI está no índice 24
                vl_ipi = float(campos[24].replace(',', '.')) if len(campos) > 24 and campos[24] else 0
                
                # valor_total no sistema = vl_item - vl_desc + vl_ipi + vl_icms_st
                valor = vl_item - vl_desc + vl_ipi + vl_icms_st
                
                # ICMS está no campo 15 - VL_ICMS
                v_icms = float(campos[15].replace(',', '.')) if len(campos) > 15 and campos[15] else 0
                
                tipo = documento_atual['tipo']
                sped_totais[tipo]['total_valor'] += valor
                
                # Aplicar mesma lógica de exclusão do sistema
                if tipo == 'entradas' and excluir_creditos_despesa_st and cfop in CFOPS_SEM_CREDITO:
                    pass  # Não conta o ICMS de despesa/ST
                else:
                    sped_totais[tipo]['total_icms'] += v_icms
                
                if cfop not in sped_totais[tipo]['por_cfop']:
                    sped_totais[tipo]['por_cfop'][cfop] = {'valor': 0, 'icms': 0, 'qtd': 0}
                
                sped_totais[tipo]['por_cfop'][cfop]['valor'] += valor
                sped_totais[tipo]['por_cfop'][cfop]['icms'] += v_icms
                sped_totais[tipo]['por_cfop'][cfop]['qtd'] += 1
        
        # E110 - Apuração ICMS
        elif reg == 'E110':
            # |E110|VL_TOT_DEBITOS|VL_AJ_DEBITOS|VL_TOT_AJ_DEBITOS|VL_ESTORNOS_CRED|VL_TOT_CREDITOS|...
            if len(campos) > 6:
                sped_totais['apuracao']['debitos'] = float(campos[2].replace(',', '.')) if campos[2] else 0
                sped_totais['apuracao']['creditos'] = float(campos[6].replace(',', '.')) if campos[6] else 0
                sped_totais['apuracao']['saldo'] = sped_totais['apuracao']['debitos'] - sped_totais['apuracao']['creditos']
    
    # ===== COMPARAR E GERAR RELATÓRIO DE VALIDAÇÃO =====
    validacao = {
        'status': 'OK',
        'divergencias': [],
        'totais_sistema': {
            'entradas': {
                'valor': round(sistema_totais['entradas']['total_valor'], 2),
                'icms': round(sistema_totais['entradas']['total_icms'], 2),
                'cfops': len(sistema_totais['entradas']['por_cfop'])
            },
            'saidas': {
                'valor': round(sistema_totais['saidas']['total_valor'], 2),
                'icms': round(sistema_totais['saidas']['total_icms'], 2),
                'cfops': len(sistema_totais['saidas']['por_cfop'])
            }
        },
        'totais_sped': {
            'entradas': {
                'valor': round(sped_totais['entradas']['total_valor'], 2),
                'icms': round(sped_totais['entradas']['total_icms'], 2),
                'cfops': len(sped_totais['entradas']['por_cfop'])
            },
            'saidas': {
                'valor': round(sped_totais['saidas']['total_valor'], 2),
                'icms': round(sped_totais['saidas']['total_icms'], 2),
                'cfops': len(sped_totais['saidas']['por_cfop'])
            }
        },
        'comparativo_cfop': {
            'entradas': [],
            'saidas': []
        }
    }
    
    # Comparar por CFOP
    for tipo in ['entradas', 'saidas']:
        all_cfops = set(sistema_totais[tipo]['por_cfop'].keys()) | set(sped_totais[tipo]['por_cfop'].keys())
        
        for cfop in sorted(all_cfops):
            sistema_cfop = sistema_totais[tipo]['por_cfop'].get(cfop, {'valor': 0, 'icms': 0, 'qtd': 0})
            sped_cfop = sped_totais[tipo]['por_cfop'].get(cfop, {'valor': 0, 'icms': 0, 'qtd': 0})
            
            diff_valor = abs(round(sistema_cfop['valor'], 2) - round(sped_cfop['valor'], 2))
            diff_icms = abs(round(sistema_cfop['icms'], 2) - round(sped_cfop['icms'], 2))
            
            # Para CFOPs de despesa/uso-consumo, ignorar diferença de ICMS
            # pois o sistema zera o ICMS (não gera crédito) mas o SPED mostra o valor original
            is_cfop_sem_credito = cfop in CFOPS_SEM_CREDITO
            
            # Status OK se os VALORES batem (divergência de ICMS em CFOPs sem crédito é esperada)
            if diff_valor < 0.01:
                if diff_icms < 0.01 or is_cfop_sem_credito:
                    status_cfop = 'OK'
                else:
                    status_cfop = 'ICMS_DIVERGENTE'
            else:
                status_cfop = 'DIVERGENTE'
            
            if status_cfop == 'DIVERGENTE':
                validacao['status'] = 'DIVERGENTE'
                validacao['divergencias'].append({
                    'tipo': tipo,
                    'cfop': cfop,
                    'valor_sistema': round(sistema_cfop['valor'], 2),
                    'valor_sped': round(sped_cfop['valor'], 2),
                    'icms_sistema': round(sistema_cfop['icms'], 2),
                    'icms_sped': round(sped_cfop['icms'], 2)
                })
            
            validacao['comparativo_cfop'][tipo].append({
                'cfop': cfop,
                'sistema': {
                    'valor': round(sistema_cfop['valor'], 2),
                    'icms': round(sistema_cfop['icms'], 2),
                    'qtd': sistema_cfop['qtd']
                },
                'sped': {
                    'valor': round(sped_cfop['valor'], 2),
                    'icms': round(sped_cfop['icms'], 2),
                    'qtd': sped_cfop['qtd']
                },
                'status': status_cfop
            })
    
    # Adicionar itens pendentes (CST tributado mas ICMS = 0) à validação
    if itens_pendentes:
        validacao['status'] = 'PENDENTE'
        validacao['itens_pendentes'] = itens_pendentes[:100]  # Limitar a 100 itens
        validacao['total_itens_pendentes'] = len(itens_pendentes)
    
    # Gerar filename
    cnpj_limpo = company.cnpj.replace('.', '').replace('/', '').replace('-', '')
    filename = f"SPED_{cnpj_limpo}_{competencia.replace('/', '')}.txt"
    
    return {
        "filename": filename,
        "content": sped_content,
        "validacao": validacao
    }


