def normalize_product_key(descricao: str) -> str:
    """Normaliza descrição do produto para usar como chave de cache"""
    import unicodedata
    # Remover acentos, converter para minúsculas, remover caracteres especiais
    text = unicodedata.normalize('NFD', descricao.lower())
    text = ''.join(c for c in text if unicodedata.category(c) != 'Mn')
    text = re.sub(r'[^a-z0-9\s]', '', text)
    text = ' '.join(text.split())  # Normalizar espaços
    return text

async def get_cached_classification(company_id: str, descricao: str) -> Optional[Dict]:
    """Busca classificação no cache (learned_rules)"""
    normalized_key = normalize_product_key(descricao)
    
    # Buscar por descrição normalizada similar
    rules = await db.learned_rules.find({
        "company_id": company_id
    }, {"_id": 0}).to_list(1000)
    
    for rule in rules:
        rule_key = normalize_product_key(rule.get('produto_descricao', ''))
        # Match exato ou substring significativa
        if rule_key == normalized_key or (len(rule_key) > 5 and rule_key in normalized_key) or (len(normalized_key) > 5 and normalized_key in rule_key):
            return {
                "categoria": rule['categoria_correta'],
                "cfop": rule['cfop_correto'],
                "justificativa": f"Memorizado: {rule.get('motivo', 'Classificação anterior')}"
            }
    return None

def get_cached_classification_from_memory(rules_cache: List[Dict], descricao: str) -> Optional[Dict]:
    """Busca classificação no cache em memória (sem query ao banco)"""
    normalized_key = normalize_product_key(descricao)
    
    for rule in rules_cache:
        rule_key = normalize_product_key(rule.get('produto_descricao', ''))
        # Match exato ou substring significativa
        if rule_key == normalized_key or (len(rule_key) > 5 and rule_key in normalized_key) or (len(normalized_key) > 5 and normalized_key in rule_key):
            # Suportar ambos os formatos de campos (com e sem sufixo _correta/_correto)
            categoria = rule.get('categoria_correta') or rule.get('categoria', 'revenda')
            cfop = rule.get('cfop_correto') or rule.get('cfop', '')
            return {
                "categoria": categoria,
                "cfop": cfop,
                "justificativa": f"Memorizado: {rule.get('motivo', 'Classificação anterior')}"
            }
    return None

async def save_classification_to_cache(company_id: str, product: Dict, categoria: str, cfop: str, justificativa: str, created_by: str = "system"):
    """Salva classificação no cache para uso futuro"""
    # Verificar se já existe
    existing = await db.learned_rules.find_one({
        "company_id": company_id,
        "produto_descricao": product.get('descricao', '')
    })
    
    if not existing:
        rule = {
            "id": str(uuid.uuid4()),
            "company_id": company_id,
            "produto_descricao": product.get('descricao', ''),
            "produto_codigo": product.get('codigo', ''),
            "ncm": product.get('ncm', ''),
            "categoria_correta": categoria,
            "cfop_correto": cfop,
            "motivo": justificativa,
            "aprendido_de": "ai_classification",
            "created_by": created_by,
            "created_at": datetime.now(timezone.utc).isoformat()
        }
        await db.learned_rules.insert_one(rule)

async def save_classifications_batch(company_id: str, classifications_to_save: List[Dict]):
    """Salva múltiplas classificações de uma vez só (otimizado)"""
    if not classifications_to_save:
        return
    
    # Buscar todas as descrições existentes de uma vez
    descricoes = [c['descricao'] for c in classifications_to_save]
    existing_cursor = db.learned_rules.find({
        "company_id": company_id,
        "produto_descricao": {"$in": descricoes}
    }, {"produto_descricao": 1, "_id": 0})
    existing_descricoes = set()
    async for doc in existing_cursor:
        existing_descricoes.add(doc.get('produto_descricao', ''))
    
    # Filtrar apenas os novos
    new_rules = []
    for c in classifications_to_save:
        if c['descricao'] not in existing_descricoes:
            new_rules.append({
                "id": str(uuid.uuid4()),
                "company_id": company_id,
                "produto_descricao": c['descricao'],
                "produto_codigo": c.get('codigo', ''),
                "ncm": c.get('ncm', ''),
                "categoria_correta": c['categoria'],
                "cfop_correto": c['cfop'],
                "motivo": c['justificativa'],
                "aprendido_de": "ai_classification",
                "created_by": "system",
                "created_at": datetime.now(timezone.utc).isoformat()
            })
            # Adicionar ao set para evitar duplicados dentro do mesmo batch
            existing_descricoes.add(c['descricao'])
    
    # Inserir em lote
    if new_rules:
        await db.learned_rules.insert_many(new_rules)
        logger.info(f"CLASSIFY: {len(new_rules)} novas regras salvas em batch")

async def classify_products_with_cache(products: List[Dict], company_id: str, company_data: Dict, emitente_uf: str = '', sales_cache: Dict = None) -> tuple:
    """
    Classifica produtos usando cache primeiro, depois IA para os não-cacheados.
    Inclui análise de produtos vendidos para melhorar a classificação.
    OTIMIZADO: Todas as classificações são salvas em batch no final.
    
    Args:
        sales_cache: Cache opcional com dados de vendas pré-carregados para evitar múltiplas queries
    
    Retorna: (resultados_classificados, stats)
    """
    results = {}
    stats = {
        "total": len(products),
        "from_cache": 0,
        "from_ai": 0,
        "from_rules": 0,
        "from_sales_inference": 0
    }
    
    # Lista para acumular classificações a serem salvas em batch no final
    classifications_to_save = []
    
    products_for_ai = []
    company_uf = company_data.get('uf', 'SP')
    
    # ===== PRÉ-CARREGAR CACHE DE CLASSIFICAÇÕES (uma única query) =====
    try:
        rules_cache = await db.learned_rules.find({
            "company_id": company_id
        }, {"_id": 0}).to_list(1000)
        logger.info(f"CLASSIFY: Cache de regras carregado - {len(rules_cache)} regras")
    except Exception as e:
        logger.warning(f"CLASSIFY: Erro ao carregar cache de regras: {e}")
        rules_cache = []
    
    # ===== ANÁLISE AVANÇADA DE PRODUTOS VENDIDOS (COM CACHE) =====
    produtos_vendidos_list = []
    ncms_vendidos = set()
    palavras_produtos_vendidos = set()
    
    # Usar cache se disponível (evita múltiplas queries durante upload em lote)
    if sales_cache and sales_cache.get('company_id') == company_id:
        ncms_vendidos = sales_cache.get('ncms_vendidos', set())
        palavras_produtos_vendidos = sales_cache.get('palavras_produtos_vendidos', set())
        produtos_vendidos_list = sales_cache.get('produtos_vendidos_list', [])
    else:
        # Buscar dados de vendas (apenas se não houver cache)
        try:
            saidas_cursor = db.xml_documents.find({
                "company_id": company_id,
                "tipo": "saida",
                **get_filtro_notas_ativas()
            }, {"produtos.descricao": 1, "produtos.ncm": 1, "_id": 0}).limit(200)
            
            saidas = await saidas_cursor.to_list(length=200)
            produtos_vendidos = set()
            
            for doc in saidas:
                for prod in doc.get('produtos', []):
                    desc = prod.get('descricao', '')
                    ncm = prod.get('ncm', '')
                    
                    if ncm and len(ncm) >= 4:
                        ncms_vendidos.add(ncm[:4])
                        ncms_vendidos.add(ncm[:6])
                    
                    if desc and len(desc) > 5:
                        palavras = [p.upper() for p in desc.split() if len(p) > 3 and p.upper() not in ['PARA', 'COM', 'SEM', 'UNID', 'PEÇA', 'PECA', 'CADA', 'CAIXA']]
                        for palavra in palavras[:3]:
                            palavras_produtos_vendidos.add(palavra)
                        if palavras:
                            produtos_vendidos.add(' '.join(palavras[:2]))
            
            produtos_vendidos_list = list(produtos_vendidos)[:50]
            
        except Exception as e:
            logger.warning(f"Erro ao buscar produtos vendidos: {e}")
    
    for idx, product in enumerate(products):
        product['_temp_id'] = str(idx)
        descricao = product.get('descricao', '')
        cfop_original = str(product.get('cfop_original_emissor', product.get('cfop', '')))
        
        # Detectar ST pelo CFOP original (mais confiável que CST)
        is_st_by_cfop = cfop_original in ['5403', '5405', '5408', '5409', '5410', '5411', '5412', '5413', '5414', '5415',
                                          '6403', '6404', '6405', '6408', '6409', '6410', '6411', '6412', '6413', '6414', '6415',
                                          '1403', '1405', '1408', '1409', '1410', '1411', '1412', '1413', '1414', '1415',
                                          '2403', '2404', '2405', '2408', '2409', '2410', '2411', '2412', '2413', '2414', '2415']
        
        # 1. Verificar cache primeiro (usando cache em memória, sem query)
        cached = get_cached_classification_from_memory(rules_cache, descricao)
        if cached:
            # SEMPRE recalcular o CFOP baseado na categoria e no ST do produto original
            cfop_prefix = '2' if (emitente_uf and emitente_uf != company_uf) else '1'
            categoria = cached.get('categoria', 'revenda').lower()
            
            # Calcular o CFOP correto para a categoria
            if categoria == 'revenda':
                cached['cfop'] = (cfop_prefix + '403') if is_st_by_cfop else (cfop_prefix + '102')
            elif categoria == 'insumo':
                cached['cfop'] = (cfop_prefix + '401') if is_st_by_cfop else (cfop_prefix + '101')
            elif categoria == 'despesa':
                cached['cfop'] = (cfop_prefix + '407') if is_st_by_cfop else (cfop_prefix + '556')
            elif categoria == 'ativo_imobilizado':
                cached['cfop'] = (cfop_prefix + '406') if is_st_by_cfop else (cfop_prefix + '551')
            elif categoria == 'combustivel':
                cached['cfop'] = cfop_prefix + '653'
            # Para outras categorias, manter o CFOP do cache
            
            results[str(idx)] = cached
            stats["from_cache"] += 1
            continue
        
        # 2. NOVA VERIFICAÇÃO: Match por NCM com produtos vendidos (aprendizado automático)
        product_ncm = product.get('ncm', '')
        if product_ncm and len(product_ncm) >= 4 and ncms_vendidos:
            ncm_match = False
            match_level = ""
            
            # Verifica match exato ou por categoria (primeiros 4-6 dígitos)
            if product_ncm[:6] in ncms_vendidos:
                ncm_match = True
                match_level = "subcategoria"
            elif product_ncm[:4] in ncms_vendidos:
                ncm_match = True
                match_level = "categoria"
            
            if ncm_match:
                cfop_prefix = '2' if (emitente_uf and emitente_uf != company_uf) else '1'
                cst = str(product.get('cst', ''))
                is_st = is_st_by_cfop or cst in ['10', '30', '60', '70', '201', '202', '203', '500']
                cfop = (cfop_prefix + '403') if is_st else (cfop_prefix + '102')
                
                results[str(idx)] = {
                    "categoria": "revenda",
                    "cfop": cfop,
                    "justificativa": f"Aprendizado automático: NCM {product_ncm[:6]} similar aos produtos vendidos pela empresa ({match_level})"
                }
                stats["from_sales_inference"] += 1
                
                # Acumular para salvar em batch no final
                classifications_to_save.append({
                    "descricao": descricao,
                    "ncm": product.get('ncm', ''),
                    "categoria": "revenda",
                    "cfop": cfop,
                    "justificativa": f"Inferido de vendas (NCM {match_level})"
                })
                continue
        
        # 3. Verificar match por palavras-chave dos produtos vendidos
        descricao_upper = descricao.upper()
        palavras_match = [p for p in palavras_produtos_vendidos if p in descricao_upper and len(p) > 4]
        if len(palavras_match) >= 2:  # Pelo menos 2 palavras em comum
            cfop_prefix = '2' if (emitente_uf and emitente_uf != company_uf) else '1'
            cst = str(product.get('cst', ''))
            is_st = is_st_by_cfop or cst in ['10', '30', '60', '70', '201', '202', '203', '500']
            cfop = (cfop_prefix + '403') if is_st else (cfop_prefix + '102')
            
            results[str(idx)] = {
                "categoria": "revenda",
                "cfop": cfop,
                "justificativa": f"Aprendizado automático: Palavras '{', '.join(palavras_match[:3])}' encontradas em produtos vendidos"
            }
            stats["from_sales_inference"] += 1
            
            # Acumular para salvar em batch no final
            classifications_to_save.append({
                "descricao": descricao,
                "ncm": product.get('ncm', ''),
                "categoria": "revenda",
                "cfop": cfop,
                "justificativa": f"Inferido de vendas (palavras-chave)"
            })
            continue
        
        # 4. Verificar regras diretas (keywords cadastradas pelo usuário)
        produtos_comercializados = company_data.get('produtos_comercializados', [])
        insumos_producao = company_data.get('insumos_producao', [])
        produtos_despesa = company_data.get('produtos_despesa', [])
        
        categoria, justificativa = classify_product_category(
            descricao,
            product.get('ncm', ''),
            produtos_comercializados,
            insumos_producao,
            produtos_despesa
        )
        
        is_strong_match = "cadastrado" in justificativa.lower()
        
        if is_strong_match:
            # Prefixo baseado em UF
            cfop_prefix = '2' if (emitente_uf and emitente_uf != company_uf) else '1'
            cst = str(product.get('cst', ''))
            # ST: verifica tanto pelo CST quanto pelo CFOP original
            is_st = is_st_by_cfop or cst in ['10', '30', '60', '70', '201', '202', '203', '500']
            
            if categoria == 'revenda':
                cfop = (cfop_prefix + '403') if is_st else (cfop_prefix + '102')
            elif categoria == 'insumo':
                cfop = (cfop_prefix + '401') if is_st else (cfop_prefix + '101')
            elif categoria == 'despesa':
                cfop = (cfop_prefix + '407') if is_st else (cfop_prefix + '556')  # Uso e consumo
            elif categoria == 'ativo_imobilizado':
                cfop = (cfop_prefix + '406') if is_st else (cfop_prefix + '551')  # Ativo imobilizado
            elif categoria == 'combustivel':
                cfop = cfop_prefix + '653'
            else:
                cfop = cfop_prefix + '102'
            
            results[str(idx)] = {
                "categoria": categoria,
                "cfop": cfop,
                "justificativa": justificativa
            }
            stats["from_rules"] += 1
            continue
        
        # 3. Enviar para IA (guarda is_st_by_cfop para uso posterior)
        product['_is_st_by_cfop'] = is_st_by_cfop
        products_for_ai.append(product)
    
    # Classificar com IA os produtos restantes (inclui produtos vendidos para inferência)
    if products_for_ai:
        ai_results = await classify_products_batch_llm(products_for_ai, company_data, produtos_vendidos=produtos_vendidos_list)
        
        for product in products_for_ai:
            p_id = product.get('_temp_id')
            if p_id in ai_results:
                ai_result = ai_results[p_id]
                categoria = ai_result['categoria']
                
                # Calcular CFOP
                cfop_prefix = '2' if (emitente_uf and emitente_uf != company_uf) else '1'
                cst = str(product.get('cst', ''))
                # ST: verifica tanto pelo CST quanto pelo CFOP original
                is_st = product.get('_is_st_by_cfop', False) or cst in ['10', '30', '60', '70', '201', '202', '203', '500']
                
                if categoria == 'revenda':
                    cfop = (cfop_prefix + '403') if is_st else (cfop_prefix + '102')
                elif categoria == 'insumo':
                    cfop = (cfop_prefix + '401') if is_st else (cfop_prefix + '101')
                elif categoria == 'despesa':
                    cfop = (cfop_prefix + '407') if is_st else (cfop_prefix + '556')  # Uso e consumo
                elif categoria == 'combustivel':
                    cfop = cfop_prefix + '653'
                elif categoria == 'ativo_imobilizado':
                    cfop = (cfop_prefix + '406') if is_st else (cfop_prefix + '551')  # Ativo imobilizado
                else:
                    cfop = cfop_prefix + '102'
                
                justificativa = f"IA ({categoria.upper()}): {ai_result['justificativa']}"
                
                results[p_id] = {
                    "categoria": categoria,
                    "cfop": cfop,
                    "justificativa": justificativa
                }
                
                # Acumular para salvar em batch no final
                classifications_to_save.append({
                    "descricao": product.get('descricao', ''),
                    "codigo": product.get('codigo', ''),
                    "ncm": product.get('ncm', ''),
                    "categoria": categoria,
                    "cfop": cfop,
                    "justificativa": justificativa
                })
                
                stats["from_ai"] += 1
            else:
                # Fallback baseado no tipo de atividade da empresa
                tipo_atividade = company_data.get('tipo_atividade', 'comercio')
                cfop_prefix = '2' if (emitente_uf and emitente_uf != company_uf) else '1'
                is_st = product.get('_is_st_by_cfop', False) or str(product.get('cst', '')) in ['10', '30', '60', '70', '201', '202', '203', '500']
                
                # Determinar categoria padrão baseado no tipo de atividade
                if tipo_atividade == 'servicos':
                    categoria_padrao = 'aplicacao_servico'
                    cfop_padrao = cfop_prefix + '128' if not is_st else cfop_prefix + '401'
                    justificativa_padrao = "Classificado automaticamente como APLICAÇÃO EM SERVIÇOS (empresa de serviços)"
                else:
                    # Comercio, industria ou mista → padrão é revenda
                    categoria_padrao = 'revenda'
                    cfop_padrao = (cfop_prefix + '403') if is_st else (cfop_prefix + '102')
                    justificativa_padrao = "Classificado automaticamente como COMPRA P/ REVENDA (padrão comercial)"
                
                results[p_id] = {
                    "categoria": categoria_padrao,
                    "cfop": cfop_padrao,
                    "justificativa": justificativa_padrao
                }
                stats["from_rules"] += 1  # Conta como regra automática
    
    # GARANTIR que TODOS os produtos tenham classificação (eliminar pendentes)
    for idx, product in enumerate(products):
        p_id = str(idx)
        if p_id not in results:
            tipo_atividade = company_data.get('tipo_atividade', 'comercio')
            cfop_prefix = '2' if (emitente_uf and emitente_uf != company_uf) else '1'
            is_st_by_cfop = str(product.get('cfop_original_emissor', product.get('cfop', ''))) in [
                '5403', '5405', '6403', '6404', '1403', '2403', '2404', '2405'
            ]
            is_st = is_st_by_cfop or str(product.get('cst', '')) in ['10', '30', '60', '70', '201', '202', '203', '500']
            
            if tipo_atividade == 'servicos':
                results[p_id] = {
                    "categoria": "aplicacao_servico",
                    "cfop": cfop_prefix + '128' if not is_st else cfop_prefix + '401',
                    "justificativa": "Auto: Aplicação em serviços (empresa de serviços)"
                }
            else:
                results[p_id] = {
                    "categoria": "revenda",
                    "cfop": (cfop_prefix + '403') if is_st else (cfop_prefix + '102'),
                    "justificativa": "Auto: Compra para revenda (padrão comercial)"
                }
            stats["from_rules"] += 1
    
    # ===== SALVAR TODAS AS CLASSIFICAÇÕES EM BATCH (uma única operação no banco) =====
    if classifications_to_save:
        try:
            await save_classifications_batch(company_id, classifications_to_save)
        except Exception as e:
            logger.warning(f"CLASSIFY: Erro ao salvar classificações em batch: {e}")
    
    return results, stats

async def classify_products_batch_llm(products: List[Dict[str, Any]], company_data: Dict[str, Any], batch_size: int = 20, produtos_vendidos: List[str] = None) -> Dict[str, Any]:
    """
    Classifica uma lista de produtos usando LLM com base nas regras da empresa.
    PRIORIDADE: 
    1. Palavras-chave cadastradas na empresa têm MÁXIMA prioridade.
    2. Análise de produtos vendidos (saídas) para inferir o que a empresa comercializa.
    """
    if not products:
        return {}
        
    classified_results = {}
    
    # Extrair palavras-chave cadastradas (com destaque para importância)
    revenda_keywords = company_data.get('produtos_comercializados', [])
    insumo_keywords = company_data.get('insumos_producao', [])
    despesa_keywords = company_data.get('produtos_despesa', [])
    ativo_keywords = company_data.get('ativo_imobilizado', [])
    combustivel_keywords = company_data.get('combustivel', [])
    
    # Seção de produtos vendidos (inferência)
    produtos_vendidos_section = ""
    if produtos_vendidos and len(produtos_vendidos) > 0:
        produtos_vendidos_section = f"""
=== PRODUTOS QUE A EMPRESA JÁ VENDE (ANÁLISE DE SAÍDAS) ===
Com base nas notas de saída da empresa, estes são os produtos que ela comercializa:
{', '.join(produtos_vendidos[:50])}

REGRA: Se o produto sendo classificado é SIMILAR ou RELACIONADO aos produtos vendidos, provavelmente é REVENDA.
Por exemplo: se a empresa vende "ESPONJA DE AÇO" e está comprando "ESPONJA MULTIUSO", classifique como REVENDA.
"""
    
    # Construir contexto da empresa com ênfase nas palavras-chave
    context = f"""Você é um especialista em classificação fiscal de produtos.

=== EMPRESA ===
Nome: {company_data.get('razao_social', 'N/A')}
Atividade: {company_data.get('tipo_atividade', 'comercio')}
CNAE: {company_data.get('cnae_principal_descricao', 'N/A')}

=== REGRAS ABSOLUTAS DE CLASSIFICAÇÃO (MÁXIMA PRIORIDADE) ===
O cliente cadastrou as seguintes palavras-chave para classificação. 
Se o produto corresponder a QUALQUER uma destas palavras-chave, USE ESSA CLASSIFICAÇÃO.
Use correspondência SEMÂNTICA - não precisa ser exata, produtos relacionados também devem ser incluídos.

🛒 REVENDA (produtos para comercialização): 
{', '.join(revenda_keywords) if revenda_keywords else '(nenhum cadastrado)'}

⚙️ INSUMO (matéria-prima para produção): 
{', '.join(insumo_keywords) if insumo_keywords else '(nenhum cadastrado)'}

📋 DESPESA (uso e consumo da empresa): 
{', '.join(despesa_keywords) if despesa_keywords else '(nenhum cadastrado)'}

🏭 ATIVO IMOBILIZADO (bens permanentes): 
{', '.join(ativo_keywords) if ativo_keywords else '(nenhum cadastrado)'}

⛽ COMBUSTÍVEL: 
{', '.join(combustivel_keywords) if combustivel_keywords else '(nenhum cadastrado)'}
{produtos_vendidos_section}
=== REGRAS GERAIS (se não houver match com palavras-chave ou produtos vendidos) ===
- DESPESA: materiais de limpeza, escritório, manutenção, uso interno
- ATIVO_IMOBILIZADO: máquinas, equipamentos, veículos, móveis, computadores
- COMBUSTIVEL: gasolina, diesel, etanol, GNV
- INSUMO: matéria-prima para produção/industrialização
- REVENDA: produtos para revenda (padrão para empresas comerciais)

=== IMPORTANTE ===
1. Se o produto tem QUALQUER relação com as palavras-chave cadastradas, USE essa classificação
2. Se não houver palavra-chave mas houver SIMILARIDADE com produtos vendidos, classifique como REVENDA
3. Use busca SEMÂNTICA (sinônimos, variações, termos relacionados)
4. Exemplo: se "construção" está em REVENDA, então "cimento", "argamassa", "tijolo" também são REVENDA
5. Na justificativa, indique qual palavra-chave ou produto vendido você usou como referência

Responda APENAS um JSON válido:
{{
    "resultados": [
        {{
            "id": "id_do_produto",
            "categoria": "revenda|insumo|despesa|ativo_imobilizado|combustivel",
            "justificativa": "Baseado em [palavra-chave/produto vendido] cadastrada como [categoria]" ou "Regra geral: [motivo]"
        }}
    ]
}}"""
    
    # Adicionar ID temporário para cada produto para garantir mapeamento correto
    for idx, p in enumerate(products):
        p['_temp_id'] = str(idx)
    
    for i in range(0, len(products), batch_size):
        batch = products[i:i+batch_size]
        
        batch_prompt = "Classifique estes produtos:\n" + json.dumps([{
            'id': p['_temp_id'],
            'descricao': p['descricao'],
            'ncm': p['ncm']
        } for p in batch], ensure_ascii=False)
        
        try:
            chat = await get_ai_chat(session_id=f"classification_{uuid.uuid4()}", system_message=context)
            response = await chat.send_message(UserMessage(text=batch_prompt))
            
            # Extrair JSON
            response_text = response.strip()
            if "```json" in response_text:
                response_text = response_text.split("```json")[1].split("```")[0]
            elif "```" in response_text:
                response_text = response_text.split("```")[1].split("```")[0]
                
            result = json.loads(response_text)
            
            for item in result.get('resultados', []):
                classified_results[item['id']] = {
                    "categoria": item['categoria'],
                    "justificativa": item['justificativa']
                }
                
        except Exception as e:
            print(f"Erro na classificação LLM: {str(e)}")
            continue
            
    return classified_results

@api_router.post("/manual-reclassify")
async def run_analise_task_wrapper(task_id: str, request: AnaliseTributariaRequest):
    try:
        tasks_store[task_id] = {"status": "processing", "progress": 0}
        result = await internal_analise_tributaria(request)
        tasks_store[task_id] = {"status": "completed", "result": result}
    except Exception as e:
        tasks_store[task_id] = {"status": "error", "error": str(e)}

@api_router.post("/ai/analise-tributaria")
async def ai_analise_tributaria(
    request: AnaliseTributariaRequest,
    background_tasks: BackgroundTasks,
    current_user: User = Depends(get_current_user)
):
    """Inicia análise tributária em background"""
    task_id = str(uuid.uuid4())
    tasks_store[task_id] = {"status": "pending"}
    background_tasks.add_task(run_analise_task_wrapper, task_id, request)
    return {"task_id": task_id, "status": "pending"}

@api_router.get("/ai/tasks/{task_id}")
async def get_task_status(task_id: str):
    task = tasks_store.get(task_id)
    if not task:
        raise HTTPException(status_code=404, detail="Task not found")
    return task

async def manual_reclassify_product(
    doc_id: str,
    produto_codigo: str,
    novo_cfop: str,
    nova_categoria: str,
    motivo: str,
    salvar_regra: bool = True,
    current_user: User = Depends(get_current_user)
):
    """Reclassifica manualmente um produto e opcionalmente salva como regra aprendida"""
    doc = await db.xml_documents.find_one({"id": doc_id}, {"_id": 0})
    if not doc:
        raise HTTPException(status_code=404, detail="Documento não encontrado")
    
    produto_atualizado = None
    produtos_atualizados = []
    
    for prod in doc.get('produtos', []):
        if prod.get('codigo') == produto_codigo:
            prod['cfop_original'] = prod.get('cfop', '')
            prod['cfop'] = novo_cfop
            prod['categoria_classificada'] = nova_categoria
            prod['reclassificado_manualmente'] = True
            prod['motivo_reclassificacao'] = motivo
            prod['reclassificado_por'] = current_user.id
            prod['data_reclassificacao'] = datetime.now(timezone.utc).isoformat()
            produto_atualizado = prod
        produtos_atualizados.append(prod)
    
    if not produto_atualizado:
        raise HTTPException(status_code=404, detail="Produto não encontrado no documento")
    
    await db.xml_documents.update_one(
        {"id": doc_id},
        {"$set": {"produtos": produtos_atualizados}}
    )
    
    # Salvar como regra aprendida
    if salvar_regra:
        learned_rule = LearnedRule(
            company_id=doc['company_id'],
            produto_descricao=produto_atualizado.get('descricao', ''),
            produto_codigo=produto_codigo,
            ncm=produto_atualizado.get('ncm', ''),
            categoria_correta=nova_categoria,
            cfop_correto=novo_cfop,
            motivo=motivo,
            aprendido_de='user_correction',
            created_by=current_user.id
        )
        rule_doc = learned_rule.model_dump()
        rule_doc['created_at'] = rule_doc['created_at'].isoformat()
        await db.learned_rules.insert_one(rule_doc)
    
    return {
        "success": True,
        "produto_atualizado": produto_atualizado,
        "regra_salva": salvar_regra
    }

# Estoque por Competência
class EstoqueCompetencia(BaseModel):
    competencia: str
    estoque_inicial: float = 0
    estoque_final: float = 0

@api_router.get("/estoque-competencia/{company_id}")
async def get_estoque_competencia(company_id: str, competencia: str, current_user: dict = Depends(get_current_user)):
    """Buscar estoque de uma competência específica"""
    estoque = await db.estoques_competencia.find_one(
        {"company_id": company_id, "competencia": competencia},
        {"_id": 0}
    )
    if not estoque:
        return {"estoque_inicial": 0, "estoque_final": 0}
    return estoque

@api_router.post("/estoque-competencia/{company_id}")
async def save_estoque_competencia(company_id: str, estoque: EstoqueCompetencia, current_user: dict = Depends(get_current_user)):
    """Salvar estoque de uma competência"""
    await db.estoques_competencia.update_one(
        {"company_id": company_id, "competencia": estoque.competencia},
        {"$set": {
            "company_id": company_id,
            "competencia": estoque.competencia,
            "estoque_inicial": estoque.estoque_inicial,
            "estoque_final": estoque.estoque_final,
            "updated_at": datetime.now(timezone.utc)
        }},
        upsert=True
    )
    return {"success": True, "message": "Estoque salvo com sucesso"}


@api_router.get("/relacao-notas/{company_id}")
async def relacao_notas(
    company_id: str,
    competencia: str,
    incluir_canceladas: bool = True,
    current_user: User = Depends(get_current_user)
):
    """
    Retorna relação completa de notas fiscais com CFOP, valores e status (ativa/cancelada).
    Inclui tanto entradas quanto saídas.
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Buscar documentos - incluir ou não canceladas
    query = {
        "company_id": company_id,
        "competencia": competencia
    }
    
    if not incluir_canceladas:
        query.update(get_filtro_notas_ativas())
    
    documents = await db.xml_documents.find(
        query, 
        {"_id": 0, "xml_content": 0}
    ).to_list(None)
    
    # Processar notas
    notas = []
    for doc in documents:
        # Determinar se é entrada ou saída pelo CFOP dos produtos
        tipo_operacao = doc.get('tipo', '')
        produtos = doc.get('produtos', [])
        
        # Calcular totais por CFOP da nota
        cfops_nota = {}
        for prod in produtos:
            cfop = str(prod.get('cfop', '') or '')
            valor = float(prod.get('valor_total', 0) or 0)
            v_icms = float(prod.get('v_icms', 0) or 0)
            v_pis = float(prod.get('v_pis', 0) or 0)
            v_cofins = float(prod.get('v_cofins', 0) or 0)
            
            if cfop not in cfops_nota:
                cfops_nota[cfop] = {
                    'valor': 0,
                    'v_icms': 0,
                    'v_pis': 0,
                    'v_cofins': 0,
                    'qtd_itens': 0
                }
            
            cfops_nota[cfop]['valor'] += valor
            cfops_nota[cfop]['v_icms'] += v_icms
            cfops_nota[cfop]['v_pis'] += v_pis
            cfops_nota[cfop]['v_cofins'] += v_cofins
            cfops_nota[cfop]['qtd_itens'] += 1
        
        # Determinar o CFOP principal (o de maior valor)
        cfop_principal = ''
        if cfops_nota:
            cfop_principal = max(cfops_nota.keys(), key=lambda k: cfops_nota[k]['valor']) if cfops_nota else ''
        
        # Determinar tipo pela CFOP principal
        if cfop_principal:
            primeiro = cfop_principal[0] if cfop_principal else ''
            if primeiro in ['1', '2', '3']:
                tipo_operacao = 'entrada'
            elif primeiro in ['5', '6', '7']:
                tipo_operacao = 'saida'
        
        # Status da nota
        cancelada = doc.get('cancelada', False)
        status = 'CANCELADA' if cancelada else 'ATIVA'
        
        nota_info = {
            'numero_nfe': doc.get('numero_nfe', ''),
            'chave_nfe': doc.get('chave_nfe', ''),
            'data_emissao': doc.get('data_emissao', ''),
            'emitente_cnpj': doc.get('emitente_cnpj', ''),
            'emitente_nome': doc.get('emitente_nome', ''),
            'destinatario_cnpj': doc.get('destinatario_cnpj', ''),
            'destinatario_nome': doc.get('destinatario_nome', ''),
            'tipo_operacao': tipo_operacao,
            'cfop_principal': cfop_principal,
            'valor_total': doc.get('valor_total', 0),
            'status': status,
            'cancelada': cancelada,
            # Dados de cancelamento (se houver)
            'cStat_cancelamento': doc.get('cStat_cancelamento', ''),
            'xMotivo_cancelamento': doc.get('xMotivo_cancelamento', ''),
            'dhRecbto_cancelamento': doc.get('dhRecbto_cancelamento', ''),
            # Detalhamento por CFOP
            'cfops_detalhados': [
                {
                    'cfop': cfop,
                    'valor': round(dados['valor'], 2),
                    'v_icms': round(dados['v_icms'], 2),
                    'v_pis': round(dados['v_pis'], 2),
                    'v_cofins': round(dados['v_cofins'], 2),
                    'qtd_itens': dados['qtd_itens']
                }
                for cfop, dados in cfops_nota.items()
            ]
        }
        
        notas.append(nota_info)
    
    # Ordenar por tipo e número da NF
    notas.sort(key=lambda x: (x['tipo_operacao'], x['numero_nfe']))
    
    # Separar entradas e saídas
    entradas = [n for n in notas if n['tipo_operacao'] == 'entrada']
    saidas = [n for n in notas if n['tipo_operacao'] == 'saida']
    
    # Totalizadores
    total_entradas_ativas = sum(n['valor_total'] for n in entradas if not n['cancelada'])
    total_entradas_canceladas = sum(n['valor_total'] for n in entradas if n['cancelada'])
    total_saidas_ativas = sum(n['valor_total'] for n in saidas if not n['cancelada'])
    total_saidas_canceladas = sum(n['valor_total'] for n in saidas if n['cancelada'])
    
    return {
        "empresa": {
            "id": company_id,
            "razao_social": company.get('razao_social', ''),
            "cnpj": company.get('cnpj', '')
        },
        "competencia": competencia,
        "resumo": {
            "total_notas": len(notas),
            "entradas": {
                "total": len(entradas),
                "ativas": len([n for n in entradas if not n['cancelada']]),
                "canceladas": len([n for n in entradas if n['cancelada']]),
                "valor_ativas": round(total_entradas_ativas, 2),
                "valor_canceladas": round(total_entradas_canceladas, 2)
            },
            "saidas": {
                "total": len(saidas),
                "ativas": len([n for n in saidas if not n['cancelada']]),
                "canceladas": len([n for n in saidas if n['cancelada']]),
                "valor_ativas": round(total_saidas_ativas, 2),
                "valor_canceladas": round(total_saidas_canceladas, 2)
            }
        },
        "entradas": entradas,
        "saidas": saidas
    }


@api_router.get("/relacao-notas-detalhada/{company_id}")
async def relacao_notas_detalhada(
    company_id: str,
    competencia: str,
    incluir_canceladas: bool = True,
    current_user: User = Depends(get_current_user)
):
    """
    Retorna relação completa de notas fiscais com DETALHAMENTO de impostos (IPI, ST, Frete, Desconto).
    Mostra separadamente cada componente do valor da NF.
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Buscar documentos
    query = {
        "company_id": company_id,
        "competencia": competencia
    }
    
    if not incluir_canceladas:
        query.update(get_filtro_notas_ativas())
    
    documents = await db.xml_documents.find(
        query, 
        {"_id": 0, "xml_content": 0}
    ).to_list(None)
    
    # Processar notas
    notas = []
    for doc in documents:
        produtos = doc.get('produtos', [])
        
        # Calcular totais dos produtos
        total_valor_produto = 0
        total_ipi = 0
        total_icms_st = 0
        total_frete = 0
        total_seguro = 0
        total_outras = 0
        total_desconto = 0
        
        # Determinar CFOP principal
        cfop_valores = {}
        for prod in produtos:
            cfop = str(prod.get('cfop', '') or '')
            valor_prod = float(prod.get('valor_produto', 0) or 0)
            v_ipi = float(prod.get('v_ipi', 0) or 0)
            v_st = float(prod.get('v_icms_st', 0) or 0)
            v_frete = float(prod.get('v_frete', 0) or 0)
            v_seg = float(prod.get('v_seguro', 0) or 0)
            v_outro = float(prod.get('v_outras_despesas', 0) or 0)
            v_desc = float(prod.get('v_desconto', 0) or 0)
            
            total_valor_produto += valor_prod
            total_ipi += v_ipi
            total_icms_st += v_st
            total_frete += v_frete
            total_seguro += v_seg
            total_outras += v_outro
            total_desconto += v_desc
            
            if cfop:
                if cfop not in cfop_valores:
                    cfop_valores[cfop] = 0
                cfop_valores[cfop] += valor_prod
        
        # CFOP principal
        cfop_principal = max(cfop_valores.keys(), key=lambda k: cfop_valores[k]) if cfop_valores else ''
        
        # Determinar tipo pela CFOP principal
        tipo_operacao = doc.get('tipo', '')
        if cfop_principal:
            primeiro = cfop_principal[0] if cfop_principal else ''
            if primeiro in ['1', '2', '3']:
                tipo_operacao = 'entrada'
            elif primeiro in ['5', '6', '7']:
                tipo_operacao = 'saida'
        
        # Status da nota
        cancelada = doc.get('cancelada', False)
        status = 'CANCELADA' if cancelada else 'ATIVA'
        
        nota_info = {
            'numero_nfe': doc.get('numero_nfe', ''),
            'chave_nfe': doc.get('chave_nfe', ''),
            'data_emissao': doc.get('data_emissao', ''),
            'emitente_cnpj': doc.get('emitente_cnpj', ''),
            'emitente_nome': doc.get('emitente_nome', ''),
            'destinatario_cnpj': doc.get('destinatario_cnpj', ''),
            'destinatario_nome': doc.get('destinatario_nome', ''),
            'tipo_operacao': tipo_operacao,
            'cfop_principal': cfop_principal,
            # Valor total da NF (conforme XML)
            'valor_total': round(doc.get('valor_total', 0), 2),
            # Detalhamento dos componentes
            'total_valor_produto': round(total_valor_produto, 2),  # vProd
            'total_ipi': round(total_ipi, 2),
            'total_icms_st': round(total_icms_st, 2),
            'total_frete': round(total_frete, 2),
            'total_seguro': round(total_seguro, 2),
            'total_outras_despesas': round(total_outras, 2),
            'total_desconto': round(total_desconto, 2),
            # Valor calculado = vProd + IPI + ST + Frete + Seg + Outras - Desc
            'valor_calculado': round(total_valor_produto + total_ipi + total_icms_st + total_frete + total_seguro + total_outras - total_desconto, 2),
            # Diferença
            'diferenca': round(doc.get('valor_total', 0) - (total_valor_produto + total_ipi + total_icms_st + total_frete + total_seguro + total_outras - total_desconto), 2),
            'status': status,
            'cancelada': cancelada
        }
        
        notas.append(nota_info)
    
    # Ordenar por tipo e número da NF
    notas.sort(key=lambda x: (x['tipo_operacao'], x['numero_nfe']))
    
    # Separar entradas e saídas
    entradas = [n for n in notas if n['tipo_operacao'] == 'entrada']
    saidas = [n for n in notas if n['tipo_operacao'] == 'saida']
    
    return {
        "empresa": {
            "id": company_id,
            "razao_social": company.get('razao_social', ''),
            "cnpj": company.get('cnpj', '')
        },
        "competencia": competencia,
        "entradas": entradas,
        "saidas": saidas
    }


# ============================================================
# APURAÇÃO - RESUMO DO MOVIMENTO POR CFOP
# ============================================================

# Função para obter descrição genérica do CFOP
def obter_descricao_cfop_generica(cfop: str) -> str:
    """Retorna uma descrição genérica baseada no padrão do CFOP"""
    if not cfop or cfop == 'SEM CFOP':
        return "Sem CFOP definido"
    
    # Dicionário de descrições por CFOP comum
    descricoes = {
        '1101': 'Compra p/ industrialização',
        '1102': 'Compra p/ comercialização',
        '1116': 'Compra p/ industrialização originada de encomenda p/ entrega futura',
        '1117': 'Compra p/ comercialização originada de encomenda p/ entrega futura',
        '1201': 'Devolução de venda',
        '1202': 'Devolução de venda de merc. de terceiros',
        '1403': 'Compra p/ comercialização em ST',
        '1407': 'Compra de mercadoria p/ uso ou consumo',
        '1411': 'Devolução de venda ST',
        '1501': 'Entrada de energia elétrica',
        '1551': 'Compra de bem p/ ativo imobilizado',
        '1556': 'Compra de material p/ uso ou consumo',
        '1653': 'Compra de combustível ou lubrificante',
        '1910': 'Entrada de bonificação, doação',
        '1911': 'Entrada de amostra grátis',
        '1949': 'Outra entrada não especificada',
        '2101': 'Compra p/ industrialização (interestadual)',
        '2102': 'Compra p/ comercialização (interestadual)',
        '2403': 'Compra p/ comercialização ST (interestadual)',
        '2407': 'Compra de mercadoria p/ uso ou consumo (interestadual)',
        '2551': 'Compra de bem p/ ativo imobilizado (interestadual)',
        '2556': 'Compra de material p/ uso ou consumo (interestadual)',
        '2949': 'Outra entrada não especificada (interestadual)',
        '5101': 'Venda de produção própria',
        '5102': 'Venda de merc. adquirida',
        '5116': 'Venda produção estabelecimento',
        '5117': 'Venda merc. adquirida ou recebida de terceiros',
        '5118': 'Venda de produção por encomenda',
        '5201': 'Devolução de compra p/ industrialização',
        '5202': 'Devolução de compra p/ comercialização',
        '5401': 'Venda de produção ST',
        '5403': 'Venda de merc. adquirida ST',
        '5405': 'Venda de merc. adquirida ST p/ contrib. substituído',
        '5501': 'Remessa de energia elétrica',
        '5901': 'Remessa p/ industrialização por encomenda',
        '5902': 'Retorno de merc. industrialização',
        '5910': 'Remessa em bonificação',
        '5911': 'Remessa de amostra grátis',
        '5949': 'Outra saída não especificada',
        '6101': 'Venda produção própria (interestadual)',
        '6102': 'Venda merc. adquirida (interestadual)',
        '6108': 'Venda de merc. adquirida por conta e ordem de terceiros',
        '6401': 'Venda produção ST (interestadual)',
        '6403': 'Venda merc. adquirida ST (interestadual)',
        '6949': 'Outra saída não especificada (interestadual)',
    }
    
    if cfop in descricoes:
        return descricoes[cfop]
    
    # Descrição genérica baseada no primeiro dígito
    primeiro = cfop[0] if cfop else ''
    segundo = cfop[1] if len(cfop) > 1 else ''
    
    tipo_operacao = {
        '1': 'Entrada estadual',
        '2': 'Entrada interestadual',
        '3': 'Entrada importação',
        '5': 'Saída estadual',
        '6': 'Saída interestadual',
        '7': 'Saída exportação'
    }.get(primeiro, 'Operação')
    
    natureza = {
        '1': 'compra/aquisição',
        '2': 'devolução',
        '3': 'transferência',
        '4': 'devolução ST',
        '5': 'energia/comunicação',
        '9': 'outras'
    }.get(segundo, '')
    
    return f"{tipo_operacao} - {natureza}" if natureza else tipo_operacao


def obter_natureza_cfop(cfop: str) -> str:
    """Retorna a natureza da operação baseada no CFOP"""
    if not cfop:
        return "N/D"
    
    primeiro = cfop[0] if cfop else ''
    
    if primeiro in ['1', '2', '3']:
        return "Entrada"
    elif primeiro in ['5', '6', '7']:
        return "Saída"
    
    return "N/D"


@api_router.get("/apuracao-movimento/{company_id}")
async def apuracao_movimento(
    company_id: str,
    competencia: str,
    current_user: User = Depends(get_current_user)
):
    """
    Retorna o resumo do movimento do período agrupado por CFOP.
    Inclui quantidade de documentos, valor total, base de cálculo e impostos.
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Buscar documentos do período
    docs = await db.xml_documents.find({
        "company_id": company_id,
        "competencia": competencia,
        **get_filtro_notas_ativas()
    }, {"_id": 0}).to_list(None)
    
    # Agrupar por CFOP
    entradas_por_cfop = {}
    saidas_por_cfop = {}
    
    totais_entradas = {
        "qtd_docs": 0,
        "qtd_produtos": 0,
        "valor_total": 0,
        "bc_icms": 0,
        "valor_icms": 0,
        "bc_pis_cofins": 0,
        "valor_pis": 0,
        "valor_cofins": 0,
        "valor_ipi": 0,
        "icms_st": 0
    }
    
    totais_saidas = {
        "qtd_docs": 0,
        "qtd_produtos": 0,
        "valor_total": 0,
        "bc_icms": 0,
        "valor_icms": 0,
        "bc_pis_cofins": 0,
        "valor_pis": 0,
        "valor_cofins": 0,
        "valor_ipi": 0,
        "icms_st": 0
    }
    
    for doc in docs:
        tipo = doc.get('tipo', 'entrada')
        doc_id = doc.get('id', '')
        numero_nfe = doc.get('numero_nfe', '')
        
        for prod in doc.get('produtos', []):
            cfop = str(prod.get('cfop', 'SEM CFOP'))
            valor_produto = float(prod.get('valor_total', 0) or prod.get('valor_produto', 0) or 0)
            bc_icms = float(prod.get('bc_icms', 0) or prod.get('v_bc', 0) or 0)
            valor_icms = float(prod.get('v_icms', 0) or prod.get('valor_icms', 0) or 0)
            valor_pis = float(prod.get('v_pis', 0) or prod.get('valor_pis', 0) or 0)
            valor_cofins = float(prod.get('v_cofins', 0) or prod.get('valor_cofins', 0) or 0)
            valor_ipi = float(prod.get('v_ipi', 0) or prod.get('valor_ipi', 0) or 0)
            icms_st = float(prod.get('v_icms_st', 0) or prod.get('valor_icms_st', 0) or 0)
            
            # Determinar agrupamento por tipo
            cfop_primeiro = cfop[0] if cfop else ''
            is_entrada = cfop_primeiro in ['1', '2', '3'] or tipo == 'entrada'
            
            if is_entrada:
                agrupamento = entradas_por_cfop
                totais = totais_entradas
            else:
                agrupamento = saidas_por_cfop
                totais = totais_saidas
            
            if cfop not in agrupamento:
                # Obter descrição do CFOP a partir da constante existente ou descrição genérica
                cfop_info = CFOPS_SEM_DEBITO_SAIDA.get(cfop, {})
                descricao_cfop = cfop_info.get('motivo', obter_descricao_cfop_generica(cfop))
                
                agrupamento[cfop] = {
                    "cfop": cfop,
                    "descricao": descricao_cfop,
                    "natureza": obter_natureza_cfop(cfop),
                    "qtd_docs": set(),
                    "qtd_produtos": 0,
                    "valor_total": 0,
                    "bc_icms": 0,
                    "valor_icms": 0,
                    "bc_pis_cofins": 0,
                    "valor_pis": 0,
                    "valor_cofins": 0,
                    "valor_ipi": 0,
                    "icms_st": 0
                }
            
            agrupamento[cfop]["qtd_docs"].add(f"{doc_id}_{numero_nfe}")
            agrupamento[cfop]["qtd_produtos"] += 1
            agrupamento[cfop]["valor_total"] += valor_produto
            agrupamento[cfop]["bc_icms"] += bc_icms
            agrupamento[cfop]["valor_icms"] += valor_icms
            agrupamento[cfop]["bc_pis_cofins"] += valor_produto
            agrupamento[cfop]["valor_pis"] += valor_pis
            agrupamento[cfop]["valor_cofins"] += valor_cofins
            agrupamento[cfop]["valor_ipi"] += valor_ipi
            agrupamento[cfop]["icms_st"] += icms_st
            
            # Totais
            totais["qtd_produtos"] += 1
            totais["valor_total"] += valor_produto
            totais["bc_icms"] += bc_icms
            totais["valor_icms"] += valor_icms
            totais["bc_pis_cofins"] += valor_produto
            totais["valor_pis"] += valor_pis
            totais["valor_cofins"] += valor_cofins
            totais["valor_ipi"] += valor_ipi
            totais["icms_st"] += icms_st
    
    # Converter sets para contagem e formatar valores
    def formatar_agrupamento(agrupamento):
        resultado = []
        for cfop, dados in sorted(agrupamento.items()):
            resultado.append({
                "cfop": dados["cfop"],
                "descricao": dados["descricao"],
                "natureza": dados["natureza"],
                "qtd_docs": len(dados["qtd_docs"]),
                "qtd_produtos": dados["qtd_produtos"],
                "valor_total": round(dados["valor_total"], 2),
                "bc_icms": round(dados["bc_icms"], 2),
                "valor_icms": round(dados["valor_icms"], 2),
                "bc_pis_cofins": round(dados["bc_pis_cofins"], 2),
                "valor_pis": round(dados["valor_pis"], 2),
                "valor_cofins": round(dados["valor_cofins"], 2),
                "valor_ipi": round(dados["valor_ipi"], 2),
                "icms_st": round(dados["icms_st"], 2)
            })
        return resultado
    
    # Contar documentos únicos
    docs_entradas = set()
    docs_saidas = set()
    for doc in docs:
        tipo = doc.get('tipo', 'entrada')
        doc_key = f"{doc.get('id', '')}_{doc.get('numero_nfe', '')}"
        if tipo == 'entrada':
            docs_entradas.add(doc_key)
        else:
            docs_saidas.add(doc_key)
    
    totais_entradas["qtd_docs"] = len(docs_entradas)
    totais_saidas["qtd_docs"] = len(docs_saidas)
    
    # Arredondar totais
    for totais in [totais_entradas, totais_saidas]:
        for key in totais:
            if isinstance(totais[key], float):
                totais[key] = round(totais[key], 2)
    
    return {
        "empresa": {
            "id": company.get("id"),
            "razao_social": company.get("razao_social"),
            "cnpj": company.get("cnpj"),
            "regime_tributario": company.get("regime_tributario")
        },
        "competencia": competencia,
        "entradas": {
            "por_cfop": formatar_agrupamento(entradas_por_cfop),
            "totais": totais_entradas
        },
        "saidas": {
            "por_cfop": formatar_agrupamento(saidas_por_cfop),
            "totais": totais_saidas
        }
    }


# ============================================================
# EXCLUSÃO EM MASSA DE DOCUMENTOS COM FILTROS
# ============================================================

class DeleteFilters(BaseModel):
    company_id: str
    competencia: str
    tipo_operacao: str  # 'entrada' ou 'saida'
    tipo_documento: str  # '55', '65', '57', 'nfse', 'outros'
    data_inicio: Optional[str] = None  # YYYY-MM-DD
    data_fim: Optional[str] = None  # YYYY-MM-DD
    emitente_cnpj: Optional[str] = None
    emitente_nome: Optional[str] = None
    numero_inicio: Optional[int] = None
    numero_fim: Optional[int] = None
    cfops: Optional[List[str]] = None
    document_ids: Optional[List[str]] = None  # IDs específicos para excluir

@api_router.post("/xml/documents/preview-delete")
async def preview_delete_documents(
    filters: DeleteFilters,
    current_user: User = Depends(get_current_user)
):
    """
    Preview dos documentos que serão excluídos com base nos filtros.
    Retorna lista de documentos e contagem para confirmação.
    """
    company = await db.companies.find_one({"id": filters.company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Construir query base
    query = {
        "company_id": filters.company_id,
        "competencia": filters.competencia
    }
    
    # Buscar todos os documentos primeiro para filtrar por tipo_operacao inferido
    all_docs = await db.xml_documents.find(query, {"_id": 0, "xml_content": 0}).to_list(100000)
    
    # Inferir tipo_operacao para documentos que não têm
    for doc in all_docs:
        if not doc.get('tipo_operacao'):
            produtos = doc.get('produtos', [])
            if produtos:
                cfop = str(produtos[0].get('cfop', ''))
                if cfop and cfop[0] in ['1', '2', '3']:
                    doc['tipo_operacao'] = 'entrada'
                elif cfop and cfop[0] in ['5', '6', '7']:
                    doc['tipo_operacao'] = 'saida'
    
    # Filtrar por tipo_operacao
    filtered_docs = [d for d in all_docs if d.get('tipo_operacao') == filters.tipo_operacao]
    
    # Filtrar por modelo (se não for 'all')
    if filters.tipo_documento and filters.tipo_documento != 'all':
        modelo_map = {
            '55': ['55', 'nfe'],
            '65': ['65', 'nfce'],
            '57': ['57', 'cte'],
            'nfse': ['nfse', 'nfse_tomado', 'nfse_prestado'],
            'nfse_tomado': ['nfse', 'nfse_tomado'],
            'nfse_prestado': ['nfse', 'nfse_prestado'],
            'outros': ['outros']
        }
        if filters.tipo_documento in modelo_map:
            filtered_docs = [d for d in filtered_docs if d.get('modelo') in modelo_map[filters.tipo_documento]]
    
    # Aplicar filtros adicionais
    if filters.document_ids:
        filtered_docs = [d for d in filtered_docs if d.get('id') in filters.document_ids]
    
    if filters.data_inicio:
        filtered_docs = [d for d in filtered_docs if d.get('data_emissao', '') >= filters.data_inicio]
    
    if filters.data_fim:
        filtered_docs = [d for d in filtered_docs if d.get('data_emissao', '') <= filters.data_fim]
    
    if filters.emitente_cnpj:
        cnpj_limpo = filters.emitente_cnpj.replace('.', '').replace('/', '').replace('-', '')
        filtered_docs = [d for d in filtered_docs if cnpj_limpo in (d.get('emitente_cnpj', '') or '').replace('.', '').replace('/', '').replace('-', '')]
    
    if filters.emitente_nome:
        nome_lower = filters.emitente_nome.lower()
        filtered_docs = [d for d in filtered_docs if nome_lower in (d.get('emitente_nome', '') or '').lower()]
    
    if filters.numero_inicio is not None:
        filtered_docs = [d for d in filtered_docs if int(d.get('numero_nfe', 0) or 0) >= filters.numero_inicio]
    
    if filters.numero_fim is not None:
        filtered_docs = [d for d in filtered_docs if int(d.get('numero_nfe', 0) or 0) <= filters.numero_fim]
    
    if filters.cfops:
        def doc_has_cfop(doc, cfops):
            produtos = doc.get('produtos', [])
            for prod in produtos:
                if str(prod.get('cfop', '')) in cfops:
                    return True
            return False
        filtered_docs = [d for d in filtered_docs if doc_has_cfop(d, filters.cfops)]
    
    # Calcular totais
    total_valor = sum(float(d.get('valor_total', 0) or 0) for d in filtered_docs)
    
    # Retornar preview limitado a 100 documentos para visualização
    preview_docs = [{
        "id": d.get("id"),
        "numero_nfe": d.get("numero_nfe"),
        "emitente_nome": d.get("emitente_nome"),
        "emitente_cnpj": d.get("emitente_cnpj"),
        "data_emissao": d.get("data_emissao"),
        "valor_total": d.get("valor_total")
    } for d in filtered_docs[:100]]
    
    return {
        "total_documentos": len(filtered_docs),
        "total_valor": total_valor,
        "preview": preview_docs,
        "tem_mais": len(filtered_docs) > 100,
        "ids_para_excluir": [d.get("id") for d in filtered_docs]
    }


@api_router.post("/xml/documents/delete-bulk")
async def delete_documents_bulk(
    filters: DeleteFilters,
    current_user: User = Depends(get_current_user)
):
    """
    Exclui documentos em massa com base nos filtros.
    Requer confirmação prévia via preview-delete.
    """
    company = await db.companies.find_one({"id": filters.company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Se IDs específicos foram fornecidos, usar eles diretamente
    if filters.document_ids and len(filters.document_ids) > 0:
        result = await db.xml_documents.delete_many({
            "id": {"$in": filters.document_ids},
            "company_id": filters.company_id
        })
        return {
            "success": True,
            "deleted_count": result.deleted_count,
            "message": f"{result.deleted_count} documento(s) excluído(s) com sucesso"
        }
    
    # Caso contrário, buscar preview e excluir
    preview = await preview_delete_documents(filters, current_user)
    
    if preview["total_documentos"] == 0:
        return {
            "success": True,
            "deleted_count": 0,
            "message": "Nenhum documento encontrado com os filtros especificados"
        }
    
    # Excluir pelos IDs
    result = await db.xml_documents.delete_many({
        "id": {"$in": preview["ids_para_excluir"]},
        "company_id": filters.company_id
    })
    
    return {
        "success": True,
        "deleted_count": result.deleted_count,
        "message": f"{result.deleted_count} documento(s) excluído(s) com sucesso"
    }


@api_router.get("/xml/documents/cfops/{company_id}")
async def get_cfops_for_company(
    company_id: str,
    competencia: Optional[str] = None,
    tipo_operacao: Optional[str] = None,
    current_user: User = Depends(get_current_user)
):
    """
    Retorna lista de CFOPs únicos usados nos documentos da empresa.
    Útil para o filtro de exclusão.
    """
    query = {"company_id": company_id}
    if competencia:
        query["competencia"] = competencia
    
    documents = await db.xml_documents.find(query, {"_id": 0, "produtos": 1, "tipo_operacao": 1}).to_list(100000)
    
    cfops = set()
    for doc in documents:
        # Filtrar por tipo_operacao se especificado
        if tipo_operacao:
            doc_operacao = doc.get('tipo_operacao')
            if not doc_operacao:
                produtos = doc.get('produtos', [])
                if produtos:
                    cfop = str(produtos[0].get('cfop', ''))
                    if cfop and cfop[0] in ['1', '2', '3']:
                        doc_operacao = 'entrada'
                    elif cfop and cfop[0] in ['5', '6', '7']:
                        doc_operacao = 'saida'
            if doc_operacao != tipo_operacao:
                continue
        
        for prod in doc.get('produtos', []):
            cfop = prod.get('cfop')
            if cfop:
                cfops.add(str(cfop))
    
    return sorted(list(cfops))


@api_router.get("/xml/documents/emitentes/{company_id}")
async def get_emitentes_for_company(
    company_id: str,
    competencia: Optional[str] = None,
    tipo_operacao: Optional[str] = None,
    search: Optional[str] = None,
    current_user: User = Depends(get_current_user)
):
    """
    Retorna lista de emitentes únicos para autocomplete.
    """
    query = {"company_id": company_id}
    if competencia:
        query["competencia"] = competencia
    
    documents = await db.xml_documents.find(query, {"_id": 0, "emitente_nome": 1, "emitente_cnpj": 1, "tipo_operacao": 1, "produtos": 1}).to_list(100000)
    
    emitentes = {}
    for doc in documents:
        # Filtrar por tipo_operacao se especificado
        if tipo_operacao:
            doc_operacao = doc.get('tipo_operacao')
            if not doc_operacao:
                produtos = doc.get('produtos', [])
                if produtos:
                    cfop = str(produtos[0].get('cfop', ''))
                    if cfop and cfop[0] in ['1', '2', '3']:
                        doc_operacao = 'entrada'
                    elif cfop and cfop[0] in ['5', '6', '7']:
                        doc_operacao = 'saida'
            if doc_operacao != tipo_operacao:
                continue
        
        cnpj = doc.get('emitente_cnpj', '')
        nome = doc.get('emitente_nome', '')
        if cnpj and nome:
            # Filtrar por busca se especificado
            if search:
                search_lower = search.lower()
                if search_lower not in nome.lower() and search_lower not in cnpj:
                    continue
            emitentes[cnpj] = nome
    
    result = [{"cnpj": k, "nome": v} for k, v in emitentes.items()]
    return sorted(result, key=lambda x: x['nome'])[:50]  # Limitar a 50 resultados


# ============================================================
# APURAÇÃO DE ICMS
# ============================================================

@api_router.get("/apuracao-icms/{company_id}")
async def apurar_icms(
    company_id: str,
    competencia: str,
    current_user: User = Depends(get_current_user)
):
    """
    Realiza a apuração completa de ICMS para uma empresa/competência.
    Agrupa por CFOP, mostra Top 10 produtos e NCMs, e calcula saldo.
    Aplica flags de desconsiderar ICMS de CFOPs de despesa e ST.
    """
    # Buscar empresa
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    # Flags de desconsiderar ICMS
    desconsiderar_icms_despesas = company.get('desconsiderar_icms_despesas', False)
    desconsiderar_icms_st = company.get('desconsiderar_icms_st', False)
    # Benefício Fiscal ICMS
    beneficio_fiscal_icms = company.get('beneficio_fiscal_icms', False)
    
    # CFOPs de DESPESA (entradas que não geram crédito tributário)
    CFOPS_DESPESA = [
        '1407', '2407',  # Compra de mercadoria para uso ou consumo
        '1556', '2556',  # Compra de material para uso ou consumo
        '1557', '2557',  # Transferência de material para uso ou consumo
        '1128', '2128',  # Compra para utilização na prestação de serviço
        '1551', '2551',  # Compra de ativo imobilizado
        '1406', '2406',  # Compra de bem para ativo imobilizado
        '1653', '2653',  # Compra de combustíveis
        '1126', '2126',  # Compra para industrialização
        '1352', '2352',  # Aquisição de serviço de transporte
        '1353', '2353',  # Aquisição de serviço de comunicação
        '1354', '2354',  # Aquisição de serviço de energia elétrica
    ]
    
    # CFOPs de MERCADORIAS ST (Substituição Tributária)
    CFOPS_ST = [
        '1403', '2403',  # Compra para comercialização ST
        '1409', '2409',  # Transferência para comercialização ST
        '1410', '2410',  # Devolução de venda ST
        '1411', '2411',  # Devolução de venda fora do estabelecimento ST
        '1414', '2414',  # Retorno de mercadoria ST
        '1415', '2415',  # Retorno de mercadoria diversa ST
        '1651', '2651',  # Compra de combustível ST
        '1652', '2652',  # Compra de combustível ST fora do estado
    ]
    
    # Buscar documentos da competência (EXCLUIR notas canceladas - mesmo critério do Dashboard)
    query = {
        "company_id": company_id,
        "competencia": competencia
    }
    query.update(get_filtro_notas_ativas())
    
    documentos = await db.xml_documents.find(query, {"_id": 0, "xml_content": 0}).to_list(100000)
    
    # Estruturas para acumular dados
    entradas_por_cfop = {}
    saidas_por_cfop = {}
    produtos_credito = {}  # código -> {descricao, ncm, valor_icms, quantidade}
    produtos_debito = {}
    ncms_credito = {}  # ncm -> {descricao, valor_icms, quantidade}
    ncms_debito = {}
    
    # ICMS ST
    icms_st_saidas = {}  # Por CFOP
    icms_st_devolucoes = {}  # Deduções de devoluções
    
    totais = {
        "entradas": {"valor_total": 0, "bc_icms": 0, "valor_icms": 0, "valor_icms_st": 0, "qtd_docs": 0, "qtd_itens": 0},
        "saidas": {"valor_total": 0, "bc_icms": 0, "valor_icms": 0, "valor_icms_st": 0, "qtd_docs": 0, "qtd_itens": 0}
    }
    
    # Totais por DOCUMENTO (critério do Dashboard - para consistência)
    totais_por_documento = {
        "entradas": 0,
        "saidas": 0
    }
    
    # Totais desconsiderados (para mostrar no frontend)
    totais_desconsiderados = {
        "despesas": {"bc_icms": 0, "valor_icms": 0, "qtd_itens": 0},
        "st": {"bc_icms": 0, "valor_icms": 0, "qtd_itens": 0},
        "beneficio_fiscal": {"bc_icms": 0, "valor_icms": 0, "qtd_itens": 0, "produtos": []}
    }
    
    # CFOPs de devolução que geram dedução de ICMS ST
    cfops_devolucao = ['1410', '1411', '1414', '1415', '2410', '2411', '2414', '2415',
                       '5410', '5411', '5414', '5415', '6410', '6411', '6414', '6415']
    
    # Processar documentos
    for doc in documentos:
        produtos = doc.get('produtos', [])
        if not produtos:
            continue
        
        # Determinar se é entrada ou saída pelo campo TIPO do documento (mesmo critério do Dashboard)
        tipo_doc = doc.get('tipo', 'entrada')
        if tipo_doc == 'entrada':
            tipo_op = 'entrada'
            totais["entradas"]["qtd_docs"] += 1
            # Soma por DOCUMENTO (critério Dashboard)
            totais_por_documento["entradas"] += float(doc.get('valor_total', 0) or 0)
        else:  # saida
            tipo_op = 'saida'
            totais["saidas"]["qtd_docs"] += 1
            # Soma por DOCUMENTO (critério Dashboard)
            totais_por_documento["saidas"] += float(doc.get('valor_total', 0) or 0)
        
        for prod in produtos:
            cfop = str(prod.get('cfop', 'SEM CFOP'))
            ncm = str(prod.get('ncm', 'SEM NCM')).replace('.', '')
            codigo = str(prod.get('codigo', ''))
            descricao = str(prod.get('descricao', 'Produto'))[:60]
            
            valor_total = float(prod.get('valor_total', 0) or prod.get('valor_produto', 0) or 0)
            bc_icms = float(prod.get('v_bc_icms', 0) or 0)
            valor_icms = float(prod.get('v_icms', 0) or 0)
            valor_icms_st = float(prod.get('v_icms_st', 0) or 0)
            bc_icms_st = float(prod.get('v_bc_icms_st', 0) or 0)
            
            # Determinar tipo pela CFOP do produto (mais preciso)
            cfop_primeiro = cfop[0] if cfop and cfop != 'SEM CFOP' else ''
            if cfop_primeiro in ['1', '2', '3']:
                tipo_item = 'entrada'
            elif cfop_primeiro in ['5', '6', '7']:
                tipo_item = 'saida'
            else:
                tipo_item = tipo_op
            
            if tipo_item == 'entrada':
                # Verificar se CFOP é de despesa ou ST
                is_despesa = cfop in CFOPS_DESPESA
                is_st = cfop in CFOPS_ST
                
                # Verificar se produto deve ter crédito desconsiderado por benefício fiscal
                is_sem_credito_beneficio = False
                if beneficio_fiscal_icms:
                    is_sem_credito_beneficio = produto_sem_credito_icms_beneficio(ncm, descricao, company)
                
                # Agrupar por CFOP - Entradas
                if cfop not in entradas_por_cfop:
                    entradas_por_cfop[cfop] = {
                        "cfop": cfop, 
                        "valor_total": 0, 
                        "bc_icms": 0, 
                        "valor_icms": 0, 
                        "qtd": 0,
                        "is_despesa": is_despesa,
                        "is_st": is_st,
                        "desconsiderado": (is_despesa and desconsiderar_icms_despesas) or (is_st and desconsiderar_icms_st) or is_sem_credito_beneficio
                    }
                entradas_por_cfop[cfop]["valor_total"] += valor_total
                entradas_por_cfop[cfop]["bc_icms"] += bc_icms
                entradas_por_cfop[cfop]["valor_icms"] += valor_icms
                entradas_por_cfop[cfop]["qtd"] += 1
                
                # Totais de entradas (sempre soma no total geral)
                totais["entradas"]["valor_total"] += valor_total
                totais["entradas"]["valor_icms_st"] += valor_icms_st
                totais["entradas"]["qtd_itens"] += 1
                
                # Verificar se este CFOP/produto deve ter BC e ICMS zerados
                if is_despesa and desconsiderar_icms_despesas:
                    # Acumular o que foi desconsiderado
                    totais_desconsiderados["despesas"]["bc_icms"] += bc_icms
                    totais_desconsiderados["despesas"]["valor_icms"] += valor_icms
                    totais_desconsiderados["despesas"]["qtd_itens"] += 1
                    # NÃO soma no total de crédito
                elif is_st and desconsiderar_icms_st:
                    # Acumular o que foi desconsiderado
                    totais_desconsiderados["st"]["bc_icms"] += bc_icms
                    totais_desconsiderados["st"]["valor_icms"] += valor_icms
                    totais_desconsiderados["st"]["qtd_itens"] += 1
                    # NÃO soma no total de crédito
                elif is_sem_credito_beneficio:
                    # Acumular o que foi desconsiderado por benefício fiscal
                    totais_desconsiderados["beneficio_fiscal"]["bc_icms"] += bc_icms
                    totais_desconsiderados["beneficio_fiscal"]["valor_icms"] += valor_icms
                    totais_desconsiderados["beneficio_fiscal"]["qtd_itens"] += 1
                    if len(totais_desconsiderados["beneficio_fiscal"]["produtos"]) < 20:
                        totais_desconsiderados["beneficio_fiscal"]["produtos"].append({
                            "descricao": descricao[:40], "ncm": ncm, "valor_icms": valor_icms
                        })
                    # NÃO soma no total de crédito
                else:
                    # Soma normalmente no total de crédito
                    totais["entradas"]["bc_icms"] += bc_icms
                    totais["entradas"]["valor_icms"] += valor_icms
                
                # ICMS ST de devoluções (dedução)
                if cfop in cfops_devolucao and valor_icms_st > 0:
                    if cfop not in icms_st_devolucoes:
                        icms_st_devolucoes[cfop] = {"cfop": cfop, "bc_icms_st": 0, "valor_icms_st": 0, "qtd": 0}
                    icms_st_devolucoes[cfop]["bc_icms_st"] += bc_icms_st
                    icms_st_devolucoes[cfop]["valor_icms_st"] += valor_icms_st
                    icms_st_devolucoes[cfop]["qtd"] += 1
                
                # Top produtos crédito (só inclui se não foi desconsiderado)
                should_include_in_credito = not (
                    (is_despesa and desconsiderar_icms_despesas) or 
                    (is_st and desconsiderar_icms_st) or
                    is_sem_credito_beneficio
                )
                if valor_icms > 0 and should_include_in_credito:
                    key = codigo or descricao[:30]
                    if key not in produtos_credito:
                        produtos_credito[key] = {"codigo": codigo, "descricao": descricao, "ncm": ncm, "valor_icms": 0, "qtd": 0}
                    produtos_credito[key]["valor_icms"] += valor_icms
                    produtos_credito[key]["qtd"] += 1
                    
                    # Top NCMs crédito
                    if ncm not in ncms_credito:
                        ncms_credito[ncm] = {"ncm": ncm, "valor_icms": 0, "qtd": 0, "produtos": set()}
                    ncms_credito[ncm]["valor_icms"] += valor_icms
                    ncms_credito[ncm]["qtd"] += 1
                    ncms_credito[ncm]["produtos"].add(descricao[:30])
            
            else:  # saída
                # Agrupar por CFOP - Saídas
                if cfop not in saidas_por_cfop:
                    saidas_por_cfop[cfop] = {"cfop": cfop, "valor_total": 0, "bc_icms": 0, "valor_icms": 0, "qtd": 0}
                saidas_por_cfop[cfop]["valor_total"] += valor_total
                saidas_por_cfop[cfop]["bc_icms"] += bc_icms
                saidas_por_cfop[cfop]["valor_icms"] += valor_icms
                saidas_por_cfop[cfop]["qtd"] += 1
                
                # Totais de saídas
                totais["saidas"]["valor_total"] += valor_total
                totais["saidas"]["bc_icms"] += bc_icms
                totais["saidas"]["valor_icms"] += valor_icms
                totais["saidas"]["valor_icms_st"] += valor_icms_st
                totais["saidas"]["qtd_itens"] += 1
                
                # ICMS ST de saídas (débito)
                if valor_icms_st > 0:
                    if cfop not in icms_st_saidas:
                        icms_st_saidas[cfop] = {"cfop": cfop, "bc_icms_st": 0, "valor_icms_st": 0, "qtd": 0}
                    icms_st_saidas[cfop]["bc_icms_st"] += bc_icms_st
                    icms_st_saidas[cfop]["valor_icms_st"] += valor_icms_st
                    icms_st_saidas[cfop]["qtd"] += 1
                
                # Top produtos débito
                if valor_icms > 0:
                    key = codigo or descricao[:30]
                    if key not in produtos_debito:
                        produtos_debito[key] = {"codigo": codigo, "descricao": descricao, "ncm": ncm, "valor_icms": 0, "qtd": 0}
                    produtos_debito[key]["valor_icms"] += valor_icms
                    produtos_debito[key]["qtd"] += 1
                    
                    # Top NCMs débito
                    if ncm not in ncms_debito:
                        ncms_debito[ncm] = {"ncm": ncm, "valor_icms": 0, "qtd": 0, "produtos": set()}
                    ncms_debito[ncm]["valor_icms"] += valor_icms
                    ncms_debito[ncm]["qtd"] += 1
                    ncms_debito[ncm]["produtos"].add(descricao[:30])
    
    # Converter sets para listas nos NCMs
    for ncm in ncms_credito.values():
        ncm["produtos"] = list(ncm["produtos"])[:3]
    for ncm in ncms_debito.values():
        ncm["produtos"] = list(ncm["produtos"])[:3]
    
    # Ordenar e pegar Top 10
    top_produtos_credito = sorted(produtos_credito.values(), key=lambda x: -x["valor_icms"])[:10]
    top_produtos_debito = sorted(produtos_debito.values(), key=lambda x: -x["valor_icms"])[:10]
    top_ncms_credito = sorted(ncms_credito.values(), key=lambda x: -x["valor_icms"])[:10]
    top_ncms_debito = sorted(ncms_debito.values(), key=lambda x: -x["valor_icms"])[:10]
    
    # Ordenar CFOPs por valor_icms
    lista_entradas = sorted(entradas_por_cfop.values(), key=lambda x: -x["valor_icms"])
    lista_saidas = sorted(saidas_por_cfop.values(), key=lambda x: -x["valor_icms"])
    
    # Calcular saldo
    credito_icms = totais["entradas"]["valor_icms"]
    debito_icms = totais["saidas"]["valor_icms"]
    
    # NOVO: Verificar se é transportadora e calcular crédito presumido
    is_transportadora = company.get('is_transportadora', False)
    credito_presumido_percent = company.get('credito_presumido_icms_percent', 20.0)
    credito_presumido_icms = 0
    
    if is_transportadora and debito_icms > 0:
        credito_presumido_icms = calcular_credito_presumido_icms_transportadora(debito_icms, credito_presumido_percent)
    
    # Saldo final = Débito - Crédito - Crédito Presumido (transportadora)
    saldo = debito_icms - credito_icms - credito_presumido_icms
    
    # Arredondar valores
    def arredondar_dict(d):
        for k, v in d.items():
            if isinstance(v, float):
                d[k] = round(v, 2)
        return d
    
    for item in lista_entradas:
        arredondar_dict(item)
    for item in lista_saidas:
        arredondar_dict(item)
    for item in top_produtos_credito:
        arredondar_dict(item)
    for item in top_produtos_debito:
        arredondar_dict(item)
    for item in top_ncms_credito:
        arredondar_dict(item)
    for item in top_ncms_debito:
        arredondar_dict(item)
    
    return {
        "empresa": {
            "id": company_id,
            "razao_social": company.get('razao_social', ''),
            "cnpj": company.get('cnpj', ''),
            "uf": company.get('uf', ''),
            "regime_tributario": company.get('regime_tributario', '')
        },
        "competencia": competencia,
        # Totais por DOCUMENTO (mesmo critério do Dashboard)
        "valores_por_documento": {
            "total_entradas": round(totais_por_documento["entradas"], 2),
            "total_saidas": round(totais_por_documento["saidas"], 2)
        },
        "entradas": {
            "por_cfop": lista_entradas,
            "totais": {
                "valor_total": round(totais["entradas"]["valor_total"], 2),
                "valor_total_por_documento": round(totais_por_documento["entradas"], 2),
                "bc_icms": round(totais["entradas"]["bc_icms"], 2),
                "valor_icms": round(totais["entradas"]["valor_icms"], 2),
                "valor_icms_st": round(totais["entradas"]["valor_icms_st"], 2),
                "qtd_documentos": totais["entradas"]["qtd_docs"],
                "qtd_itens": totais["entradas"]["qtd_itens"]
            }
        },
        "saidas": {
            "por_cfop": lista_saidas,
            "totais": {
                "valor_total": round(totais["saidas"]["valor_total"], 2),
                "valor_total_por_documento": round(totais_por_documento["saidas"], 2),
                "bc_icms": round(totais["saidas"]["bc_icms"], 2),
                "valor_icms": round(totais["saidas"]["valor_icms"], 2),
                "valor_icms_st": round(totais["saidas"]["valor_icms_st"], 2),
                "qtd_documentos": totais["saidas"]["qtd_docs"],
                "qtd_itens": totais["saidas"]["qtd_itens"]
            }
        },
        "top_10": {
            "produtos_credito": top_produtos_credito,
            "produtos_debito": top_produtos_debito,
            "ncms_credito": top_ncms_credito,
            "ncms_debito": top_ncms_debito
        },
        "apuracao": {
            "credito_icms": round(credito_icms, 2),
            "debito_icms": round(debito_icms, 2),
            "credito_presumido_icms": round(credito_presumido_icms, 2),
            "credito_presumido_percent": credito_presumido_percent if is_transportadora else 0,
            "is_transportadora": is_transportadora,
            "saldo": round(saldo, 2),
            "situacao": "A_PAGAR" if saldo > 0 else "A_RECUPERAR" if saldo < 0 else "ZERADO"
        },
        "icms_st": {
            "saidas": {
                "por_cfop": sorted([arredondar_dict(x) for x in icms_st_saidas.values()], key=lambda x: -x["valor_icms_st"]),
                "total_bc": round(sum(x["bc_icms_st"] for x in icms_st_saidas.values()), 2),
                "total_icms_st": round(totais["saidas"]["valor_icms_st"], 2)
            },
            "devolucoes": {
                "por_cfop": sorted([arredondar_dict(x) for x in icms_st_devolucoes.values()], key=lambda x: -x["valor_icms_st"]),
                "total_bc": round(sum(x["bc_icms_st"] for x in icms_st_devolucoes.values()), 2),
                "total_icms_st": round(sum(x["valor_icms_st"] for x in icms_st_devolucoes.values()), 2)
            },
            "apuracao": {
                "icms_st_gerado": round(totais["saidas"]["valor_icms_st"], 2),
                "icms_st_devolucoes": round(sum(x["valor_icms_st"] for x in icms_st_devolucoes.values()), 2),
                "icms_st_a_recolher": round(
                    totais["saidas"]["valor_icms_st"] - sum(x["valor_icms_st"] for x in icms_st_devolucoes.values()), 2
                ),
                "situacao": "A_RECOLHER" if (totais["saidas"]["valor_icms_st"] - sum(x["valor_icms_st"] for x in icms_st_devolucoes.values())) > 0 else "ZERADO"
            }
        },
        "flags": {
            "desconsiderar_icms_despesas": desconsiderar_icms_despesas,
            "desconsiderar_icms_st": desconsiderar_icms_st,
            "cfops_despesa": CFOPS_DESPESA,
            "cfops_st": CFOPS_ST
        },
        "desconsiderados": {
            "despesas": {
                "bc_icms": round(totais_desconsiderados["despesas"]["bc_icms"], 2),
                "valor_icms": round(totais_desconsiderados["despesas"]["valor_icms"], 2),
                "qtd_itens": totais_desconsiderados["despesas"]["qtd_itens"]
            },
            "st": {
                "bc_icms": round(totais_desconsiderados["st"]["bc_icms"], 2),
                "valor_icms": round(totais_desconsiderados["st"]["valor_icms"], 2),
                "qtd_itens": totais_desconsiderados["st"]["qtd_itens"]
            },
            "beneficio_fiscal": {
                "bc_icms": round(totais_desconsiderados["beneficio_fiscal"]["bc_icms"], 2),
                "valor_icms": round(totais_desconsiderados["beneficio_fiscal"]["valor_icms"], 2),
                "qtd_itens": totais_desconsiderados["beneficio_fiscal"]["qtd_itens"],
                "produtos": totais_desconsiderados["beneficio_fiscal"]["produtos"]
            },
            "total_icms_desconsiderado": round(
                totais_desconsiderados["despesas"]["valor_icms"] + 
                totais_desconsiderados["st"]["valor_icms"] + 
                totais_desconsiderados["beneficio_fiscal"]["valor_icms"], 2
            )
        }
    }


# ============================================================
# BENEFÍCIO FISCAL ICMS - DETALHAMENTO
# ============================================================

@api_router.get("/beneficio-fiscal-detalhes/{company_id}")
async def get_beneficio_fiscal_detalhes(
    company_id: str,
    competencia: str = Query(..., description="Competência no formato MM/YYYY"),
    current_user: User = Depends(get_current_user)
):
    """
    Retorna o detalhamento dos créditos de ICMS desconsiderados pelo benefício fiscal.
    Agrupa os dados por produto e por NCM.
    """
    # Buscar empresa
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not company.get('beneficio_fiscal_icms', False):
        return {
            "total_produtos": 0,
            "valor_total": 0,
            "valor_icms_desconsiderado": 0,
            "por_produto": [],
            "por_ncm": []
        }
    
    # Buscar documentos de entrada da competência
    # Usar mesma lógica que o endpoint de apuração ICMS
    docs = await db.xml_documents.find({
        "company_id": company_id,
        "competencia": competencia
    }, {"_id": 0, "xml_content": 0}).to_list(50000)
    
    # Filtrar apenas documentos de entrada (mesma lógica da apuração ICMS)
    docs_entrada = []
    for doc in docs:
        # Determinar se é entrada pelo campo 'tipo' (usado na apuração) ou 'tipo_operacao'
        tipo = doc.get('tipo', doc.get('tipo_operacao', 'saida'))
        if tipo == 'entrada':
            docs_entrada.append(doc)
    
    docs = docs_entrada
    
    # Estruturas para acumular dados
    por_produto = {}  # Chave: descrição do produto
    por_ncm = {}  # Chave: NCM
    
    total_valor = 0
    total_icms = 0
    total_produtos = 0
    
    # Descrições de NCM comuns
    ncm_descricoes = {
        "02": "Carnes e miudezas",
        "0201": "Carnes bovina, frescas ou refrigeradas",
        "0202": "Carnes bovina, congeladas",
        "0203": "Carnes suína, frescas, refrigeradas ou congeladas",
        "0204": "Carnes ovina/caprina",
        "0207": "Carnes de aves",
        "03": "Peixes e crustáceos",
        "04": "Leite e laticínios, ovos, mel",
        "0401": "Leite e creme de leite",
        "0402": "Leite em pó",
        "0403": "Iogurte e leite fermentado",
        "0405": "Manteiga",
        "0406": "Queijos e requeijão",
        "07": "Produtos hortícolas",
        "08": "Frutas",
        "10": "Cereais",
        "11": "Produtos da indústria de moagem",
        "15": "Gorduras e óleos",
        "16": "Preparações de carne e peixes",
        "17": "Açúcares e confeitaria",
        "18": "Cacau e suas preparações",
        "19": "Preparações à base de cereais",
        "20": "Preparações de produtos hortícolas",
        "21": "Preparações alimentícias diversas",
        "22": "Bebidas, líquidos alcoólicos e vinagres",
        "2201": "Águas minerais e gaseificadas",
        "2202": "Bebidas não alcoólicas (refrigerantes, sucos)",
        "2203": "Cervejas de malte",
        "2204": "Vinhos de uvas frescas",
        "2205": "Vermutes",
        "2206": "Outras bebidas fermentadas",
        "2207": "Álcool etílico",
        "2208": "Bebidas destiladas",
        "23": "Resíduos e desperdícios da indústria alimentar",
    }
    
    def get_ncm_descricao(ncm: str) -> str:
        """Retorna descrição do NCM baseada em prefixos conhecidos"""
        ncm_str = str(ncm or '').strip()
        # Tentar match exato primeiro
        if ncm_str in ncm_descricoes:
            return ncm_descricoes[ncm_str]
        # Tentar prefixos (do maior para o menor)
        for i in range(len(ncm_str), 1, -1):
            prefix = ncm_str[:i]
            if prefix in ncm_descricoes:
                return ncm_descricoes[prefix]
        return "Produto"
    
    # CFOPs que já não geram crédito (ST e Despesas) - NÃO devem entrar no benefício fiscal
    CFOPS_ST = {'1401', '1403', '1407', '1408', '1409', '2401', '2403', '2407', '2408', '2409'}
    CFOPS_DESPESA = {
        '1128', '1407', '1556', '1557', '1651', '1652', '1653', '1658', '1659', '1660', '1661', '1662',
        '1663', '1664', '1901', '1902', '1903', '1904', '1905', '1906', '1907', '1908', '1909', '1910',
        '1911', '1912', '1913', '1914', '1915', '1916', '1917', '1918', '1919', '1920', '1921', '1922',
        '1923', '1924', '1925', '1926', '1949', '2128', '2407', '2556', '2557', '2651', '2652', '2653',
        '2658', '2659', '2660', '2661', '2662', '2663', '2664', '2901', '2902', '2903', '2904', '2905',
        '2906', '2907', '2908', '2909', '2910', '2911', '2912', '2913', '2914', '2915', '2916', '2917',
        '2918', '2919', '2920', '2921', '2922', '2923', '2924', '2925', '2949'
    }
    CFOPS_SEM_CREDITO = CFOPS_ST | CFOPS_DESPESA
    
    # Processar documentos
    for doc in docs:
        # Itens podem estar em 'itens' ou 'produtos' dependendo da fonte
        itens = doc.get('itens', []) or doc.get('produtos', [])
        if not itens:
            continue
        
        for item in itens:
            cfop = str(item.get('cfop', '') or '').strip()
            ncm = str(item.get('ncm', '') or '').strip()
            descricao = str(item.get('descricao', '') or item.get('produto', '') or '').strip()
            valor_produto = float(item.get('valor_produto', 0) or item.get('valor_total', 0) or 0)
            # Suportar diferentes nomes para campos de ICMS
            bc_icms = float(item.get('bc_icms', 0) or item.get('v_bc_icms', 0) or 0)
            valor_icms = float(item.get('valor_icms', 0) or item.get('v_icms', 0) or 0)
            
            # EXCLUIR CFOPs de ST e Despesas - estes já não geram crédito normalmente
            # Só devem entrar no benefício fiscal produtos que NORMALMENTE gerariam crédito
            if cfop in CFOPS_SEM_CREDITO:
                continue
            
            # Verificar se o produto está sujeito ao benefício fiscal
            if not produto_sem_credito_icms_beneficio(ncm, descricao, company):
                continue
            
            # Acumular totais
            total_valor += valor_produto
            total_icms += valor_icms
            total_produtos += 1
            
            # Agregar por produto (descrição)
            desc_key = descricao[:100] if descricao else "Produto sem descrição"
            if desc_key not in por_produto:
                por_produto[desc_key] = {
                    "descricao": desc_key,
                    "ncm": ncm,
                    "cfop": cfop,
                    "valor_total": 0,
                    "bc_icms": 0,
                    "valor_icms": 0,
                    "notas": []
                }
            por_produto[desc_key]["valor_total"] += valor_produto
            por_produto[desc_key]["bc_icms"] += bc_icms
            por_produto[desc_key]["valor_icms"] += valor_icms
            
            # Adicionar nota se ainda não existir
            numero_nfe = doc.get('numero_nfe', doc.get('numero', ''))
            emitente = doc.get('emitente_nome', '')
            if isinstance(doc.get('emitente'), dict):
                emitente = doc.get('emitente', {}).get('razao_social', emitente)
            
            nota_existe = any(n.get('numero') == numero_nfe for n in por_produto[desc_key]["notas"])
            if numero_nfe and not nota_existe:
                por_produto[desc_key]["notas"].append({
                    "numero": numero_nfe,
                    "emitente": emitente[:40] if emitente else "",
                    "valor": valor_produto,
                    "bc_icms": bc_icms,
                    "valor_icms": valor_icms
                })
            
            # Agregar por NCM
            ncm_key = ncm[:8] if ncm else "SEM_NCM"
            if ncm_key not in por_ncm:
                por_ncm[ncm_key] = {
                    "ncm": ncm_key,
                    "descricao_ncm": get_ncm_descricao(ncm_key),
                    "valor_total": 0,
                    "bc_icms": 0,
                    "valor_icms": 0,
                    "produtos": {}
                }
            por_ncm[ncm_key]["valor_total"] += valor_produto
            por_ncm[ncm_key]["bc_icms"] += bc_icms
            por_ncm[ncm_key]["valor_icms"] += valor_icms
            
            # Adicionar produto ao NCM
            prod_key = desc_key[:50]
            if prod_key not in por_ncm[ncm_key]["produtos"]:
                por_ncm[ncm_key]["produtos"][prod_key] = {
                    "descricao": prod_key,
                    "cfop": cfop,
                    "valor_total": 0,
                    "bc_icms": 0,
                    "valor_icms": 0
                }
            por_ncm[ncm_key]["produtos"][prod_key]["valor_total"] += valor_produto
            por_ncm[ncm_key]["produtos"][prod_key]["bc_icms"] += bc_icms
            por_ncm[ncm_key]["produtos"][prod_key]["valor_icms"] += valor_icms
    
    # Converter para listas e ordenar por valor de ICMS desconsiderado
    lista_produtos = []
    for p in por_produto.values():
        lista_produtos.append({
            "descricao": p["descricao"],
            "ncm": p["ncm"],
            "cfop": p["cfop"],
            "valor_total": round(p["valor_total"], 2),
            "bc_icms": round(p["bc_icms"], 2),
            "valor_icms": round(p["valor_icms"], 2),
            "qtd_notas": len(p["notas"]),
            "notas": p["notas"][:10]  # Limitar a 10 notas
        })
    lista_produtos.sort(key=lambda x: x["valor_icms"], reverse=True)
    
    lista_ncm = []
    for n in por_ncm.values():
        # Converter produtos do NCM para lista
        produtos_ncm = []
        for prod in n["produtos"].values():
            produtos_ncm.append({
                "descricao": prod["descricao"],
                "cfop": prod["cfop"],
                "valor_total": round(prod["valor_total"], 2),
                "bc_icms": round(prod["bc_icms"], 2),
                "valor_icms": round(prod["valor_icms"], 2)
            })
        produtos_ncm.sort(key=lambda x: x["valor_icms"], reverse=True)
        
        lista_ncm.append({
            "ncm": n["ncm"],
            "descricao_ncm": n["descricao_ncm"],
            "valor_total": round(n["valor_total"], 2),
            "bc_icms": round(n["bc_icms"], 2),
            "valor_icms": round(n["valor_icms"], 2),
            "qtd_produtos": len(produtos_ncm),
            "produtos": produtos_ncm
        })
    lista_ncm.sort(key=lambda x: x["valor_icms"], reverse=True)
    
    return {
        "total_produtos": total_produtos,
        "valor_total": round(total_valor, 2),
        "bc_icms_total": round(sum(p["bc_icms"] for p in lista_produtos), 2),
        "valor_icms_desconsiderado": round(total_icms, 2),
        "por_produto": lista_produtos,
        "por_ncm": lista_ncm,
        "configuracao": {
            "tipo_beneficio": company.get('tipo_beneficio_fiscal', ''),
            "produtos_sem_credito": company.get('produtos_sem_credito_icms', [])
        }
    }


@api_router.get("/desconsiderados-detalhes/{company_id}")
async def get_desconsiderados_detalhes(
    company_id: str,
    competencia: str = Query(..., description="Competência no formato MM/YYYY"),
    tipo: str = Query(..., description="Tipo: 'st', 'despesas' ou 'todos'"),
    current_user: User = Depends(get_current_user)
):
    """
    Retorna o detalhamento dos créditos de ICMS desconsiderados por ST ou Despesas.
    Agrupa os dados por produto e por NCM.
    """
    # Buscar empresa
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    # Buscar documentos de entrada da competência
    docs = await db.xml_documents.find({
        "company_id": company_id,
        "competencia": competencia
    }, {"_id": 0, "xml_content": 0}).to_list(50000)
    
    # Filtrar apenas documentos de entrada
    docs_entrada = [doc for doc in docs if doc.get('tipo', doc.get('tipo_operacao', 'saida')) == 'entrada']
    
    # CFOPs de ST e Despesas
    CFOPS_ST = {'1401', '1403', '1407', '1408', '1409', '2401', '2403', '2407', '2408', '2409'}
    CFOPS_DESPESA = {
        '1128', '1407', '1556', '1557', '1651', '1652', '1653', '1658', '1659', '1660', '1661', '1662',
        '1663', '1664', '1901', '1902', '1903', '1904', '1905', '1906', '1907', '1908', '1909', '1910',
        '1911', '1912', '1913', '1914', '1915', '1916', '1917', '1918', '1919', '1920', '1921', '1922',
        '1923', '1924', '1925', '1926', '1949', '2128', '2407', '2556', '2557', '2651', '2652', '2653',
        '2658', '2659', '2660', '2661', '2662', '2663', '2664', '2901', '2902', '2903', '2904', '2905',
        '2906', '2907', '2908', '2909', '2910', '2911', '2912', '2913', '2914', '2915', '2916', '2917',
        '2918', '2919', '2920', '2921', '2922', '2923', '2924', '2925', '2949'
    }
    
    # Determinar quais CFOPs filtrar
    if tipo == 'st':
        cfops_filtrar = CFOPS_ST
        titulo = "Produtos com ICMS ST Desconsiderado"
    elif tipo == 'despesas':
        cfops_filtrar = CFOPS_DESPESA
        titulo = "Produtos de Despesa (ICMS Desconsiderado)"
    else:
        cfops_filtrar = CFOPS_ST | CFOPS_DESPESA
        titulo = "Todos os Produtos Desconsiderados"
    
    # Estruturas para acumular dados
    por_produto = {}
    por_ncm = {}
    
    total_valor = 0
    total_icms = 0
    total_produtos = 0
    
    # Processar documentos
    for doc in docs_entrada:
        itens = doc.get('itens', []) or doc.get('produtos', [])
        if not itens:
            continue
        
        numero_nfe = doc.get('numero_nfe', doc.get('numero', ''))
        emitente = doc.get('emitente_nome', '')
        if isinstance(doc.get('emitente'), dict):
            emitente = doc.get('emitente', {}).get('razao_social', emitente)
        
        for item in itens:
            cfop = str(item.get('cfop', '') or '').strip()
            
            # Verificar se o CFOP está na lista de filtro
            if cfop not in cfops_filtrar:
                continue
            
            ncm = str(item.get('ncm', '') or '').strip()
            descricao = str(item.get('descricao', '') or item.get('produto', '') or '').strip()
            valor_produto = float(item.get('valor_produto', 0) or item.get('valor_total', 0) or 0)
            bc_icms = float(item.get('bc_icms', 0) or item.get('v_bc_icms', 0) or 0)
            valor_icms = float(item.get('valor_icms', 0) or item.get('v_icms', 0) or 0)
            
            # Determinar o tipo (ST ou Despesa)
            tipo_item = "ST" if cfop in CFOPS_ST else "Despesa"
            
            # Acumular totais
            total_valor += valor_produto
            total_icms += valor_icms
            total_produtos += 1
            
            # Agregar por produto
            desc_key = descricao[:100] if descricao else "Produto sem descrição"
            if desc_key not in por_produto:
                por_produto[desc_key] = {
                    "descricao": desc_key,
                    "ncm": ncm,
                    "cfop": cfop,
                    "tipo": tipo_item,
                    "valor_total": 0,
                    "valor_icms": 0,
                    "qtd_notas": 0,
                    "notas": []
                }
            por_produto[desc_key]["valor_total"] += valor_produto
            por_produto[desc_key]["valor_icms"] += valor_icms
            if numero_nfe and numero_nfe not in [n.get('numero') for n in por_produto[desc_key]["notas"]]:
                por_produto[desc_key]["notas"].append({
                    "numero": numero_nfe,
                    "emitente": emitente[:30] if emitente else ""
                })
            por_produto[desc_key]["qtd_notas"] = len(por_produto[desc_key]["notas"])
            
            # Agregar por NCM
            ncm_key = ncm[:8] if ncm else "SEM_NCM"
            if ncm_key not in por_ncm:
                por_ncm[ncm_key] = {
                    "ncm": ncm_key,
                    "valor_total": 0,
                    "valor_icms": 0,
                    "qtd_itens": 0,
                    "produtos": set()
                }
            por_ncm[ncm_key]["valor_total"] += valor_produto
            por_ncm[ncm_key]["valor_icms"] += valor_icms
            por_ncm[ncm_key]["qtd_itens"] += 1
            por_ncm[ncm_key]["produtos"].add(desc_key[:50])
    
    # Converter para listas ordenadas
    lista_produtos = []
    for item in por_produto.values():
        lista_produtos.append({
            "descricao": item["descricao"],
            "ncm": item["ncm"],
            "cfop": item["cfop"],
            "tipo": item["tipo"],
            "valor_total": round(item["valor_total"], 2),
            "valor_icms": round(item["valor_icms"], 2),
            "qtd_notas": item["qtd_notas"],
            "notas": item["notas"][:5]  # Limitar a 5 notas
        })
    lista_produtos.sort(key=lambda x: x["valor_icms"], reverse=True)
    
    lista_ncm = []
    for ncm_key, item in por_ncm.items():
        lista_ncm.append({
            "ncm": ncm_key,
            "valor_total": round(item["valor_total"], 2),
            "valor_icms": round(item["valor_icms"], 2),
            "qtd_itens": item["qtd_itens"],
            "produtos": list(item["produtos"])[:5]  # Limitar a 5 produtos
        })
    lista_ncm.sort(key=lambda x: x["valor_icms"], reverse=True)
    
    return {
        "titulo": titulo,
        "tipo": tipo,
        "total_produtos": total_produtos,
        "valor_total": round(total_valor, 2),
        "valor_icms_desconsiderado": round(total_icms, 2),
        "por_produto": lista_produtos,
        "por_ncm": lista_ncm
    }


@api_router.get("/beneficio-fiscal-detalhes/{company_id}/exportar")
async def exportar_beneficio_fiscal_detalhes(
    company_id: str,
    competencia: str = Query(..., description="Competência no formato MM/YYYY"),
    formato: str = Query(..., description="Formato de exportação: 'excel' ou 'pdf'"),
    agrupamento: str = Query("produto", description="Agrupamento: 'produto' ou 'ncm'"),
    current_user: User = Depends(get_current_user)
):
    """
    Exporta o detalhamento do benefício fiscal para Excel ou PDF.
    """
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    from reportlab.lib.pagesizes import A4, landscape
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib import colors
    from reportlab.lib.units import cm
    
    # Buscar dados
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    # Reutilizar a lógica do endpoint de detalhes
    dados = await get_beneficio_fiscal_detalhes(company_id, competencia, current_user)
    
    if formato == 'excel':
        wb = Workbook()
        
        # Estilo cabeçalho
        header_fill = PatternFill(start_color="C8A951", end_color="C8A951", fill_type="solid")
        header_font = Font(bold=True, color="FFFFFF")
        total_fill = PatternFill(start_color="FEF3C7", end_color="FEF3C7", fill_type="solid")
        total_font = Font(bold=True)
        thin_border = Border(
            left=Side(style='thin'),
            right=Side(style='thin'),
            top=Side(style='thin'),
            bottom=Side(style='thin')
        )
        
        # Aba por Produto
        ws_produto = wb.active
        ws_produto.title = "Por Produto"
        
        # Cabeçalho
        ws_produto['A1'] = f"BENEFÍCIO FISCAL ICMS - {company.get('razao_social', '')}"
        ws_produto['A1'].font = Font(bold=True, size=14)
        ws_produto['A2'] = f"Competência: {competencia} | CNPJ: {company.get('cnpj', '')}"
        ws_produto['A3'] = f"Tipo de Benefício: {company.get('tipo_beneficio_fiscal', 'Geral')}"
        
        # Resumo
