# ========== IMPOSTOS RETIDOS ==========

@api_router.get("/impostos-retidos/{company_id}")
async def get_impostos_retidos(
    company_id: str,
    competencia: str,
    current_user: User = Depends(get_current_user)
):
    """
    Retorna a apuração de impostos retidos para serviços tomados e prestados.
    Inclui ISS, IR, PIS, COFINS, CSLL e INSS.
    
    IMPORTANTE para Simples Nacional:
    - O ISS retido na fonte (quando a empresa presta serviço e o tomador retém)
      deve ser DESCONTADO do DAS, pois a tributação do ISS no Simples é própria.
    - Isso significa que se o tomador já reteve R$ 500 de ISS, esse valor não
      entra no cálculo do DAS.
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    regime = company.get('regime_tributario', '')
    
    # Buscar documentos de serviços da competência
    documentos = await db.xml_documents.find({
        "company_id": company_id,
        "competencia": competencia,
        "$or": [
            {"modelo": "nfse"},
            {"modelo": {"$in": ["nfse_tomado", "nfse_prestado"]}},
            {"tipo_operacao": {"$in": ["tomado", "prestado"]}}
        ],
        **get_filtro_notas_ativas()
    }, {"_id": 0}).to_list(100000)
    
    # Estrutura para acumular dados
    retencoes_tomados = {
        "iss": 0, "ir": 0, "pis": 0, "cofins": 0, "csll": 0, "inss": 0,
        "total_servicos": 0, "qtd_docs": 0, "detalhes": []
    }
    retencoes_prestados = {
        "iss": 0, "ir": 0, "pis": 0, "cofins": 0, "csll": 0, "inss": 0,
        "total_servicos": 0, "qtd_docs": 0, "detalhes": []
    }
    
    # Processar documentos
    for doc in documentos:
        tipo = doc.get('tipo_operacao', doc.get('tipo', 'tomado'))
        if tipo in ['saida', 'prestado']:
            estrutura = retencoes_prestados
        else:
            estrutura = retencoes_tomados
        
        estrutura["qtd_docs"] += 1
        
        # Valores do documento
        valor_servicos = float(doc.get('valor_servicos', 0) or doc.get('valor_total', 0) or 0)
        estrutura["total_servicos"] += valor_servicos
        
        # Impostos retidos - primeiro verificar campos novos, depois legados
        # ISS Retido
        iss_retido = float(doc.get('iss_retido', 0) or 0)
        # Se o campo é booleano (True/False) ou flag (1/2), usar valor_iss
        if isinstance(doc.get('iss_retido'), bool) or doc.get('iss_retido_flag'):
            if doc.get('iss_retido_flag', False) or doc.get('iss_retido') == True:
                iss_retido = float(doc.get('valor_iss', 0) or 0)
        
        # Outras retenções
        ir_retido = float(doc.get('ir_retido', 0) or doc.get('irrf_retido', 0) or 0)
        pis_retido = float(doc.get('pis_retido', 0) or 0)
        cofins_retido = float(doc.get('cofins_retido', 0) or 0)
        csll_retido = float(doc.get('csll_retido', 0) or 0)
        inss_retido = float(doc.get('inss_retido', 0) or 0)
        
        # Verificar também nos serviços (estrutura antiga)
        for servico in doc.get('servicos', []):
            # ISS nos serviços
            if servico.get('iss_retido') == True or servico.get('iss_retido') == '1':
                iss_retido += float(servico.get('valor_iss', 0) or 0)
            elif isinstance(servico.get('iss_retido'), (int, float)) and servico.get('iss_retido') > 0:
                iss_retido += float(servico.get('iss_retido', 0))
            
            # Outras retenções nos serviços
            ir_retido += float(servico.get('v_ir', 0) or servico.get('ir_retido', 0) or 0)
            pis_retido += float(servico.get('v_pis', 0) or servico.get('pis_retido', 0) or 0)
            cofins_retido += float(servico.get('v_cofins', 0) or servico.get('cofins_retido', 0) or 0)
            csll_retido += float(servico.get('v_csll', 0) or servico.get('csll_retido', 0) or 0)
            inss_retido += float(servico.get('v_inss', 0) or servico.get('inss_retido', 0) or 0)
        
        # Acumular
        estrutura["iss"] += iss_retido
        estrutura["ir"] += ir_retido
        estrutura["pis"] += pis_retido
        estrutura["cofins"] += cofins_retido
        estrutura["csll"] += csll_retido
        estrutura["inss"] += inss_retido
        
        # Adicionar aos detalhes se tiver alguma retenção
        total_retido = iss_retido + ir_retido + pis_retido + cofins_retido + csll_retido + inss_retido
        if total_retido > 0:
            estrutura["detalhes"].append({
                "numero_nf": doc.get('numero_nfe', ''),
                "data_emissao": doc.get('data_emissao', ''),
                "prestador" if tipo in ['entrada', 'tomado'] else "tomador": doc.get('emitente_nome', '') if tipo in ['entrada', 'tomado'] else doc.get('destinatario_nome', ''),
                "cnpj": doc.get('emitente_cnpj', '') if tipo in ['entrada', 'tomado'] else doc.get('destinatario_cnpj', ''),
                "valor_servicos": round(valor_servicos, 2),
                "retencoes": {
                    "iss": round(iss_retido, 2),
                    "ir": round(ir_retido, 2),
                    "pis": round(pis_retido, 2),
                    "cofins": round(cofins_retido, 2),
                    "csll": round(csll_retido, 2),
                    "inss": round(inss_retido, 2)
                },
                "total_retido": round(total_retido, 2)
            })
    
    # Calcular totais
    total_retido_tomados = sum([
        retencoes_tomados["iss"], retencoes_tomados["ir"], 
        retencoes_tomados["pis"], retencoes_tomados["cofins"],
        retencoes_tomados["csll"], retencoes_tomados["inss"]
    ])
    
    total_retido_prestados = sum([
        retencoes_prestados["iss"], retencoes_prestados["ir"], 
        retencoes_prestados["pis"], retencoes_prestados["cofins"],
        retencoes_prestados["csll"], retencoes_prestados["inss"]
    ])
    
    return {
        "empresa": {
            "id": company_id,
            "razao_social": company.get('razao_social', ''),
            "cnpj": company.get('cnpj', '')
        },
        "competencia": competencia,
        "servicos_tomados": {
            "total_servicos": round(retencoes_tomados["total_servicos"], 2),
            "qtd_documentos": retencoes_tomados["qtd_docs"],
            "retencoes": {
                "iss": round(retencoes_tomados["iss"], 2),
                "ir": round(retencoes_tomados["ir"], 2),
                "pis": round(retencoes_tomados["pis"], 2),
                "cofins": round(retencoes_tomados["cofins"], 2),
                "csll": round(retencoes_tomados["csll"], 2),
                "inss": round(retencoes_tomados["inss"], 2)
            },
            "total_retido": round(total_retido_tomados, 2),
            "detalhes": sorted(retencoes_tomados["detalhes"], key=lambda x: -x["total_retido"])
        },
        "servicos_prestados": {
            "total_servicos": round(retencoes_prestados["total_servicos"], 2),
            "qtd_documentos": retencoes_prestados["qtd_docs"],
            "retencoes": {
                "iss": round(retencoes_prestados["iss"], 2),
                "ir": round(retencoes_prestados["ir"], 2),
                "pis": round(retencoes_prestados["pis"], 2),
                "cofins": round(retencoes_prestados["cofins"], 2),
                "csll": round(retencoes_prestados["csll"], 2),
                "inss": round(retencoes_prestados["inss"], 2)
            },
            "total_retido": round(total_retido_prestados, 2),
            "detalhes": sorted(retencoes_prestados["detalhes"], key=lambda x: -x["total_retido"])
        },
        "resumo": {
            "total_retido_como_tomador": round(total_retido_tomados, 2),
            "total_retido_como_prestador": round(total_retido_prestados, 2),
            "liquido": round(total_retido_tomados - total_retido_prestados, 2),
            "orientacao": "A empresa reteve impostos de prestadores (tem obrigação de recolher)" if total_retido_tomados > 0 else "A empresa não possui obrigações de recolhimento de impostos retidos de terceiros"
        },
        # Informações para Simples Nacional
        "simples_nacional": {
            "regime": regime,
            "is_simples": regime == 'simples_nacional',
            "iss_retido_abater_das": round(retencoes_prestados["iss"], 2) if regime == 'simples_nacional' else 0,
            "orientacao_iss": "O ISS retido na fonte pelos tomadores de serviço deve ser DESCONTADO do DAS. Este valor não entra no cálculo do Simples Nacional pois já foi retido." if regime == 'simples_nacional' and retencoes_prestados["iss"] > 0 else ""
        }
    }


@api_router.get("/impostos-retidos/{company_id}/guias")
async def get_guias_retencao(
    company_id: str,
    competencia: str,
    current_user: User = Depends(get_current_user)
):
    """
    Gera relatório de guias de retenção para serviços TOMADOS.
    Separa as retenções por tipo de guia:
    
    - DARF 1708: IR Retido na Fonte (IRRF)
    - DARF 5952: PCC (PIS + COFINS + CSLL) - Contribuições Sociais Retidas
    - ISS: Uma guia por município (separado por código do município)
    - INSS: GPS - Vai junto com o eSocial
    
    Cada guia contém:
    - Lista de notas que geraram a retenção
    - Valor total da guia
    - Código de recolhimento
    - Data de vencimento sugerida
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    # Buscar documentos de serviços TOMADOS da competência
    documentos = await db.xml_documents.find({
        "company_id": company_id,
        "competencia": competencia,
        "$or": [
            {"modelo": "nfse", "tipo": "entrada"},
            {"modelo": "nfse_tomado"},
            {"tipo_operacao": "tomado"}
        ],
        **get_filtro_notas_ativas()
    }, {"_id": 0}).to_list(100000)
    
    # Estruturas para acumular por tipo de guia
    guia_ir = {
        "codigo": "1708",
        "descricao": "IRRF - Imposto de Renda Retido na Fonte",
        "valor_total": 0,
        "notas": []
    }
    
    guia_pcc = {
        "codigo": "5952",
        "descricao": "PCC - Contribuições Sociais Retidas (PIS + COFINS + CSLL)",
        "valor_total": 0,
        "valor_pis": 0,
        "valor_cofins": 0,
        "valor_csll": 0,
        "notas": []
    }
    
    guias_iss = {}  # Dicionário por código do município
    
    guia_inss = {
        "codigo": "GPS",
        "descricao": "INSS - Contribuição Previdenciária Retida (vai no eSocial)",
        "valor_total": 0,
        "notas": []
    }
    
    # Processar documentos
    for doc in documentos:
        numero_nf = doc.get('numero_nfe', '')
        data_emissao = doc.get('data_emissao', '')
        prestador = doc.get('emitente_nome', '')
        cnpj_prestador = doc.get('emitente_cnpj', '')
        valor_servicos = float(doc.get('valor_servicos', 0) or doc.get('valor_total', 0) or 0)
        
        # Código do município (para ISS)
        cod_municipio = doc.get('codigo_municipio_servico', '') or doc.get('emitente_cod_municipio', '') or doc.get('codigo_municipio', '')
        nome_municipio = doc.get('municipio_servico', '') or doc.get('emitente_municipio', '') or 'Não identificado'
        uf_municipio = doc.get('emitente_uf', '') or doc.get('uf_servico', '') or ''
        
        # Extrair retenções do documento
        iss_retido = float(doc.get('iss_retido', 0) or 0)
        if isinstance(doc.get('iss_retido'), bool) or doc.get('iss_retido_flag'):
            if doc.get('iss_retido_flag', False) or doc.get('iss_retido') == True:
                iss_retido = float(doc.get('valor_iss', 0) or 0)
        
        ir_retido = float(doc.get('ir_retido', 0) or doc.get('irrf_retido', 0) or 0)
        pis_retido = float(doc.get('pis_retido', 0) or 0)
        cofins_retido = float(doc.get('cofins_retido', 0) or 0)
        csll_retido = float(doc.get('csll_retido', 0) or 0)
        inss_retido = float(doc.get('inss_retido', 0) or 0)
        
        # Verificar também nos serviços
        for servico in doc.get('servicos', []):
            if servico.get('iss_retido') == True or servico.get('iss_retido') == '1':
                iss_retido += float(servico.get('valor_iss', 0) or 0)
            ir_retido += float(servico.get('v_ir', 0) or servico.get('ir_retido', 0) or 0)
            pis_retido += float(servico.get('v_pis', 0) or servico.get('pis_retido', 0) or 0)
            cofins_retido += float(servico.get('v_cofins', 0) or servico.get('cofins_retido', 0) or 0)
            csll_retido += float(servico.get('v_csll', 0) or servico.get('csll_retido', 0) or 0)
            inss_retido += float(servico.get('v_inss', 0) or servico.get('inss_retido', 0) or 0)
        
        # Montar dados base da nota
        nota_base = {
            "numero_nf": numero_nf,
            "data_emissao": data_emissao,
            "prestador": prestador,
            "cnpj_prestador": cnpj_prestador,
            "valor_servicos": round(valor_servicos, 2)
        }
        
        # DARF 1708 - IR Retido
        if ir_retido > 0:
            guia_ir["valor_total"] += ir_retido
            guia_ir["notas"].append({
                **nota_base,
                "valor_retido": round(ir_retido, 2)
            })
        
        # DARF 5952 - PCC (PIS + COFINS + CSLL)
        valor_pcc = pis_retido + cofins_retido + csll_retido
        if valor_pcc > 0:
            guia_pcc["valor_total"] += valor_pcc
            guia_pcc["valor_pis"] += pis_retido
            guia_pcc["valor_cofins"] += cofins_retido
            guia_pcc["valor_csll"] += csll_retido
            guia_pcc["notas"].append({
                **nota_base,
                "valor_pis": round(pis_retido, 2),
                "valor_cofins": round(cofins_retido, 2),
                "valor_csll": round(csll_retido, 2),
                "valor_retido": round(valor_pcc, 2)
            })
        
        # ISS - Separado por município
        if iss_retido > 0:
            chave_mun = cod_municipio or nome_municipio
            if chave_mun not in guias_iss:
                guias_iss[chave_mun] = {
                    "codigo_municipio": cod_municipio,
                    "nome_municipio": nome_municipio,
                    "uf": uf_municipio,
                    "descricao": f"ISS Retido - {nome_municipio}/{uf_municipio}" if uf_municipio else f"ISS Retido - {nome_municipio}",
                    "valor_total": 0,
                    "notas": []
                }
            
            guias_iss[chave_mun]["valor_total"] += iss_retido
            guias_iss[chave_mun]["notas"].append({
                **nota_base,
                "valor_retido": round(iss_retido, 2)
            })
        
        # GPS - INSS
        if inss_retido > 0:
            guia_inss["valor_total"] += inss_retido
            guia_inss["notas"].append({
                **nota_base,
                "valor_retido": round(inss_retido, 2)
            })
    
    # Calcular data de vencimento (dia 20 do mês seguinte)
    mes, ano = map(int, competencia.split('/'))
    if mes == 12:
        mes_venc = 1
        ano_venc = ano + 1
    else:
        mes_venc = mes + 1
        ano_venc = ano
    data_vencimento = f"20/{mes_venc:02d}/{ano_venc}"
    
    # Montar lista de guias
    guias = []
    
    # DARF 1708 - IR
    if guia_ir["valor_total"] > 0:
        guia_ir["valor_total"] = round(guia_ir["valor_total"], 2)
        guia_ir["data_vencimento"] = data_vencimento
        guia_ir["qtd_notas"] = len(guia_ir["notas"])
        guias.append(guia_ir)
    
    # DARF 5952 - PCC
    if guia_pcc["valor_total"] > 0:
        guia_pcc["valor_total"] = round(guia_pcc["valor_total"], 2)
        guia_pcc["valor_pis"] = round(guia_pcc["valor_pis"], 2)
        guia_pcc["valor_cofins"] = round(guia_pcc["valor_cofins"], 2)
        guia_pcc["valor_csll"] = round(guia_pcc["valor_csll"], 2)
        guia_pcc["data_vencimento"] = data_vencimento
        guia_pcc["qtd_notas"] = len(guia_pcc["notas"])
        guias.append(guia_pcc)
    
    # ISS - Uma guia por município
    for chave, guia in guias_iss.items():
        guia["valor_total"] = round(guia["valor_total"], 2)
        guia["data_vencimento"] = f"10/{mes_venc:02d}/{ano_venc}"  # ISS geralmente vence dia 10
        guia["qtd_notas"] = len(guia["notas"])
        guias.append(guia)
    
    # GPS - INSS
    if guia_inss["valor_total"] > 0:
        guia_inss["valor_total"] = round(guia_inss["valor_total"], 2)
        guia_inss["data_vencimento"] = f"20/{mes_venc:02d}/{ano_venc}"
        guia_inss["qtd_notas"] = len(guia_inss["notas"])
        guia_inss["observacao"] = "Este valor deve ser somado à GPS da folha de pagamento (eSocial)"
        guias.append(guia_inss)
    
    # Calcular totais
    total_ir = guia_ir["valor_total"]
    total_pcc = guia_pcc["valor_total"]
    total_iss = sum(g["valor_total"] for g in guias_iss.values())
    total_inss = guia_inss["valor_total"]
    total_geral = total_ir + total_pcc + total_iss + total_inss
    
    return {
        "empresa": {
            "id": company_id,
            "razao_social": company.get('razao_social', ''),
            "cnpj": company.get('cnpj', '')
        },
        "competencia": competencia,
        "data_geracao": datetime.now().strftime("%d/%m/%Y %H:%M"),
        "resumo": {
            "total_guias": len(guias),
            "total_ir_1708": round(total_ir, 2),
            "total_pcc_5952": round(total_pcc, 2),
            "total_iss": round(total_iss, 2),
            "qtd_municipios_iss": len(guias_iss),
            "total_inss_gps": round(total_inss, 2),
            "total_geral": round(total_geral, 2)
        },
        "guias": guias,
        "orientacoes": {
            "darf_1708": "DARF código 1708 - IRRF sobre serviços profissionais. Vencimento: dia 20 do mês subsequente.",
            "darf_5952": "DARF código 5952 - Retenções de PIS, COFINS e CSLL. Vencimento: dia 20 do mês subsequente. Somente se valor >= R$ 10,00.",
            "iss": "Guia de ISS - Emitir no site da prefeitura de cada município. Vencimento varia por município (geralmente dia 10).",
            "inss": "GPS - O valor de INSS retido deve ser somado à guia GPS da folha de pagamento, informado via eSocial."
        }
    }


# ========== ENDPOINTS PARA CANCELAMENTO DE NFS-e ==========

@api_router.post("/nfse/preview")
async def preview_nfse_for_cancellation(
    company_id: str = Form(...),
    files: List[UploadFile] = File(...),
    current_user: User = Depends(get_current_user)
):
    """
    Pré-visualiza NFS-e de um arquivo XML para permitir marcação de notas canceladas.
    Retorna lista de notas com número, data, valor e tomador para seleção.
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    cnpj_empresa = company.get('cnpj', '').replace('.', '').replace('/', '').replace('-', '')
    
    all_nfse = []
    
    for file in files:
        try:
            content = await file.read()
            xml_str = content.decode('utf-8')
            
            # Verificar se é uma lista de NFS-e
            if is_lista_nfse(xml_str):
                lista_nfse = parse_xml_lista_nfse(xml_str)
                
                for idx, nfse in enumerate(lista_nfse):
                    cnpj_emitente = nfse.get('emitente_cnpj', '').replace('.', '').replace('/', '').replace('-', '')
                    
                    # Só incluir se pertencer à empresa
                    if cnpj_emitente == cnpj_empresa:
                        # Verificar se já existe no banco
                        existing = await db.xml_documents.find_one({
                            "chave_nfe": nfse.get('chave_nfe', ''),
                            "company_id": company_id
                        })
                        
                        all_nfse.append({
                            "numero": nfse.get('numero_nfe', ''),
                            "data_emissao": nfse.get('data_emissao', ''),
                            "valor": nfse.get('valor_total', 0),
                            "tomador_nome": nfse.get('destinatario_nome', ''),
                            "tomador_cnpj": nfse.get('destinatario_cnpj', ''),
                            "competencia": nfse.get('competencia_nfse', ''),
                            "chave": nfse.get('chave_nfe', ''),
                            "arquivo": file.filename,
                            "indice": idx,
                            "ja_importada": existing is not None
                        })
            else:
                # Arquivo único de NFS-e
                parsed = parse_xml_nfse(xml_str)
                cnpj_emitente = parsed.get('emitente_cnpj', '').replace('.', '').replace('/', '').replace('-', '')
                
                if cnpj_emitente == cnpj_empresa:
                    existing = await db.xml_documents.find_one({
                        "chave_nfe": parsed.get('chave_nfe', ''),
                        "company_id": company_id
                    })
                    
                    all_nfse.append({
                        "numero": parsed.get('numero_nfe', ''),
                        "data_emissao": parsed.get('data_emissao', ''),
                        "valor": parsed.get('valor_total', 0),
                        "tomador_nome": parsed.get('destinatario_nome', ''),
                        "tomador_cnpj": parsed.get('destinatario_cnpj', ''),
                        "competencia": parsed.get('competencia_nfse', ''),
                        "chave": parsed.get('chave_nfe', ''),
                        "arquivo": file.filename,
                        "indice": 0,
                        "ja_importada": existing is not None
                    })
        except Exception as e:
            print(f"Erro ao processar arquivo {file.filename}: {str(e)}")
            continue
    
    # Ordenar por número
    all_nfse.sort(key=lambda x: int(x['numero']) if x['numero'].isdigit() else 0)
    
    return {
        "total": len(all_nfse),
        "notas": all_nfse,
        "empresa": {
            "razao_social": company.get('razao_social', ''),
            "cnpj": company.get('cnpj', '')
        }
    }


@api_router.post("/nfse/import-with-cancellations")
async def import_nfse_with_cancellations(
    company_id: str = Form(...),
    competencia: str = Form(...),
    tipo: str = Form(...),
    notas_canceladas: str = Form(default=""),  # JSON array de números de notas canceladas
    files: List[UploadFile] = File(...),
    current_user: User = Depends(get_current_user)
):
    """
    Importa NFS-e com suporte a marcação de notas canceladas.
    As notas marcadas como canceladas são importadas com status 'cancelada' e valor zerado.
    """
    import json
    
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    cnpj_empresa = company.get('cnpj', '').replace('.', '').replace('/', '').replace('-', '')
    
    # Parse da lista de notas canceladas
    try:
        numeros_cancelados = json.loads(notas_canceladas) if notas_canceladas else []
    except:
        numeros_cancelados = []
    
    numeros_cancelados_set = set(str(n) for n in numeros_cancelados)
    
    results = []
    errors = []
    duplicadas = []
    rejeitadas_cnpj = []
    canceladas_importadas = []
    
    for file in files:
        try:
            content = await file.read()
            xml_str = content.decode('utf-8')
            
            notas_para_processar = []
            
            if is_lista_nfse(xml_str):
                notas_para_processar = parse_xml_lista_nfse(xml_str)
            else:
                parsed = parse_xml_nfse(xml_str)
                if parsed:
                    notas_para_processar = [parsed]
            
            for idx, parsed_data in enumerate(notas_para_processar):
                try:
                    chave_nfe = parsed_data.get('chave_nfe', '')
                    numero_nota = str(parsed_data.get('numero_nfe', ''))
                    
                    # Verificar se é nota cancelada
                    is_cancelada = numero_nota in numeros_cancelados_set
                    
                    # Validar CNPJ
                    cnpj_emitente = parsed_data.get('emitente_cnpj', '').replace('.', '').replace('/', '').replace('-', '')
                    cnpj_destinatario = parsed_data.get('destinatario_cnpj', '').replace('.', '').replace('/', '').replace('-', '')
                    
                    cnpj_valido = False
                    if tipo == 'saida':
                        cnpj_valido = cnpj_emitente == cnpj_empresa
                    else:
                        cnpj_valido = cnpj_destinatario == cnpj_empresa
                    
                    if not cnpj_valido:
                        rejeitadas_cnpj.append({
                            "arquivo": f"{file.filename} (nota {numero_nota})",
                            "numero": numero_nota,
                            "motivo": "CNPJ não corresponde à empresa"
                        })
                        continue
                    
                    # Verificar duplicidade
                    existing = await db.xml_documents.find_one({
                        "chave_nfe": chave_nfe,
                        "company_id": company_id
                    })
                    
                    if existing:
                        duplicadas.append({
                            "arquivo": f"{file.filename} (nota {numero_nota})",
                            "numero": numero_nota
                        })
                        continue
                    
                    # Extrair competência
                    competencia_nfse = parsed_data.get('competencia_nfse', '')
                    if competencia_nfse:
                        try:
                            comp_date = competencia_nfse.split('T')[0]
                            ano, mes, _ = comp_date.split('-')
                            competencia_doc = f"{mes}/{ano}"
                        except:
                            competencia_doc = competencia
                    else:
                        competencia_doc = competencia
                    
                    # Valores - zerar se cancelada
                    valor_original = parsed_data.get('valor_total', 0)
                    valor_final = 0 if is_cancelada else valor_original
                    valor_servicos = 0 if is_cancelada else parsed_data.get('valor_servicos', 0)
                    
                    # Preparar documento
                    document = {
                        "id": str(uuid.uuid4()),
                        "company_id": company_id,
                        "chave_nfe": chave_nfe,
                        "numero_nfe": numero_nota,
                        "serie": parsed_data.get('serie', '1'),
                        "modelo": 'nfse',
                        "data_emissao": parsed_data.get('data_emissao', ''),
                        "valor_total": valor_final,
                        "valor_servicos": valor_servicos,
                        "valor_original": valor_original,  # Guardar valor original para referência
                        "emitente_cnpj": cnpj_emitente,
                        "emitente_nome": parsed_data.get('emitente_nome', ''),
                        "emitente_ie": parsed_data.get('emitente_ie', ''),
                        "emitente_uf": parsed_data.get('emitente_uf', ''),
                        "emitente_endereco": parsed_data.get('emitente_endereco', {}),
                        "destinatario_cnpj": cnpj_destinatario,
                        "destinatario_nome": parsed_data.get('destinatario_nome', ''),
                        "destinatario_ie": parsed_data.get('destinatario_ie', ''),
                        "destinatario_uf": parsed_data.get('destinatario_uf', ''),
                        "destinatario_endereco": parsed_data.get('destinatario_endereco', {}),
                        "produtos": [],
                        "servicos": parsed_data.get('servicos', []) if not is_cancelada else [],
                        "tipo": tipo,
                        "tipo_operacao": "prestado" if tipo == "saida" else "tomado",
                        "competencia": competencia_doc,
                        "imported_at": datetime.now(timezone.utc).isoformat(),
                        "status": "cancelada" if is_cancelada else "active"
                    }
                    
                    await db.xml_documents.insert_one(document)
                    
                    result_item = {
                        "arquivo": f"{file.filename} (nota {numero_nota})",
                        "numero": numero_nota,
                        "valor": valor_final,
                        "valor_original": valor_original,
                        "emitente": parsed_data.get('emitente_nome', ''),
                        "tomador": parsed_data.get('destinatario_nome', ''),
                        "status": "cancelada" if is_cancelada else "ativa",
                        "competencia": competencia_doc
                    }
                    
                    results.append(result_item)
                    
                    if is_cancelada:
                        canceladas_importadas.append(result_item)
                    
                except Exception as e:
                    errors.append({
                        "arquivo": f"{file.filename} (nota {idx + 1})",
                        "erro": str(e)
                    })
        
        except Exception as e:
            errors.append({
                "arquivo": file.filename,
                "erro": str(e)
            })
    
    # Calcular resumo
    total_ativas = len([r for r in results if r['status'] == 'ativa'])
    total_canceladas = len([r for r in results if r['status'] == 'cancelada'])
    valor_total_importado = sum(r['valor'] for r in results)
    
    return {
        "sucesso": True,
        "resumo": {
            "total_arquivos": len(files),
            "total_notas": len(results),
            "ativas": total_ativas,
            "canceladas": total_canceladas,
            "duplicadas": len(duplicadas),
            "rejeitadas": len(rejeitadas_cnpj),
            "erros": len(errors),
            "valor_total": valor_total_importado
        },
        "notas_importadas": results,
        "notas_canceladas": canceladas_importadas,
        "duplicadas": duplicadas,
        "rejeitadas_cnpj": rejeitadas_cnpj,
        "errors": errors
    }


@api_router.post("/nfse/import-cancellation-report")
async def import_cancellation_from_report(
    company_id: str = Form(...),
    report_file: UploadFile = File(...),
    current_user: User = Depends(get_current_user)
):
    """
    Processa um arquivo de relatório (Excel, TXT, CSV, XML, PDF) contendo números de notas canceladas.
    Retorna lista de números para ser usada na importação.
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    content = await report_file.read()
    filename = report_file.filename.lower()
    
    numeros_cancelados = []
    
    try:
        if filename.endswith('.csv') or filename.endswith('.txt'):
            # Processar CSV/TXT
            text = content.decode('utf-8', errors='ignore')
            lines = text.strip().split('\n')
            
            for line in lines:
                # Tentar extrair números de cada linha
                parts = line.replace(';', ',').split(',')
                for part in parts:
                    clean = ''.join(filter(str.isdigit, part.strip()))
                    if clean and len(clean) <= 15:  # Número de NF razoável
                        numeros_cancelados.append(clean)
        
        elif filename.endswith('.xlsx') or filename.endswith('.xls'):
            # Processar Excel
            import io
            import openpyxl
            
            wb = openpyxl.load_workbook(io.BytesIO(content))
            ws = wb.active
            
            for row in ws.iter_rows():
                for cell in row:
                    if cell.value:
                        valor = str(cell.value).strip()
                        clean = ''.join(filter(str.isdigit, valor))
                        if clean and len(clean) <= 15:
                            numeros_cancelados.append(clean)
        
        elif filename.endswith('.xml'):
            # Processar XML - pode ser relatório de cancelamento ou NFS-e cancelada
            import xml.etree.ElementTree as ET
            import re
            
            try:
                text = content.decode('utf-8', errors='ignore')
                # Remover declaração XML se houver problema
                text = re.sub(r'<\?xml[^>]+\?>', '', text)
                
                root = ET.fromstring(text)
                
                # Procurar por tags comuns que contêm número de nota
                tags_numero = ['NumeroNfse', 'Numero', 'numero', 'InfNfse', 'IdentificacaoNfse', 
                              'NumeroNota', 'nNFe', 'nNF', 'NumeroRps', 'Rps']
                
                for tag in tags_numero:
                    for elem in root.iter(tag):
                        if elem.text:
                            clean = ''.join(filter(str.isdigit, elem.text.strip()))
                            if clean and len(clean) <= 15:
                                numeros_cancelados.append(clean)
                        # Verificar atributos também
                        for attr_name, attr_val in elem.attrib.items():
                            if 'numero' in attr_name.lower():
                                clean = ''.join(filter(str.isdigit, attr_val))
                                if clean and len(clean) <= 15:
                                    numeros_cancelados.append(clean)
                
            except ET.ParseError:
                # Se falhar parsing XML, tentar extrair números via regex
                text = content.decode('utf-8', errors='ignore')
                # Procurar padrões como <Numero>123</Numero> ou numero="123"
                matches = re.findall(r'[Nn]umero[^>]*>(\d+)<|numero\s*=\s*["\'](\d+)["\']', text)
                for match in matches:
                    num = match[0] or match[1]
                    if num and len(num) <= 15:
                        numeros_cancelados.append(num)
        
        elif filename.endswith('.pdf'):
            # Processar PDF - extrair texto e buscar números
            import io
            try:
                import PyPDF2
                
                pdf_reader = PyPDF2.PdfReader(io.BytesIO(content))
                text = ""
                for page in pdf_reader.pages:
                    text += page.extract_text() or ""
                
                # Procurar por padrões de número de nota (geralmente após "Nota" ou "NFS-e")
                import re
                # Padrões comuns: "Nota: 123", "NFS-e nº 123", "Número: 123"
                patterns = [
                    r'[Nn]ota[:\s]+(\d+)',
                    r'[Nn]FS-e[:\s#nº]+(\d+)',
                    r'[Nn]úmero[:\s]+(\d+)',
                    r'^\s*(\d{1,10})\s*$'  # Linhas com apenas números
                ]
                
                for pattern in patterns:
                    matches = re.findall(pattern, text, re.MULTILINE)
                    for match in matches:
                        if len(match) <= 15:
                            numeros_cancelados.append(match)
                            
            except Exception as pdf_err:
                logger.warning(f"Erro ao processar PDF: {pdf_err}")
                raise HTTPException(status_code=400, detail="Não foi possível extrair dados do PDF. Tente CSV ou Excel.")
        
        else:
            # Tentar processar como texto genérico
            text = content.decode('utf-8', errors='ignore')
            lines = text.strip().split('\n')
            
            for line in lines:
                parts = line.replace(';', ',').replace('\t', ',').split(',')
                for part in parts:
                    clean = ''.join(filter(str.isdigit, part.strip()))
                    if clean and len(clean) <= 15:
                        numeros_cancelados.append(clean)
        
        # Remover duplicatas mantendo ordem
        seen = set()
        numeros_unicos = []
        for num in numeros_cancelados:
            if num not in seen:
                seen.add(num)
                numeros_unicos.append(num)
        
        return {
            "sucesso": True,
            "total_encontrados": len(numeros_unicos),
            "numeros_cancelados": numeros_unicos
        }
        
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Erro ao processar arquivo: {str(e)}")


# ============================================================
# ANÁLISE HORIZONTAL (Evolução Fiscal) - Endpoints
# ============================================================

@api_router.get("/analise-horizontal/{company_id}")
async def get_analise_horizontal(
    company_id: str,
    ano: int = Query(default=None),
    current_user: User = Depends(get_current_user)
):
    """
    Retorna dados para análise horizontal (evolução de compras, vendas e impostos).
    Compara ano atual com ano anterior.
    """
    try:
        # Buscar empresa
        company = await db.companies.find_one({"id": company_id}, {"_id": 0})
        if not company:
            raise HTTPException(status_code=404, detail="Empresa não encontrada")
        
        # Definir ano de referência
        ano_atual = ano if ano else datetime.now().year
        ano_anterior = ano_atual - 1
        
        regime_tributario = company.get('regime_tributario', 'lucro_presumido')
        
        # Buscar documentos dos dois anos
        filtro_base = {
            "company_id": company_id,
            **get_filtro_notas_ativas()
        }
        
        # Estrutura para armazenar dados mensais
        dados_mensal = {}
        dados_mensal_anterior = {}
        
        # Processar 12 meses para ambos os anos
        for mes in range(1, 13):
            comp_atual = f"{str(mes).padStart(2, '0') if hasattr(str(mes), 'padStart') else str(mes).zfill(2)}/{ano_atual}"
            comp_anterior = f"{str(mes).zfill(2)}/{ano_anterior}"
            
            # Inicializar estrutura
            for comp, dados_dict in [(comp_atual, dados_mensal), (comp_anterior, dados_mensal_anterior)]:
                dados_dict[comp] = {
                    "compras": 0,
                    "vendas": 0,
                    "impostos_pagar": 0,
                    "credito_acumulado": 0,
                    "icms": 0,
                    "icms_st": 0,
                    "pis": 0,
                    "cofins": 0,
                    "ipi": 0,
                    "iss": 0,
                    "das": 0,
                    "difal": 0
                }
            
            # Buscar documentos do mês atual
            for comp, dados_dict in [(comp_atual, dados_mensal), (comp_anterior, dados_mensal_anterior)]:
                docs = await db.xml_documents.find({
                    **filtro_base,
                    "competencia": comp
                }, {"_id": 0, "xml_content": 0}).to_list(length=None)
                
                total_compras = 0
                total_vendas = 0
                total_icms_debito = 0
                total_icms_credito = 0
                total_icms_st = 0
                total_pis_debito = 0
                total_pis_credito = 0
                total_cofins_debito = 0
                total_cofins_credito = 0
                total_ipi = 0
                total_iss = 0
                
                for doc in docs:
                    tipo = doc.get('tipo', '')
                    valor_total = doc.get('valor_total', 0) or 0
                    produtos = doc.get('produtos', []) or []
                    servicos = doc.get('servicos', []) or []
                    
                    if tipo == 'entrada':
                        total_compras += valor_total
                        # Somar créditos (entradas)
                        for prod in produtos:
                            total_icms_credito += float(prod.get('v_icms', 0) or 0)
                            total_pis_credito += float(prod.get('v_pis', 0) or 0)
                            total_cofins_credito += float(prod.get('v_cofins', 0) or 0)
                            total_icms_st += float(prod.get('v_icms_st', 0) or 0)
                    
                    elif tipo == 'saida':
                        total_vendas += valor_total
                        # Somar débitos (saídas)
                        for prod in produtos:
                            total_icms_debito += float(prod.get('v_icms', 0) or 0)
                            total_pis_debito += float(prod.get('v_pis', 0) or 0)
                            total_cofins_debito += float(prod.get('v_cofins', 0) or 0)
                            total_ipi += float(prod.get('v_ipi', 0) or 0)
                        
                        # ISS de serviços
                        for serv in servicos:
                            total_iss += float(serv.get('valor_iss', 0) or 0)
                
                # Calcular saldos
                saldo_icms = total_icms_debito - total_icms_credito
                saldo_pis = total_pis_debito - total_pis_credito
                saldo_cofins = total_cofins_debito - total_cofins_credito
                
                # Atualizar dados do mês
                dados_dict[comp]["compras"] = round(total_compras, 2)
                dados_dict[comp]["vendas"] = round(total_vendas, 2)
                dados_dict[comp]["icms"] = round(saldo_icms, 2)
                dados_dict[comp]["icms_st"] = round(total_icms_st, 2)
                dados_dict[comp]["pis"] = round(saldo_pis, 2)
                dados_dict[comp]["cofins"] = round(saldo_cofins, 2)
                dados_dict[comp]["ipi"] = round(total_ipi, 2)
                dados_dict[comp]["iss"] = round(total_iss, 2)
                
                # Calcular impostos totais a pagar
                if regime_tributario == 'simples_nacional':
                    # Para Simples, usar DAS (precisa calcular baseado no faturamento)
                    # Por simplicidade, somar ICMS + ISS como estimativa
                    dados_dict[comp]["impostos_pagar"] = round(max(0, saldo_icms) + total_iss, 2)
                    dados_dict[comp]["credito_acumulado"] = round(abs(min(0, saldo_icms)), 2)
                else:
                    # Lucro Presumido/Real
                    impostos_pagar = max(0, saldo_icms) + max(0, saldo_pis) + max(0, saldo_cofins) + total_ipi + total_iss
                    credito_acumulado = abs(min(0, saldo_icms)) + abs(min(0, saldo_pis)) + abs(min(0, saldo_cofins))
                    dados_dict[comp]["impostos_pagar"] = round(impostos_pagar, 2)
                    dados_dict[comp]["credito_acumulado"] = round(credito_acumulado, 2)
        
        # Para empresas do Simples Nacional, enriquecer com dados do PGDAS
        historico_faturamento = {}
        historico_das = {}
        
        if regime_tributario == 'simples_nacional':
            historico_fat_sn = company.get('historico_faturamento_sn', {}) or company.get('historico_faturamento', {})
            historico_das_empresa = company.get('historico_das', {}) or company.get('historico_das_calculado', {})
            
            # Processar histórico de faturamento do PGDAS
            for mes_ano, dados_pgdas in historico_fat_sn.items():
                if isinstance(dados_pgdas, dict):
                    # Normalizar competência para formato MM/YYYY
                    if '-' in mes_ano:
                        partes = mes_ano.split('-')
                        if len(partes) == 2:
                            ano_hist = partes[0]
                            mes_hist = partes[1].zfill(2)
                            comp_normalizada = f"{mes_hist}/{ano_hist}"
                        else:
                            continue
                    else:
                        comp_normalizada = mes_ano
                    
                    faturamento = dados_pgdas.get('receita_pa', 0) or dados_pgdas.get('faturamento', 0) or 0
                    rbt12 = dados_pgdas.get('rbt12', 0) or 0
                    
                    historico_faturamento[comp_normalizada] = {
                        'faturamento': faturamento,
                        'rbt12': rbt12,
                        'fonte': 'pgdas'
                    }
            
            # Processar histórico de DAS
            for mes_ano, dados_das_hist in historico_das_empresa.items():
                if isinstance(dados_das_hist, dict):
                    # Normalizar competência
                    if '-' in mes_ano:
                        partes = mes_ano.split('-')
                        if len(partes) == 2:
                            ano_hist = partes[0]
                            mes_hist = partes[1].zfill(2)
                            comp_normalizada = f"{mes_hist}/{ano_hist}"
                        else:
                            continue
                    else:
                        comp_normalizada = mes_ano
                    
                    # Suportar tanto das_calculado (PGDAS) quanto valor_das (legado)
                    valor_das = dados_das_hist.get('das_calculado', 0) or dados_das_hist.get('valor_das', 0) or 0
                    
                    historico_das[comp_normalizada] = {
                        'das': valor_das,
                        'aliquota_efetiva': dados_das_hist.get('aliquota_efetiva', 0) or 0,
                        'fonte': 'pgdas'
                    }
                    
                    # Atualizar os dados mensais com o DAS do PGDAS se disponível
                    if comp_normalizada in dados_mensal:
                        dados_mensal[comp_normalizada]['das'] = valor_das
                        dados_mensal[comp_normalizada]['impostos_pagar'] = valor_das
                    if comp_normalizada in dados_mensal_anterior:
                        dados_mensal_anterior[comp_normalizada]['das'] = valor_das
                        dados_mensal_anterior[comp_normalizada]['impostos_pagar'] = valor_das
        
        return {
            "company_id": company_id,
            "ano_atual": ano_atual,
            "ano_anterior": ano_anterior,
            "regime_tributario": regime_tributario,
            "mensal": dados_mensal,
            "mensal_ano_anterior": dados_mensal_anterior,
            "historico_faturamento_pgdas": historico_faturamento,
            "historico_das_pgdas": historico_das
        }
        
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Erro na análise horizontal: {str(e)}")
        raise HTTPException(status_code=500, detail=f"Erro ao processar análise horizontal: {str(e)}")


@api_router.post("/analise-horizontal/insights/{company_id}")
async def gerar_insights_analise_horizontal(
    company_id: str,
    dados: dict = Body(...),
    current_user: User = Depends(get_current_user)
):
    """
    Gera insights com IA comparando dados de evolução fiscal.
    """
    try:
        company = await db.companies.find_one({"id": company_id}, {"_id": 0})
        if not company:
            raise HTTPException(status_code=404, detail="Empresa não encontrada")
        
        dados_grafico = dados.get('dados_grafico', [])
        totais = dados.get('totais', {})
        ano_atual = dados.get('ano_atual', datetime.now().year)
        ano_anterior = dados.get('ano_anterior', ano_atual - 1)
        
        # Preparar contexto para IA
        contexto = f"""
        Você é um consultor fiscal especializado. Analise a evolução fiscal da empresa {company.get('razao_social', 'N/A')} ({company.get('regime_tributario', 'lucro_presumido')}).
        
        DADOS COMPARATIVOS {ano_atual} vs {ano_anterior}:
        
        TOTAIS ANO ATUAL ({ano_atual}):
        - Compras: R$ {totais.get('atual', {}).get('compras', 0):,.2f}
        - Vendas: R$ {totais.get('atual', {}).get('vendas', 0):,.2f}
        - Impostos: R$ {totais.get('atual', {}).get('impostos', 0):,.2f}
        
        TOTAIS ANO ANTERIOR ({ano_anterior}):
        - Compras: R$ {totais.get('anterior', {}).get('compras', 0):,.2f}
        - Vendas: R$ {totais.get('anterior', {}).get('vendas', 0):,.2f}
        - Impostos: R$ {totais.get('anterior', {}).get('impostos', 0):,.2f}
        
        EVOLUÇÃO MENSAL:
        """
        
        for mes in dados_grafico[:12]:  # Limitar a 12 meses
            var_vendas = mes.get('var_vendas', 0)
            var_compras = mes.get('var_compras', 0)
            contexto += f"\n{mes.get('mes', 'N/A')}: Vendas R$ {mes.get('vendas', 0):,.2f} ({'+' if var_vendas >= 0 else ''}{var_vendas:.1f}%) | Compras R$ {mes.get('compras', 0):,.2f} ({'+' if var_compras >= 0 else ''}{var_compras:.1f}%)"
        
        contexto += """
        
        Por favor, forneça:
        1. RESUMO EXECUTIVO: Tendência geral da empresa (crescimento, estabilidade ou retração)
        2. PONTOS POSITIVOS: Aspectos favoráveis identificados
        3. PONTOS DE ATENÇÃO: Riscos ou oportunidades de melhoria
        4. RECOMENDAÇÕES: Sugestões práticas para otimização fiscal
        
        Responda de forma clara e objetiva, em português.
        """
        
        # Chamar IA
        from emergentintegrations.llm.chat import LlmChat, UserMessage
        import uuid
        
        llm_key = os.environ.get('EMERGENT_LLM_KEY', '')
        
        if not llm_key:
            return {"analise": "Chave LLM não configurada. Configure EMERGENT_LLM_KEY para habilitar análises com IA."}
        
        try:
            session_id = str(uuid.uuid4())
            chat = LlmChat(
                api_key=llm_key,
                session_id=session_id,
                system_message="Você é um consultor fiscal especializado em análise de evolução tributária de empresas brasileiras. Responda sempre em português."
            ).with_model("gemini", "gemini-2.5-flash")
            
            # send_message é assíncrono, precisa de await
            response = await chat.send_message(user_message=UserMessage(text=contexto))
            
            return {"analise": response}
        except Exception as llm_error:
            logger.error(f"Erro na chamada LLM: {str(llm_error)}")
            return {"analise": f"Erro ao gerar análise com IA: {str(llm_error)}"}
        
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Erro ao gerar insights: {str(e)}")
        return {"analise": f"Não foi possível gerar análise: {str(e)}"}


# ============================================================
# ALERTA DE NOTAS FISCAIS AUSENTES
# ============================================================

@api_router.get("/notas-ausentes/{company_id}")
async def get_notas_ausentes(
    company_id: str,
    competencia: Optional[str] = None,
    current_user: User = Depends(get_current_user)
):
    """
    Detecta notas fiscais de saída ausentes (gaps na sequência numérica).
    Analisa todos os modelos de documentos de saída (NF-e, NFC-e, CT-e, NFS-e).
    Retorna lista de números faltantes por modelo e série.
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Determinar quais modelos a empresa usa com base no tipo de atividade
    tipo_atividade = company.get('tipo_atividade', 'comercio')
    modelos_saida = []
    
    # NF-e (modelo 55) - Todos usam
    modelos_saida.append({'codigo': 'nfe', 'nome': 'NF-e (Modelo 55)', 'modelo_db': ['nfe', '55']})
    
    # NFC-e (modelo 65) - Comércio varejo
    if tipo_atividade in ['comercio', 'mista'] or 'varejo' in company.get('perfis_comerciais', []):
        modelos_saida.append({'codigo': 'nfce', 'nome': 'NFC-e (Modelo 65)', 'modelo_db': ['nfce', '65']})
    
    # CT-e (modelo 57) - Transportadoras
    if tipo_atividade == 'transporte' or 'transportadora' in str(company.get('cnae_principal', '')).lower():
        modelos_saida.append({'codigo': 'cte', 'nome': 'CT-e (Modelo 57)', 'modelo_db': ['cte', '57']})
    
    # NFS-e - Serviços
    if tipo_atividade in ['servicos', 'mista']:
        modelos_saida.append({'codigo': 'nfse', 'nome': 'NFS-e (Serviços)', 'modelo_db': ['nfse']})
    
    # Query base para buscar notas de saída
    base_query = {
        "company_id": company_id,
        "$or": [
            {"tipo": "saida"},
            {"tipo_operacao": "saida"}
        ]
    }
    base_query.update(get_filtro_notas_ativas())
    
    if competencia:
        base_query['competencia'] = competencia
    
    # Analisar cada modelo
    resultado_por_modelo = []
    total_notas_geral = 0
    total_ausentes_geral = 0
    
    for modelo_info in modelos_saida:
        # Query específica para este modelo
        query = base_query.copy()
        query['modelo'] = {"$in": modelo_info['modelo_db']}
        
        # Buscar documentos
        documents = await db.xml_documents.find(
            query, 
            {"_id": 0, "numero_nfe": 1, "serie": 1, "data_emissao": 1, "competencia": 1, "modelo": 1}
        ).to_list(50000)
        
        if not documents:
            resultado_por_modelo.append({
                "modelo": modelo_info['codigo'],
                "modelo_nome": modelo_info['nome'],
                "total_notas": 0,
                "total_ausentes": 0,
                "sequencias": [],
                "notas_ausentes": []
            })
            continue
        
        # Agrupar por série
        notas_por_serie = {}
        for doc in documents:
            doc_serie = doc.get('serie', '1') or '1'
            if doc_serie not in notas_por_serie:
                notas_por_serie[doc_serie] = []
            
            try:
                numero = int(doc.get('numero_nfe', '0'))
                if numero > 0:
                    notas_por_serie[doc_serie].append({
                        'numero': numero,
                        'data_emissao': doc.get('data_emissao', ''),
                        'competencia': doc.get('competencia', '')
                    })
            except (ValueError, TypeError):
                continue
        
        # Detectar gaps em cada série
        notas_ausentes_modelo = []
        sequencias_modelo = []
        
        for serie_num, notas in notas_por_serie.items():
            if not notas:
                continue
                
            # Ordenar por número
            notas_ordenadas = sorted(notas, key=lambda x: x['numero'])
            numeros = [n['numero'] for n in notas_ordenadas]
            
            primeiro = min(numeros)
            ultimo = max(numeros)
            
            sequencias_modelo.append({
                "serie": serie_num,
                "primeiro_numero": primeiro,
                "ultimo_numero": ultimo,
                "total_notas": len(numeros),
                "total_esperado": ultimo - primeiro + 1
            })
            
            # Encontrar gaps
            numeros_set = set(numeros)
            for num in range(primeiro, ultimo + 1):
                if num not in numeros_set:
                    # Encontrar a nota anterior e posterior para contexto
                    nota_anterior = None
                    nota_posterior = None
                    
                    for n in notas_ordenadas:
                        if n['numero'] < num:
                            nota_anterior = n
                        elif n['numero'] > num and nota_posterior is None:
                            nota_posterior = n
                            break
                    
                    notas_ausentes_modelo.append({
                        "numero": num,
                        "serie": serie_num,
                        "nota_anterior": nota_anterior,
                        "nota_posterior": nota_posterior
                    })
        
        # Ordenar por série e número
        notas_ausentes_modelo.sort(key=lambda x: (x['serie'], x['numero']))
        
        total_notas_modelo = len(documents)
        total_ausentes_modelo = len(notas_ausentes_modelo)
        
        total_notas_geral += total_notas_modelo
        total_ausentes_geral += total_ausentes_modelo
        
        resultado_por_modelo.append({
            "modelo": modelo_info['codigo'],
            "modelo_nome": modelo_info['nome'],
            "total_notas": total_notas_modelo,
            "total_ausentes": total_ausentes_modelo,
            "sequencias": sequencias_modelo,
            "notas_ausentes": notas_ausentes_modelo[:500]  # Limitar a 500 por modelo
        })
    
    return {
        "empresa": company.get('nome', company.get('razao_social', 'N/A')),
        "cnpj": company.get('cnpj', 'N/A'),
        "competencia": competencia or "Todas",
        "tipo_atividade": tipo_atividade,
        "total_notas": total_notas_geral,
        "total_ausentes": total_ausentes_geral,
        "modelos_analisados": resultado_por_modelo,
        "gerado_em": datetime.now(timezone.utc).isoformat()
    }


@api_router.get("/notas-ausentes/{company_id}/exportar")
async def exportar_notas_ausentes(
    company_id: str,
    formato: str = "excel",  # excel ou pdf
    competencia: Optional[str] = None,
    current_user: User = Depends(get_current_user)
):
    """
    Exporta relatório de notas fiscais ausentes em Excel ou PDF.
    Analisa todos os modelos de documentos de saída.
    """
    from io import BytesIO
    from fastapi.responses import StreamingResponse
    
    # Obter dados
    dados = await get_notas_ausentes(company_id, competencia, current_user)
    
    if formato.lower() == "excel":
        # Exportar para Excel
        from openpyxl import Workbook
        from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
        
        wb = Workbook()
        ws = wb.active
        ws.title = "Resumo Geral"
        
        # Estilos
        header_font = Font(bold=True, color="FFFFFF")
        header_fill = PatternFill(start_color="C8A951", end_color="C8A951", fill_type="solid")
        red_fill = PatternFill(start_color="FF6B6B", end_color="FF6B6B", fill_type="solid")
        thin_border = Border(
            left=Side(style='thin'),
            right=Side(style='thin'),
            top=Side(style='thin'),
            bottom=Side(style='thin')
        )
        
        # Cabeçalho do relatório
        ws.merge_cells('A1:G1')
        ws['A1'] = f"RELATÓRIO DE NOTAS FISCAIS AUSENTES - TODOS OS MODELOS"
        ws['A1'].font = Font(bold=True, size=14)
        ws['A1'].alignment = Alignment(horizontal='center')
        
        ws['A3'] = f"Empresa: {dados['empresa']}"
        ws['A4'] = f"CNPJ: {dados['cnpj']}"
        ws['A5'] = f"Competência: {dados['competencia']}"
        ws['A6'] = f"Tipo de Atividade: {dados.get('tipo_atividade', 'N/A')}"
        ws['A7'] = f"Total Geral de Notas Emitidas: {dados['total_notas']}"
        ws['A8'] = f"Total Geral de Notas Ausentes: {dados['total_ausentes']}"
        ws['A9'] = f"Gerado em: {dados.get('gerado_em', '')[:19].replace('T', ' ')}"
        
        # Resumo por Modelo
        row = 11
        ws[f'A{row}'] = "RESUMO POR MODELO DE DOCUMENTO"
        ws[f'A{row}'].font = Font(bold=True, size=12)
        row += 1
        
        headers_modelo = ['Modelo', 'Total Emitidas', 'Total Ausentes', 'Status']
        for col, header in enumerate(headers_modelo, 1):
            cell = ws.cell(row=row, column=col, value=header)
            cell.font = header_font
            cell.fill = header_fill
            cell.border = thin_border
            cell.alignment = Alignment(horizontal='center')
        
        row += 1
        for modelo in dados.get('modelos_analisados', []):
            ws.cell(row=row, column=1, value=modelo['modelo_nome']).border = thin_border
            ws.cell(row=row, column=2, value=modelo['total_notas']).border = thin_border
            cell_ausentes = ws.cell(row=row, column=3, value=modelo['total_ausentes'])
            cell_ausentes.border = thin_border
            if modelo['total_ausentes'] > 0:
                cell_ausentes.fill = red_fill
                cell_ausentes.font = Font(bold=True, color="FFFFFF")
            status = "OK" if modelo['total_ausentes'] == 0 else "GAPS DETECTADOS"
            ws.cell(row=row, column=4, value=status).border = thin_border
            row += 1
        
        # Criar uma aba para cada modelo com dados
        for modelo in dados.get('modelos_analisados', []):
            if modelo['total_notas'] == 0:
                continue
            
            ws_modelo = wb.create_sheet(title=modelo['modelo'][:31])
            
            # Título
            ws_modelo.merge_cells('A1:G1')
            ws_modelo['A1'] = f"DETALHAMENTO - {modelo['modelo_nome']}"
            ws_modelo['A1'].font = Font(bold=True, size=14)
            ws_modelo['A1'].alignment = Alignment(horizontal='center')
            
            ws_modelo['A3'] = f"Total Emitidas: {modelo['total_notas']}"
            ws_modelo['A4'] = f"Total Ausentes: {modelo['total_ausentes']}"
            
            # Resumo por série
            row = 6
            ws_modelo[f'A{row}'] = "RESUMO POR SÉRIE"
            ws_modelo[f'A{row}'].font = Font(bold=True, size=12)
            row += 1
            
            headers_serie = ['Série', 'Primeiro Nº', 'Último Nº', 'Emitidas', 'Esperado', 'Ausentes']
            for col, header in enumerate(headers_serie, 1):
                cell = ws_modelo.cell(row=row, column=col, value=header)
                cell.font = header_font
                cell.fill = header_fill
                cell.border = thin_border
                cell.alignment = Alignment(horizontal='center')
            
            row += 1
            for seq in modelo.get('sequencias', []):
                ausentes = seq['total_esperado'] - seq['total_notas']
                ws_modelo.cell(row=row, column=1, value=f"Série {seq['serie']}").border = thin_border
                ws_modelo.cell(row=row, column=2, value=seq['primeiro_numero']).border = thin_border
                ws_modelo.cell(row=row, column=3, value=seq['ultimo_numero']).border = thin_border
                ws_modelo.cell(row=row, column=4, value=seq['total_notas']).border = thin_border
                ws_modelo.cell(row=row, column=5, value=seq['total_esperado']).border = thin_border
                ws_modelo.cell(row=row, column=6, value=ausentes).border = thin_border
                row += 1
            
            # Detalhamento das notas ausentes
            if modelo.get('notas_ausentes'):
                row += 2
                ws_modelo[f'A{row}'] = "NOTAS AUSENTES"
                ws_modelo[f'A{row}'].font = Font(bold=True, size=12)
                row += 1
                
                headers_detalhe = ['Nº Ausente', 'Série', 'Nº Anterior', 'Data Anterior', 'Nº Posterior', 'Data Posterior']
                for col, header in enumerate(headers_detalhe, 1):
                    cell = ws_modelo.cell(row=row, column=col, value=header)
                    cell.font = header_font
                    cell.fill = header_fill
                    cell.border = thin_border
                    cell.alignment = Alignment(horizontal='center')
                
                row += 1
                for nota in modelo['notas_ausentes']:
                    cell = ws_modelo.cell(row=row, column=1, value=nota['numero'])
                    cell.border = thin_border
                    cell.fill = red_fill
                    cell.font = Font(bold=True, color="FFFFFF")
                    ws_modelo.cell(row=row, column=2, value=nota['serie']).border = thin_border
                    
                    if nota.get('nota_anterior'):
                        ws_modelo.cell(row=row, column=3, value=nota['nota_anterior']['numero']).border = thin_border
                        data_ant = nota['nota_anterior'].get('data_emissao', '')[:10]
                        ws_modelo.cell(row=row, column=4, value=data_ant).border = thin_border
                    else:
                        ws_modelo.cell(row=row, column=3, value='-').border = thin_border
                        ws_modelo.cell(row=row, column=4, value='-').border = thin_border
                    
                    if nota.get('nota_posterior'):
                        ws_modelo.cell(row=row, column=5, value=nota['nota_posterior']['numero']).border = thin_border
                        data_post = nota['nota_posterior'].get('data_emissao', '')[:10]
                        ws_modelo.cell(row=row, column=6, value=data_post).border = thin_border
                    else:
                        ws_modelo.cell(row=row, column=5, value='-').border = thin_border
                        ws_modelo.cell(row=row, column=6, value='-').border = thin_border
                    
                    row += 1
            
            # Ajustar largura das colunas
            for col in ['A', 'B', 'C', 'D', 'E', 'F']:
                ws_modelo.column_dimensions[col].width = 15
        
        # Ajustar largura das colunas da aba principal
        ws.column_dimensions['A'].width = 25
        ws.column_dimensions['B'].width = 15
        ws.column_dimensions['C'].width = 15
        ws.column_dimensions['D'].width = 20
        
        # Salvar em memória
        output = BytesIO()
        wb.save(output)
        output.seek(0)
        
        filename = f"notas_ausentes_{dados['cnpj'].replace('.', '').replace('/', '').replace('-', '')}_{(competencia or 'todas').replace('/', '_')}.xlsx"
        
        return StreamingResponse(
            output,
            media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            headers={"Content-Disposition": f"attachment; filename={filename}"}
        )
    
    elif formato.lower() == "pdf":
        # Exportar para PDF
        from reportlab.lib.pagesizes import A4
        from reportlab.lib import colors
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak
        from reportlab.lib.units import cm
        
        output = BytesIO()
        doc = SimpleDocTemplate(output, pagesize=A4, rightMargin=1.5*cm, leftMargin=1.5*cm, topMargin=1.5*cm, bottomMargin=1.5*cm)
        
        styles = getSampleStyleSheet()
        title_style = ParagraphStyle('Title', parent=styles['Heading1'], fontSize=16, alignment=1, spaceAfter=20)
        subtitle_style = ParagraphStyle('Subtitle', parent=styles['Heading2'], fontSize=12, spaceAfter=10)
        modelo_style = ParagraphStyle('Modelo', parent=styles['Heading2'], fontSize=14, spaceAfter=10, spaceBefore=20)
        
        elements = []
        
        # Título
        elements.append(Paragraph("RELATÓRIO DE NOTAS FISCAIS AUSENTES", title_style))
        elements.append(Paragraph("ANÁLISE DE TODOS OS MODELOS DE DOCUMENTOS", subtitle_style))
        elements.append(Spacer(1, 10))
        
        # Informações da empresa
        info_data = [
            [f"Empresa: {dados['empresa']}", f"CNPJ: {dados['cnpj']}"],
            [f"Competência: {dados['competencia']}", f"Tipo Atividade: {dados.get('tipo_atividade', 'N/A')}"],
            [f"Total Geral Emitidas: {dados['total_notas']}", f"Total Geral Ausentes: {dados['total_ausentes']}"],
            [f"Gerado em: {dados.get('gerado_em', '')[:19].replace('T', ' ')}", ""]
        ]
        
        info_table = Table(info_data, colWidths=[9*cm, 9*cm])
        info_table.setStyle(TableStyle([
            ('FONTSIZE', (0, 0), (-1, -1), 10),
            ('BOTTOMPADDING', (0, 0), (-1, -1), 5),
        ]))
        elements.append(info_table)
        elements.append(Spacer(1, 20))
        
        # Resumo por Modelo
        elements.append(Paragraph("RESUMO POR MODELO", subtitle_style))
        
        resumo_modelo_data = [['Modelo', 'Emitidas', 'Ausentes', 'Status']]
        for modelo in dados.get('modelos_analisados', []):
            status = "OK" if modelo['total_ausentes'] == 0 else "GAPS"
            resumo_modelo_data.append([
                modelo['modelo_nome'],
                str(modelo['total_notas']),
                str(modelo['total_ausentes']),
                status
            ])
        
        resumo_modelo_table = Table(resumo_modelo_data, colWidths=[7*cm, 3*cm, 3*cm, 3*cm])
        resumo_modelo_table.setStyle(TableStyle([
            ('BACKGROUND', (0, 0), (-1, 0), colors.Color(0.78, 0.66, 0.32)),
            ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
            ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
            ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
            ('FONTSIZE', (0, 0), (-1, -1), 9),
            ('BOTTOMPADDING', (0, 0), (-1, 0), 8),
            ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
        ]))
        elements.append(resumo_modelo_table)
        
        # Detalhamento por modelo
        for modelo in dados.get('modelos_analisados', []):
            if modelo['total_ausentes'] == 0:
                continue
            
            elements.append(PageBreak())
            elements.append(Paragraph(f"DETALHAMENTO: {modelo['modelo_nome']}", modelo_style))
            
            # Resumo por série do modelo
            elements.append(Paragraph("Resumo por Série", subtitle_style))
            
            serie_data = [['Série', 'Primeiro Nº', 'Último Nº', 'Emitidas', 'Esperado', 'Ausentes']]
            for seq in modelo.get('sequencias', []):
                ausentes = seq['total_esperado'] - seq['total_notas']
                serie_data.append([
                    f"Série {seq['serie']}",
                    str(seq['primeiro_numero']),
                    str(seq['ultimo_numero']),
                    str(seq['total_notas']),
                    str(seq['total_esperado']),
                    str(ausentes)
                ])
            
            serie_table = Table(serie_data, colWidths=[2.5*cm, 2.5*cm, 2.5*cm, 2.5*cm, 2.5*cm, 2.5*cm])
            serie_table.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (-1, 0), colors.Color(0.78, 0.66, 0.32)),
                ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
                ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                ('FONTSIZE', (0, 0), (-1, -1), 8),
                ('BOTTOMPADDING', (0, 0), (-1, 0), 6),
                ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
            ]))
            elements.append(serie_table)
            elements.append(Spacer(1, 15))
            
            # Notas ausentes
            if modelo.get('notas_ausentes'):
                elements.append(Paragraph("Notas Ausentes", subtitle_style))
                
                detalhe_data = [['Nº Ausente', 'Série', 'Nº Anterior', 'Data Ant.', 'Nº Posterior', 'Data Post.']]
                for nota in modelo['notas_ausentes'][:100]:
                    row = [
                        str(nota['numero']),
                        nota['serie'],
                        str(nota['nota_anterior']['numero']) if nota.get('nota_anterior') else '-',
                        nota['nota_anterior'].get('data_emissao', '')[:10] if nota.get('nota_anterior') else '-',
                        str(nota['nota_posterior']['numero']) if nota.get('nota_posterior') else '-',
                        nota['nota_posterior'].get('data_emissao', '')[:10] if nota.get('nota_posterior') else '-'
                    ]
                    detalhe_data.append(row)
                
                if len(modelo['notas_ausentes']) > 100:
                    detalhe_data.append(['...', f"+ {len(modelo['notas_ausentes']) - 100}", '', '', '', ''])
                
                detalhe_table = Table(detalhe_data, colWidths=[2.5*cm, 2*cm, 2.5*cm, 2.5*cm, 2.5*cm, 2.5*cm])
                detalhe_table.setStyle(TableStyle([
                    ('BACKGROUND', (0, 0), (-1, 0), colors.Color(0.78, 0.66, 0.32)),
                    ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
                    ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                    ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                    ('FONTSIZE', (0, 0), (-1, -1), 8),
                    ('BOTTOMPADDING', (0, 0), (-1, 0), 6),
                    ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
                    ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, colors.Color(0.95, 0.95, 0.95)]),
                ]))
                elements.append(detalhe_table)
        
        doc.build(elements)
        output.seek(0)
        
        filename = f"notas_ausentes_{dados['cnpj'].replace('.', '').replace('/', '').replace('-', '')}_{(competencia or 'todas').replace('/', '_')}.pdf"
        
        return StreamingResponse(
            output,
            media_type="application/pdf",
            headers={"Content-Disposition": f"attachment; filename={filename}"}
        )
    
    else:
        raise HTTPException(status_code=400, detail="Formato inválido. Use 'excel' ou 'pdf'")


# ============================================================
# EXPORTAR DOCUMENTOS POR CATEGORIA (TIPO DE DOCUMENTO)
# ============================================================

@api_router.get("/xml/exportar-categoria/{company_id}")
async def exportar_documentos_categoria(
    company_id: str,
    competencia: str = Query(..., description="Competência no formato MM/YYYY"),
    operacao: str = Query(..., description="Tipo de operação: 'entrada' ou 'saida'"),
    tipo_doc: str = Query(..., description="Tipo de documento: 'nfe', 'nfce', 'cte', 'nfse', 'outros'"),
    formato: str = Query(..., description="Formato de exportação: 'excel' ou 'pdf'"),
    current_user: User = Depends(get_current_user)
):
    """
    Exporta todos os documentos de uma categoria específica para Excel ou PDF.
    Permite exportar por tipo de documento (NF-e, NFC-e, CT-e, NFS-e, Outros).
    """
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    from reportlab.lib.pagesizes import A4, landscape
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib import colors
    from reportlab.lib.units import cm
    
    # Buscar empresa
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    # Verificar acesso
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Mapear tipo de documento para modelos no banco
    modelos_map = {
        'nfe': ['nfe', 'NFe', 'NF-e', '55'],
        'nfce': ['nfce', 'NFCe', 'NFC-e', '65'],
        'cte': ['cte', 'CTe', 'CT-e', '57'],
        'nfse': ['nfse', 'NFSe', 'NFS-e'],
        'outros': []  # Documentos que não são dos modelos conhecidos
    }
    
    # Construir query
    query = {
        "company_id": company_id,
        "competencia": competencia,
        "tipo": operacao
    }
    query.update(get_filtro_notas_ativas())
    
    # Filtrar por modelo
    modelos_conhecidos = modelos_map['nfe'] + modelos_map['nfce'] + modelos_map['cte'] + modelos_map['nfse']
    
    if tipo_doc == 'outros':
        query["modelo"] = {"$nin": modelos_conhecidos}
    else:
        query["modelo"] = {"$in": modelos_map.get(tipo_doc, [])}
    
    # Buscar documentos
    documentos = await db.xml_documents.find(query, {"_id": 0, "xml_content": 0}).to_list(100000)
    
    if not documentos:
        raise HTTPException(status_code=404, detail="Nenhum documento encontrado para os filtros informados")
    
    # Mapear nomes para display
    tipo_doc_nome = {
        'nfe': 'NF-e',
        'nfce': 'NFC-e',
        'cte': 'CT-e',
        'nfse': 'NFS-e',
        'outros': 'Outros Documentos'
    }.get(tipo_doc, tipo_doc.upper())
    
    operacao_nome = 'Entradas' if operacao == 'entrada' else 'Saídas'
    
    if formato == 'excel':
        wb = Workbook()
        ws = wb.active
        ws.title = f"{tipo_doc_nome} - {operacao_nome}"
        
        # Estilos
        header_fill = PatternFill(start_color="C8A951", end_color="C8A951", fill_type="solid")
        header_font = Font(bold=True, color="FFFFFF")
        total_fill = PatternFill(start_color="FEF3C7", end_color="FEF3C7", fill_type="solid")
        total_font = Font(bold=True)
        thin_border = Border(
            left=Side(style='thin'),
            right=Side(style='thin'),
            top=Side(style='thin'),
            bottom=Side(style='thin')
        )
        
        # Cabeçalho
        ws['A1'] = f"RELATÓRIO DE {tipo_doc_nome.upper()} - {operacao_nome.upper()}"
        ws['A1'].font = Font(bold=True, size=14)
        ws['A2'] = f"Empresa: {company.get('razao_social', '')}"
        ws['A3'] = f"CNPJ: {company.get('cnpj', '')} | Competência: {competencia}"
        ws['A4'] = f"Total de Documentos: {len(documentos)}"
        
        # Tabela de documentos
        row = 6
        headers = ['Número', 'Série', 'Data Emissão', 'Emitente/Destinatário', 'CNPJ', 'UF', 'Valor Total', 'BC ICMS', 'ICMS', 'ICMS ST', 'PIS', 'COFINS']
        for col, h in enumerate(headers, 1):
            cell = ws.cell(row=row, column=col, value=h)
            cell.fill = header_fill
            cell.font = header_font
            cell.border = thin_border
            cell.alignment = Alignment(horizontal='center')
        
        total_valor = 0
        total_bc_icms = 0
        total_icms = 0
        total_icms_st = 0
        total_pis = 0
        total_cofins = 0
        
        for doc in documentos:
            row += 1
            valor = float(doc.get('valor_total', 0) or 0)
            
            # Calcular BC ICMS e ICMS a partir dos produtos
            produtos = doc.get('produtos', [])
            bc_icms = sum(float(p.get('v_bc_icms', 0) or p.get('v_bc', 0) or p.get('bc_icms', 0) or 0) for p in produtos)
            icms = sum(float(p.get('v_icms', 0) or p.get('valor_icms', 0) or 0) for p in produtos)
            icms_st = sum(float(p.get('v_icms_st', 0) or p.get('valor_icms_st', 0) or 0) for p in produtos)
            pis = sum(float(p.get('v_pis', 0) or p.get('valor_pis', 0) or 0) for p in produtos)
            cofins = sum(float(p.get('v_cofins', 0) or p.get('valor_cofins', 0) or 0) for p in produtos)
            
            # Fallback para campos no documento se produtos não tiverem valores
            if bc_icms == 0:
                bc_icms = float(doc.get('bc_icms_total', 0) or doc.get('total_bc_icms', 0) or 0)
            if icms == 0:
                icms = float(doc.get('icms_total', 0) or doc.get('total_icms', 0) or 0)
            if icms_st == 0:
                icms_st = float(doc.get('total_icms_st', 0) or 0)
            if pis == 0:
                pis = float(doc.get('total_pis', 0) or 0)
            if cofins == 0:
                cofins = float(doc.get('total_cofins', 0) or 0)
            
            total_valor += valor
            total_bc_icms += bc_icms
            total_icms += icms
            total_icms_st += icms_st
            total_pis += pis
            total_cofins += cofins
            
            # Emitente ou destinatário
            if operacao == 'entrada':
                nome = doc.get('emitente', {}).get('razao_social', '') if isinstance(doc.get('emitente'), dict) else doc.get('emitente', '')
                cnpj = doc.get('emitente', {}).get('cnpj', '') if isinstance(doc.get('emitente'), dict) else ''
            else:
                nome = doc.get('destinatario', {}).get('razao_social', '') if isinstance(doc.get('destinatario'), dict) else doc.get('destinatario', '')
                cnpj = doc.get('destinatario', {}).get('cnpj', '') if isinstance(doc.get('destinatario'), dict) else ''
            
            if not nome:
                nome = doc.get('emitente_nome', '') or doc.get('destinatario_nome', '') or '-'
            if not cnpj:
                cnpj = doc.get('emitente_cnpj', '') or doc.get('destinatario_cnpj', '') or '-'
            
            ws.cell(row=row, column=1, value=doc.get('numero_nfe', '')).border = thin_border
            ws.cell(row=row, column=2, value=doc.get('serie', '')).border = thin_border
            
            data_emissao = doc.get('data_emissao', '')
            if data_emissao:
                try:
                    if isinstance(data_emissao, str):
                        data_emissao = data_emissao[:10]
                except:
                    pass
            ws.cell(row=row, column=3, value=data_emissao).border = thin_border
            
            ws.cell(row=row, column=4, value=nome[:40] if nome else '-').border = thin_border
            ws.cell(row=row, column=5, value=cnpj).border = thin_border
            ws.cell(row=row, column=6, value=doc.get('uf_emitente', '') or doc.get('uf', '')).border = thin_border
            
            ws.cell(row=row, column=7, value=valor).border = thin_border
            ws.cell(row=row, column=7).number_format = '#,##0.00'
            ws.cell(row=row, column=8, value=bc_icms).border = thin_border
            ws.cell(row=row, column=8).number_format = '#,##0.00'
            ws.cell(row=row, column=9, value=icms).border = thin_border
            ws.cell(row=row, column=9).number_format = '#,##0.00'
            ws.cell(row=row, column=10, value=icms_st).border = thin_border
            ws.cell(row=row, column=10).number_format = '#,##0.00'
            ws.cell(row=row, column=11, value=pis).border = thin_border
            ws.cell(row=row, column=11).number_format = '#,##0.00'
            ws.cell(row=row, column=12, value=cofins).border = thin_border
            ws.cell(row=row, column=12).number_format = '#,##0.00'
        
        # Total
        row += 1
        ws.cell(row=row, column=1, value="TOTAL").font = total_font
        ws.cell(row=row, column=1).fill = total_fill
        for col in range(2, 8):
            ws.cell(row=row, column=col).fill = total_fill
        ws.cell(row=row, column=7, value=total_valor).font = total_font
        ws.cell(row=row, column=7).fill = total_fill
        ws.cell(row=row, column=7).number_format = '#,##0.00'
        ws.cell(row=row, column=8, value=total_bc_icms).font = total_font
        ws.cell(row=row, column=8).fill = total_fill
        ws.cell(row=row, column=8).number_format = '#,##0.00'
        ws.cell(row=row, column=9, value=total_icms).font = total_font
        ws.cell(row=row, column=9).fill = total_fill
        ws.cell(row=row, column=9).number_format = '#,##0.00'
        ws.cell(row=row, column=10, value=total_icms_st).font = total_font
        ws.cell(row=row, column=10).fill = total_fill
        ws.cell(row=row, column=10).number_format = '#,##0.00'
        ws.cell(row=row, column=11, value=total_pis).font = total_font
        ws.cell(row=row, column=11).fill = total_fill
        ws.cell(row=row, column=11).number_format = '#,##0.00'
        ws.cell(row=row, column=12, value=total_cofins).font = total_font
        ws.cell(row=row, column=12).fill = total_fill
        ws.cell(row=row, column=12).number_format = '#,##0.00'
        
        # Ajustar largura das colunas
        ws.column_dimensions['A'].width = 12
        ws.column_dimensions['B'].width = 8
        ws.column_dimensions['C'].width = 12
        ws.column_dimensions['D'].width = 40
        ws.column_dimensions['E'].width = 18
        ws.column_dimensions['F'].width = 6
        ws.column_dimensions['G'].width = 15
        ws.column_dimensions['H'].width = 14
        ws.column_dimensions['I'].width = 12
        ws.column_dimensions['J'].width = 12
        ws.column_dimensions['K'].width = 12
        ws.column_dimensions['L'].width = 12
        
        # Salvar e retornar
        output = io.BytesIO()
        wb.save(output)
        output.seek(0)
        
        cnpj_limpo = company.get('cnpj', '').replace('.', '').replace('/', '').replace('-', '')
        filename = f"{tipo_doc}_{operacao}_{cnpj_limpo}_{competencia.replace('/', '_')}.xlsx"
        
        return StreamingResponse(
            output,
            media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            headers={"Content-Disposition": f"attachment; filename={filename}"}
        )
    
    elif formato == 'pdf':
        output = io.BytesIO()
        doc_pdf = SimpleDocTemplate(output, pagesize=landscape(A4), leftMargin=1*cm, rightMargin=1*cm, topMargin=1*cm, bottomMargin=1*cm)
        
        styles = getSampleStyleSheet()
        title_style = ParagraphStyle('Title', parent=styles['Heading1'], fontSize=14, alignment=1)
        subtitle_style = ParagraphStyle('Subtitle', parent=styles['Normal'], fontSize=10, alignment=1)
        
        elements = []
        
        # Título
        elements.append(Paragraph(f"RELATÓRIO DE {tipo_doc_nome.upper()} - {operacao_nome.upper()}", title_style))
        elements.append(Spacer(1, 10))
        elements.append(Paragraph(f"Empresa: {company.get('razao_social', '')} | CNPJ: {company.get('cnpj', '')}", subtitle_style))
        elements.append(Paragraph(f"Competência: {competencia} | Total: {len(documentos)} documentos", subtitle_style))
        elements.append(Spacer(1, 20))
        
        # Tabela
        headers = ['Número', 'Série', 'Data', 'Emitente/Dest.', 'CNPJ', 'Valor Total', 'BC ICMS', 'ICMS']
        data = [headers]
        
        total_valor = 0
        total_bc_icms = 0
        total_icms = 0
        
        for doc in documentos:
            valor = float(doc.get('valor_total', 0) or 0)
            
            # Calcular BC ICMS e ICMS a partir dos produtos
            produtos = doc.get('produtos', [])
            bc_icms = sum(float(p.get('v_bc_icms', 0) or p.get('v_bc', 0) or p.get('bc_icms', 0) or 0) for p in produtos)
            icms = sum(float(p.get('v_icms', 0) or p.get('valor_icms', 0) or 0) for p in produtos)
            
            # Fallback para campos no documento se produtos não tiverem valores
            if bc_icms == 0:
                bc_icms = float(doc.get('bc_icms_total', 0) or doc.get('total_bc_icms', 0) or 0)
            if icms == 0:
                icms = float(doc.get('icms_total', 0) or doc.get('total_icms', 0) or 0)
            
            total_valor += valor
            total_bc_icms += bc_icms
            total_icms += icms
            
            if operacao == 'entrada':
                nome = doc.get('emitente', {}).get('razao_social', '') if isinstance(doc.get('emitente'), dict) else doc.get('emitente', '')
                cnpj = doc.get('emitente', {}).get('cnpj', '') if isinstance(doc.get('emitente'), dict) else ''
            else:
                nome = doc.get('destinatario', {}).get('razao_social', '') if isinstance(doc.get('destinatario'), dict) else doc.get('destinatario', '')
                cnpj = doc.get('destinatario', {}).get('cnpj', '') if isinstance(doc.get('destinatario'), dict) else ''
            
            if not nome:
                nome = doc.get('emitente_nome', '') or doc.get('destinatario_nome', '') or '-'
            if not cnpj:
                cnpj = doc.get('emitente_cnpj', '') or doc.get('destinatario_cnpj', '') or '-'
            
            data_emissao = doc.get('data_emissao', '')
            if data_emissao and isinstance(data_emissao, str):
                data_emissao = data_emissao[:10]
            
            data.append([
                str(doc.get('numero_nfe', '')),
                str(doc.get('serie', '')),
                str(data_emissao or '-'),
                str(nome)[:25] if nome else '-',
                str(cnpj),
                f"R$ {valor:,.2f}",
                f"R$ {bc_icms:,.2f}",
                f"R$ {icms:,.2f}"
            ])
        
        # Total
        data.append(['TOTAL', '', '', '', '', f"R$ {total_valor:,.2f}", f"R$ {total_bc_icms:,.2f}", f"R$ {total_icms:,.2f}"])
        
        table = Table(data, colWidths=[50, 35, 60, 130, 90, 70, 70, 70])
        table.setStyle(TableStyle([
            ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#C8A951')),
            ('TEXTCOLOR', (0, 0), (-1, 0), colors.whitesmoke),
            ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
            ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
            ('FONTSIZE', (0, 0), (-1, 0), 9),
            ('FONTSIZE', (0, 1), (-1, -1), 8),
            ('BOTTOMPADDING', (0, 0), (-1, 0), 8),
            ('TOPPADDING', (0, 0), (-1, 0), 8),
            ('BACKGROUND', (0, -1), (-1, -1), colors.HexColor('#FEF3C7')),
            ('FONTNAME', (0, -1), (-1, -1), 'Helvetica-Bold'),
            ('GRID', (0, 0), (-1, -1), 0.5, colors.grey),
            ('ROWBACKGROUNDS', (0, 1), (-1, -2), [colors.whitesmoke, colors.white]),
        ]))
        
        elements.append(table)
        doc_pdf.build(elements)
        
        output.seek(0)
        cnpj_limpo = company.get('cnpj', '').replace('.', '').replace('/', '').replace('-', '')
        filename = f"{tipo_doc}_{operacao}_{cnpj_limpo}_{competencia.replace('/', '_')}.pdf"
        
        return StreamingResponse(
            output,
            media_type="application/pdf",
            headers={"Content-Disposition": f"attachment; filename={filename}"}
        )
    
    else:
        raise HTTPException(status_code=400, detail="Formato inválido. Use 'excel' ou 'pdf'")


# ============================================================
# IMPORTAÇÃO DE ARQUIVOS PARA DADOS MANUAIS
# ============================================================

class DadosManuaisItem(BaseModel):
    compras: float = 0
    vendas: float = 0
    icms: float = 0
    pis: float = 0
    cofins: float = 0
    iss: float = 0
    das: float = 0

class DadosManuaisRequest(BaseModel):
    dados: dict  # {competencia: DadosManuaisItem}


@api_router.post("/analise-horizontal/salvar-dados-manuais/{company_id}")
async def salvar_dados_manuais(
    company_id: str,
    request: DadosManuaisRequest,
    current_user: User = Depends(get_current_user)
):
    """
    Salva dados manuais de períodos anteriores no MongoDB.
    Esses dados são usados no RET para empresas Lucro Presumido/Real.
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    # Estrutura para salvar
    dados_formatados = {}
    for competencia, valores in request.dados.items():
        if isinstance(valores, dict):
            dados_formatados[competencia] = {
                "compras": float(valores.get("compras", 0) or 0),
                "vendas": float(valores.get("vendas", 0) or 0),
                "icms": float(valores.get("icms", 0) or 0),
                "pis": float(valores.get("pis", 0) or 0),
                "cofins": float(valores.get("cofins", 0) or 0),
                "iss": float(valores.get("iss", 0) or 0),
                "das": float(valores.get("das", 0) or 0),
                "updated_at": datetime.utcnow().isoformat()
            }
    
    # Salvar na empresa
    await db.companies.update_one(
        {"id": company_id},
        {"$set": {"dados_manuais_historico": dados_formatados}}
    )
    
    return {
        "success": True,
        "message": f"Dados de {len(dados_formatados)} competências salvos com sucesso",
        "competencias": list(dados_formatados.keys())
    }


@api_router.get("/analise-horizontal/dados-manuais/{company_id}")
async def get_dados_manuais(
    company_id: str,
    current_user: User = Depends(get_current_user)
):
    """
    Retorna dados manuais salvos para uma empresa.
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0, "dados_manuais_historico": 1})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    return {
        "dados": company.get("dados_manuais_historico", {})
    }


@api_router.post("/analise-horizontal/importar-arquivo/{company_id}")
async def importar_arquivo_dados_manuais(
    company_id: str,
    ano: int = Query(..., description="Ano para importar os dados"),
    file: UploadFile = File(...),
    current_user: User = Depends(get_current_user)
):
    """
    Importa dados de Excel, Word ou PDF para preencher movimento de períodos anteriores.
    Usa IA para identificar valores de entradas, saídas e impostos mês a mês.
    """
    import pdfplumber
    from docx import Document as DocxDocument
    from openpyxl import load_workbook
    import io
    import re
    
    # Verificar empresa
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    # Identificar tipo de arquivo
    filename = file.filename.lower()
    content = await file.read()
    
    extracted_text = ""
    extracted_data = []
    
    try:
        if filename.endswith(('.xlsx', '.xls')):
            # Processar Excel
            wb = load_workbook(io.BytesIO(content), data_only=True)
            for sheet in wb.worksheets:
                for row in sheet.iter_rows():
                    row_data = []
                    for cell in row:
                        if cell.value is not None:
                            row_data.append(str(cell.value))
                    if row_data:
                        extracted_text += " | ".join(row_data) + "\n"
                        extracted_data.append(row_data)
        
        elif filename.endswith(('.doc', '.docx')):
            # Processar Word
            doc = DocxDocument(io.BytesIO(content))
            for para in doc.paragraphs:
                if para.text.strip():
                    extracted_text += para.text + "\n"
            # Processar tabelas
            for table in doc.tables:
                for row in table.rows:
                    row_data = [cell.text.strip() for cell in row.cells if cell.text.strip()]
                    if row_data:
                        extracted_text += " | ".join(row_data) + "\n"
                        extracted_data.append(row_data)
        
        elif filename.endswith('.pdf'):
            # Processar PDF
            with pdfplumber.open(io.BytesIO(content)) as pdf:
                for page in pdf.pages:
                    text = page.extract_text()
                    if text:
                        extracted_text += text + "\n"
                    # Extrair tabelas
                    tables = page.extract_tables()
                    for table in tables:
                        for row in table:
                            if row:
                                row_data = [str(cell).strip() for cell in row if cell]
                                if row_data:
                                    extracted_data.append(row_data)
        else:
            raise HTTPException(status_code=400, detail="Formato não suportado. Use Excel (.xlsx), Word (.docx) ou PDF (.pdf)")
    
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Erro ao processar arquivo: {str(e)}")
    
    if not extracted_text and not extracted_data:
        raise HTTPException(status_code=400, detail="Não foi possível extrair dados do arquivo")
    
    # Usar IA para interpretar os dados
    meses_pt = ["janeiro", "fevereiro", "março", "abril", "maio", "junho", 
                "julho", "agosto", "setembro", "outubro", "novembro", "dezembro"]
    meses_abrev = ["jan", "fev", "mar", "abr", "mai", "jun", "jul", "ago", "set", "out", "nov", "dez"]
    
    prompt = f"""Analise o seguinte conteúdo extraído de um documento fiscal/contábil e extraia os dados mensais.

CONTEÚDO DO ARQUIVO:
{extracted_text[:8000]}

INSTRUÇÕES:
1. Identifique valores mensais de: compras (entradas), vendas (saídas/faturamento), ICMS, PIS, COFINS, ISS, DAS (Simples Nacional)
2. Os meses podem estar em formato: "01", "janeiro", "jan", etc.
3. Valores podem estar em formato: "1.234,56" ou "1234.56" ou "R$ 1.234,56"
4. Retorne APENAS um JSON válido com a estrutura abaixo, sem explicações adicionais:

{{
  "dados": [
    {{"mes": 1, "compras": 0, "vendas": 0, "icms": 0, "pis": 0, "cofins": 0, "iss": 0, "das": 0}},
    {{"mes": 2, "compras": 0, "vendas": 0, "icms": 0, "pis": 0, "cofins": 0, "iss": 0, "das": 0}},
    ...
  ],
  "ano_identificado": {ano},
  "observacoes": "descrição breve do que foi encontrado"
}}

Se não encontrar dados para um mês, deixe como 0. Retorne SOMENTE o JSON."""

    try:
        from emergentintegrations.llm.chat import chat, LlmModel
        
        response = await chat(
            api_key=os.environ.get('EMERGENT_API_KEY', ''),
            model=LlmModel.GEMINI_2_0_FLASH,
            system_message="Você é um especialista em extrair dados fiscais e contábeis de documentos. Retorne apenas JSON válido.",
            user_message=prompt,
            is_structured=False
        )
        
        # Extrair JSON da resposta
        response_text = response.message if hasattr(response, 'message') else str(response)
        
        # Tentar encontrar JSON na resposta
        json_match = re.search(r'\{[\s\S]*\}', response_text)
        if json_match:
            import json
            dados_extraidos = json.loads(json_match.group())
        else:
            raise ValueError("IA não retornou JSON válido")
        
    except Exception as e:
        # Fallback: tentar extrair dados manualmente se IA falhar
        dados_extraidos = {"dados": [], "ano_identificado": ano, "observacoes": f"Extração automática falhou: {str(e)}"}
        
        # Tentar extrair padrões numéricos básicos
        for i, mes in enumerate(meses_pt, 1):
            dados_mes = {"mes": i, "compras": 0, "vendas": 0, "icms": 0, "pis": 0, "cofins": 0, "iss": 0, "das": 0}
            dados_extraidos["dados"].append(dados_mes)
    
    # Converter para formato esperado pelo frontend
    resultado = {
        "success": True,
        "ano": ano,
        "dados_por_mes": {},
        "observacoes": dados_extraidos.get("observacoes", ""),
        "texto_extraido_preview": extracted_text[:500] + "..." if len(extracted_text) > 500 else extracted_text
    }
    
    for item in dados_extraidos.get("dados", []):
        mes = item.get("mes", 0)
        if 1 <= mes <= 12:
            competencia = f"{str(mes).zfill(2)}/{ano}"
            resultado["dados_por_mes"][competencia] = {
                "compras": float(item.get("compras", 0) or 0),
                "vendas": float(item.get("vendas", 0) or 0),
                "icms": float(item.get("icms", 0) or 0),
                "pis": float(item.get("pis", 0) or 0),
                "cofins": float(item.get("cofins", 0) or 0),
                "iss": float(item.get("iss", 0) or 0),
                "das": float(item.get("das", 0) or 0)
            }
    
    return resultado


# ============================================================
# FASE 6 - Apuração Consolidada Mensal
# ============================================================

class FechamentoMensalRequest(BaseModel):
    competencia: str
    observacoes: Optional[str] = ""

@api_router.get("/fechamento-mensal/{company_id}")
async def get_fechamento_mensal(
    company_id: str,
    competencia: str,
    current_user: User = Depends(get_current_user)
):
    """
    Retorna a apuração consolidada de todos os impostos para a competência.
    Combina ICMS, PIS, COFINS, ISS e IPI em um único relatório.
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    regime = company.get('regime_tributario', 'lucro_presumido')
    is_simples = regime == 'simples_nacional'
    tipo_atividade = company.get('tipo_atividade', 'comercio')
    
    # Verificar se já existe fechamento para esta competência
    fechamento_existente = await db.fechamentos_mensais.find_one(
        {"company_id": company_id, "competencia": competencia},
        {"_id": 0}
    )
    
    # Buscar documentos da competência
    query = {
        "company_id": company_id,
        "competencia": competencia
    }
    query.update(get_filtro_notas_ativas())
    
    documents = await db.xml_documents.find(query, {"_id": 0, "xml_content": 0}).to_list(100000)
    
    # Calcular totais de entradas e saídas
    entradas = [d for d in documents if d.get('tipo') == 'entrada' or d.get('tipo_operacao') == 'entrada']
    saidas = [d for d in documents if d.get('tipo') == 'saida' or d.get('tipo_operacao') == 'saida']
    
    total_entradas = sum(float(d.get('valor_total', 0) or 0) for d in entradas)
    total_saidas = sum(float(d.get('valor_total', 0) or 0) for d in saidas)
    
    # Calcular ICMS
    icms_debito = 0
    icms_credito = 0
    icms_st = 0
    
    for doc in saidas:
        for prod in doc.get('produtos', []):
            icms_debito += float(prod.get('v_icms', 0) or 0)
            icms_st += float(prod.get('v_icms_st', 0) or 0)
    
    for doc in entradas:
        for prod in doc.get('produtos', []):
            cfop = str(prod.get('cfop', ''))
            # Verificar se CFOP dá direito a crédito
            if cfop and cfop[0] in ['1', '2', '3'] and cfop not in ['1556', '2556', '1403', '2403', '1409', '2409']:
                icms_credito += float(prod.get('v_icms', 0) or 0)
    
    icms_saldo = icms_debito - icms_credito
    
    # Calcular PIS/COFINS
    pis_debito = 0
    pis_credito = 0
    cofins_debito = 0
    cofins_credito = 0
    
    for doc in saidas:
        for prod in doc.get('produtos', []):
            pis_debito += float(prod.get('v_pis', 0) or 0)
            cofins_debito += float(prod.get('v_cofins', 0) or 0)
    
    for doc in entradas:
        for prod in doc.get('produtos', []):
            cst_pis = str(prod.get('cst_pis', '') or prod.get('cst_pis_calculado', ''))
            # CSTs com crédito: 50-56, 60-66
            if cst_pis in ['50', '51', '52', '53', '54', '55', '56', '60', '61', '62', '63', '64', '65', '66']:
                pis_credito += float(prod.get('v_pis', 0) or 0)
                cofins_credito += float(prod.get('v_cofins', 0) or 0)
    
    pis_saldo = pis_debito - pis_credito
    cofins_saldo = cofins_debito - cofins_credito
    
    # Calcular ISS (apenas se empresa presta serviços)
    iss_total = 0
    if tipo_atividade in ['servicos', 'mista']:
        nfse_saida = [d for d in saidas if d.get('modelo', '').lower() in ['nfse', 'nfs-e']]
        for doc in nfse_saida:
            iss_total += float(doc.get('total_iss', 0) or doc.get('valor_iss', 0) or 0)
    
    # Calcular IPI
    ipi_debito = 0
    ipi_credito = 0
    
    for doc in saidas:
        for prod in doc.get('produtos', []):
            ipi_debito += float(prod.get('v_ipi', 0) or 0)
    
    for doc in entradas:
        for prod in doc.get('produtos', []):
            ipi_credito += float(prod.get('v_ipi', 0) or 0)
    
    ipi_saldo = ipi_debito - ipi_credito
    
    # Total de impostos a pagar
    total_impostos = 0
    if not is_simples:
        total_impostos = max(icms_saldo, 0) + max(pis_saldo, 0) + max(cofins_saldo, 0) + iss_total + max(ipi_saldo, 0)
    
    # Buscar saldo credor disponível
    saldo_credor = await db.saldos_credores.find_one(
        {"company_id": company_id, "competencia": competencia},
        {"_id": 0}
    )
    
    return {
        "company_id": company_id,
        "competencia": competencia,
        "regime_tributario": regime,
        "tipo_atividade": tipo_atividade,
        "fechamento_existente": fechamento_existente is not None,
        "data_fechamento": fechamento_existente.get('data_fechamento') if fechamento_existente else None,
        "status": "fechado" if fechamento_existente else "aberto",
        "resumo": {
            "total_entradas": round(total_entradas, 2),
            "total_saidas": round(total_saidas, 2),
            "qtd_entradas": len(entradas),
            "qtd_saidas": len(saidas),
            "qtd_documentos": len(documents)
        },
        "icms": {
            "debito": round(icms_debito, 2),
            "credito": round(icms_credito, 2),
            "saldo": round(icms_saldo, 2),
            "st": round(icms_st, 2),
            "a_pagar": round(max(icms_saldo, 0), 2),
            "a_compensar": round(abs(min(icms_saldo, 0)), 2)
        },
        "pis": {
            "debito": round(pis_debito, 2),
            "credito": round(pis_credito, 2),
            "saldo": round(pis_saldo, 2),
            "a_pagar": round(max(pis_saldo, 0), 2),
            "a_compensar": round(abs(min(pis_saldo, 0)), 2)
        },
        "cofins": {
            "debito": round(cofins_debito, 2),
            "credito": round(cofins_credito, 2),
            "saldo": round(cofins_saldo, 2),
            "a_pagar": round(max(cofins_saldo, 0), 2),
            "a_compensar": round(abs(min(cofins_saldo, 0)), 2)
        },
        "iss": {
            "total": round(iss_total, 2),
            "a_pagar": round(iss_total, 2)
        },
        "ipi": {
            "debito": round(ipi_debito, 2),
            "credito": round(ipi_credito, 2),
            "saldo": round(ipi_saldo, 2),
            "a_pagar": round(max(ipi_saldo, 0), 2),
            "a_compensar": round(abs(min(ipi_saldo, 0)), 2)
        },
        "total_impostos": {
            "a_pagar": round(total_impostos, 2),
            "icms": round(max(icms_saldo, 0), 2),
            "pis": round(max(pis_saldo, 0), 2),
            "cofins": round(max(cofins_saldo, 0), 2),
            "iss": round(iss_total, 2),
            "ipi": round(max(ipi_saldo, 0), 2)
        },
        "saldo_credor_anterior": saldo_credor.get('saldo_a_transportar') if saldo_credor else None,
        "observacoes": fechamento_existente.get('observacoes') if fechamento_existente else ""
    }


@api_router.post("/fechamento-mensal/{company_id}")
async def fechar_competencia_mensal(
    company_id: str,
    request: FechamentoMensalRequest,
    current_user: User = Depends(get_current_user)
):
    """
    Fecha a competência e registra o fechamento mensal.
    Após fechamento, alterações em documentos desta competência são bloqueadas.
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Verificar se já está fechado
    existente = await db.fechamentos_mensais.find_one(
        {"company_id": company_id, "competencia": request.competencia}
    )
    if existente:
        raise HTTPException(status_code=400, detail="Esta competência já está fechada")
    
    # Obter dados da apuração
    apuracao = await get_fechamento_mensal(company_id, request.competencia, current_user)
    
    # Registrar fechamento
    fechamento = {
        "company_id": company_id,
        "competencia": request.competencia,
        "data_fechamento": datetime.now(timezone.utc).isoformat(),
        "usuario": current_user.email,
        "usuario_id": current_user.id,
        "observacoes": request.observacoes,
        "resumo": apuracao["resumo"],
        "icms": apuracao["icms"],
        "pis": apuracao["pis"],
        "cofins": apuracao["cofins"],
        "iss": apuracao["iss"],
        "ipi": apuracao["ipi"],
        "total_impostos": apuracao["total_impostos"]
    }
    
    await db.fechamentos_mensais.insert_one(fechamento)
    
    # Registrar no audit log
    await log_audit(
        action=AuditAction.COMPETENCIA_FECHAR,
        user_id=current_user.id,
        user_email=current_user.email,
        company_id=company_id,
        company_name=company.get('razao_social'),
        details={
            "competencia": request.competencia,
            "total_impostos": apuracao["total_impostos"]["a_pagar"],
            "qtd_documentos": apuracao["resumo"]["qtd_documentos"]
        },
        success=True
    )
    
    # Calcular próxima competência
    try:
        mes, ano = request.competencia.split('/')
        mes_int = int(mes)
        ano_int = int(ano)
        if mes_int == 12:
            prox_comp = f"01/{ano_int + 1}"
        else:
            prox_comp = f"{mes_int + 1:02d}/{ano_int}"
    except:
        prox_comp = request.competencia
    
    return {
        "success": True,
        "competencia": request.competencia,
        "proxima_competencia": prox_comp,
        "data_fechamento": fechamento["data_fechamento"],
        "total_impostos": apuracao["total_impostos"],
        "mensagem": f"Competência {request.competencia} fechada com sucesso!"
    }


@api_router.delete("/fechamento-mensal/{company_id}/{competencia}")
async def reabrir_competencia_mensal(
    company_id: str,
    competencia: str,
    current_user: User = Depends(get_current_user)
):
    """
    Reabre uma competência fechada (apenas admin/super_admin).
    """
    if current_user.role not in ['admin', 'super_admin']:
        raise HTTPException(status_code=403, detail="Apenas administradores podem reabrir competências")
    
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    result = await db.fechamentos_mensais.delete_one(
        {"company_id": company_id, "competencia": competencia}
    )
    
    if result.deleted_count == 0:
        raise HTTPException(status_code=404, detail="Fechamento não encontrado")
    
    # Registrar no audit log
    await log_audit(
        action=AuditAction.COMPETENCIA_REABRIR,
        user_id=current_user.id,
        user_email=current_user.email,
        company_id=company_id,
        company_name=company.get('razao_social'),
        details={"competencia": competencia},
        success=True
    )
    
    return {
        "success": True,
        "competencia": competencia,
        "mensagem": f"Competência {competencia} reaberta com sucesso!"
    }


@api_router.get("/fechamento-mensal/{company_id}/historico")
async def get_historico_fechamentos(
    company_id: str,
    current_user: User = Depends(get_current_user)
):
    """
    Retorna o histórico de todos os fechamentos mensais da empresa.
    """
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    fechamentos = await db.fechamentos_mensais.find(
        {"company_id": company_id},
        {"_id": 0}
    ).sort("competencia", -1).to_list(100)
    
    return {
        "company_id": company_id,
        "fechamentos": fechamentos,
        "total": len(fechamentos)
    }


