@api_router.post("/batch-import/upload-estrutura")
async def batch_import_upload_estrutura(
    file: UploadFile = File(...),
    competencia: str = Form(""),
    skip_ai: bool = Form(False),
    current_user: User = Depends(get_current_user)
):
    """
    Importa um arquivo ZIP contendo estrutura de pastas de empresas.
    
    Estrutura esperada do ZIP:
    arquivo.zip/
    └── 0175 - NOME EMPRESA/
        └── 2026/
            └── 002 - FISCAL/
                └── 01/
                    ├── nota1.xml
                    └── nota2.xml
    """
    import zipfile
    import tempfile
    import shutil
    import re
    from pathlib import Path
    
    # Todos os usuários autenticados podem fazer importação em lote
    # (antes era restrito apenas a admin/super_admin)
    
    if not file.filename.endswith('.zip'):
        raise HTTPException(status_code=400, detail="Arquivo deve ser um ZIP")
        raise HTTPException(status_code=400, detail="Arquivo deve ser um ZIP")
    
    # Criar ID da importação
    import_id = str(uuid.uuid4())
    
    # Competência padrão
    if not competencia:
        now = datetime.now()
        competencia = f"{now.strftime('%m')}/{now.strftime('%Y')}"
    
    # Criar registro inicial
    import_record = {
        "import_id": import_id,
        "type": "upload_estrutura",
        "filename": file.filename,
        "competencia_padrao": competencia,
        "skip_ai": skip_ai,
        "status": "processing",
        "created_at": datetime.now(timezone.utc).isoformat(),
        "created_by": current_user.id,
        "total_empresas": 0,
        "total_arquivos": 0,
        "total_importados": 0,
        "total_duplicados": 0,
        "total_erros": 0,
        "empresas_processadas": [],
        "empresas_nao_encontradas": [],
        "erros": []
    }
    
    await db.batch_import_history.insert_one(import_record)
    
    # Processar em background
    try:
        # Salvar ZIP temporariamente
        temp_dir = tempfile.mkdtemp()
        zip_path = os.path.join(temp_dir, file.filename)
        
        content = await file.read()
        with open(zip_path, 'wb') as f:
            f.write(content)
        
        # Extrair ZIP
        extract_dir = os.path.join(temp_dir, 'extracted')
        os.makedirs(extract_dir)
        
        with zipfile.ZipFile(zip_path, 'r') as zf:
            zf.extractall(extract_dir)
        
        # Carregar mapeamento de empresas
        companies = await db.companies.find({}, {"_id": 0, "id": 1, "codigo_empresa": 1, "razao_social": 1}).to_list(length=None)
        companies_map = {}
        for c in companies:
            codigo = c.get('codigo_empresa', '').strip()
            if codigo:
                companies_map[codigo] = c
                companies_map[codigo.zfill(4)] = c
        
        # Função para extrair código da pasta
        def extract_codigo(folder_name):
            match = re.match(r'^(\d+)\s*-\s*', folder_name)
            if match:
                return match.group(1).zfill(4)
            return None
        
        # Função para extrair competência do caminho
        def extract_competencia(path_parts):
            ano = None
            mes = None
            for part in path_parts:
                if re.match(r'^20\d{2}$', part):
                    ano = part
                elif re.match(r'^(0?[1-9]|1[0-2])$', part):
                    mes = part.zfill(2)
            if ano and mes:
                return f"{mes}/{ano}"
            return None
        
        # Varrer estrutura
        extract_path = Path(extract_dir)
        empresas_encontradas = {}
        
        for item in extract_path.iterdir():
            if item.is_dir():
                codigo = extract_codigo(item.name)
                if codigo:
                    if codigo not in empresas_encontradas:
                        empresas_encontradas[codigo] = {
                            "nome_pasta": item.name,
                            "arquivos": []
                        }
                    
                    # Buscar XMLs recursivamente
                    for xml_file in item.rglob('*.xml'):
                        relative_parts = xml_file.relative_to(item).parts
                        comp = extract_competencia(relative_parts) or competencia
                        empresas_encontradas[codigo]["arquivos"].append({
                            "path": str(xml_file),
                            "filename": xml_file.name,
                            "competencia": comp
                        })
        
        import_record["total_empresas"] = len(empresas_encontradas)
        
        # Contar total de arquivos para progresso
        total_arquivos_geral = sum(len(data["arquivos"]) for data in empresas_encontradas.values())
        arquivos_processados = 0
        empresa_atual_idx = 0
        
        # Processar cada empresa
        for codigo, data in empresas_encontradas.items():
            empresa_atual_idx += 1
            company = companies_map.get(codigo)
            
            if not company:
                import_record["empresas_nao_encontradas"].append({
                    "codigo": codigo,
                    "nome_pasta": data["nome_pasta"],
                    "qtd_arquivos": len(data["arquivos"])
                })
                continue
            
            empresa_result = {
                "codigo": codigo,
                "company_id": company["id"],
                "razao_social": company.get("razao_social", ""),
                "total_arquivos": len(data["arquivos"]),
                "importados": 0,
                "duplicados": 0,
                "erros": 0,
                "desconsiderados": 0
            }
            
            # Atualizar progresso no banco - início da empresa
            await db.batch_import_history.update_one(
                {"import_id": import_id},
                {"$set": {
                    "progress": {
                        "percent": int((arquivos_processados / total_arquivos_geral) * 100) if total_arquivos_geral > 0 else 0,
                        "empresa_atual": empresa_result["razao_social"],
                        "empresa_atual_idx": empresa_atual_idx,
                        "total_empresas": len(empresas_encontradas),
                        "arquivos_processados": arquivos_processados,
                        "total_arquivos": total_arquivos_geral,
                        "empresa_arquivos_processados": 0,
                        "empresa_total_arquivos": len(data["arquivos"])
                    }
                }}
            )
            
            arquivos_empresa_processados = 0
            
            # Carregar dados da empresa para classificação
            company_doc = await db.companies.find_one({"id": company["id"]})
            company_cnpj = company_doc.get("cnpj", "").replace(".", "").replace("/", "").replace("-", "") if company_doc else ""
            uf_empresa = company_doc.get("uf", "") if company_doc else ""
            regime_tributario = company_doc.get("regime_tributario", "simples_nacional") if company_doc else "simples_nacional"
            
            # Cache de vendas para classificação por aprendizado (uma vez por empresa)
            sales_cache = {}
            if not skip_ai:
                try:
                    pipeline = [
                        {"$match": {"company_id": company["id"], "tipo": "saida"}},
                        {"$unwind": "$produtos"},
                        {"$group": {
                            "_id": {
                                "descricao": {"$toLower": "$produtos.descricao"},
                                "codigo": "$produtos.codigo"
                            },
                            "categoria": {"$first": "$produtos.categoria_classificada"},
                            "cfop": {"$first": "$produtos.cfop"},
                            "count": {"$sum": 1}
                        }},
                        {"$match": {"count": {"$gte": 1}}}
                    ]
                    sales_products = await db.xml_documents.aggregate(pipeline).to_list(length=10000)
                    for sp in sales_products:
                        key = (sp["_id"]["descricao"] or "", sp["_id"]["codigo"] or "")
                        if sp.get("categoria"):
                            sales_cache[key] = {"categoria": sp["categoria"], "cfop": sp.get("cfop", "")}
                except Exception as e:
                    logger.warning(f"Erro ao carregar cache de vendas: {e}")
            
            # Estatísticas de classificação
            classification_stats = {"from_cache": 0, "from_rules": 0, "from_ai": 0, "from_sales_inference": 0, "total": 0}
            
            # Agrupar por competência
            by_competencia = {}
            for arq in data["arquivos"]:
                comp = arq["competencia"]
                if comp not in by_competencia:
                    by_competencia[comp] = []
                by_competencia[comp].append(arq)
            
            # Processar cada competência
            for comp, arquivos in by_competencia.items():
                for arq in arquivos:
                    try:
                        with open(arq["path"], 'r', encoding='utf-8') as f:
                            xml_content = f.read()
                        
                        # ==== VERIFICAR SE É XML DE CANCELAMENTO ====
                        cancelamento_data = parse_xml_evento_cancelamento(xml_content)
                        if cancelamento_data:
                            # É um evento de cancelamento - marcar a nota original como cancelada
                            chave_cancelada = cancelamento_data.get('chave_nfe', '')
                            if chave_cancelada:
                                # Buscar e atualizar a nota original
                                update_result = await db.xml_documents.update_one(
                                    {"chave_nfe": chave_cancelada, "company_id": company["id"]},
                                    {
                                        "$set": {
                                            "cancelada": True,
                                            "data_cancelamento": cancelamento_data.get('data_cancelamento', ''),
                                            "justificativa_cancelamento": cancelamento_data.get('justificativa', ''),
                                            "protocolo_cancelamento": cancelamento_data.get('protocolo', '')
                                        }
                                    }
                                )
                                
                                if update_result.modified_count > 0:
                                    empresa_result["importados"] += 1
                                    import_record["total_importados"] += 1
                                else:
                                    # Salvar o evento para processar depois
                                    await db.eventos_cancelamento.update_one(
                                        {"chave_nfe": chave_cancelada},
                                        {
                                            "$set": {
                                                "chave_nfe": chave_cancelada,
                                                "company_id": company["id"],
                                                "data_cancelamento": cancelamento_data.get('data_cancelamento', ''),
                                                "justificativa": cancelamento_data.get('justificativa', ''),
                                                "protocolo": cancelamento_data.get('protocolo', ''),
                                                "xml_filename": arq["filename"],
                                                "processado": False,
                                                "created_at": datetime.now(timezone.utc).isoformat()
                                            }
                                        },
                                        upsert=True
                                    )
                                    empresa_result["importados"] += 1
                                    import_record["total_importados"] += 1
                            
                            # Pular para o próximo arquivo
                            arquivos_empresa_processados += 1
                            arquivos_processados += 1
                            continue
                        
                        # Detectar tipo de documento e parsear
                        parsed = None
                        modelo = None
                        
                        # Verificar se é NFC-e
                        if '<NFe' in xml_content or '<nfeProc' in xml_content:
                            # Verificar se é NFC-e (modelo 65) ou NF-e (modelo 55)
                            if 'mod>65</mod>' in xml_content or '-nfce' in arq["filename"].lower():
                                parsed = parse_xml_nfce(xml_content)
                                modelo = "nfce"
                            else:
                                parsed = parse_xml_nfe(xml_content)
                                modelo = "nfe"
                        elif '<CTeOS' in xml_content or '<CTe' in xml_content or '<cteProc' in xml_content:
                            parsed = parse_xml_cte(xml_content)
                            modelo = "cte"
                        else:
                            empresa_result["erros"] += 1
                            import_record["erros"].append({
                                "empresa": codigo,
                                "arquivo": arq["filename"],
                                "erro": "Formato de XML não reconhecido"
                            })
                            continue
                        
                        if not parsed:
                            empresa_result["erros"] += 1
                            import_record["erros"].append({
                                "empresa": codigo,
                                "arquivo": arq["filename"],
                                "erro": "Erro ao parsear XML"
                            })
                            continue
                        
                        chave_nfe = parsed.get('chave_nfe', '')
                        
                        # ==== VERIFICAR SE A NOTA ESTÁ CANCELADA PELO STATUS ====
                        situacao = str(parsed.get('situacao', '100'))
                        is_cancelada = situacao not in ['100']  # 100 = Autorizada
                        
                        # Verificar duplicado
                        existing = await db.xml_documents.find_one({
                            "company_id": company["id"],
                            "chave_nfe": chave_nfe
                        })
                        
                        if existing:
                            empresa_result["duplicados"] += 1
                            continue
                        
                        # Determinar tipo (entrada/saída) e verificar regras
                        emit_cnpj = parsed.get("cnpj_emitente", "").replace(".", "").replace("/", "").replace("-", "")
                        dest_cnpj = parsed.get("cnpj_destinatario", "").replace(".", "").replace("/", "").replace("-", "")
                        emitente_uf = parsed.get("emitente_uf", "")
                        
                        # Flags de controle
                        is_emissao_propria = (emit_cnpj == company_cnpj)
                        is_destinatario = (dest_cnpj == company_cnpj)
                        desconsiderada_devolucao = False
                        motivo_desconsideracao = ""
                        
                        # NFC-e é SEMPRE saída
                        if modelo == "nfce":
                            tipo = "saida"
                        else:
                            # Determinar tipo baseado em CNPJ
                            if is_emissao_propria:
                                tipo = "saida"
                            elif is_destinatario:
                                tipo = "entrada"
                            else:
                                tipo = "entrada"
                        
                        # ==== REGRAS DE DESCONSIDERAÇÃO (igual upload normal) ====
                        if tipo == "entrada" and modelo == "nfe":
                            cfops_produtos = [p.get('cfop', '') for p in parsed.get('produtos', [])]
                            
                            # Verificar se deve desconsiderar (usando constante global)
                            cfops_devolucao = [c for c in cfops_produtos if c in CFOPS_DEVOLUCAO_TERCEIROS_GLOBAL]
                            if cfops_devolucao and not is_emissao_propria:
                                desconsiderada_devolucao = True
                                motivo_desconsideracao = f"NF de terceiro com CFOP de devolução/bonificação ({', '.join(cfops_devolucao[:3])})"
                        
                        # ==== CLASSIFICAÇÃO DE PRODUTOS (igual upload normal) ====
                        produtos = parsed.get('produtos', [])
                        
                        if tipo == "entrada" and not skip_ai and not desconsiderada_devolucao and modelo == "nfe":
                            # Aplicar CST e classificar produtos
                            produtos_para_classificar = []
                            
                            for product in produtos:
                                cfop_original = product.get('cfop', '')
                                ncm = product.get('ncm', '')
                                
                                # Calcular CST de PIS/COFINS
                                cst_info = calcular_cst_pis_cofins(
                                    ncm=ncm,
                                    cfop=cfop_original,
                                    tipo_operacao=tipo,
                                    cst_xml=product.get('cst_pis_xml', product.get('cst_pis', '')),
                                    regime=regime_tributario
                                )
                                
                                product.update({
                                    'cst_pis_calculado': cst_info['cst_calculado'],
                                    'cst_cofins_calculado': cst_info['cst_calculado'],
                                    'cst_pis': cst_info['cst_calculado'],
                                    'cst_cofins': cst_info['cst_calculado'],
                                })
                                
                                # Verificar se é CFOP de devolução (classificar automaticamente)
                                categoria_cfop = obter_categoria_por_cfop(cfop_original)
                                if categoria_cfop == 'devolucao':
                                    product['cfop_original'] = cfop_original
                                    product['categoria_classificada'] = 'devolucao'
                                    product['justificativa_ia'] = f'CFOP {cfop_original} é devolução - classificação automática'
                                    classification_stats["from_rules"] += 1
                                elif not is_emissao_propria:
                                    product['cfop_original_emissor'] = cfop_original
                                    produtos_para_classificar.append(product)
                            
                            # Classificar produtos com cache/IA
                            if produtos_para_classificar:
                                try:
                                    classifications, stats = await classify_products_with_cache(
                                        produtos_para_classificar,
                                        company["id"],
                                        company_doc,
                                        emitente_uf,
                                        sales_cache
                                    )
                                    
                                    classification_stats["from_cache"] += stats.get("from_cache", 0)
                                    classification_stats["from_rules"] += stats.get("from_rules", 0)
                                    classification_stats["from_ai"] += stats.get("from_ai", 0)
                                    classification_stats["from_sales_inference"] += stats.get("from_sales_inference", 0)
                                    
                                    # Aplicar classificações
                                    for idx, product in enumerate(produtos_para_classificar):
                                        p_id = str(idx)
                                        if p_id in classifications:
                                            result_class = classifications[p_id]
                                            cfop_original = product.get('cfop', '')
                                            cfop_novo = result_class['cfop']
                                            
                                            product['cfop_original'] = cfop_original
                                            product['cfop'] = cfop_novo
                                            product['cfop_sugerido'] = cfop_novo
                                            product['categoria_classificada'] = result_class['categoria']
                                            product['justificativa_ia'] = result_class['justificativa']
                                        else:
                                            # Fallback: classificar como revenda
                                            cfop_original = product.get('cfop', '')
                                            cfop_prefix = '2' if (emitente_uf and emitente_uf != uf_empresa) else '1'
                                            cfop_novo = cfop_prefix + '102'
                                            product['cfop_original'] = cfop_original
                                            product['cfop'] = cfop_novo
                                            product['categoria_classificada'] = 'revenda'
                                            product['justificativa_ia'] = 'Classificação padrão: REVENDA'
                                except Exception as e:
                                    logger.warning(f"Erro na classificação: {e}")
                        
                        # Calcular competência correta
                        data_emissao = parsed.get('data_emissao', '')
                        data_saida_entrada = parsed.get('data_saida_entrada', '')
                        
                        if tipo == 'saida' or is_emissao_propria:
                            data_ref = data_emissao
                        elif tipo == 'entrada' and data_saida_entrada:
                            data_ref = data_saida_entrada
                        else:
                            data_ref = data_emissao
                        
                        if data_ref and len(data_ref) >= 7:
                            competencia_doc = f"{data_ref[5:7]}/{data_ref[:4]}"
                        else:
                            competencia_doc = comp
                        
                        # Criar documento
                        xml_doc = {
                            "id": str(uuid.uuid4()),
                            "company_id": company["id"],
                            "competencia": competencia_doc,
                            "tipo": tipo,
                            "modelo": modelo,
                            "xml_content": xml_content,
                            "uploaded_by": current_user.id,
                            "uploaded_at": datetime.now(timezone.utc).isoformat(),
                            "origem_importacao": "batch_upload",
                            "desconsiderada_devolucao": desconsiderada_devolucao,
                            "motivo_desconsideracao": motivo_desconsideracao,
                            "cancelada": is_cancelada,  # Flag de cancelamento pelo status
                            **{k: v for k, v in parsed.items() if k != 'modelo'}
                        }
                        
                        await db.xml_documents.insert_one(xml_doc)
                        empresa_result["importados"] += 1
                        import_record["total_importados"] += 1
                        
                    except Exception as e:
                        empresa_result["erros"] += 1
                        import_record["erros"].append({
                            "empresa": codigo,
                            "arquivo": arq["filename"],
                            "erro": str(e)
                        })
                    finally:
                        # Atualizar contadores de progresso
                        arquivos_processados += 1
                        arquivos_empresa_processados += 1
                        
                        # Atualizar progresso no banco a cada 50 arquivos ou no final da empresa
                        if arquivos_empresa_processados % 50 == 0 or arquivos_empresa_processados == len(data["arquivos"]):
                            await db.batch_import_history.update_one(
                                {"import_id": import_id},
                                {"$set": {
                                    "progress": {
                                        "percent": int((arquivos_processados / total_arquivos_geral) * 100) if total_arquivos_geral > 0 else 0,
                                        "empresa_atual": empresa_result["razao_social"],
                                        "empresa_atual_idx": empresa_atual_idx,
                                        "total_empresas": len(empresas_encontradas),
                                        "arquivos_processados": arquivos_processados,
                                        "total_arquivos": total_arquivos_geral,
                                        "empresa_arquivos_processados": arquivos_empresa_processados,
                                        "empresa_total_arquivos": len(data["arquivos"]),
                                        "empresa_importados": empresa_result["importados"],
                                        "empresa_duplicados": empresa_result["duplicados"],
                                        "empresa_erros": empresa_result["erros"]
                                    }
                                }}
                            )
            
            import_record["total_arquivos"] += empresa_result["total_arquivos"]
            import_record["total_duplicados"] += empresa_result["duplicados"]
            import_record["total_erros"] += empresa_result["erros"]
            
            # Adicionar estatísticas de classificação à empresa
            empresa_result["classificacao"] = classification_stats.copy()
            import_record["empresas_processadas"].append(empresa_result)
        
        # Atualizar status
        import_record["status"] = "completed"
        import_record["completed_at"] = datetime.now(timezone.utc).isoformat()
        
        await db.batch_import_history.update_one(
            {"import_id": import_id},
            {"$set": import_record}
        )
        
        # Limpar temporários
        shutil.rmtree(temp_dir, ignore_errors=True)
        
        return {
            "import_id": import_id,
            "status": "completed",
            "total_empresas": import_record["total_empresas"],
            "total_arquivos": import_record["total_arquivos"],
            "total_importados": import_record["total_importados"],
            "total_duplicados": import_record["total_duplicados"],
            "total_erros": import_record["total_erros"],
            "empresas_nao_encontradas": len(import_record["empresas_nao_encontradas"]),
            "empresas_processadas": import_record["empresas_processadas"],
            "erros": import_record["erros"][:100],
            "skip_ai": skip_ai
        }
        
    except Exception as e:
        logger.error(f"Erro na importação em lote: {e}")
        await db.batch_import_history.update_one(
            {"import_id": import_id},
            {"$set": {"status": "error", "error": str(e)}}
        )
        raise HTTPException(status_code=500, detail=f"Erro na importação: {str(e)}")


@api_router.get("/batch-import/empresas-mapeamento")
async def get_empresas_mapeamento(
    current_user: User = Depends(get_current_user)
):
    """Retorna lista de empresas com seus códigos para mapeamento"""
    if current_user.role not in ['admin', 'super_admin']:
        raise HTTPException(status_code=403, detail="Apenas administradores")
    
    companies = await db.companies.find(
        {},
        {"_id": 0, "id": 1, "codigo_empresa": 1, "razao_social": 1, "nome_fantasia": 1, "cnpj": 1}
    ).to_list(length=None)
    
    # Separar empresas com e sem código
    com_codigo = [c for c in companies if c.get('codigo_empresa')]
    sem_codigo = [c for c in companies if not c.get('codigo_empresa')]
    
    return {
        "com_codigo": com_codigo,
        "sem_codigo": sem_codigo,
        "total": len(companies)
    }


@api_router.post("/batch-import/atualizar-codigo/{company_id}")
async def atualizar_codigo_empresa(
    company_id: str,
    codigo: str = Body(..., embed=True),
    current_user: User = Depends(get_current_user)
):
    """Atualiza o código de uma empresa para mapeamento de importação em lote"""
    if current_user.role not in ['admin', 'super_admin']:
        raise HTTPException(status_code=403, detail="Apenas administradores")
    
    result = await db.companies.update_one(
        {"id": company_id},
        {"$set": {"codigo_empresa": codigo.strip()}}
    )
    
    if result.modified_count == 0:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    return {"success": True, "codigo": codigo.strip()}


@api_router.get("/batch-import/download-script")
async def download_batch_script():
    """Retorna o script Python para importação em lote"""
    from fastapi.responses import FileResponse
    
    script_path = os.path.join(os.path.dirname(__file__), 'batch_import.py')
    if os.path.exists(script_path):
        return FileResponse(
            script_path,
            media_type='text/x-python',
            filename='batch_import.py'
        )
    else:
        raise HTTPException(status_code=404, detail="Script não encontrado")


