def get_filter_docs_nao_canceladas_ou_desconsideradas():
    """Retorna filtro MongoDB para excluir documentos cancelados ou desconsiderados"""
    return {
        "$and": [
            {"$or": [
                {"cancelada": {"$exists": False}},
                {"cancelada": False}
            ]},
            {"$or": [
                {"desconsiderada_devolucao": {"$exists": False}},
                {"desconsiderada_devolucao": False}
            ]}
        ]
    }


@api_router.get("/wizard-fechamento/status/{company_id}")
async def get_wizard_status(
    company_id: str,
    competencia: str = Query(...),
    current_user: User = Depends(get_current_user)
):
    """Retorna o status atual do wizard para uma empresa/competência"""
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Buscar status existente
    wizard = await db.wizard_fechamento.find_one(
        {"company_id": company_id, "competencia": competencia},
        {"_id": 0}
    )
    
    if not wizard:
        # Criar novo registro
        wizard = {
            "id": str(uuid.uuid4()),
            "company_id": company_id,
            "competencia": competencia,
            "current_step": 1,
            "steps_completed": [],
            "steps_data": {},
            "status": "in_progress",
            "created_at": datetime.now(timezone.utc).isoformat(),
            "updated_at": datetime.now(timezone.utc).isoformat()
        }
        await db.wizard_fechamento.insert_one(wizard)
    
    return {
        "wizard": wizard,
        "steps": WIZARD_STEPS,
        "empresa": {
            "id": company["id"],
            "razao_social": company.get("razao_social", ""),
            "cnpj": company.get("cnpj", "")
        }
    }


@api_router.post("/wizard-fechamento/reset/{company_id}")
async def reset_wizard(
    company_id: str,
    competencia: str = Query(...),
    current_user: User = Depends(get_current_user)
):
    """Reinicia o wizard do zero"""
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Deletar wizard existente
    await db.wizard_fechamento.delete_one(
        {"company_id": company_id, "competencia": competencia}
    )
    
    # Criar novo
    wizard = {
        "id": str(uuid.uuid4()),
        "company_id": company_id,
        "competencia": competencia,
        "current_step": 1,
        "steps_completed": [],
        "steps_data": {},
        "status": "in_progress",
        "created_at": datetime.now(timezone.utc).isoformat(),
        "updated_at": datetime.now(timezone.utc).isoformat()
    }
    await db.wizard_fechamento.insert_one(wizard)
    
    return {"message": "Wizard reiniciado", "wizard": wizard}


@api_router.get("/wizard-fechamento/summary/{company_id}")
async def get_wizard_summary(
    company_id: str,
    competencia: str = Query(...),
    current_user: User = Depends(get_current_user)
):
    """Retorna um resumo do wizard para exibição no menu"""
    wizard = await db.wizard_fechamento.find_one(
        {"company_id": company_id, "competencia": competencia},
        {"_id": 0, "status": 1, "current_step": 1, "steps_completed": 1, "steps_data": 1, "updated_at": 1}
    )
    
    if not wizard:
        return {
            "has_wizard": False,
            "message": "Nenhum processamento realizado",
            "last_update": None,
            "steps_summary": []
        }
    
    # Montar resumo das etapas
    steps_summary = []
    step_names = {
        1: "Notas Canceladas",
        2: "Devoluções",
        3: "Classificação CFOPs",
        4: "PIS/COFINS Entradas",
        5: "PIS/COFINS Saídas",
        6: "Reforma Tributária"
    }
    
    for step_id in range(1, 7):
        step_key = {1: "notas_canceladas", 2: "devolucoes", 3: "classificacao_cfop", 
                    4: "pis_cofins_entrada", 5: "pis_cofins_saida", 6: "reforma_tributaria"}.get(step_id, "")
        step_data = wizard.get("steps_data", {}).get(step_key, {})
        
        steps_summary.append({
            "step_id": step_id,
            "name": step_names.get(step_id, ""),
            "completed": step_id in wizard.get("steps_completed", []),
            "completed_at": step_data.get("completed_at"),
            "actions": step_data.get("actions", [])
        })
    
    return {
        "has_wizard": True,
        "status": wizard.get("status", "in_progress"),
        "current_step": wizard.get("current_step", 1),
        "last_update": wizard.get("updated_at"),
        "steps_completed": len(wizard.get("steps_completed", [])),
        "total_steps": 6,
        "steps_summary": steps_summary
    }


@api_router.get("/wizard-fechamento/step/{company_id}/{step_id}")
async def get_wizard_step_data(
    company_id: str,
    step_id: int,
    competencia: str = Query(...),
    current_user: User = Depends(get_current_user)
):
    """Retorna os dados necessários para uma etapa específica do wizard"""
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Filtro base para documentos
    base_filter = {
        "company_id": company_id,
        "competencia": competencia,
        **get_filter_docs_nao_canceladas_ou_desconsideradas()
    }
    
    result = {"step_id": step_id, "data": {}}
    
    if step_id == 1:  # Notas Canceladas
        # Buscar APENAS notas que foram marcadas como canceladas durante a importação
        # - cancelada: True = nota com XML de cancelamento importado junto
        # - status: 'cancelada' = status identificado no próprio XML
        # - evento_cancelamento existe = evento de cancelamento foi processado
        canceladas = await db.xml_documents.find({
            "company_id": company_id,
            "competencia": competencia,
            "$or": [
                {"cancelada": True},
                {"status": "cancelada"},
                {"evento_cancelamento": {"$exists": True, "$ne": None}},
                {"data_cancelamento": {"$exists": True, "$ne": None}}
            ]
        }, {"_id": 0, "id": 1, "numero_nfe": 1, "chave_nfe": 1, "emitente_nome": 1, 
            "valor_total": 1, "data_emissao": 1, "cancelada": 1, "status": 1,
            "data_cancelamento": 1, "tipo": 1, "modelo": 1}).to_list(length=500)
        
        result["data"] = {
            "notas_canceladas": canceladas,
            "total": len(canceladas)
        }
    
    elif step_id == 2:  # Devoluções - Notas de entrada com CFOP de entrada emitidas por terceiros/filiais
        # Buscar a empresa para pegar o CNPJ
        company = await db.companies.find_one({"id": company_id}, {"_id": 0, "cnpj": 1})
        cnpj_empresa = (company.get('cnpj', '') if company else '').replace('.', '').replace('/', '').replace('-', '')
        
        # Buscar notas de ENTRADA emitidas por TERCEIROS/FILIAIS com CFOP de ENTRADA (1xxx, 2xxx, 3xxx)
        # Essas são potenciais devoluções de vendas da nossa empresa
        
        notas_terceiros_cfop_entrada = await db.xml_documents.find({
            "company_id": company_id,
            "competencia": competencia,
            "tipo": "entrada",
            # CFOPs de entrada (1xxx, 2xxx, 3xxx)
            "produtos.cfop": {"$regex": "^[123]"}
        }, {"_id": 0, "id": 1, "numero_nfe": 1, "chave_nfe": 1, "emitente_nome": 1,
            "emitente_cnpj": 1, "valor_total": 1, "data_emissao": 1, 
            "desconsiderada_devolucao": 1, "motivo_desconsideracao": 1,
            "produtos": 1, "nfe_referenciada": 1}).to_list(length=2000)
        
        # Filtrar apenas terceiros/filiais (CNPJ COMPLETO diferente da empresa)
        notas_filtradas = []
        for nota in notas_terceiros_cfop_entrada:
            cnpj_emit = (nota.get('emitente_cnpj', '') or '').replace('.', '').replace('/', '').replace('-', '')
            
            # Verificar se é terceiro/filial (CNPJ completo diferente)
            if cnpj_emit and cnpj_emit != cnpj_empresa:
                notas_filtradas.append(nota)
        
        # Para cada nota, extrair CFOPs e buscar nota referenciada
        devolucoes_com_original = []
        for nota in notas_filtradas:
            # Extrair todos os CFOPs únicos da nota
            cfops = list(set([str(p.get('cfop', '')) for p in nota.get('produtos', []) if p.get('cfop')]))
            cfops_entrada = [c for c in cfops if c and c[0] in ['1', '2', '3']]
            
            if not cfops_entrada:
                continue
            
            dev_info = {
                "id": nota.get("id"),
                "numero_nfe": nota.get("numero_nfe"),
                "chave_nfe": nota.get("chave_nfe"),
                "emitente_nome": nota.get("emitente_nome"),
                "emitente_cnpj": nota.get("emitente_cnpj"),
                "valor_total": nota.get("valor_total"),
                "data_emissao": nota.get("data_emissao"),
                "cfops": cfops,  # Todos os CFOPs
                "cfops_entrada": cfops_entrada,  # Apenas os de entrada
                "desconsiderada": nota.get("desconsiderada_devolucao", False),
                "motivo_desconsideracao": nota.get("motivo_desconsideracao", ""),
                "nota_original": None,
                "nota_original_encontrada": False,
                "nfe_referenciada": nota.get("nfe_referenciada", "")
            }
            
            # Tentar encontrar a nota original pela chave referenciada
            nfe_ref = nota.get("nfe_referenciada", "")
            if nfe_ref and len(nfe_ref) >= 10:
                nota_original = await db.xml_documents.find_one({
                    "company_id": company_id,
                    "$or": [
                        {"chave_nfe": nfe_ref},
                        {"chave_nfe": {"$regex": nfe_ref[-20:] if len(nfe_ref) > 20 else nfe_ref}}
                    ]
                }, {"_id": 0, "id": 1, "numero_nfe": 1, "chave_nfe": 1, 
                    "valor_total": 1, "data_emissao": 1, "desconsiderada_devolucao": 1,
                    "produtos": 1})
                
                if nota_original:
                    # Extrair CFOPs da nota original também
                    cfops_original = list(set([str(p.get('cfop', '')) for p in nota_original.get('produtos', []) if p.get('cfop')]))
                    dev_info["nota_original"] = {
                        "id": nota_original.get("id"),
                        "numero_nfe": nota_original.get("numero_nfe"),
                        "chave_nfe": nota_original.get("chave_nfe"),
                        "valor_total": nota_original.get("valor_total"),
                        "data_emissao": nota_original.get("data_emissao"),
                        "cfops": cfops_original
                    }
                    dev_info["nota_original_encontrada"] = True
            
            devolucoes_com_original.append(dev_info)
        
        result["data"] = {
            "notas_devolucao": devolucoes_com_original,
            "total": len(devolucoes_com_original),
            "total_com_original": sum(1 for d in devolucoes_com_original if d["nota_original_encontrada"]),
            "total_sem_original": sum(1 for d in devolucoes_com_original if not d["nota_original_encontrada"]),
            "total_desconsideradas": sum(1 for d in devolucoes_com_original if d["desconsiderada"]),
            "cnpj_empresa": cnpj_empresa
        }
    
    elif step_id == 3:  # Alertas de CFOP - Mesmo critério da Classificação Inteligente
        # Buscar APENAS documentos de ENTRADA que tenham produtos pendentes de revisão
        # Excluir saídas e notas desconsideradas
        docs = await db.xml_documents.find({
            **base_filter,
            "tipo": "entrada",
            "$or": [
                {"desconsiderada_devolucao": {"$ne": True}},
                {"desconsiderada_devolucao": {"$exists": False}}
            ]
        }, {"_id": 0, "id": 1, "numero_nfe": 1, "chave_nfe": 1, "emitente_nome": 1,
            "valor_total": 1, "data_emissao": 1, "produtos": 1, "tipo": 1}).to_list(length=None)
        
        # Agrupar por CFOP atual - APENAS produtos com pendente_revisao_cfop
        cfops_agrupados = {}
        for doc in docs:
            for idx, p in enumerate(doc.get("produtos", [])):
                # Critério: produto deve estar pendente de revisão
                if not p.get("pendente_revisao_cfop"):
                    continue
                    
                cfop_atual = str(p.get("cfop", ""))
                cfop_original = str(p.get("cfop_original_emissor", cfop_atual))
                
                if not cfop_atual:
                    continue
                
                if cfop_atual not in cfops_agrupados:
                    # Buscar descrição do CFOP
                    natureza = p.get('natureza_operacao_original', '')
                    cfop_info = CFOPS_OPERACOES_DISTINTAS.get(cfop_original, "")
                    descricao_cfop = cfop_info if cfop_info else natureza or f'Operação {cfop_atual}'
                    
                    # Calcular CFOP de compra sugerido
                    # Verificar se é operação com ST pelo CFOP original
                    cfops_st = ['5403', '5405', '5408', '5409', '5410', '5411', '5412', '5413', '5414', '5415',
                               '6403', '6404', '6405', '6408', '6409', '6410', '6411', '6412', '6413', '6414', '6415']
                    is_st = cfop_original in cfops_st
                    
                    if cfop_atual.startswith('1'):
                        cfop_compra = '1403' if is_st else '1102'
                    elif cfop_atual.startswith('2'):
                        cfop_compra = '2403' if is_st else '2102'
                    else:
                        cfop_compra = cfop_atual[:2] + '02' if len(cfop_atual) >= 2 else cfop_atual
                    
                    # Obter categorias
                    categoria_manter = obter_categoria_por_cfop(cfop_atual)
                    categoria_compra = obter_categoria_por_cfop(cfop_compra)
                    
                    cfops_agrupados[cfop_atual] = {
                        "cfop": cfop_atual,
                        "cfop_original": cfop_original,
                        "descricao": descricao_cfop,
                        "tipo_operacao": "entrada",
                        "produtos": [],
                        "notas": {},
                        "total_valor": 0,
                        "total_produtos": 0,
                        "sugestao_manter": {
                            "cfop": cfop_atual,
                            "descricao": f"Manter {cfop_atual}",
                            "categoria": categoria_manter,
                            "categoria_nome": obter_nome_categoria(categoria_manter) if categoria_manter else "Pendente"
                        },
                        "sugestao_compra": {
                            "cfop": cfop_compra,
                            "descricao": f"Converter para {cfop_compra}",
                            "categoria": categoria_compra,
                            "categoria_nome": obter_nome_categoria(categoria_compra) if categoria_compra else "Compra para Revenda"
                        }
                    }
                
                # Agrupar produtos por nota fiscal
                nfe_key = doc.get("numero_nfe", "")
                if nfe_key not in cfops_agrupados[cfop_atual]["notas"]:
                    cfops_agrupados[cfop_atual]["notas"][nfe_key] = {
                        "doc_id": doc["id"],
                        "numero_nfe": nfe_key,
                        "chave_nfe": doc.get("chave_nfe", ""),
                        "emitente": doc.get("emitente_nome", ""),
                        "data_emissao": doc.get("data_emissao", ""),
                        "valor_total_nfe": doc.get("valor_total", 0),
                        "produtos": []
                    }
                
                # Adicionar produto à nota
                produto_info = {
                    "produto_idx": idx,
                    "codigo": p.get("codigo", ""),
                    "descricao": p.get("descricao", ""),
                    "ncm": p.get("ncm", ""),
                    "quantidade": p.get("quantidade", 0),
                    "valor_unitario": p.get("valor_unitario", 0),
                    "valor_total": p.get("valor_total", 0),
                    "cfop_original_emissor": cfop_original
                }
                cfops_agrupados[cfop_atual]["notas"][nfe_key]["produtos"].append(produto_info)
                cfops_agrupados[cfop_atual]["total_valor"] += p.get("valor_total", 0) or 0
                cfops_agrupados[cfop_atual]["total_produtos"] += 1
        
        # Converter notas dict para lista e ordenar por quantidade (maior primeiro)
        for cfop_key in cfops_agrupados:
            cfops_agrupados[cfop_key]["notas"] = list(cfops_agrupados[cfop_key]["notas"].values())
        
        cfops_list = sorted(cfops_agrupados.values(), key=lambda x: -x["total_produtos"])
        
        result["data"] = {
            "alertas_cfop": cfops_list,
            "total_cfops": len(cfops_agrupados),
            "total_produtos": sum(c["total_produtos"] for c in cfops_agrupados.values()),
            "total_pendentes": sum(c["total_produtos"] for c in cfops_agrupados.values()),
            "opcoes_acao": [
                {"id": "manter", "label": "Manter CFOP", "description": "Manter o CFOP atual"},
                {"id": "converter_compra", "label": "Converter para Compra", "description": "Converte para CFOP de compra"},
                {"id": "converter_manual", "label": "Digitar CFOP", "description": "Informar CFOP manualmente"}
            ]
        }
    
    elif step_id == 4:  # Classificação de CFOPs (antigo step 3)
        # Buscar produtos sem classificação ou pendentes - SEM LIMITE para contar corretamente
        docs_entrada = await db.xml_documents.find({
            **base_filter,
            "tipo": "entrada",
            "modelo": "nfe"
        }, {"_id": 0, "id": 1, "numero_nfe": 1, "emitente_nome": 1, "produtos": 1}).to_list(length=None)
        
        produtos_pendentes = []
        produtos_classificados = []
        
        for doc in docs_entrada:
            for p in doc.get("produtos", []):
                produto_info = {
                    "doc_id": doc["id"],
                    "nfe": doc.get("numero_nfe", ""),
                    "emitente": doc.get("emitente_nome", ""),
                    "descricao": p.get("descricao", ""),
                    "codigo": p.get("codigo", ""),
                    "ncm": p.get("ncm", ""),
                    "cfop": p.get("cfop", ""),
                    "cfop_original": p.get("cfop_original", p.get("cfop_original_emissor", "")),
                    "categoria": p.get("categoria_classificada", ""),
                    "valor": p.get("valor_total", 0)
                }
                
                # Usar MESMA lógica da Central de Inteligência: pendente_revisao_cfop
                if p.get("pendente_revisao_cfop") or not p.get("categoria_classificada"):
                    produtos_pendentes.append(produto_info)
                else:
                    produtos_classificados.append(produto_info)
        
        result["data"] = {
            "produtos_pendentes": produtos_pendentes[:100],
            "produtos_classificados": len(produtos_classificados),
            "total_pendentes": len(produtos_pendentes),
            "total_classificados": len(produtos_classificados)
        }
    
    elif step_id == 5:  # PIS/COFINS Entradas
        # Buscar entradas com divergências de CST - SEM LIMITE para totalizar corretamente
        docs_entrada = await db.xml_documents.find({
            **base_filter,
            "tipo": "entrada"
        }, {"_id": 0, "id": 1, "numero_nfe": 1, "emitente_nome": 1, "valor_total": 1,
            "produtos": 1}).to_list(length=None)
        
        total_docs = len(docs_entrada)
        docs_com_divergencia = []
        
        for doc in docs_entrada:
            divergencias = []
            for p in doc.get("produtos", []):
                if p.get("cst_divergente"):
                    divergencias.append({
                        "produto": p.get("descricao", "")[:50],
                        "cst_xml": p.get("cst_pis_xml", ""),
                        "cst_calculado": p.get("cst_pis_calculado", ""),
                        "motivo": p.get("cst_motivo", "")
                    })
            
            if divergencias:
                docs_com_divergencia.append({
                    "id": doc["id"],
                    "nfe": doc.get("numero_nfe", ""),
                    "emitente": doc.get("emitente_nome", ""),
                    "divergencias": divergencias[:5]
                })
        
        result["data"] = {
            "total_documentos": total_docs,
            "docs_com_divergencia": docs_com_divergencia[:100],  # Limitar exibição, não contagem
            "total_divergencias": len(docs_com_divergencia)
        }
    
    elif step_id == 6:  # PIS/COFINS Saídas
        # Similar ao passo 4, mas para saídas - SEM LIMITE para totalizar corretamente
        docs_saida = await db.xml_documents.find({
            **base_filter,
            "tipo": "saida"
        }, {"_id": 0, "id": 1, "numero_nfe": 1, "destinatario_nome": 1, "valor_total": 1,
            "produtos": 1, "modelo": 1}).to_list(length=None)
        
        total_docs = len(docs_saida)
        
        result["data"] = {
            "total_documentos": total_docs,
            "resumo": {
                "nfe_saida": sum(1 for d in docs_saida if d.get("modelo") == "nfe"),
                "nfce": sum(1 for d in docs_saida if d.get("modelo") == "nfce")
            }
        }
    
    elif step_id == 7:  # Reforma Tributária
        # Buscar dados para cálculo da Reforma Tributária
        try:
            # Buscar configuração
            config_doc = await db.reforma_tributaria_config.find_one(
                {"company_id": company_id},
                {"_id": 0}
            )
            
            config = ConfiguracaoReformaTributaria(
                aliquota_cbs=Decimal(str(config_doc.get('aliquota_cbs', 8.80))) if config_doc else Decimal('8.80'),
                aliquota_ibs=Decimal(str(config_doc.get('aliquota_ibs', 17.70))) if config_doc else Decimal('17.70')
            )
            
            # Buscar documentos de entrada
            docs_entrada = await db.xml_documents.find({
                "company_id": company_id,
                "competencia": competencia,
                "tipo": "entrada",
                "desconsiderada_devolucao": {"$ne": True}
            }).to_list(length=100000)
            
            # Buscar documentos de saída
            docs_saida = await db.xml_documents.find({
                "company_id": company_id,
                "competencia": competencia,
                "tipo": "saida",
                "desconsiderada_devolucao": {"$ne": True}
            }).to_list(length=100000)
            
            # Classificar entradas
            creditos = []
            for doc in docs_entrada:
                produtos = doc.get('produtos', [])
                for prod in produtos:
                    cfop = prod.get('cfop', '') or prod.get('cfop_original_emissor', '')
                    ncm = prod.get('ncm', '')
                    valor = Decimal(str(prod.get('valor_total', 0) or 0))
                    
                    if valor > 0:
                        resultado = classificar_entrada(cfop, ncm, valor, config)
                        creditos.append(resultado)
            
            # Classificar saídas
            debitos = []
            for doc in docs_saida:
                produtos = doc.get('produtos', [])
                for prod in produtos:
                    cfop = prod.get('cfop', '') or prod.get('cfop_original_emissor', '')
                    ncm = prod.get('ncm', '')
                    valor = Decimal(str(prod.get('valor_total', 0) or 0))
                    
                    if valor > 0:
                        resultado = classificar_saida(cfop, ncm, valor, config)
                        debitos.append(resultado)
            
            # Calcular apuração
            apuracao = calcular_apuracao(creditos, debitos)
            
            result["data"] = {
                "apuracao": apuracao,
                "config": {
                    "aliquota_cbs": float(config.aliquota_cbs),
                    "aliquota_ibs": float(config.aliquota_ibs),
                    "aliquota_total": float(config.aliquota_total)
                },
                "total_entradas": len(docs_entrada),
                "total_saidas": len(docs_saida)
            }
        except Exception as e:
            import traceback
            result["data"] = {"error": str(e), "traceback": traceback.format_exc()}
    
    elif step_id == 8:  # Concluído
        # Resumo final
        wizard = await db.wizard_fechamento.find_one(
            {"company_id": company_id, "competencia": competencia},
            {"_id": 0}
        )
        
        result["data"] = {
            "wizard": wizard,
            "steps_completed": wizard.get("steps_completed", []) if wizard else [],
            "all_complete": len(wizard.get("steps_completed", [])) >= 6 if wizard else False
        }
    
    return result


@api_router.post("/wizard-fechamento/step/{company_id}/{step_id}/complete")
async def complete_wizard_step(
    company_id: str,
    step_id: int,
    competencia: str = Query(...),
    step_data: Dict[str, Any] = Body(default={}),
    current_user: User = Depends(get_current_user)
):
    """Marca uma etapa como completa e salva os dados"""
    company = await db.companies.find_one({"id": company_id}, {"_id": 0})
    if not company:
        raise HTTPException(status_code=404, detail="Empresa não encontrada")
    
    if not await check_company_access(company, current_user):
        raise HTTPException(status_code=403, detail="Acesso negado")
    
    # Processar ações específicas de cada etapa
    actions_taken = []
    
    if step_id == 1:  # Notas Canceladas
        # Confirmar notas canceladas
        notas_ids = step_data.get("notas_confirmar", [])
        if notas_ids:
            result = await db.xml_documents.update_many(
                {"id": {"$in": notas_ids}},
                {"$set": {"cancelada": True, "confirmada_wizard": True}}
            )
            actions_taken.append(f"{result.modified_count} notas marcadas como canceladas")
    
    elif step_id == 2:  # Devoluções
        # Marcar notas de devolução como desconsideradas
        # E também marcar as notas originais referenciadas
        notas_ids = step_data.get("notas_desconsiderar", [])
        notas_originais_ids = step_data.get("notas_originais_desconsiderar", [])
        
        total_desconsideradas = 0
        
        if notas_ids:
            result = await db.xml_documents.update_many(
                {"id": {"$in": notas_ids}},
                {"$set": {
                    "desconsiderada_devolucao": True,
                    "motivo_desconsideracao": "Devolução de terceiro - Confirmado via Wizard de Fechamento"
                }}
            )
            total_desconsideradas += result.modified_count
            actions_taken.append(f"{result.modified_count} notas de devolução desconsideradas")
        
        # Excluir também as notas originais (que originaram a devolução)
        if notas_originais_ids:
            result = await db.xml_documents.update_many(
                {"id": {"$in": notas_originais_ids}},
                {"$set": {
                    "desconsiderada_devolucao": True,
                    "motivo_desconsideracao": "Nota original de devolução - Excluída via Wizard de Fechamento"
                }}
            )
            total_desconsideradas += result.modified_count
            actions_taken.append(f"{result.modified_count} notas originais desconsideradas")
        
        if total_desconsideradas > 0:
            actions_taken.append(f"Total: {total_desconsideradas} documentos excluídos da apuração")
    
    elif step_id == 3:  # Alertas de CFOP - Processar ações definidas
        # Processar as ações definidas para cada CFOP
        acoes_cfops = step_data.get("acoes_cfops", {})
        
        for cfop, acao_data in acoes_cfops.items():
            # Suportar formato antigo (string) e novo (objeto)
            if isinstance(acao_data, str):
                acao = acao_data
                cfop_destino_manual = None
            else:
                acao = acao_data.get("acao", "manter")
                cfop_destino_manual = acao_data.get("cfop_destino")
            
            if acao == "manter":
                # Apenas remover o flag pendente_revisao_cfop sem alterar o CFOP
                # MAS TAMBÉM definir categoria_classificada baseada no CFOP atual
                docs = await db.xml_documents.find({
                    "company_id": company_id,
                    "competencia": competencia,
                    "tipo": "entrada",
                    "produtos.cfop": cfop
                }).to_list(length=1000)
                
                count = 0
                for doc in docs:
                    produtos_atualizados = doc.get("produtos", [])
                    alterado = False
                    for p in produtos_atualizados:
                        if str(p.get("cfop")) == cfop and p.get("pendente_revisao_cfop"):
                            # Determinar categoria baseada no CFOP
                            categoria_cfop = obter_categoria_por_cfop(cfop)
                            
                            p["pendente_revisao_cfop"] = False
                            p["cfop_revisado_wizard"] = True
                            p["cfop_revisado_em"] = datetime.now(timezone.utc).isoformat()
                            
                            # SINCRONIZAR com Classificação Inteligente
                            if categoria_cfop:
                                p["categoria"] = categoria_cfop
                                p["categoria_classificada"] = categoria_cfop
                                p["categoria_origem"] = "wizard_manter"
                                p["categoria_classificada_em"] = datetime.now(timezone.utc).isoformat()
                            
                            alterado = True
                            count += 1
                    
                    if alterado:
                        await db.xml_documents.update_one(
                            {"id": doc["id"]},
                            {"$set": {"produtos": produtos_atualizados}}
                        )
                
                actions_taken.append(f"CFOP {cfop}: {count} produtos mantidos e classificados")
            
            elif acao == "converter_compra":
                # Converter para CFOP de compra (entradas)
                cfop_destino = cfop_destino_manual or ("1102" if cfop.startswith("1") else "2102")
                
                # Determinar categoria baseada no CFOP de destino
                categoria_cfop = obter_categoria_por_cfop(cfop_destino)
                
                docs = await db.xml_documents.find({
                    "company_id": company_id,
                    "competencia": competencia,
                    "tipo": "entrada",
                    "produtos.cfop": cfop
                }).to_list(length=1000)
                
                count = 0
                for doc in docs:
                    produtos_atualizados = doc.get("produtos", [])
                    alterado = False
                    for p in produtos_atualizados:
                        if str(p.get("cfop")) == cfop and p.get("pendente_revisao_cfop"):
                            p["cfop_original_distinto"] = cfop
                            p["cfop"] = cfop_destino
                            p["pendente_revisao_cfop"] = False
                            p["cfop_convertido_wizard"] = True
                            p["cfop_revisado_em"] = datetime.now(timezone.utc).isoformat()
                            
                            # SINCRONIZAR com Classificação Inteligente
                            if categoria_cfop:
                                p["categoria"] = categoria_cfop
                                p["categoria_classificada"] = categoria_cfop
                                p["categoria_origem"] = "wizard_converter_compra"
                                p["categoria_classificada_em"] = datetime.now(timezone.utc).isoformat()
                            
                            alterado = True
                            count += 1
                    
                    if alterado:
                        await db.xml_documents.update_one(
                            {"id": doc["id"]},
                            {"$set": {"produtos": produtos_atualizados}}
                        )
                
                actions_taken.append(f"CFOP {cfop} → {cfop_destino}: {count} produtos convertidos e classificados")
            
            elif acao == "converter_manual" and cfop_destino_manual:
                # Converter para CFOP digitado manualmente
                cfop_destino = str(cfop_destino_manual)
                
                docs = await db.xml_documents.find({
                    "company_id": company_id,
                    "competencia": competencia,
                    "tipo": "entrada",
                    "produtos.cfop": cfop
                }).to_list(length=1000)
                
                count = 0
                for doc in docs:
                    produtos_atualizados = doc.get("produtos", [])
                    alterado = False
                    for p in produtos_atualizados:
                        if str(p.get("cfop")) == cfop and p.get("pendente_revisao_cfop"):
                            p["cfop_original_distinto"] = cfop
                            p["cfop"] = cfop_destino
                            p["pendente_revisao_cfop"] = False
                            p["cfop_convertido_wizard"] = True
                            alterado = True
                            count += 1
                    
                    if alterado:
                        await db.xml_documents.update_one(
                            {"id": doc["id"]},
                            {"$set": {"produtos": produtos_atualizados}}
                        )
                
                actions_taken.append(f"CFOP {cfop} → {cfop_destino}: {count} produtos convertidos (manual)")
    
    
    elif step_id == 4:  # Classificação de CFOPs (antigo step 3)
        # Classificar produtos com IA se necessário
        classificar = step_data.get("classificar_produtos", False)
        if classificar:
            # Buscar documentos de entrada sem classificação
            docs = await db.xml_documents.find({
                "company_id": company_id,
                "competencia": competencia,
                "tipo": "entrada",
                "modelo": "nfe"
            }).to_list(length=500)
            
            total_classificados = 0
            for doc in docs:
                produtos_para_classificar = []
                for p in doc.get("produtos", []):
                    if not p.get("categoria_classificada"):
                        produtos_para_classificar.append(p)
                
                if produtos_para_classificar:
                    try:
                        emitente_uf = doc.get("emitente_uf", "")
                        
                        # Carregar cache de vendas para aprendizado (igual importação normal)
                        sales_cache = {}
                        try:
                            pipeline = [
                                {"$match": {"company_id": company_id, "tipo": "saida"}},
                                {"$unwind": "$produtos"},
                                {"$group": {
                                    "_id": {
                                        "descricao": {"$toLower": "$produtos.descricao"},
                                        "codigo": "$produtos.codigo"
                                    },
                                    "categoria": {"$first": "$produtos.categoria_classificada"},
                                    "cfop": {"$first": "$produtos.cfop"},
                                    "count": {"$sum": 1}
                                }},
                                {"$match": {"count": {"$gte": 1}}}
                            ]
                            sales_products = await db.xml_documents.aggregate(pipeline).to_list(length=10000)
                            for sp in sales_products:
                                key = (sp["_id"]["descricao"] or "", sp["_id"]["codigo"] or "")
                                if sp.get("categoria"):
                                    sales_cache[key] = {"categoria": sp["categoria"], "cfop": sp.get("cfop", "")}
                        except Exception as e:
                            logger.warning(f"Erro ao carregar cache de vendas: {e}")
                        
                        # Calcular CST ANTES de classificar (igual importação normal)
                        regime = company.get("regime_tributario", "simples_nacional")
                        for product in produtos_para_classificar:
                            cfop = product.get('cfop', '')
                            ncm = product.get('ncm', '')
                            
                            # Salvar CFOP original do emissor
                            if not product.get('cfop_original') and not product.get('cfop_original_emissor'):
                                product['cfop_original_emissor'] = cfop
                            
                            # Calcular CST de PIS/COFINS
                            cst_info = calcular_cst_pis_cofins(
                                ncm=ncm,
                                cfop=cfop,
                                tipo_operacao="entrada",
                                cst_xml=product.get('cst_pis_xml', product.get('cst_pis', '')),
                                regime=regime
                            )
                            
                            product['cst_pis_calculado'] = cst_info['cst_calculado']
                            product['cst_cofins_calculado'] = cst_info['cst_calculado']
                            product['cst_pis'] = cst_info['cst_calculado']
                            product['cst_cofins'] = cst_info['cst_calculado']
                        
                        # Classificar com cache e IA
                        classifications, stats = await classify_products_with_cache(
                            produtos_para_classificar,
                            company_id,
                            company,
                            emitente_uf,
                            sales_cache
                        )
                        
                        # Aplicar classificações
                        for idx, product in enumerate(produtos_para_classificar):
                            p_id = str(idx)
                            if p_id in classifications:
                                result_class = classifications[p_id]
                                cfop_original = product.get('cfop', '')
                                product['cfop_original'] = cfop_original
                                product['cfop'] = result_class['cfop']
                                product['cfop_sugerido'] = result_class['cfop']
                                product['categoria_classificada'] = result_class['categoria']
                                product['justificativa_ia'] = result_class['justificativa']
                                total_classificados += 1
                        
                        # Salvar documento atualizado
                        await db.xml_documents.update_one(
                            {"id": doc["id"]},
                            {"$set": {"produtos": doc["produtos"]}}
                        )
                    except Exception as e:
                        logger.warning(f"Erro ao classificar: {e}")
            
            actions_taken.append(f"{total_classificados} produtos classificados")
    
    elif step_id == 5:  # PIS/COFINS Entradas
        # Recalcular CST de entradas
        recalcular = step_data.get("recalcular_cst", False)
        if recalcular:
            regime = company.get("regime_tributario", "simples_nacional")
            docs = await db.xml_documents.find({
                "company_id": company_id,
                "competencia": competencia,
                "tipo": "entrada"
            }).to_list(length=500)
            
            total_corrigidos = 0
            for doc in docs:
                updated = False
                for p in doc.get("produtos", []):
                    cst_info = calcular_cst_pis_cofins(
                        ncm=p.get("ncm", ""),
                        cfop=p.get("cfop", ""),
                        tipo_operacao="entrada",
                        cst_xml=p.get("cst_pis_xml", ""),
                        regime=regime
                    )
                    
                    if p.get("cst_pis") != cst_info['cst_calculado']:
                        p['cst_pis'] = cst_info['cst_calculado']
                        p['cst_cofins'] = cst_info['cst_calculado']
                        p['cst_corrigido_wizard'] = True
                        updated = True
                        total_corrigidos += 1
                
                if updated:
                    await db.xml_documents.update_one(
                        {"id": doc["id"]},
                        {"$set": {"produtos": doc["produtos"]}}
                    )
            
            actions_taken.append(f"{total_corrigidos} CSTs corrigidos nas entradas")
    
    elif step_id == 6:  # PIS/COFINS Saídas
        # Similar ao passo 4, mas para saídas
        recalcular = step_data.get("recalcular_cst", False)
        if recalcular:
            regime = company.get("regime_tributario", "simples_nacional")
            docs = await db.xml_documents.find({
                "company_id": company_id,
                "competencia": competencia,
                "tipo": "saida"
            }).to_list(length=500)
            
            total_corrigidos = 0
            for doc in docs:
                updated = False
                for p in doc.get("produtos", []):
                    cst_info = calcular_cst_pis_cofins(
                        ncm=p.get("ncm", ""),
                        cfop=p.get("cfop", ""),
                        tipo_operacao="saida",
                        cst_xml=p.get("cst_pis_xml", ""),
                        regime=regime
                    )
                    
                    if p.get("cst_pis") != cst_info['cst_calculado']:
                        p['cst_pis'] = cst_info['cst_calculado']
                        p['cst_cofins'] = cst_info['cst_calculado']
                        p['cst_corrigido_wizard'] = True
                        updated = True
                        total_corrigidos += 1
                
                if updated:
                    await db.xml_documents.update_one(
                        {"id": doc["id"]},
                        {"$set": {"produtos": doc["produtos"]}}
                    )
            
            actions_taken.append(f"{total_corrigidos} CSTs corrigidos nas saídas")
    
    elif step_id == 7:  # Reforma Tributária
        # Apenas salvar que o cálculo foi revisado
        actions_taken.append("Cálculo da Reforma Tributária revisado")
    
    # Atualizar wizard
    step_name = WIZARD_STEPS[step_id - 1]["name"] if step_id <= len(WIZARD_STEPS) else "unknown"
    next_step = min(step_id + 1, len(WIZARD_STEPS))
    
    update_data = {
        "current_step": next_step,
        "updated_at": datetime.now(timezone.utc).isoformat(),
        f"steps_data.{step_name}": {
            "completed_at": datetime.now(timezone.utc).isoformat(),
            "completed_by": current_user.id,
            "actions": actions_taken,
            "input_data": step_data
        }
    }
    
    # Adicionar step aos completados
    await db.wizard_fechamento.update_one(
        {"company_id": company_id, "competencia": competencia},
        {
            "$set": update_data,
            "$addToSet": {"steps_completed": step_id}
        },
        upsert=True
    )
    
    # Se último passo, marcar como concluído
    if step_id >= 7:
        await db.wizard_fechamento.update_one(
            {"company_id": company_id, "competencia": competencia},
            {"$set": {"status": "completed"}}
        )
    
    return {
        "success": True,
        "step_completed": step_id,
        "next_step": next_step,
        "actions_taken": actions_taken
    }


@api_router.post("/wizard-fechamento/step/{company_id}/{step_id}/go")
async def go_to_wizard_step(
    company_id: str,
    step_id: int,
    competencia: str = Query(...),
    current_user: User = Depends(get_current_user)
):
    """Navega para uma etapa específica do wizard"""
    await db.wizard_fechamento.update_one(
        {"company_id": company_id, "competencia": competencia},
        {
            "$set": {
                "current_step": step_id,
                "updated_at": datetime.now(timezone.utc).isoformat()
            }
        }
    )
    
    return {"success": True, "current_step": step_id}


